var OSHA_QUESTIONS=[{id:"osha_1",categoria:"OSHA_PPE",pregunta:"Si un t\xE9cnico usa ropa de 100% poli\xE9ster bajo un traje de Arc Flash, \xBFcu\xE1l es el peligro?",opciones:["Se ensucia m\xE1s r\xE1pido","El poli\xE9ster se puede derretir sobre la piel debido al calor transferido por el arco","Aumenta la est\xE1tica del mult\xEDmetro","No hay peligro si el traje exterior es Categor\xEDa 4"],respuesta_correcta:1,explicacion:"La ropa sint\xE9tica se derrite a bajas temperaturas. Solo se permite algod\xF3n tratado o capas FR (Flame Resistant) debajo del EPP."},{id:"osha_2",categoria:"OSHA_PPE",pregunta:"En un sistema de refrigeraci\xF3n industrial con Amon\xEDaco (R-717), el t\xE9cnico debe saber que este gas es:",opciones:["Inodoro e inofensivo","Altamente t\xF3xico y tambi\xE9n inflamable en ciertas concentraciones","M\xE1s pesado que el aire y se queda en el suelo","Seguro para respirar por 10 minutos"],respuesta_correcta:1,explicacion:"El amon\xEDaco es t\xF3xico, corrosivo y puede volverse explosivo si se mezcla con aire en proporciones del 15% al 28%."},{id:"osha_3",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 se debe hacer con una herramienta el\xE9ctrica que produce chispas excesivas en el conmutador?",opciones:["Soplar con aire comprimido","Usarla hasta que termine el turno","Retirarla de servicio para inspecci\xF3n de escobillas o bobinado","Ponerse guantes m\xE1s gruesos"],respuesta_correcta:2,explicacion:"Las chispas excesivas indican una falla el\xE9ctrica inminente o da\xF1o en el aislamiento que puede causar un choque al usuario."},{id:"osha_4",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 significa que un interruptor sea 'Current Limiting'?",opciones:["Que limita la factura de luz","Que reduce el pico de corriente de falla para disminuir la energ\xEDa del Arc Flash","Que solo permite 10 Amperios","Que no se dispara nunca"],respuesta_correcta:1,explicacion:"Los dispositivos limitadores de corriente abren tan r\xE1pido que la falla no alcanza su valor m\xE1ximo, protegiendo al personal y al equipo."},{id:"osha_5",categoria:"OSHA_PPE",pregunta:"Una amoladora (grinder) sin la guarda de seguridad instalada es una violaci\xF3n de qu\xE9 tipo:",opciones:["Menor","Seria / Grave","De mantenimiento solamente","No es violaci\xF3n si usas careta"],respuesta_correcta:1,explicacion:"OSHA considera la falta de guardas en partes rotativas como una violaci\xF3n seria que puede causar amputaciones."},{id:"osha_6",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1l es la presi\xF3n m\xE1xima permitida para usar aire comprimido en limpieza de manos o ropa?",opciones:["100 psi","50 psi","30 psi","Est\xE1 prohibido totalmente"],respuesta_correcta:2,explicacion:"OSHA proh\xEDbe el uso de aire comprimido para limpieza personal a menos que la presi\xF3n se reduzca a menos de 30 psi y se use protecci\xF3n ocular."},{id:"osha_7",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1ndo se debe inspeccionar el arn\xE9s de seguridad?",opciones:["Una vez al mes","Cada vez que se use","Solo despu\xE9s de una ca\xEDda","Cada vez que el inspector de OSHA venga"],respuesta_correcta:1,explicacion:"La inspecci\xF3n pre-uso es vital para detectar costuras rotas o corrosi\xF3n en anillos D antes de que fallen."},{id:"osha_8",categoria:"OSHA_PPE",pregunta:"En un sistema de refrigeraci\xF3n, el nitr\xF3geno se usa para pruebas de fuga. \xBFQu\xE9 dispositivo es OBLIGATORIO usar?",opciones:["Una manguera larga","Un regulador de presi\xF3n con v\xE1lvula de alivio","Un man\xF3metro de baja presi\xF3n","Cinta aislante en las conexiones"],respuesta_correcta:1,explicacion:"Conectar nitr\xF3geno directo del tanque (2500+ psi) a un sistema de refrigeraci\xF3n (dise\xF1ado para 500 psi) sin regulador causar\xE1 una explosi\xF3n fatal."},{id:"osha_9",categoria:"OSHA_PPE",pregunta:"Si ves un cable el\xE9ctrico en el suelo con agua alrededor, debes:",opciones:["Saltar el charco","Ponerse botas de goma y quitarlo","Aislar el \xE1rea y notificar al personal calificado para desenergizar","Echarle arena"],respuesta_correcta:2,explicacion:"La seguridad perimetral es la primera responsabilidad del trabajador no calificado ante un peligro el\xE9ctrico."},{id:"osha_10",categoria:"OSHA_PPE",pregunta:"Si una extensi\xF3n el\xE9ctrica se siente caliente al tacto mientras est\xE1 en uso, significa:",opciones:["Que es de buena calidad","Que el calibre del cable es muy peque\xF1o para la carga (ca\xEDda de tensi\xF3n y calor)","Que afuera hace calor","Que el motor est\xE1 enfriando el cable"],respuesta_correcta:1,explicacion:"El calor es un signo de resistencia excesiva. Un cable caliente es un riesgo de incendio inminente."},{id:"osha_11",categoria:"OSHA_PPE",pregunta:"Al soldar tuber\xEDa de cobre (brazing), \xBFpor qu\xE9 es importante usar lentes con filtro de sombra?",opciones:["Para verse profesional","Para proteger contra la radiaci\xF3n infrarroja y el deslumbramiento que da\xF1a la retina","Para ver el flujo del nitr\xF3geno","Porque OSHA lo dice solo para el acero"],respuesta_correcta:1,explicacion:"Incluso sin arco el\xE9ctrico, la llama de alta temperatura emite radiaciones que causan fatiga visual y da\xF1o a largo plazo."},{id:"osha_12",categoria:"OSHA_PPE",pregunta:"En un sistema de Amon\xEDaco (R-717), \xBFpor qu\xE9 est\xE1 estrictamente prohibido usar tuber\xEDas o accesorios de cobre?",opciones:["Porque el cobre es muy caro","El amon\xEDaco corroe el cobre y sus aleaciones en presencia de humedad, causando fugas catastr\xF3ficas","El cobre hace que el amon\xEDaco se caliente","OSHA solo permite acero inoxidable por est\xE9tica"],respuesta_correcta:1,explicacion:"El R-717 reacciona violentamente con metales no ferrosos como el cobre y el bronce."},{id:"osha_13",categoria:"OSHA_PPE",pregunta:"Antes de soldar un sistema que conten\xEDa refrigerante A2L (levemente inflamable), \xBFqu\xE9 paso es obligatorio?",opciones:["Solo abrir las ventanas","Evacuar el refrigerante, lavar con nitr\xF3geno y verificar con un detector de fugas inflamables","Soldar r\xE1pido antes de que se acumule gas","Usar una llama m\xE1s peque\xF1a"],respuesta_correcta:1,explicacion:"Los refrigerantes como el R-32 o R-454B requieren protocolos de purga estrictos para evitar deflagraciones durante la soldadura."},{id:"osha_14",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 tipo de protecci\xF3n ocular es mejor para manejar refrigerante l\xEDquido?",opciones:["Lentes de sol","Gafas de seguridad con protecci\xF3n lateral o careta completa","Lentes de contacto","No se requiere si cierras los ojos al abrir la v\xE1lvula"],respuesta_correcta:1,explicacion:"El refrigerante l\xEDquido se evapora instant\xE1neamente a temperaturas muy bajas, causando congelamiento inmediato de la c\xF3rnea (ceguera)."},{id:"osha_15",categoria:"OSHA_PPE",pregunta:"Al usar una bomba de vac\xEDo, el t\xE9cnico nota humo saliendo del escape. \xBFQu\xE9 debe hacer?",opciones:["Nada, es normal que las bombas fumen","Apagarla y revisar si hay una fuga masiva en el sistema o si el aceite est\xE1 contaminado","Echarle agua fr\xEDa","Tapar el escape con el dedo"],respuesta_correcta:1,explicacion:"El 'humo' suele ser neblina de aceite causada por bombear grandes cantidades de aire o vapor, indicando una falta de hermeticidad."},{id:"osha_16",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Vacu\xF3metro' (Micron Gauge) desde el punto de vista de la seguridad a largo plazo?",opciones:["Medir la presi\xF3n de carga","Asegurar que no queden no-condensables ni humedad que generen \xE1cidos y fallas el\xE9ctricas (hermetic burnout)","Ver si la bomba tiene aceite","Limpiar las tuber\xEDas"],respuesta_correcta:1,explicacion:"Un vac\xEDo profundo (500 micrones) elimina el aire y la humedad, previniendo la degradaci\xF3n qu\xEDmica del sistema."},{id:"osha_17",categoria:"OSHA_PPE",pregunta:"El casco de seguridad 'Clase E' (Electrical) est\xE1 dise\xF1ado para soportar hasta:",opciones:["2,000 voltios","10,000 voltios","20,000 voltios","No protege contra electricidad"],respuesta_correcta:2,explicacion:"La clase E est\xE1 probada para 20,000 voltios, siendo el est\xE1ndar para electricistas y t\xE9cnicos HVAC industriales."},{id:"osha_18",categoria:"OSHA_PPE",pregunta:"Usar un destornillador como palanca o cincel es:",opciones:["Una pr\xE1ctica eficiente","Una violaci\xF3n de seguridad que puede resultar en la rotura de la herramienta y lesiones oculares","Permitido si el mango es de goma","Solo permitido en sistemas residenciales"],respuesta_correcta:1,explicacion:"Las herramientas deben usarse \xFAnicamente para el prop\xF3sito que fueron dise\xF1adas."},{id:"osha_19",categoria:"OSHA_PPE",pregunta:"Un sensor de flujo de agua (Flow Switch) en un Chiller es un dispositivo de:",opciones:["Confort","Seguridad para evitar que el intercambiador se congele y reviente","Ahorro de energ\xEDa","Medici\xF3n de temperatura"],respuesta_correcta:1,explicacion:"Si el agua deja de fluir y el enfriador sigue operando, el agua estancada se congela y expande, rompiendo los tubos internos."},{id:"osha_20",categoria:"OSHA_PPE",pregunta:"Un sistema con una carga de m\xE1s de 50 lbs de refrigerante tiene una fuga. Seg\xFAn EPA, el l\xEDmite de tiempo para repararla antes de que sea una violaci\xF3n legal es de:",opciones:["24 horas","30 d\xEDas","6 meses","No hay l\xEDmite"],respuesta_correcta:1,explicacion:"Bajo la Secci\xF3n 608 de la Ley de Aire Limpio, hay plazos estrictos de reparaci\xF3n seg\xFAn el tipo de equipo."},{id:"osha_21",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1ndo deben usarse tapones para los o\xEDdos en una sala de m\xE1quinas?",opciones:["Cuando el t\xE9cnico quiera","Cuando el nivel de ruido supere los 85-90 dB de promedio ponderado","Solo si hay m\xFAsica fuerte","Nunca, si el t\xE9cnico est\xE1 acostumbrado"],respuesta_correcta:1,explicacion:"La p\xE9rdida auditiva es irreversible y acumulativa."},{id:"osha_22",categoria:"OSHA_PPE",pregunta:"Un detector de fugas electr\xF3nico pita constantemente en una habitaci\xF3n vac\xEDa. Esto se llama 'Falsa alarma' y puede ser causado por:",opciones:["Falta de bater\xEDa","Vapores de solventes, alcohol o falta de aire fresco (sensor contaminado)","Que hay mucho oro cerca","El campo magn\xE9tico de la tierra"],respuesta_correcta:1,explicacion:"Los sensores de diodo caliente o corona pueden reaccionar a diversos hidrocarburos, no solo a refrigerantes."},{id:"osha_23",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 tipo de guantes son obligatorios al manipular bater\xEDas de litio de gran escala (ESS)?",opciones:["Guantes de tela","Guantes aislantes de goma clase 0 con protectores de cuero y resistencia qu\xEDmica","Guantes de soldador","No se usan guantes para tener mejor tacto"],respuesta_correcta:1,explicacion:"Se requiere protecci\xF3n tanto el\xE9ctrica (voltaje de la bater\xEDa) como qu\xEDmica (posibles fugas de electrolito)."},{id:"osha_24",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 indica el s\xEDmbolo de un doble cuadrado (un cuadrado dentro de otro) en una herramienta el\xE9ctrica?",opciones:["Que es de alta potencia","Que tiene doble aislamiento y no requiere conexi\xF3n a tierra (third prong)","Que es para uso exclusivo en interiores","Que fue hecha en ACVOLT"],respuesta_correcta:1,explicacion:"El doble aislamiento protege al usuario de fallas internas sin depender de una conexi\xF3n a tierra externa."},{id:"osha_25",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 es el 'R\xE1pido Apagado' (Rapid Shutdown) en sistemas solares seg\xFAn el NEC?",opciones:["Apagar las luces de la casa","Un sistema que reduce el voltaje de los cables en el techo a niveles seguros (30V o menos) en 30 segundos tras activarse","Desconectar la bater\xEDa","Un extintor autom\xE1tico"],respuesta_correcta:1,explicacion:"Esta funci\xF3n protege a los bomberos y personal de emergencia de electrocutarse al trabajar en el techo durante un incendio."},{id:"osha_26",categoria:"OSHA_PPE",pregunta:"Un casco de seguridad que ha sufrido un impacto fuerte pero no se ve roto, \xBFpuede seguir us\xE1ndose?",opciones:["S\xED, si se ve bien","No, debe ser reemplazado ya que su estructura interna pudo haberse debilitado","Solo si el jefe lo autoriza","Solo si es de marca cara"],respuesta_correcta:1,explicacion:"La capacidad de absorci\xF3n de energ\xEDa de un casco es de un solo uso cr\xEDtico."},{id:"osha_27",categoria:"OSHA_PPE",pregunta:"Un 'Punto de Anclaje' para un sistema de detenci\xF3n de ca\xEDdas debe ser capaz de soportar:",opciones:["1,000 lbs por persona","5,000 lbs por cada persona conectada","El peso de la escalera","500 lbs"],respuesta_correcta:1,explicacion:"Debe soportar el impacto de una ca\xEDda libre, lo cual multiplica el peso del trabajador por la aceleraci\xF3n."},{id:"osha_28",categoria:"OSHA_PPE",pregunta:"Al usar un soplete de Oxiacetileno, \xBFpor qu\xE9 nunca se debe usar aceite o grasa en los reguladores de Ox\xEDgeno?",opciones:["Porque ensucian las manos","El ox\xEDgeno puro bajo presi\xF3n reacciona violentamente con hidrocarburos (aceite/grasa) causando una explosi\xF3n","Porque el aceite bloquea el gas","Porque el soplete no prender\xE1"],respuesta_correcta:1,explicacion:"El ox\xEDgeno es un comburente extremadamente potente; la grasa act\xFAa como combustible y la presi\xF3n genera el calor de ignici\xF3n."},{id:"osha_29",categoria:"OSHA_PPE",pregunta:"Un trabajador de menos de 18 a\xF1os tiene prohibido por OSHA:",opciones:["Usar un martillo","Operar la mayor\xEDa de la maquinaria pesada, como montacargas o sierras de gran potencia","Trabajar despu\xE9s de las 5 PM","Llevar el almuerzo"],respuesta_correcta:1,explicacion:"Existen restricciones de seguridad estrictas para menores en ocupaciones peligrosas de construcci\xF3n."},{id:"osha_30",categoria:"OSHA_PPE",pregunta:"En un evaporador, el 'Superheat' muy bajo (0\xB0F) es un signo de seguridad de:",opciones:["Excelente eficiencia","Inundaci\xF3n de l\xEDquido hacia el compresor (Liquid Slug)","Falta de refrigerante","Filtro de aire limpio"],respuesta_correcta:1,explicacion:"0\xB0F de sobrecalentamiento significa que el refrigerante es l\xEDquido puro, lo cual destruir\xE1 el compresor."},{id:"osha_31",categoria:"OSHA_PPE",pregunta:"Al usar una llave ajustable (Crescent wrench), la fuerza debe aplicarse:",opciones:["Hacia la mand\xEDbula fija","Hacia la mand\xEDbula m\xF3vil","No importa la direcci\xF3n","Siempre empujando con la palma"],respuesta_correcta:0,explicacion:"Tirar hacia la mand\xEDbula fija evita que la llave se abra o se resbale, previniendo lesiones en los nudillos."},{id:"osha_32",categoria:"OSHA_PPE",pregunta:"Antes de entrar a un cuarto de m\xE1quinas con Amon\xEDaco tras una alarma, el t\xE9cnico debe usar:",opciones:["Una toalla mojada","Un SCBA (Self-Contained Breathing Apparatus) y traje de protecci\xF3n qu\xEDmica","Solo lentes de seguridad","Correr muy r\xE1pido"],respuesta_correcta:1,explicacion:"El amon\xEDaco en altas concentraciones quema los pulmones y la piel h\xFAmeda instant\xE1neamente."},{id:"osha_33",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 significa el marcado 'Z87+' en unos lentes de seguridad?",opciones:["Que son para ver de lejos","Que est\xE1n certificados para alto impacto","Que son resistentes al agua","Que son marca ACVOLT"],respuesta_correcta:1,explicacion:"El signo '+' indica que pasaron la prueba de impacto de alta masa y alta velocidad."},{id:"osha_34",categoria:"OSHA_PPE",pregunta:"Al trabajar con R-410A, \xBFpor qu\xE9 los man\xF3metros de R-22 no son seguros?",opciones:["Porque los colores son distintos","Porque el R-410A opera a presiones mucho m\xE1s altas y puede reventar el vidrio o mangueras de un manifold viejo","Porque el aceite no es compatible","Porque el R-22 es ilegal"],respuesta_correcta:1,explicacion:"La seguridad f\xEDsica depende de usar herramientas con el rating de presi\xF3n adecuado (800 psi en el lado de alta para R-410A)."},{id:"osha_35",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 es una 'JSA' (Job Safety Analysis)?",opciones:["Un examen m\xE9dico","Un proceso de identificar peligros paso a paso antes de iniciar una tarea espec\xEDfica","Un reporte de ventas","Una junta de sindicato"],respuesta_correcta:1,explicacion:"La JSA permite al equipo planificar c\xF3mo mitigar cada riesgo antes de que ocurra un accidente."},{id:"osha_36",categoria:"OSHA_PPE",pregunta:"Al cargar refrigerante en fase l\xEDquida por la l\xEDnea de succi\xF3n, \xBFcu\xE1l es el peligro?",opciones:["El sistema enfr\xEDa m\xE1s r\xE1pido","Golpe de l\xEDquido al compresor (slugging) y da\xF1o a las v\xE1lvulas","Que el refrigerante se congele","No hay peligro si el tanque est\xE1 al rev\xE9s"],respuesta_correcta:1,explicacion:"Cargar l\xEDquido por succi\xF3n debe hacerse con extrema precauci\xF3n (dosificando) o a trav\xE9s de un dispositivo de expansi\xF3n para evitar romper el compresor."},{id:"osha_37",categoria:"OSHA_PPE",pregunta:"En un sitio de construcci\xF3n, \xBFqu\xE9 color de cable est\xE1 prohibido usar para conductores de fase (Hot) seg\xFAn OSHA?",opciones:["Rojo","Negro","Verde o Blanco","Azul"],respuesta_correcta:2,explicacion:"El verde se reserva para tierra (EGC) y el blanco/gris para neutro. Usarlos como fase es una violaci\xF3n grave que causa choques por confusi\xF3n."},{id:"osha_38",categoria:"OSHA_PPE",pregunta:"Al usar guantes aislantes de goma, \xBFpor qu\xE9 es obligatorio usar el protector de cuero encima?",opciones:["Para que no se ensucien","Para proteger la goma contra pinchazos, cortes o abrasiones que anular\xEDan su capacidad diel\xE9ctrica","Para que el t\xE9cnico tenga mejor agarre","Porque OSHA lo dice por est\xE9tica"],respuesta_correcta:1,explicacion:"Un pinchazo microsc\xF3pico en la goma permite que miles de voltios pasen directamente a la mano."},{id:"osha_39",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 sucede con la ropa de algod\xF3n normal (No-FR) durante un evento de Arc Flash?",opciones:["Protege la piel","Se incendia y contin\xFAa ardiendo sobre el cuerpo, agravando severamente las quemaduras","Se evapora sin dejar rastro","Se vuelve aislante"],respuesta_correcta:1,explicacion:"La ropa que no es FR (Resistente al Fuego) act\xFAa como combustible en un arco el\xE9ctrico."},{id:"osha_40",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1l es la jerarqu\xEDa de controles de OSHA para eliminar peligros (del m\xE1s efectivo al menos)?",opciones:["EPP, Ingenier\xEDa, Eliminaci\xF3n","Eliminaci\xF3n, Sustituci\xF3n, Ingenier\xEDa, Administrativo, EPP","Administrativo, EPP, Sustituci\xF3n","Eliminaci\xF3n, EPP, Ingenier\xEDa"],respuesta_correcta:1,explicacion:"El EPP es siempre la \xFAltima l\xEDnea de defensa, no la primera."},{id:"osha_41",categoria:"OSHA_PPE",pregunta:"\xBFPor qu\xE9 es peligroso usar un cincel con la cabeza 'hongueada' (espachurrada por golpes)?",opciones:["No corta bien","Pedazos de metal pueden salir volando como metralla al ser golpeados","Pesa m\xE1s","Se ve mal ante el cliente"],respuesta_correcta:1,explicacion:"El metal fatigado se desprende violentamente bajo el impacto de un martillo."},{id:"osha_42",categoria:"OSHA_PPE",pregunta:"Antes de trabajar en la banda de un motor industrial, adem\xE1s de LOTO el\xE9ctrico, \xBFqu\xE9 seguridad mec\xE1nica es vital?",opciones:["Limpiar la banda","Bloquear f\xEDsicamente la rotaci\xF3n (chocking) para evitar que la carga mueva el motor","Ponerle aceite","Quitar el motor"],respuesta_correcta:1,explicacion:"La energ\xEDa mec\xE1nica almacenada (como ventiladores movidos por el viento o gravedad) puede causar amputaciones."},{id:"osha_43",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 altura m\xEDnima de ca\xEDda requiere protecci\xF3n en la industria general (1910) comparado con construcci\xF3n (1926)?",opciones:["6 pies en ambas","4 pies en industria general / 6 pies en construcci\xF3n","10 pies en ambas","2 pies en industria general"],respuesta_correcta:1,explicacion:"OSHA tiene est\xE1ndares m\xE1s estrictos para el mantenimiento industrial (4 pies) que para la construcci\xF3n (6 pies)."},{id:"osha_44",categoria:"OSHA_PPE",pregunta:"Un casco clase G (General) protege contra voltajes de hasta:",opciones:["250V","2,200V","20,000V","No protege contra electricidad"],respuesta_correcta:1,explicacion:"Clase G (2,200V); Clase E (20,000V); Clase C (Conductivo, no protege)."},{id:"osha_45",categoria:"OSHA_PPE",pregunta:"\xBFQui\xE9n debe pagar por el EPP (cascos, guantes, lentes) seg\xFAn la ley OSHA?",opciones:["El trabajador","El sindicato","El empleador (patr\xF3n)","El cliente"],respuesta_correcta:2,explicacion:"Es obligaci\xF3n legal del empleador proveer el equipo de seguridad necesario sin costo para el empleado (salvo excepciones muy raras)."},{id:"osha_46",categoria:"OSHA_PPE",pregunta:"Una herramienta neum\xE1tica debe tener qu\xE9 dispositivo de seguridad en la conexi\xF3n de la manguera?",opciones:["Cinta","Un clip o cable de seguridad (Whip check) para evitar que la manguera 'latiguee' si se suelta","Aceite","Un silenciador"],respuesta_correcta:1,explicacion:"Evita lesiones graves por el movimiento incontrolado de una manguera bajo presi\xF3n."},{id:"osha_47",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1l es el prop\xF3sito del 'Focus Four' de OSHA?",opciones:["Aprender a usar la c\xE1mara","Identificar las 4 causas principales de muerte: Ca\xEDdas, Electrocuci\xF3n, Atrapamiento y Golpeado por","Saber los 4 colores de seguridad","Las 4 horas de descanso"],respuesta_correcta:1,explicacion:"Estos cuatro peligros causan la gran mayor\xEDa de las fatalidades en construcci\xF3n."},{id:"osha_48",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1l es la vida \xFAtil promedio de un casco de seguridad de pl\xE1stico desde su fecha de fabricaci\xF3n?",opciones:["Toda la vida","2 a 5 a\xF1os (seg\xFAn el fabricante y exposici\xF3n)","20 a\xF1os","6 meses"],respuesta_correcta:1,explicacion:"El pl\xE1stico se degrada con el tiempo y los rayos UV, perdiendo resistencia al impacto."},{id:"osha_49",categoria:"OSHA_PPE",pregunta:"Un sistema de barandillas debe tener una altura de riel superior de:",opciones:["30 pulgadas","42 pulgadas (+/- 3 pulgadas)","60 pulgadas","24 pulgadas"],respuesta_correcta:1,explicacion:"Es la altura est\xE1ndar para evitar que el centro de gravedad de una persona pase por encima del riel."},{id:"osha_50",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 clase de extintor NO debe usarse en un incendio el\xE9ctrico?",opciones:["Clase C","Clase A de agua (Chorro de agua)","Agente limpio","CO2"],respuesta_correcta:1,explicacion:"El agua es conductora y puede electrocutar al bombero si el equipo est\xE1 energizado."},{id:"osha_51",categoria:"OSHA_PPE",pregunta:"\xBFQu\xE9 es una 'Violaci\xF3n Willful' (Intencional) de OSHA?",opciones:["Un accidente sin querer","Cuando el empleador ignora deliberadamente una norma de seguridad sabiendo que hay peligro","No usar casco un d\xEDa","Llegar tarde al trabajo"],respuesta_correcta:1,explicacion:"Son las violaciones con las multas m\xE1s altas y posibles cargos criminales."},{id:"osha_52",categoria:"OSHA_PPE",pregunta:"Un martillo con el mango rajado o suelto es:",opciones:["F\xE1cil de arreglar con pegamento","Una violaci\xF3n que exige retirar la herramienta de servicio inmediatamente","Seguro si se usa con cuidado","Mejor para el balance"],respuesta_correcta:1,explicacion:"La cabeza del martillo puede salir disparada, convirti\xE9ndose en un proyectil letal."},{id:"osha_53",categoria:"OSHA_PPE",pregunta:"\xBFQui\xE9n es responsable de inspeccionar el EPP antes de cada uso?",opciones:["El supervisor","El inspector de OSHA","El usuario (trabajador)","El fabricante"],respuesta_correcta:2,explicacion:"El trabajador es la \xFAltima l\xEDnea de defensa y debe asegurar que su equipo est\xE1 en condiciones \xF3ptimas."},{id:"osha_54",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1l es el riesgo de seguridad al apilar materiales de construcci\xF3n demasiado altos?",opciones:["Que se vean mal","Inestabilidad y colapso sobre los trabajadores","Que el cliente no los encuentre","No hay riesgo"],respuesta_correcta:1,explicacion:"El apilamiento requiere seguir l\xEDmites de altura y asegurar la base para evitar derrumbes."},{id:"osha_55",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1ndo debe usarse protecci\xF3n respiratoria con suministro de aire (SCBA)?",opciones:["En cualquier trabajo","En atm\xF3sferas IDLH (Inmediatamente Peligrosas para la Vida o la Salud) o con deficiencia de ox\xEDgeno","Cuando hay mucho polvo de madera","Para no oler el solvente"],respuesta_correcta:1,explicacion:"Los respiradores de cartucho no sirven en ambientes sin ox\xEDgeno o con altas concentraciones de gases t\xF3xicos."},{id:"osha_56",categoria:"OSHA_PPE",pregunta:"\xBFPor qu\xE9 un t\xE9cnico debe quitarse los anillos de metal antes de trabajar en un panel el\xE9ctrico?",opciones:["Para no rayar el panel","Para evitar quemaduras severas por contacto accidental o inducci\xF3n t\xE9rmica en caso de arco","Para que no se pierdan","No es necesario si usa guantes de tela"],respuesta_correcta:1,explicacion:"El metal del anillo puede fundirse con la piel en milisegundos durante un cortocircuito."},{id:"osha_57",categoria:"OSHA_PPE",pregunta:"Se permite usar una sierra circular cuya guarda de seguridad ha sido bloqueada hacia atr\xE1s para cortes r\xE1pidos:",opciones:["Si el t\xE9cnico tiene mucha experiencia","Nunca; es una violaci\xF3n de seguridad extremadamente peligrosa","Solo en cortes de madera blanda","Solo si se usa careta"],respuesta_correcta:1,explicacion:"Las guardas retractables est\xE1n ah\xED para proteger los dedos tras terminar el corte; bloquearlas causa miles de amputaciones al a\xF1o."},{id:"osha_58",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1ndo se deben retirar los escombros y basura inflamable de un sitio de trabajo?",opciones:["Al final del proyecto","Una vez al mes","A intervalos regulares y al final de cada turno","Solo si el inspector viene"],respuesta_correcta:2,explicacion:"La limpieza es fundamental para prevenir ca\xEDdas e incendios espont\xE1neos."},{id:"osha_59",categoria:"OSHA_PPE",pregunta:"Un t\xE9cnico usa un destornillador para probar si una bater\xEDa tiene carga haciendo un corto entre terminales. Esto es:",opciones:["Una prueba r\xE1pida aceptable","Un acto inseguro que puede causar la explosi\xF3n de la bater\xEDa y proyecci\xF3n de \xE1cido","Permitido en bater\xEDas peque\xF1as","Una t\xE9cnica avanzada de ACVOLT"],respuesta_correcta:1,explicacion:"Nunca se debe puentear una bater\xEDa; la corriente de cortocircuito es inmensa y peligrosa."},{id:"osha_60",categoria:"OSHA_PPE",pregunta:"Si un casco de seguridad tiene una rajadura peque\xF1a, \xBFse puede reparar con resina?",opciones:["S\xED, si queda fuerte","No; cualquier da\xF1o estructural anula la certificaci\xF3n y el casco debe ser destruido","Solo si la rajadura es por fuera","S\xED, con cinta Gorilla"],respuesta_correcta:1,explicacion:"Las reparaciones caseras no est\xE1n probadas y pueden fallar ante un impacto real."},{id:"osha_61",categoria:"OSHA_PPE",pregunta:"Si un t\xE9cnico se siente fatigado o enfermo, \xBFcu\xE1l es su responsabilidad de seguridad?",opciones:["Tomar mucho caf\xE9 y seguir","Informar al supervisor, ya que la fatiga reduce el tiempo de reacci\xF3n y aumenta el riesgo de errores fatales","No decir nada para que no lo manden a casa","Trabajar m\xE1s lento"],respuesta_correcta:1,explicacion:"El estado f\xEDsico y mental es un factor cr\xEDtico en la prevenci\xF3n de accidentes el\xE9ctricos e industriales."},{id:"osha_62",categoria:"OSHA_PPE",pregunta:"Al conducir un montacargas cargado en una rampa con pendiente ascendente, \xBFhacia d\xF3nde debe mirar la carga seg\xFAn OSHA?",opciones:["Hacia abajo de la rampa","Hacia arriba de la rampa (la carga siempre 'mira' hacia el cerro)","No importa si vas despacio","Hacia los lados"],respuesta_correcta:1,explicacion:"Por estabilidad, al subir o bajar rampas con carga, esta debe estar siempre orientada hacia la parte superior de la pendiente."},{id:"osha_63",categoria:"OSHA_PPE",pregunta:"\xBFCu\xE1l es el requisito de seguridad para una herramienta de impacto (como un cincel) que presenta una cabeza 'en hongo' (mushroomed)?",opciones:["Usarla con guantes m\xE1s gruesos","Esmerilar la cabeza para quitar el exceso de metal y darle forma original","Ponerle cinta aislante","No tiene soluci\xF3n, debe tirarse"],respuesta_correcta:1,explicacion:"El metal espachurrado puede desprenderse como proyectil. El mantenimiento preventivo permite corregir la forma antes de que sea peligroso."},{id:"osha_64",categoria:"OSHA_PPE",pregunta:"Una guarda de seguridad que ha sido removida para mantenimiento debe ser reinstalada:",opciones:["Al final de la semana","Antes de que el equipo sea puesto en marcha nuevamente tras el LOTO","Solo si el inspector de OSHA est\xE1 presente","Solo si el operador tiene miedo"],respuesta_correcta:1,explicacion:"Operar maquinaria sin guardas es una violaci\xF3n seria que causa amputaciones inmediatas."},{id:"osha_65",categoria:"OSHA_PPE",pregunta:"Si el nivel de ruido en un cuarto de m\xE1quinas es de 100 dB, \xBFcu\xE1nto tiempo puede estar un t\xE9cnico sin protecci\xF3n seg\xFAn OSHA?",opciones:["8 horas","2 horas","15 minutos","Toda la jornada"],respuesta_correcta:1,explicacion:"A medida que el nivel de ruido sube, el tiempo de exposici\xF3n permitido baja dr\xE1sticamente para evitar sordera."},{id:"osha_66",categoria:"OSHA_PPE",pregunta:"Al descargar materiales de un cami\xF3n, la zona debe estar:",opciones:["Abierta a todo el p\xFAblico","Acordonada y se\xF1alizada para evitar que personal no autorizado sea golpeado","Llena de trabajadores para acabar r\xE1pido","Sin iluminaci\xF3n"],respuesta_correcta:1,explicacion:"La ca\xEDda de objetos es una de las 4 principales causas de muerte (Focus Four) de OSHA."},{id:"osha_67",categoria:"OSHA_PPE",pregunta:"Un trabajador usa respirador purificador de aire motorizado (PAPR) con filtros P100. El filtro tiene 6 meses de uso. \xBFCu\xE1ndo debe cambiarse seg\xFAn OSHA?",opciones:["Cada 3 meses sin excepci\xF3n.","Cuando el flujo de aire disminuya o se da\xF1e.","Cada a\xF1o calendario.","Cuando el trabajador sienta olor o sabor."],respuesta_correcta:1,explicacion:"No hay tiempo fijo; se cambia por obstrucci\xF3n, da\xF1o, o seg\xFAn fabricante."},{id:"osha_68",categoria:"OSHA_PPE",pregunta:"Un trabajador usa gafas de seguridad con recubrimiento anti-rayadura. \xBFQu\xE9 producto de limpieza destruye este recubrimiento silenciosamente?",opciones:["Agua y jab\xF3n suave.","Limpiador de vidrios con amon\xEDaco.","Alcohol isoprop\xEDlico al 70%.","Pa\xF1o de microfibra seco."],respuesta_correcta:1,explicacion:"Amon\xEDaco ataca recubrimientos anti-rayadura y anti-empa\xF1ante."},{id:"osha_69",categoria:"OSHA_PPE",pregunta:"Un trabajador usa protecci\xF3n respiratoria N95 para soldadura de acero inoxidable. \xBFQu\xE9 peligro espec\xEDfico del acero inoxidable ignora el N95?",opciones:["Humos de n\xEDquel y cromo hexavalente (cancer\xEDgenos).","Ozono generado por el arco.","Part\xEDculas ultrafinas (< 0.1 micras).","Gases de protecci\xF3n (arg\xF3n)."],respuesta_correcta:0,explicacion:"Cromo hexavalente es cancer\xEDgeno; N95 no es suficiente, requiere P100 o suministro de aire."},{id:"osha_70",categoria:"OSHA_PPE",pregunta:"Un trabajador usa gafas de seguridad con ventilaci\xF3n directa. \xBFQu\xE9 riesgo de salpicadura qu\xEDmica persiste?",opciones:["L\xEDquidos pueden entrar por las ventilaciones superiores.","Las ventilaciones directas permiten entrada de salpicaduras laterales.","No hay riesgo, son seguras.","Solo protegen contra impacto, no qu\xEDmicos."],respuesta_correcta:1,explicacion:"Ventilaci\xF3n directa permite entrada de l\xEDquidos; para qu\xEDmicos se requiere ventilaci\xF3n indirecta."},{id:"osha_71",categoria:"OSHA_PPE",pregunta:"Un trabajador usa respirador de cara completa con filtros P100. \xBFQu\xE9 prueba de ajuste es v\xE1lida para este respirador?",opciones:["Prueba de ajuste cualitativa con sacarina.","Prueba de ajuste cuantitativa con generador de part\xEDculas.","Prueba de presi\xF3n negativa manual.","Ninguna, los respiradores de cara completa no requieren prueba."],respuesta_correcta:1,explicacion:"Respiradores de cara completa requieren prueba cuantitativa (PortaCount o similar)."},{id:"osha_72",categoria:"OSHA_PPE",pregunta:"Un trabajador usa protecci\xF3n auditiva tipo copa sobre una gorra de b\xE9isbol. \xBFCu\xE1l es la reducci\xF3n efectiva del NRR?",opciones:["La misma, la gorra no afecta.","Reducci\xF3n del 50% del NRR por interferencia.","Aumento del NRR por aislamiento adicional.","Nula, porque la gorra impide el sello."],respuesta_correcta:3,explicacion:"Gorra impide sello de las copas contra la cabeza, anulando la protecci\xF3n."},{id:"osha_73",categoria:"OSHA_PPE",pregunta:"Un trabajador usa guantes de butilo para manipular acetona. Despu\xE9s de 1 hora, los guantes est\xE1n intactos. \xBFSon seguros?",opciones:["S\xED, el butilo resiste acetona.","No, porque la acetona permea el butilo r\xE1pidamente.","S\xED, si son de 15 mil\xE9simas.","No, el butilo se disuelve en acetona."],respuesta_correcta:1,explicacion:"Acetona permea butilo en minutos; se requiere Viton o barrera laminada."},{id:"osha_74",categoria:"OSHA_PPE",pregunta:"Un trabajador usa respirador de media cara con cartuchos para vapores org\xE1nicos. \xBFCu\xE1nto tiempo duran los cartuchos en uso continuo?",opciones:["8 horas de trabajo.","Depende de la concentraci\xF3n del contaminante.","30 d\xEDas calendario.","Hasta que el trabajador sienta olor."],respuesta_correcta:1,explicacion:"La vida \xFAtil depende de concentraci\xF3n, humedad, y tasa de respiraci\xF3n; no hay tiempo fijo."},{id:"osha_75",categoria:"OSHA_PPE",pregunta:"Un trabajador usa casco de seguridad tipo II (impacto lateral). \xBFQu\xE9 ventaja tiene sobre tipo I en ca\xEDda de herramienta desde altura?",opciones:["Protege contra impacto vertical tambi\xE9n.","Protege contra impacto lateral si la herramienta golpea de lado.","No hay ventaja, ambos protegen igual.","Tipo II es m\xE1s liviano."],respuesta_correcta:1,explicacion:"Tipo I protege solo impacto vertical; Tipo II protege vertical y lateral."},{id:"osha_76",categoria:"OSHA_PPE",pregunta:"Un trabajador usa gafas de seguridad con lentes de policarbonato. \xBFQu\xE9 radiaci\xF3n UV bloquea naturalmente el policarbonato?",opciones:["100% UV hasta 380 nm.","Solo UVB.","Solo UVA.","Ninguna, requiere recubrimiento."],respuesta_correcta:0,explicacion:"Policarbonato bloquea 100% UV hasta 380 nm inherentemente, sin recubrimiento."},{id:"osha_77",categoria:"OSHA_PPE",pregunta:"Un trabajador usa respirador purificador de aire motorizado (PAPR) con filtro HE. \xBFQu\xE9 nivel de protecci\xF3n ofrece?",opciones:["APF 25.","APF 50.","APF 1000.","APF 10."],respuesta_correcta:2,explicacion:"PAPR con filtro HE tiene APF (factor de protecci\xF3n asignado) de 1000 seg\xFAn OSHA."},{id:"osha_78",categoria:"OSHA_PPE",pregunta:"Un trabajador usa protecci\xF3n facial tipo pantalla (face shield) con certificaci\xF3n ANSI Z87.1. \xBFProtege contra impacto de alta velocidad?",opciones:["S\xED, todas las pantallas certificadas protegen contra impacto.","No, la certificaci\xF3n puede ser solo para salpicaduras.","S\xED, si tiene marcado 'V' (impacto).","No, las pantallas no protegen contra impacto."],respuesta_correcta:2,explicacion:"ANSI Z87.1 requiere marcado 'V' para impacto; sin 'V', solo salpicaduras."},{id:"osha_79",categoria:"OSHA_PPE",pregunta:"Un trabajador usa guantes de nitrilo de 8 mil\xE9simas para manipular gasolina. \xBFCu\xE1nto tiempo de protecci\xF3n tienen?",opciones:["8 horas.","30 minutos a 1 hora.","24 horas.","No protegen contra gasolina."],respuesta_correcta:1,explicacion:"Gasolina permea nitrilo delgado en menos de 1 hora."},{id:"osha_80",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Al realizar una medici\xF3n de amperaje en un motor de 460V con una pinza de 'True RMS', el t\xE9cnico nota que el cable est\xE1 vibrando. \xBFCu\xE1l es el riesgo de seguridad m\xE1s probable?",opciones:["Falta de lubricaci\xF3n en los rodamientos","Arm\xF3nicos de alta frecuencia que pueden causar fatiga en el aislamiento y falla de arco","El motor est\xE1 girando demasiado r\xE1pido","Voltaje de control bajo"],respuesta_correcta:1,explicacion:"Las corrientes arm\xF3nicas en sistemas industriales causan vibraciones mec\xE1nicas en conductores y calor excesivo, aumentando el riesgo de fallas catastr\xF3ficas del aislamiento."},{id:"osha_81",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la distancia m\xE1xima permitida entre un recept\xE1culo de pared y un equipo de HVAC en una azotea comercial seg\xFAn el NEC/OSHA?",opciones:["50 pies","10 pies","25 pies","No hay l\xEDmite si es GFCI"],respuesta_correcta:2,explicacion:"NEC 210.63 exige un recept\xE1culo de servicio a no m\xE1s de 25 pies (7.5m) del equipo para evitar el uso de extensiones peligrosas en techos."},{id:"osha_82",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFPor qu\xE9 OSHA proh\xEDbe usar tuber\xEDas de gas met\xE1licas como electrodo de puesta a tierra principal?",opciones:["Porque el gas es aislante","Riesgo de explosi\xF3n si ocurre una falla a tierra y la corriente busca camino por la tuber\xEDa","Porque el metal es muy delgado","El NEC lo permite en edificios industriales (Falso)"],respuesta_correcta:1,explicacion:"La seguridad de vida proh\xEDbe usar tuber\xEDas de gas para disipar fallas el\xE9ctricas por el riesgo obvio de ignici\xF3n."},{id:"osha_83",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un transformador de control de 24V se quema repetidamente. El t\xE9cnico decide poner un fusible de mayor amperaje. \xBFQu\xE9 riesgo crea?",opciones:["Ninguno, el fusible es m\xE1s fuerte","Incendio del cableado del circuito de control al no abrir ante una sobrecarga real","El transformador enfriar\xE1 mejor","El termostato se da\xF1ar\xE1"],respuesta_correcta:1,explicacion:"Sobredimensionar fusibles elimina la protecci\xF3n t\xE9rmica, permitiendo que los conductores alcancen temperaturas de ignici\xF3n."},{id:"osha_84",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Si mides resistencia (Ohms) en un circuito energizado, \xBFqu\xE9 sucede con un mult\xEDmetro que no tiene protecci\xF3n de sobrecarga?",opciones:["Mide la resistencia correctamente","El mult\xEDmetro puede explotar o da\xF1arse internamente de forma permanente","La bater\xEDa del mult\xEDmetro se carga","Se quema el fusible del motor"],respuesta_correcta:1,explicacion:"Nunca se debe medir resistencia en circuitos vivos; la fuente externa de voltaje destruye el puente de medici\xF3n del \xF3hmetro."},{id:"osha_85",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"En un motor de 3 fases, si el desbalance de voltaje entre fases supera el 2%, el t\xE9cnico debe:",opciones:["Continuar operando","Desenergizar y corregir, ya que esto causar\xE1 un aumento dr\xE1stico en la temperatura del motor","Cambiar el capacitor de arranque","Bajar el breaker"],respuesta_correcta:1,explicacion:"Un desbalance de voltaje del 1% puede causar un desbalance de corriente del 6% al 10%, quemando los devanados."},{id:"osha_86",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Usar un probador de voltaje de tipo 'NVC' (sin contacto/l\xE1piz) como \xFAnica prueba de seguridad es:",opciones:["Recomendado por OSHA","Peligroso, ya que puede dar falsos negativos en cables blindados o con bajo voltaje","La forma m\xE1s r\xE1pida y segura","Obligatorio en niveles comerciales"],respuesta_correcta:1,explicacion:"Los probadores de proximidad fallan ante blindajes met\xE1licos. La verificaci\xF3n final siempre debe hacerse con un mult\xEDmetro de contacto."},{id:"osha_87",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la funci\xF3n del cable verde (EGC) en un equipo de aire acondicionado?",opciones:["Llevar la corriente de retorno","Proveer un camino de baja impedancia para disparar el breaker ante una falla a chasis","Aumentar el voltaje del motor","Reducir el ruido magn\xE9tico"],respuesta_correcta:1,explicacion:"La tierra no 'tira el voltaje al suelo', su funci\xF3n real es crear un cortocircuito intencional para que la protecci\xF3n abra el circuito r\xE1pidamente."},{id:"osha_88",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 sucede si el neutro y la tierra se unen (bonded) en un panel sub-alimentado (Sub-panel)?",opciones:["Es m\xE1s seguro","Corrientes de retorno circular\xE1n por las partes met\xE1licas y conductos del edificio","El voltaje sube a 240V","Se ahorra energ\xEDa"],respuesta_correcta:1,explicacion:"La uni\xF3n neutro-tierra solo debe ocurrir en el servicio principal. En sub-paneles causa corrientes peligrosas en las superficies met\xE1licas."},{id:"osha_89",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"El 'Skin Effect' en conductores industriales de gran calibre significa que:",opciones:["El cable se siente como piel","La corriente fluye principalmente cerca de la superficie del conductor","El aislamiento es de cuero","El cable es m\xE1s flexible"],respuesta_correcta:1,explicacion:"En CA, la corriente tiende a la periferia del cable. Esto afecta los c\xE1lculos de resistencia y temperatura en cables gruesos."},{id:"osha_90",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 clase de guantes de goma se requieren para trabajar en sistemas de 480V seg\xFAn OSHA?",opciones:["Clase 00 (hasta 500V)","Clase 0 (hasta 1000V)","Cualquier guante de cuero","Guantes de l\xE1tex quir\xFArgico"],respuesta_correcta:1,explicacion:"Aunque la Clase 00 llega a 500V, la norma industrial suele preferir Clase 0 por margen de seguridad en sistemas de 480V."},{id:"osha_91",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el riesgo de usar un martillo con mango de madera h\xFAmedo cerca de un tablero el\xE9ctrico?",opciones:["Que el martillo se pudra","La madera h\xFAmeda se vuelve conductora y puede causar un choque el\xE9ctrico","El martillo pesar\xE1 m\xE1s","No hay riesgo"],respuesta_correcta:1,explicacion:"La humedad elimina las propiedades aislantes de los materiales org\xE1nicos como la madera."},{id:"osha_92",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 sucede si conectas un capacitor de marcha (Run Capacitor) con un voltaje nominal menor al del circuito?",opciones:["Funciona mejor","El capacitor fallar\xE1 violentamente y puede explotar debido al estr\xE9s del diel\xE9ctrico","El motor consume menos energ\xEDa","No pasa nada"],respuesta_correcta:1,explicacion:"El voltaje del capacitor siempre debe ser igual o superior al voltaje m\xE1ximo que ver\xE1 en el circuito (considerando el Back-EMF del motor)."},{id:"osha_93",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el prop\xF3sito de un rel\xE9 de sobrecarga t\xE9rmico en un arrancador de motor?",opciones:["Proteger contra cortocircuitos","Proteger el motor contra sobrecalentamiento por exceso de corriente sostenida","Encender el motor","Medir el voltaje"],respuesta_correcta:1,explicacion:"A diferencia del breaker que protege el cable contra cortos, la sobrecarga protege los devanados del motor contra el calor."},{id:"osha_94",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el riesgo de dejar un conductor neutro 'flotando' (abierto) en un sistema de 120/240V?",opciones:["Las luces brillan m\xE1s","Voltajes desbalanceados que pueden destruir equipos y causar incendios","Ahorro de energ\xEDa","El breaker se dispara por seguridad"],respuesta_correcta:1,explicacion:"Un neutro abierto causa que las cargas de 120V se pongan en serie, elevando el voltaje en un lado hasta casi 240V."},{id:"osha_95",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 significa la sigla 'GFCI'?",opciones:["Ground Fault Circuit Interrupter","General Fault Control Instrument","Gravity Fall Control Insurance","Great Fire Control Item"],respuesta_correcta:0,explicacion:"Dispositivo dise\xF1ado para detectar fugas de corriente a tierra y cortar el flujo en milisegundos."},{id:"osha_96",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un t\xE9cnico encuentra que el voltaje entre Neutro y Tierra es de 50V CA. Esto indica:",opciones:["Un sistema muy limpio","Una falla grave o un neutro abierto/con alta resistencia","Que el sistema es de 480V","Que la tierra es de buena calidad"],respuesta_correcta:1,explicacion:"En un sistema sano, el voltaje N-G debe ser cercano a 0V. 50V indica una condici\xF3n peligrosa de corriente buscando camino."},{id:"osha_97",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la funci\xF3n de una 'Puesta a tierra de seguridad' temporal en trabajos de media tensi\xF3n?",opciones:["Hacer que el trabajo sea m\xE1s lento","Proteger al t\xE9cnico contra una reenergizaci\xF3n accidental creando un corto s\xF3lido","Mejorar la se\xF1al de radio","Para que no se roben el cable"],respuesta_correcta:1,explicacion:"Las tierras temporales aseguran que si alguien sube el breaker, el sistema drene la corriente y dispare la protecci\xF3n antes de llegar al t\xE9cnico."},{id:"osha_98",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 es un 'Meg\xF3hmetro' (Megger) y para qu\xE9 se usa en seguridad?",opciones:["Para medir Amperios","Para probar la integridad del aislamiento de los cables aplicando alto voltaje","Para ver si hay continuidad en un fusible","Para medir la humedad del aire"],respuesta_correcta:1,explicacion:"El Megger detecta micro-fisuras en el aislamiento que un mult\xEDmetro normal de 9V no ver\xEDa."},{id:"osha_99",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un motor 'Ground Out' (aterrizado) significa que:",opciones:["Est\xE1 bien conectado a tierra","Un devanado interno toc\xF3 la carcasa met\xE1lica","El motor es nuevo","No tiene neutro"],respuesta_correcta:1,explicacion:"Es una falla el\xE9ctrica donde el chasis del motor se energiza, representando un peligro de muerte."},{id:"osha_100",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 sucede si usas un mult\xEDmetro sin fusibles internos?",opciones:["Mide m\xE1s r\xE1pido","En caso de un pico de voltaje, el mult\xEDmetro puede explotar en tus manos","Ahorras dinero en repuestos","Es igual de seguro"],respuesta_correcta:1,explicacion:"Los fusibles HRC (High Rupture Capacity) en los mult\xEDmetros de calidad (CAT III/IV) son lo \xFAnico que evita una explosi\xF3n de arco dentro del aparato."},{id:"osha_101",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFPor qu\xE9 un t\xE9cnico nunca debe puentear (bypass) un interruptor de alta presi\xF3n en un sistema comercial de forma permanente?",opciones:["Porque el compresor gasta m\xE1s luz","Elimina la \xFAnica protecci\xF3n mec\xE1nica contra la explosi\xF3n del compresor por sobrepresi\xF3n","El termostato dejar\xE1 de funcionar","El ventilador del condensador se quemar\xE1"],respuesta_correcta:1,explicacion:"Los controles de seguridad protegen la integridad f\xEDsica del equipo y del personal circundante."},{id:"osha_102",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un compresor herm\xE9tico tiene una falla a tierra (short to ground). \xBFQu\xE9 riesgo existe al tocar la carcasa si el cable de tierra est\xE1 desconectado?",opciones:["Ninguno, el compresor est\xE1 aislado por aceite","Electrocuci\xF3n letal, ya que la carcasa est\xE1 al mismo potencial que la l\xEDnea viva","Solo un peque\xF1o cosquilleo","El compresor funcionar\xE1 m\xE1s lento"],respuesta_correcta:1,explicacion:"Sin una trayectoria de tierra efectiva, el t\xE9cnico se convierte en el camino de menor resistencia hacia el suelo."},{id:"osha_103",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"En un sistema trif\xE1sico, \xBFqu\xE9 dispositivo de seguridad evita que el motor gire en sentido contrario tras un cambio en la red el\xE9ctrica?",opciones:["Un breaker de 20A","Un monitor de fase (Phase Monitor)","Un termostato digital","Un transformador de 24V"],respuesta_correcta:1,explicacion:"El monitor de fase corta el control si detecta p\xE9rdida de fase, ca\xEDda de voltaje o reversi\xF3n de secuencia, protegiendo compresores scroll."},{id:"osha_104",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un acumulador de succi\xF3n est\xE1 cubierto de escarcha. \xBFQu\xE9 peligro de seguridad mec\xE1nica representa para el compresor?",opciones:["Que el compresor se congele por fuera","Retorno de l\xEDquido (slugging), que puede destruir las v\xE1lvulas y el cig\xFCe\xF1al del compresor","Que el aceite se vuelva muy ralo","No hay peligro, el fr\xEDo es bueno"],respuesta_correcta:1,explicacion:"Los compresores est\xE1n dise\xF1ados para bombear gas, no l\xEDquido. El l\xEDquido es incompresible y causa fallas mec\xE1nicas violentas."},{id:"osha_105",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Al revisar un condensador de marcha de 45 microfaradios, el mult\xEDmetro marca 'OL' en la escala de capacitancia. \xBFQu\xE9 indica?",opciones:["Que el capacitor est\xE1 perfecto","Circuito abierto o falla interna; el capacitor debe ser reemplazado","Que la bater\xEDa del mult\xEDmetro est\xE1 baja","Que el motor est\xE1 apagado"],respuesta_correcta:1,explicacion:"OL (Over Limit) en capacitancia suele indicar que el componente ya no almacena energ\xEDa."},{id:"osha_106",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"En un panel el\xE9ctrico comercial, \xBFqu\xE9 indica una etiqueta de color amarillo 'CAUTION'?",opciones:["Peligro de muerte inmediata","Posibles riesgos de seguridad que podr\xEDan resultar en lesiones menores o moderadas","Punto de reuni\xF3n","Ubicaci\xF3n del extintor"],respuesta_correcta:1,explicacion:"Amarillo es precauci\xF3n; Rojo es peligro/prohibici\xF3n; Naranja es advertencia de riesgo grave."},{id:"osha_107",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Si un contactor tiene los puntos 'picados' o carbonizados, \xBFqu\xE9 riesgo el\xE9ctrico comercial representa?",opciones:["Aumento de la resistencia, calor excesivo y posible soldadura de los contactos que impide que el equipo apague","El equipo consumir\xE1 menos Amperios","El motor girar\xE1 m\xE1s r\xE1pido","Se quemar\xE1 el termostato"],respuesta_correcta:0,explicacion:"Los contactos da\xF1ados generan calor y pueden quedar 'pegados', causando que el compresor no se detenga, lo que genera riesgos mec\xE1nicos."},{id:"osha_108",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 componente de seguridad protege a un t\xE9cnico de recibir una descarga desde el chasis de una manejadora de aire?",opciones:["El filtro de aire","El puente de uni\xF3n (Bonding Jumper) y el cable de tierra de seguridad","El aislamiento de los ductos","La pintura del equipo"],respuesta_correcta:1,explicacion:"La puesta a tierra asegura que el chasis se mantenga a potencial cero y dispare el breaker si hay una falla."},{id:"osha_109",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"La regla de la 'Mano Izquierda' (o trabajar con una sola mano) en paneles energizados busca:",opciones:["Que el t\xE9cnico se vea m\xE1s h\xE1bil","Evitar que la corriente pase a trav\xE9s del coraz\xF3n en caso de una descarga","No ensuciar el panel","Tener la otra mano lista para el celular"],respuesta_correcta:1,explicacion:"Al usar una sola mano, se evita cerrar el circuito de brazo a brazo, lo cual es letal."},{id:"osha_110",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 significa que un motor tenga protecci\xF3n 'T\xE9rmica Interna'?",opciones:["Que no necesita breaker","Que tiene un interruptor sensible al calor dentro de los devanados que abre el circuito si se sobrecalienta","Que calienta el agua","Que funciona solo en invierno"],respuesta_correcta:1,explicacion:"Es una defensa de \xFAltima instancia contra fallas de flujo de aire o sobrecargas mec\xE1nicas."},{id:"osha_111",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 sucede si se instala un fusible de 30A en un circuito dise\xF1ado para un m\xE1ximo de 15A?",opciones:["El equipo funciona mejor","El cable se incendiar\xE1 antes de que el fusible se funda ante una sobrecarga de 25A","Se ahorra dinero en fusibles","El voltaje sube"],respuesta_correcta:1,explicacion:"El fusible debe ser el eslab\xF3n m\xE1s d\xE9bil del circuito para proteger el cableado."},{id:"osha_112",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el peligro 'invisible' m\xE1s cr\xEDtico al trabajar con paneles solares durante el d\xEDa, incluso si el inversor est\xE1 apagado?",opciones:["El reflejo del sol","Los paneles son fuentes de energ\xEDa activa (Live) que no se pueden 'apagar' mientras haya luz solar","El peso de los m\xF3dulos","La est\xE1tica del marco"],respuesta_correcta:1,explicacion:"A diferencia de un motor, un arreglo fotovoltaico genera voltaje instant\xE1neamente con la luz. Los cables de DC est\xE1n energizados y pueden causar arcos mortales."},{id:"osha_113",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"En un sistema trif\xE1sico de 480V, \xBFqu\xE9 sucede si se intercambian dos de los tres cables de alimentaci\xF3n de un compresor Scroll?",opciones:["El compresor se quema instant\xE1neamente","El compresor girar\xE1 en reversa, lo que puede causar fallas mec\xE1nicas y falta de bombeo","No sucede nada en sistemas de CA","El breaker se dispara"],respuesta_correcta:1,explicacion:"Los compresores Scroll son direccionales. La rotaci\xF3n inversa impide la lubricaci\xF3n y compresi\xF3n, da\xF1ando el equipo r\xE1pidamente."},{id:"osha_114",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFPor qu\xE9 un arco el\xE9ctrico en Corriente Continua (DC) es m\xE1s persistente y peligroso que en CA?",opciones:["Porque la DC tiene m\xE1s amperios siempre","Porque la DC no pasa por 'cero' voltios, lo que impide que el arco se extinga naturalmente","Porque la DC es azul","Porque los cables son m\xE1s delgados"],respuesta_correcta:1,explicacion:"En CA, la onda pasa por cero 120 veces por segundo (60Hz), ayudando a romper el arco. En DC, el arco se mantiene hasta que la distancia o un interruptor lo extinga."},{id:"osha_115",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un sistema de 120V tiene una resistencia a tierra de 25 Ohms. Seg\xFAn la Ley de Ohm, si ocurre un corto a chasis, \xBFcu\xE1nta corriente fluir\xE1 por la tierra?",opciones:["120A","4.8A","10A","0.5A"],respuesta_correcta:1,explicacion:"I = V/R (120/25 = 4.8A). Esto es peligroso porque 4.8A no son suficientes para disparar un breaker de 15A o 20A, dejando el chasis energizado."},{id:"osha_116",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Al instalar paneles en un techo con una inclinaci\xF3n de 5:12, \xBFqu\xE9 medida de seguridad es obligatoria?",opciones:["Zapatos con suela de goma solamente","Sistema de detenci\xF3n de ca\xEDdas (arn\xE9s, l\xEDnea de vida y punto de anclaje)","Tener una red abajo","Solo trabajar cuando no haya viento"],respuesta_correcta:1,explicacion:"Cualquier trabajo en bordes desprotegidos a m\xE1s de 6 pies requiere protecci\xF3n activa contra ca\xEDdas."},{id:"osha_117",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Si un t\xE9cnico toca un cable de 120V con la mano h\xFAmeda en lugar de seca, \xBFqu\xE9 sucede con la descarga?",opciones:["Es igual","La intensidad de la corriente aumenta dr\xE1sticamente porque la resistencia de la piel baja","La corriente disminuye","El voltaje del cable baja"],respuesta_correcta:1,explicacion:"El agua reduce la resistencia \xF3hmica del cuerpo humano, permitiendo que pase m\xE1s amperaje por el coraz\xF3n."},{id:"osha_118",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Al conectar un aire acondicionado a un sistema solar Off-Grid, \xBFpor qu\xE9 es cr\xEDtico considerar la corriente de 'LRA' (Locked Rotor Amps)?",opciones:["Porque el aire no enfriar\xE1","Porque el pico de arranque puede sobrepasar la capacidad del inversor y causar un apagado de seguridad o da\xF1o","Porque el cable verde se calienta","No es importante en sistemas solares"],respuesta_correcta:1,explicacion:"Los inversores deben dimensionarse para el pico de arranque del compresor, que puede ser 5-6 veces la corriente nominal."},{id:"osha_119",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"En un banco de bater\xEDas de \xE1cido-plomo, \xBFqu\xE9 se debe agregar primero al mezclar electrolito?",opciones:["El \xE1cido al agua","El agua al \xE1cido","No importa el orden","Mezclarlos simult\xE1neamente"],respuesta_correcta:0,explicacion:"Regla: \xC1cido sobre Agua (A sobre A). Si agregas agua al \xE1cido, la reacci\xF3n exot\xE9rmica puede causar salpicaduras violentas de \xE1cido."},{id:"osha_120",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 es la 'Corriente de Fuga' en un equipo industrial?",opciones:["Corriente que se escapa por la ventana","Peque\xF1a cantidad de corriente que fluye a trav\xE9s del aislamiento hacia la tierra","Corriente que no se paga en la factura","Voltaje de control de 24V"],respuesta_correcta:1,explicacion:"Si la corriente de fuga aumenta, indica que el aislamiento del motor o cable est\xE1 fallando."},{id:"osha_121",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 significa un breaker de tipo 'AFCI'?",opciones:["Air Flow Circuit Interruptor","Arc Fault Circuit Interrupter","Amperage Flow Control Instrument","All Faults Circuit Inverter"],respuesta_correcta:1,explicacion:"A diferencia del GFCI (falla a tierra), el AFCI detecta arcos el\xE9ctricos peligrosos (chispas por cables sueltos) para prevenir incendios."},{id:"osha_122",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"En un sistema fotovoltaico, \xBFqu\xE9 componente se encarga de evitar que las bater\xEDas se sobrecarguen?",opciones:["El panel","El Controlador de Carga (Charge Controller)","El interruptor de pared","El mult\xEDmetro"],respuesta_correcta:1,explicacion:"Es un dispositivo de seguridad vital para evitar incendios o explosiones por sobrecarga t\xE9rmica de las bater\xEDas."},{id:"osha_123",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Est\xE1s midiendo un circuito de 480V con un mult\xEDmetro CAT II. \xBFCu\xE1l es el error?",opciones:["Ninguno, 480 es menor que 600","El mult\xEDmetro CAT II no est\xE1 dise\xF1ado para transitorios de nivel comercial/industrial; puede explotar","El color del mult\xEDmetro es incorrecto","La pantalla se ver\xE1 borrosa"],respuesta_correcta:1,explicacion:"CAT III o IV es obligatorio para paneles de distribuci\xF3n comercial. CAT II es para tomas residenciales."},{id:"osha_124",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"El t\xE9rmino 'Hot Leg' en un sistema de transformador 'Delta' con toma central (High-leg delta) se identifica con el color:",opciones:["Blanco","Naranja","Azul","Verde"],respuesta_correcta:1,explicacion:"El NEC exige que la fase con el voltaje m\xE1s alto a tierra (208V en un sistema de 240V) sea naranja."},{id:"osha_125",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFPor qu\xE9 los marcos de aluminio de los paneles solares deben estar conectados a tierra (bonded)?",opciones:["Para que no se oxiden","Para disipar cargas est\xE1ticas, rayos y asegurar que no se ionicen y den choques el\xE9ctricos","Para que pesen menos","No es necesario si el techo es de madera"],respuesta_correcta:1,explicacion:"El aluminio es excelente conductor; una falla en el aislamiento de un cable de 600V DC energizar\xEDa toda la estructura del techo."},{id:"osha_126",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 es un 'Short Circuit Current Rating' (SCCR)?",opciones:["El tama\xF1o del breaker","La cantidad m\xE1xima de corriente de falla que un componente puede soportar sin explotar o incendiarse","La longitud del cable","La velocidad del motor"],respuesta_correcta:1,explicacion:"Es vital en paneles industriales para asegurar que el equipo no se convierta en metralla durante una falla masiva."},{id:"osha_127",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un interruptor diferencial (GFCI) protege contra:",opciones:["Sobrecarga de amperaje","Choque el\xE9ctrico por falla a tierra","Rayos","Costo alto de electricidad"],respuesta_correcta:1,explicacion:"El GFCI detecta cuando la corriente no regresa por el neutro, asumiendo que est\xE1 pasando por una persona."},{id:"osha_128",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el riesgo de 'Fuga T\xE9rmica' (Thermal Runaway) en bater\xEDas de Litio-Ion?",opciones:["Que la bater\xEDa se enfr\xEDe","Una reacci\xF3n en cadena que genera calor incontrolable, fuego y emisi\xF3n de gases t\xF3xicos","Que la bater\xEDa dure m\xE1s a\xF1os","Que el voltaje baje a 0V"],respuesta_correcta:1,explicacion:"Es el fallo m\xE1s peligroso de las bater\xEDas modernas, dif\xEDcil de extinguir con agua normal."},{id:"osha_129",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"El 'Arco El\xE9ctrico' es principalmente un riesgo de:",opciones:["Envenenamiento","Quemaduras t\xE9rmicas severas, presi\xF3n explosiva y da\xF1o auditivo","Falta de luz","Radiaci\xF3n nuclear"],respuesta_correcta:1,explicacion:"Es una explosi\xF3n de plasma que puede proyectar metal fundido y generar ondas de choque."},{id:"osha_130",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"En un sistema fotovoltaico conectado a la red (Grid-Tied), \xBFqu\xE9 sucede durante un apag\xF3n de la ciudad?",opciones:["El sistema sigue funcionando igual","El inversor debe apagarse (Anti-Islanding) para no inyectar energ\xEDa a la red y electrocutar a los linieros","La casa explota","Los paneles dejan de producir voltaje"],respuesta_correcta:1,explicacion:"Es una funci\xF3n de seguridad obligatoria por ley para proteger a los trabajadores de la compa\xF1\xEDa el\xE9ctrica."},{id:"osha_131",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Si un motor trif\xE1sico zumba pero no arranca, lo primero que debe verificar un t\xE9cnico de ACVOLT es:",opciones:["Si el termostato tiene pilas","Si falta una de las fases (Single Phasing)","Si el filtro de aire est\xE1 sucio","Si el motor necesita pintura"],respuesta_correcta:1,explicacion:"La p\xE9rdida de una fase impide que el motor genere el campo magn\xE9tico rotativo necesario para el torque de arranque."},{id:"osha_132",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la frontera de aproximaci\xF3n limitada para un sistema de 480V seg\xFAn la NFPA 70E?",opciones:["1 pie","3 pies 6 pulgadas","10 pies","25 pies"],respuesta_correcta:1,explicacion:"Es la distancia m\xEDnima a la cual personal no calificado puede estar cerca de partes energizadas expuestas."},{id:"osha_133",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFPor qu\xE9 es peligroso dejar herramientas de metal sobre una bater\xEDa?",opciones:["Porque se rayan","Pueden causar un cortocircuito directo entre terminales, generando una explosi\xF3n de arco o fuego","Porque el \xE1cido las corroe","Porque la bater\xEDa se descarga lento"],respuesta_correcta:1,explicacion:"Las bater\xEDas tienen una corriente de cortocircuito alt\xEDsima; una llave inglesa puede fundirse instant\xE1neamente y causar quemaduras graves."},{id:"osha_134",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"El 'Efecto Joule' en un conductor el\xE9ctrico se refiere a:",opciones:["La luz que emite","El calor generado por la corriente al pasar por una resistencia","La fuerza magn\xE9tica","La capacidad de almacenar carga"],respuesta_correcta:1,explicacion:"Este calor es el que causa incendios cuando hay conexiones flojas (resistencia alta)."},{id:"osha_135",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 color representa el conductor Neutro en un sistema comercial de 277/480V?",opciones:["Blanco","Gris","Verde","Negro"],respuesta_correcta:1,explicacion:"El NEC permite blanco o gris; en la pr\xE1ctica industrial de 480V, el gris es el est\xE1ndar para diferenciarlo del sistema de 120V (blanco)."},{id:"osha_136",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la diferencia cr\xEDtica entre una 'Falla a Tierra' y un 'Arco El\xE9ctrico' en t\xE9rminos de EPP?",opciones:["Son lo mismo","La falla a tierra requiere guantes aislantes; el arco el\xE9ctrico requiere traje con clasificaci\xF3n cal\xF3rica (Arc Rated)","Solo se necesita casco para ambos","El arco el\xE9ctrico no requiere protecci\xF3n ocular"],respuesta_correcta:1,explicacion:"La falla a tierra es un choque el\xE9ctrico (corriente por el cuerpo); el arco el\xE9ctrico es una explosi\xF3n t\xE9rmica y de presi\xF3n."},{id:"osha_137",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Seg\xFAn OSHA, \xBFcu\xE1l es el voltaje m\xE1ximo al que se permite trabajar en equipo energizado 'expuesto' sin una barrera f\xEDsica o protecci\xF3n?",opciones:["120V","50V","24V","0V (Nunca se permite)"],respuesta_correcta:1,explicacion:"OSHA 1910.303 exige que las partes energizadas de 50 voltios o m\xE1s est\xE9n protegidas contra contacto accidental."},{id:"osha_138",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el prop\xF3sito de la 'Trayectoria de Corriente de Falla Efectiva'?",opciones:["Ahorrar cable","Crear un camino de baja impedancia para que la corriente de falla sea lo suficientemente alta como para disparar el breaker","Llevar la electricidad a la tierra f\xEDsica","Evitar el ruido en la radio"],respuesta_correcta:1,explicacion:"Si la resistencia es alta, la corriente de falla ser\xE1 baja y el breaker no se disparar\xE1, dejando el equipo energizado."},{id:"osha_139",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un t\xE9cnico usa un cable de extensi\xF3n donde falta la pata de tierra (circular). \xBFQu\xE9 riesgo corre seg\xFAn OSHA?",opciones:["Ninguno, si el equipo es de pl\xE1stico","El chasis met\xE1lico del equipo conectado no tiene camino de retorno en falla, causando un choque","El equipo gastar\xE1 m\xE1s luz","El cable se derretir\xE1"],respuesta_correcta:1,explicacion:"Quitar la pata de tierra anula la protecci\xF3n de seguridad contra fallas a chasis."},{id:"osha_140",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el nivel de corriente (Amperios) que generalmente causa fibrilaci\xF3n ventricular y muerte?",opciones:["10 Amperios","1 Amperio","100 a 200 miliamperios (0.1A - 0.2A)","10 miliamperios"],respuesta_correcta:2,explicacion:"Cantidades extremadamente peque\xF1as de corriente son suficientes para interrumpir el ritmo el\xE9ctrico del coraz\xF3n."},{id:"osha_141",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 significa 'GFCI de Clase A'?",opciones:["Que es para aviones","Que se dispara entre 4mA y 6mA","Que aguanta 1000 Amperios","Que es de color blanco"],respuesta_correcta:1,explicacion:"Es el est\xE1ndar para protecci\xF3n de personas. Niveles superiores son para protecci\xF3n de equipos (GFPE)."},{id:"osha_142",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 sucede si se usa un probador de voltaje sin clasificaci\xF3n de categor\xEDa (No-CAT) en un tablero de 480V?",opciones:["Mide bien el voltaje","El probador puede explotar debido a un arco interno si hay un pico de tensi\xF3n (transitorio)","La bater\xEDa dura m\xE1s","No pasa nada"],respuesta_correcta:1,explicacion:"Los equipos CAT III/IV tienen distancias internas y fusibles especiales para contener explosiones de arco."},{id:"osha_143",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"La 'Frontera de Arc Flash' es la distancia a la cual un t\xE9cnico recibir\xEDa una quemadura de:",opciones:["Primer grado","Segundo grado","Tercer grado","Muerte instant\xE1nea"],respuesta_correcta:1,explicacion:"Se define como 1.2 cal/cm\xB2, que es el umbral para una quemadura de segundo grado curable."},{id:"osha_144",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'System Grounding' (Puesta a tierra del sistema)?",opciones:["Proteger al t\xE9cnico","Limitar el voltaje impuesto por rayos o contacto con l\xEDneas de alta tensi\xF3n","Hacer que el motor sea m\xE1s eficiente","Ahorrar energ\xEDa"],respuesta_correcta:1,explicacion:"El aterrizaje del sistema (ej. neutro a tierra en el transformador) estabiliza el voltaje respecto a la tierra f\xEDsica."},{id:"osha_145",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Medir voltaje con un mult\xEDmetro puesto en la escala de Amperios resultar\xE1 en:",opciones:["Una lectura de 0V","Un cortocircuito interno y posible explosi\xF3n del mult\xEDmetro si no tiene protecci\xF3n HRC","Que el motor se apague","Medici\xF3n correcta de corriente"],respuesta_correcta:1,explicacion:"En escala de Amperios, el mult\xEDmetro tiene impedancia casi cero. Conectarlo a voltaje es crear un corto directo."},{id:"osha_146",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 es un 'Arco Errante' (Stray Arc)?",opciones:["Un arco que se perdi\xF3","Corriente de soldadura que fluye por caminos no deseados (como rodamientos o tuber\xEDas)","Un rayo","Electricidad est\xE1tica en la alfombra"],respuesta_correcta:1,explicacion:"Puede da\xF1ar maquinaria costosa o causar incendios en \xE1reas remotas del punto de trabajo."},{id:"osha_147",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un interruptor diferencial (GFCI) protege a una persona contra el choque el\xE9ctrico al suelo, pero NO protege contra:",opciones:["Contacto entre fase y neutro (el GFCI cree que es una carga normal)","Humedad","Bajo voltaje","Electricidad est\xE1tica"],respuesta_correcta:0,explicacion:"Si tocas ambos cables vivos (L y N), la corriente que sale por L regresa por N, y el GFCI no detecta desbalance."},{id:"osha_148",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 prenda de vestir est\xE1 prohibida para un electricista incluso bajo el traje de Arc Flash?",opciones:["Algod\xF3n","Lana","Joyas de metal (anillos, relojes)","Seda"],respuesta_correcta:2,explicacion:"El metal es conductor y puede causar quemaduras por inducci\xF3n o cortocircuitos accidentales."},{id:"osha_149",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el riesgo de un cable con aislamiento 'quemado' por el sol (UV damage)?",opciones:["Se ve feo","Grietas microsc\xF3picas que permiten fugas de corriente o cortocircuitos al mojarse","El cobre se vuelve m\xE1s resistente","No hay riesgo"],respuesta_correcta:1,explicacion:"El da\xF1o por UV degrada los pol\xEDmeros del aislamiento, eliminando su capacidad diel\xE9ctrica."},{id:"osha_150",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 es la 'Tensi\xF3n de Paso' (Step Voltage) cerca de un cable de alta tensi\xF3n ca\xEDdo?",opciones:["El voltaje del zapato","La diferencia de potencial entre los pies de una persona que camina cerca de la falla","La velocidad de la corriente","No existe"],respuesta_correcta:1,explicacion:"La corriente se disipa en c\xEDrculos; si tus pies est\xE1n en c\xEDrculos distintos, la electricidad pasa de un pie a otro a trav\xE9s de tus piernas."},{id:"osha_151",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Al trabajar en un panel de 600V, \xBFcu\xE1l es la 'Frontera de Aproximaci\xF3n Restringida'?",opciones:["Evitar el contacto","1 pie (0.3 metros)","3.5 pies","10 pies"],respuesta_correcta:1,explicacion:"Es la distancia donde el riesgo de arco o choque es inminente y requiere EPP completo."},{id:"osha_152",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 significa la sigla 'AHJ' en seguridad y c\xF3digos?",opciones:["All Hazards Joined","Authority Having Jurisdiction (Autoridad Competente/Inspector)","Always High Junction","Amperage High Joule"],respuesta_correcta:1,explicacion:"Es la persona o entidad encargada de aprobar instalaciones y asegurar el cumplimiento del c\xF3digo."},{id:"osha_153",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un interruptor autom\xE1tico (breaker) que huele a quemado pero no se ha disparado indica:",opciones:["Que est\xE1 trabajando bien","Una conexi\xF3n floja o falla interna que genera calor extremo (falla inminente)","Que necesita aire acondicionado","Que el pl\xE1stico es de mala calidad"],respuesta_correcta:1,explicacion:"El calor por resistencia es un precursor com\xFAn de incendios el\xE9ctricos."},{id:"osha_154",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Al trabajar en un panel trif\xE1sico, el t\xE9cnico nota que una barra (bus bar) est\xE1 decolorada (azulada/oscura). \xBFQu\xE9 significa?",opciones:["Que es una barra de lujo","Que ha sufrido un sobrecalentamiento severo por sobrecarga o mala conexi\xF3n","Que es de acero","Que el panel es viejo"],respuesta_correcta:1,explicacion:"La decoloraci\xF3n del metal indica que ha alcanzado temperaturas cr\xEDticas que afectan su conductividad y seguridad."},{id:"osha_155",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 exige OSHA antes de que un t\xE9cnico pueda trabajar cerca de partes energizadas que no han sido bloqueadas (LOTO)?",opciones:["Solo avisar al supervisor","Demostrar que desenergizar introduce peligros adicionales o es t\xE9cnica o operativamente imposible","Usar guantes de cuero","Cerrar los ojos"],respuesta_correcta:1,explicacion:"El trabajo energizado es la excepci\xF3n, no la regla. Debe justificarse por seguridad (ej. sistemas de soporte vital) o imposibilidad t\xE9cnica."},{id:"osha_156",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un tablero industrial tiene una etiqueta de Arc Flash que indica 'Energ\xEDa Incidente de 45 cal/cm\xB2'. \xBFQu\xE9 significa esto para el t\xE9cnico?",opciones:["Que puede usar un traje de nivel 4","Que NO se puede trabajar energizado porque supera el l\xEDmite de protecci\xF3n del equipo est\xE1ndar (40 cal/cm\xB2)","Que el panel est\xE1 fr\xEDo","Que solo necesita careta"],respuesta_correcta:1,explicacion:"Por encima de 40 cal/cm\xB2, la presi\xF3n de la explosi\xF3n (Arc Blast) es tan fuerte que el EPP no garantiza la supervivencia por trauma f\xEDsico."},{id:"osha_157",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 sucede si una canalizaci\xF3n met\xE1lica (EMT) se interrumpe por una caja de pl\xE1stico sin un puente de uni\xF3n (jumper)?",opciones:["El cable fluye mejor","Se pierde la trayectoria de tierra, dejando la tuber\xEDa met\xE1lica posterior energizada en caso de falla","Se ahorra dinero","Mejora el voltaje"],respuesta_correcta:1,explicacion:"La continuidad met\xE1lica es vital para que las protecciones el\xE9ctricas funcionen correctamente."},{id:"osha_158",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 clase de guantes de goma se requieren para trabajar en un sistema de 13,200V (Media Tensi\xF3n)?",opciones:["Clase 0","Clase 1","Clase 2 (hasta 17,000V)","Clase 00"],respuesta_correcta:2,explicacion:"La Clase 2 est\xE1 probada para un voltaje de uso m\xE1ximo de 17,000V AC."},{id:"osha_159",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Al trabajar en un techo inclinado con paneles solares, \xBFcu\xE1l es el peligro de una 'Falla de Arco de Serie' (Series Arc)?",opciones:["Que el sol brille m\xE1s","Un incendio en los conectores MC4 que no puede ser detectado por un breaker convencional","Que los paneles se rompan","Que el inversor se enfr\xEDe"],respuesta_correcta:1,explicacion:"Los arcos de serie ocurren cuando una conexi\xF3n se afloja; generan calor extremo y fuego sin disparar las protecciones de sobrecorriente."},{id:"osha_160",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'De-energized' (Desenergizado) seg\xFAn la normativa de seguridad?",opciones:["Apagar el interruptor","Desconectado de todas las fuentes de energ\xEDa y verificado mediante prueba de voltaje","Quitar los cables","Ponerle cinta al breaker"],respuesta_correcta:1,explicacion:"No est\xE1 realmente desenergizado hasta que se prueba que no hay voltaje presente."},{id:"osha_161",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFPor qu\xE9 OSHA proh\xEDbe el uso de cables de extensi\xF3n (cords) como sustituto del cableado permanente de un edificio?",opciones:["Porque son muy baratos","Porque no est\xE1n dise\xF1ados para soportar el calor sostenido y el estr\xE9s f\xEDsico del uso a largo plazo","Porque los colores son molestos","No est\xE1n prohibidos"],respuesta_correcta:1,explicacion:"Las extensiones son para uso temporal solamente; el uso prolongado degrada el aislamiento y causa incendios."},{id:"osha_162",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 componente de seguridad protege contra un choque el\xE9ctrico si un cable vivo toca la carcasa de un equipo que NO est\xE1 aterrizado?",opciones:["El breaker","El fusible","Ninguno, el chasis queda vivo hasta que alguien lo toca y cierra el circuito a tierra","El aislante del motor"],respuesta_correcta:2,explicacion:"Sin tierra de seguridad, las protecciones de sobrecorriente (breakers) no 'saben' que hay una falla."},{id:"osha_163",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un t\xE9cnico encuentra que el interruptor principal tiene un candado 'Maestro' que \xE9l no puede abrir. \xBFQu\xE9 debe hacer?",opciones:["Usar su propia llave para intentar abrirlo","Colocar su propio candado personal en una aldaba (hasp) multi-candado","Cortar el candado","Trabajar as\xED"],respuesta_correcta:1,explicacion:"Cada trabajador involucrado debe tener su propio candado personal en el punto de aislamiento."},{id:"osha_164",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"En un sistema industrial de 480V, \xBFcu\xE1l es el peligro de un 'Neutro Flotante'?",opciones:["Que el equipo consuma menos","Voltajes impredecibles que pueden elevarse hasta 480V en circuitos de 277V, quemando equipos y causando incendios","Ahorro de energ\xEDa","Que el motor gire m\xE1s r\xE1pido"],respuesta_correcta:1,explicacion:"La p\xE9rdida del neutro destruye la referencia de voltaje, creando condiciones peligrosas para el personal."},{id:"osha_165",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la causa principal de la presi\xF3n explosiva en un Arc Blast?",opciones:["El aire fr\xEDo","La expansi\xF3n instant\xE1nea del metal (cobre) al vaporizarse (hasta 67,000 veces su volumen original)","El ruido","La gravedad"],respuesta_correcta:1,explicacion:"El metal s\xF3lido se convierte en gas instant\xE1neamente, creando una onda de choque mec\xE1nica destructiva."},{id:"osha_166",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la diferencia entre un 'Grounded Conductor' y un 'Grounding Conductor'?",opciones:["Son lo mismo","El 'Grounded' es el neutro (blanco); el 'Grounding' es el cable de tierra de seguridad (verde)","El 'Grounded' es el vivo","Uno es de pl\xE1stico y otro de cobre"],respuesta_correcta:1,explicacion:"Es terminolog\xEDa cr\xEDtica del NEC/OSHA para evitar conexiones err\xF3neas que energicen chasis met\xE1licos."},{id:"osha_167",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFA qu\xE9 voltaje se considera que un sistema es 'Alta Tensi\xF3n' para efectos de entrenamiento especializado?",opciones:["120V","600V o m\xE1s","240V","480V"],respuesta_correcta:1,explicacion:"Por encima de 600V (o 1000V en normativas nuevas), los riesgos de arco a trav\xE9s del aire y las distancias de seguridad cambian dr\xE1sticamente."},{id:"osha_168",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Si un cable de alimentaci\xF3n tiene el aislamiento agrietado pero el cobre no se ve, \xBFes seguro usarlo?",opciones:["S\xED, no hay peligro","No; OSHA proh\xEDbe el uso de cables da\xF1ados, ya que la humedad o el contacto pueden causar una falla","Solo si se envuelve en cinta de papel","Solo en interiores"],respuesta_correcta:1,explicacion:"El aislamiento agrietado no garantiza la rigidez diel\xE9ctrica necesaria para proteger al t\xE9cnico."},{id:"osha_169",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la funci\xF3n de una careta (Face Shield) con clasificaci\xF3n 'Arc Rated'?",opciones:["Para que no le pegue el sol","Proteger contra el calor radiante y los desechos de un arco el\xE9ctrico","Sustituir a los lentes de seguridad","Para que no le vean la cara"],respuesta_correcta:1,explicacion:"Debe usarse junto con lentes de seguridad para proteger la vista y la piel de quemaduras t\xE9rmicas."},{id:"osha_170",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFPor qu\xE9 es m\xE1s peligrosa la Corriente Alterna (60Hz) que la Continua en t\xE9rminos de choque al coraz\xF3n?",opciones:["Porque tiene m\xE1s amperios","Porque la frecuencia de 60Hz interfiere directamente con el ritmo card\xEDaco (fibrilaci\xF3n)","Porque la CA es m\xE1s r\xE1pida","No es m\xE1s peligrosa"],respuesta_correcta:1,explicacion:"La frecuencia de la red el\xE9ctrica comercial es casi id\xE9ntica a la frecuencia de los impulsos nerviosos del coraz\xF3n."},{id:"osha_171",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un mult\xEDmetro con la pantalla rota pero que a\xFAn mide debe:",opciones:["Usarse con cuidado","Ser retirado de servicio, ya que la integridad f\xEDsica del aparato es parte de su rating de seguridad","Pegarse con cinta","Usarse solo en 24V"],respuesta_correcta:1,explicacion:"Una fisura en la carcasa o pantalla puede permitir que un arco el\xE9ctrico entre al aparato y explote en las manos del t\xE9cnico."},{id:"osha_172",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un transformador de 480V tiene un ruido met\xE1lico interno (chattering). Antes de abrirlo, \xBFqu\xE9 riesgo de seguridad mec\xE1nica existe adem\xE1s del el\xE9ctrico?",opciones:["Que el aceite est\xE9 fr\xEDo","Fuerzas electromagn\xE9ticas que pueden causar que las l\xE1minas del n\xFAcleo salgan proyectadas si fallan los pernos","Que el transformador se apague solo","Ninguno"],respuesta_correcta:1,explicacion:"En fallas severas, las fuerzas magn\xE9ticas pueden ser tan intensas que destruyen f\xEDsicamente la estructura del equipo."},{id:"osha_173",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Si un t\xE9cnico usa un mult\xEDmetro para medir voltaje y este 'explota' debido a un arco interno, \xBFcu\xE1l fue la causa m\xE1s probable de seguridad?",opciones:["Puntas de prueba mal conectadas o mult\xEDmetro con categor\xEDa (CAT) insuficiente para los transitorios del sistema","La bater\xEDa del mult\xEDmetro era vieja","El t\xE9cnico ten\xEDa las manos sucias","El cable era muy largo"],respuesta_correcta:0,explicacion:"Los picos de voltaje (transitorios) pueden saltar entre las pistas del mult\xEDmetro si no tiene la protecci\xF3n CAT III/IV y fusibles HRC adecuados."},{id:"osha_174",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 se debe usar para limpiar un panel el\xE9ctrico seg\xFAn la norma de seguridad?",opciones:["Agua y jab\xF3n","Aire comprimido a baja presi\xF3n y solventes aprobados no-conductores (Dielectric cleaners)","Un trapo h\xFAmedo","Una escoba de metal"],respuesta_correcta:1,explicacion:"Los solventes diel\xE9ctricos aseguran que no se creen puentes de conducci\xF3n accidental entre fases."},{id:"osha_175",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 es un 'Grounded Loop' (Lazo de tierra) y por qu\xE9 es un riesgo de seguridad industrial?",opciones:["Un cable circular","Conexiones de tierra redundantes que crean corrientes circulantes peligrosas e interfieren con protecciones","Una buena se\xF1al de radio","No es un riesgo"],respuesta_correcta:1,explicacion:"Los lazos de tierra pueden causar que las superficies met\xE1licas tengan voltajes par\xE1sitos peligrosos."},{id:"osha_176",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFC\xF3mo se debe probar un guante aislante de goma antes de empezar el trabajo (Field Test)?",opciones:["Mir\xE1ndolo a la luz","Infl\xE1ndolo con aire (Air test) para buscar fugas microsc\xF3picas o pinchazos","Estir\xE1ndolo con fuerza","Sumergi\xE9ndolo en aceite"],respuesta_correcta:1,explicacion:"Incluso un pinchazo del tama\xF1o de un alfiler permite que la corriente pase al t\xE9cnico."},{id:"osha_177",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es el peligro de la 'Inducci\xF3n Electromagn\xE9tica' al trabajar en cables desenergizados que corren paralelos a cables de alta tensi\xF3n?",opciones:["Que los cables se atraigan como imanes","El cable 'apagado' puede cargarse con un voltaje letal por inducci\xF3n del cable energizado cercano","Que el cable se caliente","Ninguno"],respuesta_correcta:1,explicacion:"La inducci\xF3n puede matar a un t\xE9cnico que cree que el cable es seguro solo porque el breaker est\xE1 abierto."},{id:"osha_178",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un condensador (capacitor) electrol\xEDtico que est\xE1 'hinchado' o deformado indica:",opciones:["Que tiene mucha energ\xEDa acumulada","Falla interna inminente y riesgo de explosi\xF3n violenta por acumulaci\xF3n de gas","Que es de mejor calidad","Que el motor est\xE1 fr\xEDo"],respuesta_correcta:1,explicacion:"La deformaci\xF3n f\xEDsica es se\xF1al de que la presi\xF3n interna ha superado los l\xEDmites de seguridad."},{id:"osha_179",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFCu\xE1l es la diferencia entre un cable de tierra de seguridad y el 'Grounded Conductor' (Neutro)?",opciones:["Son el mismo cable","El neutro lleva corriente en condiciones normales; la tierra solo lleva corriente durante una falla","La tierra es de color rojo","El neutro es de cobre desnudo"],respuesta_correcta:1,explicacion:"Confundirlos crea condiciones donde el chasis de los equipos puede quedar energizado permanentemente."},{id:"osha_180",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"\xBFQu\xE9 es un 'Interlock' de seguridad en un panel industrial?",opciones:["Un candado de llave","Un dispositivo que corta la energ\xEDa autom\xE1ticamente si se abre la puerta del gabinete","Una marca de interruptor","Un cable m\xE1s grueso"],respuesta_correcta:1,explicacion:"Los interlocks previenen el acceso accidental a partes energizadas de alto riesgo."},{id:"osha_181",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un t\xE9cnico calificado debe realizar un 'An\xE1lisis de Peligro de Choque' para determinar:",opciones:["Cu\xE1nto va a cobrar","El voltaje del sistema, las fronteras de aproximaci\xF3n y el EPP necesario","Si el cliente es amable","La marca del panel"],respuesta_correcta:1,explicacion:"Este an\xE1lisis es obligatorio antes de realizar cualquier tarea cerca de circuitos energizados."},{id:"osha_182",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un cable de media tensi\xF3n de 15 kV tiene una pantalla semiconductora da\xF1ada en un tramo de 10 cm. \xBFQu\xE9 fen\xF3meno ocurrir\xE1 al energizar?",opciones:["Descarga parcial superficial.","Arco trif\xE1sico inmediato.","Calentamiento resistivo.","No pasa nada, la pantalla es solo mec\xE1nica."],respuesta_correcta:0,explicacion:"Da\xF1o en pantalla semiconductora causa concentraci\xF3n de campo el\xE9ctrico y descargas parciales."},{id:"osha_183",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un banco de capacitores de 13.8 kV tiene reactores de limitaci\xF3n de corriente. \xBFQu\xE9 falla hace que los reactores sean in\xFAtiles?",opciones:["Cortocircuito en los propios reactores.","Falla a tierra en el neutro.","Sobretensi\xF3n por ferroresonancia.","Saturaci\xF3n magn\xE9tica por DC offset."],respuesta_correcta:3,explicacion:"Saturaci\xF3n por componente DC elimina la inductancia, anulando la limitaci\xF3n de corriente."},{id:"osha_184",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un motor de 400 HP tiene una protecci\xF3n de sobrecarga t\xE9rmica ajustada a 1.15 x In. El motor opera a 1.1 x In continuo. \xBFEs seguro?",opciones:["S\xED, porque est\xE1 dentro del factor de servicio.","No, porque el calentamiento puede da\xF1ar el aislamiento a largo plazo.","S\xED, si el motor es clase F.","No, porque la protecci\xF3n no permite operaci\xF3n continua sobre In."],respuesta_correcta:1,explicacion:"Factor de servicio 1.15 permite sobrecarga ocasional, no continua; reduce vida \xFAtil del aislamiento."},{id:"osha_185",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un transformador de 2500 kVA tiene una prueba de relaci\xF3n de vueltas (TTR) que muestra 1% de error. \xBFEs aceptable?",opciones:["S\xED, 1% est\xE1 dentro de tolerancia.","No, la tolerancia m\xE1xima es 0.5%.","S\xED, si el transformador es de distribuci\xF3n.","No, porque puede indicar espiras en corto."],respuesta_correcta:3,explicacion:"1% de error en TTR sugiere espiras en cortocircuito en el devanado."},{id:"osha_186",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un motor de inducci\xF3n de 100 HP tiene una corriente de vac\xEDo de 30 A. La corriente a plena carga es 120 A. \xBFQu\xE9 indica una corriente de vac\xEDo de 50 A?",opciones:["Rodamientos desgastados.","Espiras en cortocircuito en el estator.","Bajo voltaje de alimentaci\xF3n.","Exceso de entrehierro."],respuesta_correcta:1,explicacion:"Alta corriente de vac\xEDo indica espiras en corto o problemas magn\xE9ticos en el n\xFAcleo."},{id:"osha_187",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un interruptor de alta tensi\xF3n SF6 tiene una presi\xF3n de gas de 6 bar. El man\xF3metro marca 5.5 bar. \xBFQu\xE9 indica?",opciones:["Fuga de SF6.","Temperatura ambiente baja.","Sobrecarga del interruptor.","Normal, variaci\xF3n permitida."],respuesta_correcta:0,explicacion:"Ca\xEDda de presi\xF3n SF6 indica fuga; riesgo de p\xE9rdida de capacidad de extinci\xF3n de arco."},{id:"osha_188",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un generador di\xE9sel de 1000 kVA tiene una corriente de excitaci\xF3n de 300 A DC. El puente rectificador tiene un diodo abierto. \xBFQu\xE9 efecto tiene en el voltaje de salida?",opciones:["Ca\xEDda del 50% del voltaje.","Ondulaci\xF3n excesiva y posible saturaci\xF3n.","Aumento del voltaje por compensaci\xF3n.","No afecta porque el regulador compensa."],respuesta_correcta:1,explicacion:"Diodo abierto causa rectificaci\xF3n de media onda, aumentando ripple y calentamiento del rotor."},{id:"osha_189",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un motor de 200 HP tiene una protecci\xF3n diferencial (87) que dispara. \xBFQu\xE9 falla interna indica?",opciones:["Falla a tierra externa.","Cortocircuito entre fases en el estator.","Sobrecarga t\xE9rmica.","P\xE9rdida de una fase."],respuesta_correcta:1,explicacion:"Protecci\xF3n diferencial compara corriente de entrada y salida; dispara por falla interna en el motor."},{id:"osha_190",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un transformador de corriente (TC) tiene su secundario en cortocircuito permanente. \xBFEs seguro?",opciones:["S\xED, los TC deben operar con secundario en corto.","No, el corto permanente puede da\xF1ar el TC.","S\xED, si la carga es menor a 5 VA.","No, porque el TC se satura."],respuesta_correcta:0,explicacion:"TC debe operar con secundario en corto (o con carga); secundario abierto es peligroso."},{id:"osha_191",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un motor de 500 HP tiene una corriente de arranque de 3000 A. El interruptor general tiene capacidad de 2000 A. \xBFQu\xE9 ocurre al arrancar?",opciones:["El interruptor dispara por sobrecorriente.","El motor arranca normalmente.","El interruptor se da\xF1a por arco.","El motor no arranca."],respuesta_correcta:0,explicacion:"Corriente de arranque (3000 A) excede capacidad del interruptor (2000 A), causando disparo."},{id:"osha_192",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un capacitor de potencia de 480V tiene una resistencia de descarga de 100 k\u03A9. El capacitor es de 100 \u03BCF. \xBFCu\xE1nto tiempo tarda en descargar a 50V?",opciones:["5 segundos.","50 segundos.","115 segundos (5 x R x C = 5 x 100k x 100\u03BCF = 50,000 \u03BCF? c\xE1lculo).","Depende del voltaje inicial."],respuesta_correcta:2,explicacion:"Tiempo = 5 x R x C = 5 x 100,000 x 0.0001 = 50 segundos."},{id:"osha_193",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un motor de inducci\xF3n de 75 HP tiene un desbalance de corriente entre fases del 8%. \xBFQu\xE9 acci\xF3n es necesaria?",opciones:["Ninguna, 8% est\xE1 dentro de tolerancia.","Investigar causa; puede indicar falla de aislamiento.","Reducir la carga a 50%.","Reemplazar el motor inmediatamente."],respuesta_correcta:1,explicacion:"Desbalance > 5% indica problema en motor o alimentaci\xF3n."},{id:"osha_194",categoria:"OSHA_RIESGO_ELECTRICO",pregunta:"Un transformador de 500 kVA tiene aceite con gas etileno > 500 ppm. \xBFQu\xE9 indica?",opciones:["Sobrecarga t\xE9rmica del papel aislante.","Arco el\xE9ctrico interno.","Oxidaci\xF3n normal del aceite.","Contaminaci\xF3n por humedad."],respuesta_correcta:0,explicacion:"Etileno indica calentamiento del papel aislante (> 150\xB0C)."},{id:"osha_195",categoria:"OSHA_CAIDAS",pregunta:"\xBFCu\xE1l es la fuerza m\xE1xima de detenci\xF3n que un arn\xE9s de cuerpo completo debe permitir sobre el trabajador seg\xFAn OSHA?",opciones:["900 lbs","1800 lbs","3000 lbs","5000 lbs"],respuesta_correcta:1,explicacion:"OSHA limita la fuerza de impacto a 1800 lbs para minimizar lesiones internas durante la ca\xEDda."},{id:"osha_196",categoria:"OSHA_CAIDAS",pregunta:"Un andamio debe ser capaz de soportar su propio peso y al menos cuantas veces la carga m\xE1xima prevista:",opciones:["2 veces","4 veces","6 veces","10 veces"],respuesta_correcta:1,explicacion:"Regla del factor de seguridad 4:1 de OSHA para plataformas y andamios."},{id:"osha_197",categoria:"OSHA_CAIDAS",pregunta:"Las barandillas de seguridad deben resistir una fuerza de:",opciones:["50 lbs","100 lbs","200 lbs","500 lbs"],respuesta_correcta:2,explicacion:"OSHA exige que el riel superior soporte 200 libras de fuerza aplicada en cualquier direcci\xF3n hacia abajo o hacia afuera."},{id:"osha_198",categoria:"OSHA_CAIDAS",pregunta:"Las \xE1reas de trabajo deben mantenerse limpias de escombros y clavos para evitar:",opciones:["Que el cliente se enoje","Punciones, tropiezos e incendios","Que el inspector cobre m\xE1s","Que se pierdan las herramientas"],respuesta_correcta:1,explicacion:"El 'housekeeping' es la base de la prevenci\xF3n de accidentes en construcci\xF3n."},{id:"osha_199",categoria:"OSHA_CAIDAS",pregunta:"\xBFA qu\xE9 altura debe estar el riel medio (mid-rail) de un andamio?",opciones:["10 pulgadas","Aproximadamente a la mitad entre la plataforma y el riel superior (21 pulgadas)","A 42 pulgadas","No se requiere riel medio"],respuesta_correcta:1,explicacion:"Sirve para evitar que un trabajador se deslice por debajo del riel superior si se cae."},{id:"osha_200",categoria:"OSHA_CAIDAS",pregunta:"Se permite el uso de mangueras de manifold que tengan grietas superficiales si:",opciones:["Se envuelven en cinta el\xE9ctrica","No se permite; deben reemplazarse para evitar rupturas bajo alta presi\xF3n","Solo se usan en el lado de baja","Si la fuga es peque\xF1a"],respuesta_correcta:1,explicacion:"Las mangueras de refrigeraci\xF3n soportan cientos de psi; cualquier defecto estructural es un riesgo de proyectil o quemadura."},{id:"osha_201",categoria:"OSHA_CAIDAS",pregunta:"Al izar un condensador con una gr\xFAa, \xBFqui\xE9n tiene la autoridad para dar la se\xF1al de parada de emergencia (Stop)?",opciones:["Solo el operador de la gr\xFAa","Solo el supervisor","Cualquier persona que vea un peligro","Nadie, una vez que sube no se detiene"],respuesta_correcta:2,explicacion:"Cualquier trabajador en el sitio tiene la autoridad y obligaci\xF3n de detener una maniobra si detecta un riesgo."},{id:"osha_202",categoria:"OSHA_CAIDAS",pregunta:"Una l\xEDnea de vida (Lanyard) con absorbedor de choque debe usarse solo si hay una distancia de ca\xEDda libre de al menos:",opciones:["6 pies","18.5 pies (considerando elongaci\xF3n, altura del trabajador y margen de seguridad)","2 pies","50 pies"],respuesta_correcta:1,explicacion:"Si la ca\xEDda es corta, el absorbedor no llegar\xE1 a desplegarse antes de que el trabajador golpee el suelo."},{id:"osha_203",categoria:"OSHA_CAIDAS",pregunta:"\xBFQu\xE9 distancia m\xEDnima debe haber entre una toma de agua y un panel el\xE9ctrico?",opciones:["1 pie","3 pies","6 pies","No hay distancia si el panel es NEMA 3R"],respuesta_correcta:1,explicacion:"Aunque el c\xF3digo var\xEDa, 3 pies es la distancia de seguridad est\xE1ndar para evitar salpicaduras accidentales en equipo vivo."},{id:"osha_204",categoria:"OSHA_CAIDAS",pregunta:"Un grillete (shackle) con el pin sustituido por un tornillo com\xFAn es:",opciones:["Una reparaci\xF3n ingeniosa","Extremadamente peligroso y prohibido por OSHA (el tornillo fallar\xE1 bajo carga)","Permitido si el tornillo es de acero inoxidable","Seguro para cargas ligeras"],respuesta_correcta:1,explicacion:"Los componentes de izaje deben estar certificados; un tornillo com\xFAn no tiene la resistencia al corte necesaria."},{id:"osha_205",categoria:"OSHA_CAIDAS",pregunta:"Al mover un andamio rodante, los trabajadores:",opciones:["Pueden quedarse arriba si se agarran fuerte","Deben bajar antes de que el andamio sea movido","Pueden ayudar a empujar desde arriba","Deben saltar al suelo"],respuesta_correcta:1,explicacion:"Mover un andamio con personas arriba es una de las causas m\xE1s comunes de vuelcos fatales."},{id:"osha_206",categoria:"OSHA_CAIDAS",pregunta:"\xBFQu\xE9 componente de un andamio evita que las herramientas caigan y golpeen a alguien abajo?",opciones:["La barandilla","El rodapi\xE9 (Toe-board)","La red de seguridad","El arn\xE9s"],respuesta_correcta:1,explicacion:"Los rodapi\xE9s son obligatorios cuando hay personal trabajando o transitando debajo del andamio."},{id:"osha_207",categoria:"OSHA_CAIDAS",pregunta:"Si hay m\xE1s de 20 trabajadores en una obra, \xBFqu\xE9 exige OSHA respecto a las escaleras?",opciones:["Que sean de oro","Que haya escaleras separadas para subir y bajar o doble ancho","Que cada trabajador tenga su propia escalera","No hay requisito extra"],respuesta_correcta:1,explicacion:"Busca evitar aglomeraciones y accidentes en puntos de acceso cr\xEDticos."},{id:"osha_208",categoria:"OSHA_CAIDAS",pregunta:"Durante una maniobra de izaje, \xBFqu\xE9 es un 'Punto de pellizco' (Pinch point)?",opciones:["Donde el t\xE9cnico se rasca","Cualquier punto donde una parte del cuerpo puede quedar atrapada entre piezas m\xF3viles o fijas","El gancho de la gr\xFAa","El peso de la carga"],respuesta_correcta:1,explicacion:"Identificar pinch points es clave para evitar aplastamientos y amputaciones."},{id:"osha_209",categoria:"OSHA_CAIDAS",pregunta:"En andamios, \xBFqu\xE9 es un 'Trabajador Calificado'?",opciones:["El que tiene m\xE1s a\xF1os de trabajo","Alguien que por posesi\xF3n de un t\xEDtulo o certificado profesional ha demostrado resolver problemas relacionados con la materia","El due\xF1o","El que no tiene miedo"],respuesta_correcta:1,explicacion:"La calificaci\xF3n se basa en conocimiento demostrado y certificaciones."},{id:"osha_210",categoria:"OSHA_CAIDAS",pregunta:"OSHA exige barandales en escaleras que tengan cu\xE1ntos elevadores (escalones) o m\xE1s?",opciones:["2","4","10","15"],respuesta_correcta:1,explicacion:"Escaleras con 4 o m\xE1s escalones deben tener al menos un pasamanos."},{id:"osha_211",categoria:"OSHA_CAIDAS",pregunta:"Al usar un sistema de 'L\xEDnea de Advertencia' en un techo plano comercial, \xBFa qu\xE9 distancia del borde debe colocarse la l\xEDnea seg\xFAn OSHA?",opciones:["2 pies","6 pies","10 pies","15 pies"],respuesta_correcta:1,explicacion:"Para trabajos de techado, la l\xEDnea de advertencia debe estar a 6 pies del borde desprotegido."},{id:"osha_212",categoria:"OSHA_CAIDAS",pregunta:"\xBFCu\xE1l es la se\xF1al manual est\xE1ndar para indicar 'Parada de Emergencia' a un operador de gr\xFAa?",opciones:["Un dedo hacia arriba","Ambos brazos extendidos horizontalmente movi\xE9ndose r\xE1pidamente de ida y vuelta","Cerrar el pu\xF1o","Hacer un c\xEDrculo con la mano"],respuesta_correcta:1,explicacion:"Es una se\xF1al universal de seguridad que cualquier trabajador debe conocer para detener una maniobra peligrosa."},{id:"osha_213",categoria:"OSHA_CAIDAS",pregunta:"\xBFQui\xE9n debe supervisar el montaje, desmontaje o alteraci\xF3n de un andamio seg\xFAn OSHA?",opciones:["Cualquier trabajador","Una 'Persona Competente' con entrenamiento espec\xEDfico en andamios","El due\xF1o del edificio","Un arquitecto"],respuesta_correcta:1,explicacion:"Solo alguien con la autoridad y el conocimiento para identificar peligros puede supervisar estas maniobras."},{id:"osha_214",categoria:"OSHA_CAIDAS",pregunta:"En una escalera fija industrial, si la altura de ascenso es mayor a 24 pies, \xBFqu\xE9 exige la nueva normativa de OSHA?",opciones:["Una jaula de protecci\xF3n solamente","Un sistema de seguridad para escaleras (l\xEDnea de vida vertical) o un sistema de detenci\xF3n de ca\xEDdas","Poner una alfombra","Que la escalera sea de madera"],respuesta_correcta:1,explicacion:"OSHA est\xE1 eliminando gradualmente las jaulas (cages) en favor de sistemas activos de detenci\xF3n de ca\xEDdas en escaleras fijas."},{id:"osha_215",categoria:"OSHA_CAIDAS",pregunta:"\xBFA qu\xE9 distancia m\xEDnima debe mantenerse cualquier maquinaria pesada de una l\xEDnea el\xE9ctrica de 50kV?",opciones:["5 pies","10 pies","20 pies","50 pies"],respuesta_correcta:1,explicacion:"OSHA exige una distancia m\xEDnima de 10 pies para voltajes de hasta 50kV para evitar arcos el\xE9ctricos al aire."},{id:"osha_216",categoria:"OSHA_CAIDAS",pregunta:"\xBFCu\xE1l es el \xE1ngulo de inclinaci\xF3n correcto para una escalera de extensi\xF3n?",opciones:["45 grados","75.5 grados (relaci\xF3n 4:1)","90 grados","30 grados"],respuesta_correcta:1,explicacion:"Por cada 4 pies de altura, la base debe estar a 1 pie de distancia de la pared."},{id:"osha_217",categoria:"OSHA_CAIDAS",pregunta:"En el montaje de estructuras de acero, \xBFa qu\xE9 altura deben estar protegidos los trabajadores (excepto conectores)?",opciones:["6 pies","15 pies","30 pies","4 pies"],respuesta_correcta:1,explicacion:"En 'Steel Erection', la regla general de protecci\xF3n contra ca\xEDdas empieza a los 15 pies."},{id:"osha_218",categoria:"OSHA_CAIDAS",pregunta:"\xBFPor qu\xE9 es obligatorio cubrir las puntas expuestas de las varillas de refuerzo (rebar)?",opciones:["Para que no se oxiden","Para evitar el empalamiento en caso de una ca\xEDda","Para que se vean mejor","Para marcar el \xE1rea"],respuesta_correcta:1,explicacion:"Caer sobre una varilla sin protecci\xF3n puede ser fatal; los 'rebar caps' deben estar dise\xF1ados para resistir el impacto."},{id:"osha_219",categoria:"OSHA_CAIDAS",pregunta:"Un agujero en el suelo de una planta industrial de m\xE1s de 2 pulgadas debe:",opciones:["Ser ignorado","Estar tapado con una cubierta que soporte el doble del peso esperado y est\xE9 marcada como 'HOLE' o 'COVER'","Pintarse de rojo","Tener un cono cerca"],respuesta_correcta:1,explicacion:"Cualquier apertura que permita la ca\xEDda de herramientas o personas debe estar asegurada f\xEDsicamente."},{id:"osha_220",categoria:"OSHA_CAIDAS",pregunta:"Un sistema de red de seguridad (safety net) debe probarse dejando caer una bolsa de arena de cu\xE1ntas libras:",opciones:["100 lbs","400 lbs","1000 lbs","50 lbs"],respuesta_correcta:1,explicacion:"La prueba de impacto asegura que la red y sus anclajes soportar\xE1n la ca\xEDda de un trabajador pesado."},{id:"osha_221",categoria:"OSHA_CAIDAS",pregunta:"\xBFCu\xE1nto debe extenderse el tabl\xF3n (plank) de un andamio m\xE1s all\xE1 de su soporte final si no est\xE1 asegurado?",opciones:["Al ras","M\xEDnimo 6 pulgadas y m\xE1ximo 12 pulgadas","2 pies","5 pies"],respuesta_correcta:1,explicacion:"Evita que el tabl\xF3n se resbale o que haga un 'efecto trampol\xEDn' si un trabajador se para en el extremo."},{id:"osha_222",categoria:"OSHA_CAIDAS",pregunta:"El 'Anclaje' de un sistema de posicionamiento debe soportar al menos:",opciones:["5,000 lbs","3,000 lbs (o el doble de la carga de impacto prevista)","1,000 lbs","El peso de la caja de herramientas"],respuesta_correcta:1,explicacion:"Sistemas de posicionamiento tienen requisitos distintos a los de detenci\xF3n de ca\xEDdas, pero siguen siendo cr\xEDticos."},{id:"osha_223",categoria:"OSHA_CAIDAS",pregunta:"\xBFCu\xE1l es el '\xC1ngulo Cr\xEDtico' de una eslinga (sling) donde la tensi\xF3n aumenta dr\xE1sticamente y puede causar una falla catastr\xF3fica?",opciones:["90 grados","Menos de 30 grados respecto a la horizontal","45 grados","60 grados"],respuesta_correcta:1,explicacion:"A \xE1ngulos bajos (horizontales), la tensi\xF3n en los brazos de la eslinga se multiplica exponencialmente, superando su capacidad nominal."},{id:"osha_224",categoria:"OSHA_CAIDAS",pregunta:"Al trabajar en una plataforma elevadora (Man-lift / Boom lift), \xBFest\xE1 permitido pararse sobre los rieles de protecci\xF3n para ganar altura?",opciones:["S\xED, si el arn\xE9s est\xE1 conectado","No, los pies deben estar firmemente sobre el piso de la plataforma en todo momento","Solo si un compa\xF1ero te sostiene","Solo en interiores"],respuesta_correcta:1,explicacion:"Subirse a los barandales anula la protecci\xF3n contra ca\xEDdas y desplaza el centro de gravedad peligrosamente."},{id:"osha_225",categoria:"OSHA_CAIDAS",pregunta:"En un andamio m\xF3vil, las ruedas deben:",opciones:["Estar siempre libres para moverlo r\xE1pido","Tener bloqueos (frenos) puestos mientras los trabajadores est\xE1n en la plataforma","Ser de madera","Ser quitadas al llegar al sitio"],respuesta_correcta:1,explicacion:"El movimiento accidental del andamio mientras hay personal arriba causa ca\xEDdas fatales."},{id:"osha_226",categoria:"OSHA_CAIDAS",pregunta:"\xBFQu\xE9 es la 'Carga de Trabajo Segura' (SWL) en un grillete o eslinga?",opciones:["El peso m\xE1ximo absoluto antes de romperse","La carga m\xE1xima recomendada por el fabricante para uso diario seguro","El peso del operario","10,000 lbs siempre"],respuesta_correcta:1,explicacion:"La SWL incluye un factor de seguridad (usualmente 5:1). Nunca se debe exceder la SWL."},{id:"osha_227",categoria:"OSHA_CAIDAS",pregunta:"Un trabajador usa un arn\xE9s con punto de anclaje dorsal. \xBFQu\xE9 ocurre si se cae de cabeza (invertido) con este punto dorsal?",opciones:["El arn\xE9s lo mantiene derecho autom\xE1ticamente.","Puede deslizarse fuera del arn\xE9s por gravedad.","El punto dorsal es solo para rescate, no para ca\xEDdas.","No hay riesgo, est\xE1 dise\xF1ado para cualquier orientaci\xF3n."],respuesta_correcta:1,explicacion:"Ca\xEDda invertida con anclaje dorsal puede permitir que el trabajador se deslice fuera del arn\xE9s."},{id:"osha_228",categoria:"OSHA_CAIDAS",pregunta:"Una l\xEDnea de vida horizontal tiene un cable de acero inoxidable. \xBFQu\xE9 riesgo espec\xEDfico del acero inoxidable es peor que el acero galvanizado?",opciones:["Menor resistencia a la tracci\xF3n.","Fragilizaci\xF3n por cloruros (corrosi\xF3n bajo tensi\xF3n).","Mayor peso por metro.","Menor flexibilidad."],respuesta_correcta:1,explicacion:"Acero inoxidable sufre fragilizaci\xF3n por cloruros (ambientes marinos o industriales)."},{id:"osha_229",categoria:"OSHA_CAIDAS",pregunta:"Un sistema de detenci\xF3n de ca\xEDdas tiene un conector de anclaje tipo argolla soldada. \xBFQu\xE9 prueba no destructiva es obligatoria peri\xF3dicamente?",opciones:["Inspecci\xF3n visual con lupa 10x.","Prueba de tintas penetrantes.","Prueba de carga al 50% de capacidad.","Medici\xF3n de espesor por ultrasonido."],respuesta_correcta:1,explicacion:"Soldaduras requieren inspecci\xF3n por tintas penetrantes o part\xEDculas magn\xE9ticas para detectar grietas."},{id:"osha_230",categoria:"OSHA_CAIDAS",pregunta:"Una l\xEDnea de vida vertical con absorbedor est\xE1 anclada a 2 metros sobre el punto de operaci\xF3n. \xBFCu\xE1l es la distancia de ca\xEDda total?",opciones:["2 metros + longitud de cuerda.","2 metros + 1.2 m (absorbedor) + estatura.","Solo la longitud de la cuerda.","Depende del peso del trabajador."],respuesta_correcta:1,explicacion:"Ca\xEDda = distancia anclaje (2 m) + despliegue absorbedor (1.2 m) + altura trabajador (1.75 m)."},{id:"osha_231",categoria:"OSHA_CAIDAS",pregunta:"Un sistema de protecci\xF3n contra ca\xEDdas tiene un mosquet\xF3n de acero. \xBFQu\xE9 tratamiento de superficie es peligroso para el acero de alta resistencia?",opciones:["Galvanizado en caliente.","Pintura ep\xF3xica.","Cromado duro.","Niquelado electrol\xEDtico."],respuesta_correcta:2,explicacion:"Cromado duro puede inducir fragilizaci\xF3n por hidr\xF3geno en aceros de alta resistencia."},{id:"osha_232",categoria:"OSHA_CAIDAS",pregunta:"Una l\xEDnea de vida retr\xE1ctil (SRL) tiene un indicador de ca\xEDda desplegado (bandera roja). \xBFPuede reutilizarse despu\xE9s de inspecci\xF3n visual?",opciones:["S\xED, si no hay da\xF1o visible.","No, el indicador desplegado significa que debe retirarse de servicio.","S\xED, despu\xE9s de recertificaci\xF3n por fabricante.","No, solo si la ca\xEDda fue de menos de 1 metro."],respuesta_correcta:1,explicacion:"Indicador de ca\xEDda desplegado significa que el SRL ha absorbido una ca\xEDda y debe reemplazarse."},{id:"osha_233",categoria:"OSHA_CAIDAS",pregunta:"Un sistema de protecci\xF3n contra ca\xEDdas tiene un mosquet\xF3n con seguro de tornillo. El trabajador no aprieta el tornillo. \xBFQu\xE9 riesgo de desenganche existe?",opciones:["El tornillo se afloja m\xE1s con la vibraci\xF3n.","El mosquet\xF3n puede abrirse por contacto lateral.","No hay riesgo si el tornillo est\xE1 al menos a medio apretar.","El seguro de tornillo no requiere apriete."],respuesta_correcta:1,explicacion:"Mosquet\xF3n con seguro sin apretar puede abrirse por fricci\xF3n contra superficies."},{id:"osha_234",categoria:"OSHA_CAIDAS",pregunta:"Una l\xEDnea de vida horizontal tiene un cable de acero con un nudo. \xBFEs aceptable?",opciones:["S\xED, los nudos son comunes en cables.","No, los nudos reducen la resistencia hasta un 80%.","S\xED, si el nudo est\xE1 soldado.","No, pero solo en cables de m\xE1s de 10 mm."],respuesta_correcta:1,explicacion:"Nudos en cable de acero reducen dr\xE1sticamente la resistencia a la tracci\xF3n."},{id:"osha_235",categoria:"OSHA_CAIDAS",pregunta:"Un sistema de detenci\xF3n de ca\xEDdas tiene un punto de anclaje port\xE1til de 200 kg de peso. \xBFEs seguro para un trabajador de 100 kg?",opciones:["S\xED, porque 200 kg > 100 kg.","No, porque la fuerza de ca\xEDda puede superar 1000 kg.","S\xED, si el anclaje est\xE1 certificado para 5000 lbs.","No, porque el peso del anclaje no indica resistencia."],respuesta_correcta:3,explicacion:"El peso del anclaje no es indicador de resistencia; requiere certificaci\xF3n a 5000 lbs (2270 kg)."},{id:"osha_236",categoria:"OSHA_CAIDAS",pregunta:"Una l\xEDnea de vida vertical tiene un absorbedor de 1.2 metros. \xBFCu\xE1l es la distancia libre m\xEDnima desde el punto de anclaje al nivel inferior?",opciones:["1.2 metros.","3.7 metros (1.2 + 1.75 estatura + 0.75 margen).","2.5 metros.","Depende del peso del trabajador."],respuesta_correcta:1,explicacion:"Distancia = absorbedor (1.2) + estatura (1.75) + margen seguridad (0.75) = 3.7 m."},{id:"osha_237",categoria:"OSHA_CAIDAS",pregunta:"Una l\xEDnea de vida retr\xE1ctil (SRL) est\xE1 anclada en el piso. El trabajador sube a una plataforma a 2 metros. \xBFEs seguro?",opciones:["S\xED, el SRL sigue al trabajador.","No, porque el cable puede engancharse al subir.","S\xED, si el SRL tiene freno de inercia.","No, porque el SRL no debe usarse con anclaje inferior."],respuesta_correcta:1,explicacion:"Cable vertical puede engancharse en escalones o bordes."},{id:"osha_238",categoria:"OSHA_CAIDAS",pregunta:"Un sistema de protecci\xF3n contra ca\xEDdas tiene un mosquet\xF3n de aluminio con desgaste visible en la garganta. \xBFQu\xE9 riesgo espec\xEDfico existe?",opciones:["El mosquet\xF3n puede romperse por fatiga.","El seguro puede no cerrar correctamente.","El desgaste reduce el di\xE1metro interior.","El aluminio se corroe m\xE1s r\xE1pido."],respuesta_correcta:1,explicacion:"Desgaste en garganta puede impedir que el seguro cierre completamente."},{id:"osha_239",categoria:"OSHA_CAIDAS",pregunta:"Una l\xEDnea de vida horizontal tiene una longitud de 30 metros con un solo anclaje intermedio. \xBFCu\xE1ntos trabajadores pueden conectarse simult\xE1neamente?",opciones:["1 trabajador.","2 trabajadores.","Depende de la deflexi\xF3n del cable.",'4 trabajadores si el cable es de 5/8".'],respuesta_correcta:0,explicacion:"L\xEDnea de vida horizontal sin anclajes intermedios suficientes solo admite un trabajador."},{id:"osha_240",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"\xBFQu\xE9 gas es conocido como 'El asesino silencioso' en espacios de calderas o cuartos de m\xE1quinas mal ventilados?",opciones:["Nitr\xF3geno","Mon\xF3xido de Carbono (CO)","Ox\xEDgeno","Di\xF3xido de Carbono"],respuesta_correcta:1,explicacion:"El CO es incoloro e inodoro, y se une a la hemoglobina 200 veces m\xE1s r\xE1pido que el ox\xEDgeno."},{id:"osha_241",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Una escalera para salir de una zanja debe extenderse al menos cu\xE1ntas pulgadas por encima del borde:",opciones:["12 pulgadas","24 pulgadas","36 pulgadas","No importa"],respuesta_correcta:2,explicacion:"OSHA exige 3 pies (36 pulgadas) para que el trabajador tenga de d\xF3nde agarrarse al salir."},{id:"osha_242",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"\xBFPor qu\xE9 los refrigerantes son peligrosos en un s\xF3tano sin ventilaci\xF3n si hay una fuga masiva?",opciones:["Porque huelen mal","Son m\xE1s pesados que el aire y desplazan el ox\xEDgeno, causando asfixia sin advertencia","Hacen que el suelo se vuelva resbaladizo","Aumentan la humedad"],respuesta_correcta:1,explicacion:"La mayor\xEDa de los refrigerantes se acumulan en zonas bajas, creando atm\xF3sferas deficientes de ox\xEDgeno."},{id:"osha_243",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Permit-Required Confined Space' (Permiso de entrada)?",opciones:["Cobrar m\xE1s al cliente","Documentar los peligros, las pruebas de aire, el equipo de rescate y las personas autorizadas","Saber a qu\xE9 hora termina el turno","Es un papel innecesario"],respuesta_correcta:1,explicacion:"El permiso asegura que se hayan tomado todas las medidas preventivas antes de arriesgar una vida."},{id:"osha_244",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado que contiene un peligro el\xE9ctrico expuesto se clasifica autom\xE1ticamente como:",opciones:["Espacio no-permitido","Espacio que requiere permiso (Permit-Required Confined Space)","Espacio abierto","Zona de confort"],respuesta_correcta:1,explicacion:"Cualquier peligro f\xEDsico o atmosf\xE9rico convierte el espacio en uno 'con permiso requerido'."},{id:"osha_245",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"En una excavaci\xF3n de 4 pies de profundidad, \xBFqu\xE9 riesgo 'atmosf\xE9rico' debe monitorearse seg\xFAn OSHA?",opciones:["Humedad","Acumulaci\xF3n de gases pesados (como CO2) o deficiencia de ox\xEDgeno","Velocidad del viento","Temperatura del aire"],respuesta_correcta:1,explicacion:"Las zanjas pueden atrapar gases m\xE1s pesados que el aire, creando atm\xF3sferas letales."},{id:"osha_246",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"\xBFA qu\xE9 profundidad de zanja se requiere un dise\xF1o de ingenier\xEDa profesional para el sistema de protecci\xF3n?",opciones:["5 pies","10 pies","20 pies","No se requiere ingenieros"],respuesta_correcta:2,explicacion:"Zanjas de m\xE1s de 20 pies de profundidad son extremadamente peligrosas y requieren dise\xF1o t\xE9cnico."},{id:"osha_247",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"En una excavaci\xF3n de 6 pies, \xBFa qu\xE9 distancia m\xE1xima debe estar una escalera o rampa para que el trabajador pueda salir de forma segura?",opciones:["10 pies","25 pies de desplazamiento lateral","50 pies","No hay l\xEDmite"],respuesta_correcta:1,explicacion:"OSHA 1926.651(c)(2) exige un medio de salida cada 25 pies de desplazamiento lateral en zanjas de 4 pies o m\xE1s."},{id:"osha_248",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"En un espacio confinado, \xBFcu\xE1l es el orden correcto para probar los gases en la atm\xF3sfera?",opciones:["1. Inflamables, 2. Ox\xEDgeno, 3. T\xF3xicos","1. Ox\xEDgeno, 2. Inflamables, 3. T\xF3xicos","1. T\xF3xicos primero","No importa el orden"],respuesta_correcta:1,explicacion:"Primero se prueba el ox\xEDgeno, ya que los sensores de gases inflamables y t\xF3xicos requieren ox\xEDgeno para dar lecturas precisas."},{id:"osha_249",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"El suelo Tipo A es el m\xE1s estable. \xBFCu\xE1l es la pendiente de inclinaci\xF3n (sloping) m\xE1xima permitida por OSHA para este tipo de suelo?",opciones:["1:1 (45 grados)","3/4:1 (53 grados)","1 1/2:1 (34 grados)","Vertical (90 grados)"],respuesta_correcta:1,explicacion:"Aun siendo suelo estable, OSHA exige una inclinaci\xF3n m\xEDnima para evitar derrumbes repentinos."},{id:"osha_250",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"\xBFQu\xE9 es un 'Entry Supervisor'?",opciones:["El guardia de la puerta","La persona responsable de determinar si las condiciones son seguras, autorizar la entrada y cancelar el permiso","El que entra primero","El cliente"],respuesta_correcta:1,explicacion:"Es la autoridad legal dentro del protocolo de espacios confinados."},{id:"osha_251",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 18.5% O2 y 10% LEL de gasolina. \xBFSe puede ingresar con respirador de l\xEDnea de aire?",opciones:["S\xED, porque el respirador suministra aire limpio.","No, porque 10% LEL excede 5% LEL para ingreso.","S\xED, si se usa ropa antiest\xE1tica.","No, porque el O2 bajo afecta al rescatista."],respuesta_correcta:1,explicacion:"10% LEL > 5% LEL (l\xEDmite para ingreso), independientemente del respirador."},{id:"osha_252",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 0% LEL, 20.9% O2, pero el monitor PID (fotioinizador) marca 500 ppm. \xBFQu\xE9 significa?",opciones:["Gas inerte no detectable por LEL.","Vapores org\xE1nicos t\xF3xicos no inflamables.","Mon\xF3xido de carbono.","Falso positivo por humedad."],respuesta_correcta:1,explicacion:"PID detecta compuestos org\xE1nicos vol\xE1tiles que pueden ser t\xF3xicos sin ser inflamables."},{id:"osha_253",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado tiene 20 ppm de H2S y 0% LEL. \xBFSe puede ingresar con respirador de media cara con filtro de H2S?",opciones:["S\xED, los filtros para H2S existen.","No, porque el H2S no tiene filtro efectivo; requiere SCBA.","S\xED, con cartucho tipo H2S color gris.","No, porque 20 ppm excede el l\xEDmite de filtros."],respuesta_correcta:1,explicacion:"No existen filtros comerciales efectivos para H2S; solo SCBA o l\xEDnea de aire."},{id:"osha_254",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado tiene 500 ppm de CO y 18% O2. \xBFQu\xE9 respirador es adecuado?",opciones:["Media cara con cartucho para CO.","M\xE1scara completa con l\xEDnea de aire.","PAPR con filtro de CO.","Ninguno, el CO no tiene filtro efectivo."],respuesta_correcta:1,explicacion:"CO requiere SCBA o l\xEDnea de aire; no hay filtros efectivos."},{id:"osha_255",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 19% O2 y 50 ppm de Cl2 (cloro). \xBFQu\xE9 respirador es adecuado?",opciones:["Media cara con filtro para gases \xE1cidos.","M\xE1scara completa con cartucho tipo B (gris).","PAPR con filtro de cloro.","SCBA obligatorio por 19% O2."],respuesta_correcta:1,explicacion:"Cloro requiere cartucho tipo B (gases \xE1cidos); m\xE1scara completa protege ojos del cloro."},{id:"osha_256",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 15% O2 y 5000 ppm de CO2. \xBFSe puede ingresar con respirador de l\xEDnea de aire?",opciones:["S\xED, el respirador suministra aire normal.","No, porque 5000 ppm CO2 excede l\xEDmite.","S\xED, si el respirador tiene filtro de CO2.","No, porque 15% O2 es muy bajo para el rescatista."],respuesta_correcta:0,explicacion:"Respirador de l\xEDnea suministra aire independiente; CO2 externo no afecta al usuario."},{id:"osha_257",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 17% O2 y 0 ppm de t\xF3xicos. \xBFSe puede ingresar sin respirador?",opciones:["S\xED, 17% es aceptable si no hay otros peligros.","No, OSHA requiere m\xEDnimo 19.5% O2 para ingreso sin respirador.","S\xED, si se usa monitoreo continuo.","No, porque el O2 bajo puede no ser detectado por el trabajador."],respuesta_correcta:1,explicacion:"OSHA define atm\xF3sfera deficiente de ox\xEDgeno como < 19.5%; requiere respirador de suministro de aire."},{id:"osha_258",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 20.8% O2 y 1000 ppm de acetona. \xBFEs inflamable?",opciones:["No, 1000 ppm est\xE1 bajo LEL de acetona (2.5% = 25000 ppm).","S\xED, porque la acetona es inflamable a cualquier concentraci\xF3n.","No, porque el O2 es normal.","S\xED, si hay una fuente de ignici\xF3n."],respuesta_correcta:0,explicacion:"LEL acetona es 2.5% volumen (25000 ppm); 1000 ppm es seguro para ignici\xF3n."},{id:"osha_259",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 19% O2 y 10% LEL de propano. \xBFSe puede ingresar con respirador de l\xEDnea de aire?",opciones:["S\xED, porque el respirador suministra aire limpio.","No, porque 10% LEL > 5% LEL permitido.","S\xED, si se usa ropa antiest\xE1tica.","No, porque el O2 est\xE1 bajo 19.5%."],respuesta_correcta:1,explicacion:"10% LEL excede 5% LEL (l\xEDmite para ingreso a espacio confinado)."},{id:"osha_260",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 19% O2 y 25 ppm de H2S. \xBFQu\xE9 respirador es adecuado?",opciones:["Media cara con filtro de H2S.","M\xE1scara completa con l\xEDnea de aire.","PAPR con filtro de H2S.","SCBA obligatorio por 19% O2."],respuesta_correcta:1,explicacion:"H2S requiere SCBA o l\xEDnea de aire; no hay filtros efectivos."},{id:"osha_261",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 18% O2 y 50 ppm de NO2. \xBFQu\xE9 respirador es adecuado?",opciones:["Media cara con filtro para NO2.","M\xE1scara completa con l\xEDnea de aire.","PAPR con filtro de NO2.","SCBA obligatorio por 18% O2."],respuesta_correcta:1,explicacion:"NO2 requiere SCBA o l\xEDnea de aire; 18% O2 tambi\xE9n requiere suministro de aire."},{id:"osha_262",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 16% O2 y 0% LEL. \xBFSe puede ingresar con respirador de l\xEDnea de aire?",opciones:["S\xED, porque el respirador suministra aire.","No, porque 16% O2 es deficiente para el rescatista.","S\xED, si se usa monitoreo continuo.","No, porque requiere SCBA, no l\xEDnea de aire."],respuesta_correcta:0,explicacion:"Respirador de l\xEDnea suministra aire normal; el O2 ambiente no afecta al usuario."},{id:"osha_263",categoria:"OSHA_ESPACIOS_CONFINADOS",pregunta:"Un espacio confinado con 20.8% O2 y 1000 ppm de H2S. \xBFQu\xE9 respirador es adecuado?",opciones:["Media cara con filtro de H2S.","M\xE1scara completa con l\xEDnea de aire.","PAPR con filtro de H2S.","SCBA obligatorio."],respuesta_correcta:1,explicacion:"H2S requiere SCBA o l\xEDnea de aire; no hay filtros efectivos."},{id:"osha_264",categoria:"OSHA_ESCALERAS",pregunta:"Seg\xFAn OSHA, si una escalera de mano (A-frame) no tiene un separador o dispositivo de bloqueo esparcidor, el t\xE9cnico debe:",opciones:["Usar una cuerda para amarrar las patas","Apoyarla cerrada contra la pared","No usarla y retirarla de servicio inmediatamente","Tener a un ayudante sosteniendo ambos lados"],respuesta_correcta:2,explicacion:"OSHA 1926.1053(a)(8) exige que las escaleras de tijera tengan un dispositivo de bloqueo de metal para evitar que se cierren durante el uso."},{id:"osha_265",categoria:"OSHA_ESCALERAS",pregunta:"Al subir por una escalera de extensi\xF3n, \xBFcu\xE1ntos puntos de contacto deben mantenerse siempre?",opciones:["Uno","Dos","Tres","Cuatro"],respuesta_correcta:2,explicacion:"La regla de los 3 puntos (dos pies y una mano, o dos manos y un pie) es obligatoria por OSHA para evitar ca\xEDdas."},{id:"osha_266",categoria:"OSHA_ESCALERAS",pregunta:"Al trabajar desde una escalera de tijera, \xBFcu\xE1l es el pelda\xF1o m\xE1s alto en el que puedes pararte?",opciones:["El \xFAltimo (la tapa superior)","El segundo contando desde arriba","El tercero contando desde arriba","Cualquiera si tienes buen equilibrio"],respuesta_correcta:1,explicacion:"OSHA y los fabricantes proh\xEDben pararse en los dos pelda\xF1os superiores debido a la inestabilidad extrema."},{id:"osha_267",categoria:"OSHA_ESCALERAS",pregunta:"Las escaleras de mano deben inspeccionarse:",opciones:["Cada a\xF1o","Peri\xF3dicamente por una persona competente y antes de cada uso por el trabajador","Solo si se caen del cami\xF3n","Cuando el t\xE9cnico se siente inseguro"],respuesta_correcta:1,explicacion:"La inspecci\xF3n pre-uso detecta fallas que causan la mayor\xEDa de los accidentes en construcci\xF3n."},{id:"osha_268",categoria:"OSHA_ESCALERAS",pregunta:"Si una escalera est\xE1 da\xF1ada, el t\xE9cnico debe:",opciones:["Repararla con cinta adhesiva","Poner una etiqueta de 'No Usar' y destruirla o retirarla del sitio inmediatamente","Usarla solo en el primer pelda\xF1o","Dejarla ah\xED para que otro la use"],respuesta_correcta:1,explicacion:"Una escalera defectuosa no tiene reparaci\xF3n permitida que garantice la seguridad original del fabricante."},{id:"osha_269",categoria:"OSHA_ESCALERAS",pregunta:"\xBFCu\xE1l es la m\xE1xima longitud permitida para una escalera de mano simple (no de extensi\xF3n)?",opciones:["10 pies","20 pies","30 pies","50 pies"],respuesta_correcta:2,explicacion:"OSHA limita las escaleras simples a 30 pies por razones de estabilidad estructural."},{id:"osha_270",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de madera tiene un pelda\xF1o suelto. El trabajador lo clava nuevamente. \xBFEs aceptable esta reparaci\xF3n?",opciones:["S\xED, los clavos son m\xE1s fuertes que los originales.","No, porque los pelda\xF1os deben estar ensamblados con mortaja y espiga.","S\xED, si se usa pegamento ep\xF3xico tambi\xE9n.","No, pero solo si la escalera es de m\xE1s de 3 metros."],respuesta_correcta:1,explicacion:"Pelda\xF1os de madera deben estar ensamblados (mortaja y espiga); clavarlos no restaura integridad."},{id:"osha_271",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de tijera est\xE1 abierta en \xE1ngulo de 15 grados (muy cerrada). \xBFQu\xE9 falla mec\xE1nica ocurre primero?",opciones:["Las patas traseras se doblan hacia afuera.","La bisagra central se sobrecarga.","Los pelda\xF1os se pandean.","La plataforma superior se separa."],respuesta_correcta:1,explicacion:"\xC1ngulo cerrado aumenta momento en la bisagra central, punto m\xE1s d\xE9bil."},{id:"osha_272",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de aluminio tiene los remaches de los pelda\xF1os flojos. \xBFSe pueden apretar?",opciones:["S\xED, apretando con un martillo.","No, los remaches son de una sola pieza; la holgura indica falla.","S\xED, si se reemplazan por tornillos.","No, pero solo si la escalera es de menos de 2 metros."],respuesta_correcta:1,explicacion:"Remaches flojos indican desgaste del orificio; no se pueden apretar, la escalera debe retirarse."},{id:"osha_273",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de fibra de vidrio tiene una mancha oscura en un larguero. \xBFQu\xE9 indica?",opciones:["Moho superficial sin importancia.","Degradaci\xF3n por UV o qu\xEDmicos.","Humedad atrapada.","Residuo de grasa."],respuesta_correcta:1,explicacion:"Manchas oscuras en fibra de vidrio pueden indicar degradaci\xF3n de la resina por UV o qu\xEDmicos."},{id:"osha_274",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de aluminio est\xE1 apoyada sobre un piso de concreto mojado con aceite. El coeficiente de fricci\xF3n estimado es 0.2. \xBFEs segura?",opciones:["S\xED, 0.2 es suficiente.","No, se requiere m\xEDnimo 0.5 para escaleras.","S\xED, si se usa un segundo trabajador estabilizando.","No, porque el aluminio es resbaladizo por s\xED mismo."],respuesta_correcta:1,explicacion:"Coeficiente de fricci\xF3n m\xEDnimo recomendado para escaleras es 0.5 en condiciones secas."},{id:"osha_275",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de madera tiene un nudo en un larguero. \xBFQu\xE9 norma ANSI dice sobre nudos?",opciones:["Los nudos peque\xF1os son aceptables.","No se permiten nudos en largueros.","Solo se permiten nudos sanos menores a 2 cm.","Los nudos deben rellenarse con masilla."],respuesta_correcta:1,explicacion:"ANSI A14.1 proh\xEDbe nudos en largueros de escaleras de madera."},{id:"osha_276",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de tijera tiene las patas traseras sin zapatas antideslizantes. \xBFEs seguro usarla sobre alfombra?",opciones:["S\xED, la alfombra proporciona agarre.","No, la alfombra puede deslizarse sobre el piso.","S\xED, si la alfombra est\xE1 fija.","No, porque las patas traseras perforan la alfombra."],respuesta_correcta:1,explicacion:"Alfombra puede deslizarse como un tapete, llevando la escalera con ella."},{id:"osha_277",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de aluminio est\xE1 pintada con esmalte automotriz. \xBFQu\xE9 peligro introduce la pintura?",opciones:["La pintura puede ocultar corrosi\xF3n.","El esmalte es inflamable.","La pintura conduce electricidad.","No hay peligro, la pintura protege."],respuesta_correcta:0,explicacion:"Pintura puede ocultar corrosi\xF3n o grietas en el aluminio."},{id:"osha_278",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de fibra de vidrio tiene un olor a quemado. \xBFQu\xE9 indica?",opciones:["Exposici\xF3n a calor excesivo que degrad\xF3 la resina.","Limpieza reciente con solvente.","Moho por humedad.","Normal en escaleras nuevas."],respuesta_correcta:0,explicacion:"Olor a quemado indica que la resina de fibra de vidrio se sobrecalent\xF3, perdiendo resistencia."},{id:"osha_279",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de aluminio tiene una abolladura de 3 mm en un larguero. \xBFEs segura?",opciones:["S\xED, 3 mm es superficial.","No, cualquier abolladura en larguero es cr\xEDtica.","S\xED, si est\xE1 en la parte inferior.","No, pero solo si est\xE1 en la zona media."],respuesta_correcta:1,explicacion:"Abolladura en larguero crea concentraci\xF3n de tensiones; debe retirarse."},{id:"osha_280",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de mano de madera tiene una grieta en la uni\xF3n del pelda\xF1o con el larguero. \xBFSe puede reparar con pegamento?",opciones:["S\xED, con pegamento ep\xF3xico estructural.","No, las uniones de escaleras de madera no son reparables.","S\xED, si se a\xF1aden grapas met\xE1licas.","No, pero solo si la grieta es menor a 1 cm."],respuesta_correcta:1,explicacion:"Uniones escal\xF3n-larguero no son reparables; la escalera debe retirarse."},{id:"osha_281",categoria:"OSHA_ESCALERAS",pregunta:"Una escalera de tijera tiene una etiqueta ilegible. \xBFQu\xE9 debe hacerse?",opciones:["Solicitar una etiqueta de reemplazo al fabricante.","Continuar us\xE1ndola si se ve en buen estado.","Retirar la escalera de servicio.","Escribir una etiqueta manual con marcador."],respuesta_correcta:2,explicacion:"Etiqueta ilegible impide conocer capacidad y certificaci\xF3n; retirar de servicio."},{id:"osha_282",categoria:"OSHA_LOTO",pregunta:"Un t\xE9cnico aplica LOTO en un chiller. Despu\xE9s de colocar el candado y la etiqueta, \xBFcu\xE1l es el paso de verificaci\xF3n de 'Energ\xEDa Cero' m\xE1s olvidado pero obligatorio?",opciones:["Revisar la fecha de la etiqueta","Intentar arrancar el equipo localmente (Push Start Button)","Llamar al supervisor","Mirar si las luces del panel est\xE1n apagadas"],respuesta_correcta:1,explicacion:"El paso de 'Verificaci\xF3n' exige intentar encender el equipo tras el bloqueo para asegurar que no existan puentes el\xE9ctricos o energ\xEDa residual."},{id:"osha_283",categoria:"OSHA_LOTO",pregunta:"\xBFQui\xE9n es la \xFAnica persona autorizada para quitar un candado de bloqueo?",opciones:["El supervisor","El due\xF1o de la empresa","La persona que lo coloc\xF3","El cliente"],respuesta_correcta:2,explicacion:"Bajo OSHA 1910.147, solo el trabajador autorizado que aplic\xF3 el bloqueo puede retirarlo (salvo procedimientos de emergencia muy espec\xEDficos)."},{id:"osha_284",categoria:"OSHA_LOTO",pregunta:"Si un equipo tiene m\xFAltiples fuentes de energ\xEDa (El\xE9ctrica y Neum\xE1tica), \xBFcu\xE1ntos candados requiere?",opciones:["Uno para la el\xE9ctrica solamente","Dos candados, uno para cada fuente de energ\xEDa independiente","Ninguno si el supervisor est\xE1 mirando","Un candado compartido"],respuesta_correcta:1,explicacion:"LOTO requiere el aislamiento de TODAS las fuentes de energ\xEDa peligrosa."},{id:"osha_285",categoria:"OSHA_LOTO",pregunta:"Un t\xE9cnico encuentra un candado LOTO de otro compa\xF1ero en el desconectador. \xBFPuede quitarlo si el compa\xF1ero se fue a almorzar?",opciones:["S\xED, para no perder tiempo","No, est\xE1 estrictamente prohibido quitar el candado de otra persona","Solo si el supervisor le da permiso verbal","Solo si el cliente lo pide"],respuesta_correcta:1,explicacion:"La regla fundamental de LOTO es: 'Tu vida, tu candado'. Nadie m\xE1s puede retirarlo sin un protocolo de emergencia documentado."},{id:"osha_286",categoria:"OSHA_LOTO",pregunta:"Al aplicar LOTO en un Variador de Frecuencia (VFD), \xBFcu\xE1nto tiempo debe esperar el t\xE9cnico tras desconectar la energ\xEDa antes de abrir el panel?",opciones:["Ninguno, es instant\xE1neo","El tiempo especificado por el fabricante (usualmente 5-20 min) para que los capacitores internos se descarguen","30 segundos","24 horas"],respuesta_correcta:1,explicacion:"Los VFD almacenan energ\xEDa masiva en sus bancos de capacitores de DC (DC Bus) que puede ser letal incluso sin alimentaci\xF3n externa."},{id:"osha_287",categoria:"OSHA_LOTO",pregunta:"\xBFQu\xE9 se debe hacer si el candado de un t\xE9cnico se queda puesto y \xE9l ya se fue a su casa en otra ciudad?",opciones:["Cortarlo con una cizalla de inmediato","Seguir un protocolo escrito de 'Remoci\xF3n de candado ausente' que incluye verificar que el t\xE9cnico no est\xE9 en el sitio y autorizaci\xF3n gerencial","Llamar a la polic\xEDa","Dejar el equipo apagado hasta que regrese en 3 d\xEDas"],respuesta_correcta:1,explicacion:"Nunca se corta un candado sin un proceso formal, pues la vida del t\xE9cnico que lo puso podr\xEDa estar en riesgo si regresa."},{id:"osha_288",categoria:"OSHA_LOTO",pregunta:"Un t\xE9cnico coloca un candado en un interruptor. \xBFEs suficiente para establecer una 'Condici\xF3n de Trabajo El\xE9ctricamente Segura'?",opciones:["S\xED, el candado garantiza seguridad","No, falta verificar la ausencia de tensi\xF3n con un volt\xEDmetro CAT adecuado","Solo si la etiqueta es roja","S\xED, si el cliente firm\xF3 el permiso"],respuesta_correcta:1,explicacion:"La prueba de ausencia de tensi\xF3n (Live-Dead-Live) es el \xFAnico paso que confirma que el circuito no tiene energ\xEDa residual o retroalimentaci\xF3n."},{id:"osha_289",categoria:"OSHA_LOTO",pregunta:"Si un interruptor no tiene capacidad f\xEDsica para ser bloqueado con candado, \xBFqu\xE9 permite OSHA?",opciones:["No bloquearlo y avisar al jefe","Usar solo una etiqueta (Tagout) con medidas adicionales de seguridad equivalentes a un bloqueo","Poner cinta aislante","Dejar a un compa\xF1ero vigilando el interruptor"],respuesta_correcta:1,explicacion:"El Tagout solo se permite si el equipo no es 'lockable', pero requiere vigilancia o medidas f\xEDsicas extra."},{id:"osha_290",categoria:"OSHA_LOTO",pregunta:"\xBFCu\xE1l es el 'Peligro de Energ\xEDa Acumulada' en un resorte industrial comprimido?",opciones:["Ninguno","Energ\xEDa mec\xE1nica potencial que puede liberarse violentamente durante el desmontaje","Calor","Electricidad est\xE1tica"],respuesta_correcta:1,explicacion:"LOTO incluye bloquear energ\xEDas mec\xE1nicas, hidr\xE1ulicas y neum\xE1ticas, no solo el\xE9ctricas."},{id:"osha_291",categoria:"OSHA_LOTO",pregunta:"\xBFQu\xE9 se debe hacer con la energ\xEDa neum\xE1tica (aire a presi\xF3n) durante un LOTO industrial?",opciones:["Nada, el aire es inofensivo","Purgar la presi\xF3n residual y bloquear la v\xE1lvula de suministro en posici\xF3n cerrada","Solo apagar el compresor","Desconectar la manguera y dejarla libre"],respuesta_correcta:1,explicacion:"La presi\xF3n acumulada en un tanque o manguera puede activar un cilindro y causar un aplastamiento inesperado."},{id:"osha_292",categoria:"OSHA_LOTO",pregunta:"En un sistema de aire comprimido industrial, \xBFqu\xE9 dispositivo evita que un tanque explote si el interruptor de presi\xF3n (pressure switch) falla?",opciones:["El man\xF3metro","La v\xE1lvula de alivio de seguridad (Pop-off valve)","La manguera","El filtro de aire"],respuesta_correcta:1,explicacion:"Es un dispositivo mec\xE1nico de seguridad de \xFAltima instancia que libera la presi\xF3n excedente."},{id:"osha_293",categoria:"OSHA_LOTO",pregunta:"En LOTO de una m\xE1quina con dos fuentes de energ\xEDa (el\xE9ctrica y neum\xE1tica), se bloquea solo la el\xE9ctrica. \xBFQu\xE9 energ\xEDa neum\xE1tica peligrosa persiste?",opciones:["Presi\xF3n residual en cilindros.","Vac\xEDo en l\xEDneas de succi\xF3n.","Energ\xEDa de resorte en v\xE1lvulas.","Aire comprimido en el compresor remoto."],respuesta_correcta:0,explicacion:"Cilindros neum\xE1ticos pueden retener presi\xF3n atrapada aunque el compresor est\xE9 apagado."},{id:"osha_294",categoria:"OSHA_LOTO",pregunta:"En LOTO de un reactor qu\xEDmico, se bloquean todas las l\xEDneas de entrada. El reactor est\xE1 a 150\xB0C. \xBFQu\xE9 riesgo qu\xEDmico persiste?",opciones:["Polimerizaci\xF3n t\xE9rmica del contenido.","Generaci\xF3n de gases por descomposici\xF3n.","Aumento de presi\xF3n por expansi\xF3n t\xE9rmica.","Todos los anteriores."],respuesta_correcta:3,explicacion:"Calor residual puede causar m\xFAltiples reacciones peligrosas incluso con entradas bloqueadas."},{id:"osha_295",categoria:"OSHA_LOTO",pregunta:"En LOTO de una caldera, se cierra la v\xE1lvula de gas y se pone candado. \xBFSe requiere tambi\xE9n purgar la l\xEDnea de gas?",opciones:["No, con la v\xE1lvula cerrada es suficiente.","S\xED, porque puede haber gas residual presurizado.","Solo si la caldera es de alta presi\xF3n.","No, el gas se disipa solo."],respuesta_correcta:1,explicacion:"L\xEDnea de gas puede retener presi\xF3n entre v\xE1lvula de bloqueo y quemador."},{id:"osha_296",categoria:"OSHA_LOTO",pregunta:"En LOTO de una m\xE1quina rotativa, se bloquea el motor. El volante sigue girando 2 minutos. \xBFSe puede considerar seguro despu\xE9s de que pare?",opciones:["S\xED, una vez que para totalmente.","No, porque la energ\xEDa potencial del volante puede liberarse al desbloquear.","S\xED, si se usa un freno mec\xE1nico.","No, porque el volante puede tener energ\xEDa residual invisible."],respuesta_correcta:0,explicacion:"Una vez que todo movimiento cesa, la energ\xEDa cin\xE9tica se ha disipado."},{id:"osha_297",categoria:"OSHA_LOTO",pregunta:"En LOTO de un sistema de vac\xEDo, se bloquea la bomba y se purga la c\xE1mara a presi\xF3n atmosf\xE9rica. \xBFEs seguro abrir?",opciones:["S\xED, presi\xF3n atmosf\xE9rica es segura.","No, porque puede haber vac\xEDo residual local.","S\xED, si se usa un man\xF3metro.","No, porque la purga puede no haber sido completa."],respuesta_correcta:0,explicacion:"Presi\xF3n atmosf\xE9rica significa cero diferencial, seguro para abrir."},{id:"osha_298",categoria:"OSHA_LOTO",pregunta:"En LOTO de una extrusora, se bloquea el motor del tornillo. El barril est\xE1 a 200\xB0C con pl\xE1stico fundido. \xBFQu\xE9 energ\xEDa peligrosa persiste?",opciones:["Presi\xF3n del pl\xE1stico fundido.","Temperatura del barril.","Energ\xEDa qu\xEDmica del pl\xE1stico.","Todas las anteriores."],respuesta_correcta:3,explicacion:"Pl\xE1stico fundido tiene presi\xF3n, temperatura, y puede descomponerse qu\xEDmicamente."},{id:"osha_299",categoria:"OSHA_LOTO",pregunta:"En LOTO de un sistema neum\xE1tico, se bloquea el suministro de aire. \xBFSe requiere purgar todas las l\xEDneas?",opciones:["S\xED, para eliminar presi\xF3n residual.","No, si se bloquea en la fuente principal.","Solo las l\xEDneas que alimentan actuadores.","No, el aire no es energ\xEDa peligrosa."],respuesta_correcta:0,explicacion:"Las l\xEDneas pueden retener presi\xF3n atrapada aunque la fuente est\xE9 bloqueada."},{id:"osha_300",categoria:"OSHA_LOTO",pregunta:"En LOTO de una bomba centr\xEDfuga, se bloquea el motor. La bomba tiene una v\xE1lvula de retenci\xF3n. \xBFSe requiere bloquear tambi\xE9n la v\xE1lvula de succi\xF3n?",opciones:["No, la v\xE1lvula de retenci\xF3n previene flujo inverso.","S\xED, porque la v\xE1lvula de retenci\xF3n puede fugarse.","Solo si la bomba est\xE1 por debajo del nivel del l\xEDquido.","No, si se drena la bomba."],respuesta_correcta:1,explicacion:"V\xE1lvulas de retenci\xF3n pueden tener fugas; se requiere bloqueo en succi\xF3n si hay presi\xF3n aguas arriba."},{id:"osha_301",categoria:"OSHA_LOTO",pregunta:"En LOTO de una mezcladora industrial, se bloquea el motor. El agitador tiene impulsores sumergidos en l\xEDquido. \xBFQu\xE9 energ\xEDa peligrosa persiste?",opciones:["Energ\xEDa hidr\xE1ulica por circulaci\xF3n del l\xEDquido.","Energ\xEDa potencial del l\xEDquido en altura.","Energ\xEDa qu\xEDmica del producto.","Todas las anteriores."],respuesta_correcta:3,explicacion:"L\xEDquido en movimiento puede seguir girando el agitador por inercia hidr\xE1ulica."},{id:"osha_302",categoria:"OSHA_LOTO",pregunta:"En LOTO de un compresor de aire, se bloquea el motor. El tanque de aire est\xE1 a 10 bar. \xBFSe requiere despresurizar el tanque?",opciones:["No, porque el bloqueo del motor impide que el compresor arranque.","S\xED, porque la presi\xF3n almacenada es energ\xEDa independiente.","Solo si se va a abrir el tanque.","No, si se usa una v\xE1lvula de seguridad."],respuesta_correcta:1,explicacion:"Presi\xF3n de aire en tanque es energ\xEDa almacenada que debe disiparse."},{id:"osha_303",categoria:"OSHA_LOTO",pregunta:"En LOTO de una caldera de vapor, se cierran v\xE1lvulas de vapor y alimentaci\xF3n. \xBFSe requiere etiquetar la caldera como 'fuera de servicio'?",opciones:["S\xED, para advertir a otros trabajadores.","No, el LOTO es suficiente.","Solo si la caldera est\xE1 caliente.","No, porque las etiquetas no son obligatorias."],respuesta_correcta:0,explicacion:"Etiquetas informan el estado de LOTO a todos los trabajadores."},{id:"osha_304",categoria:"OSHA_LOTO",pregunta:"En LOTO de una m\xE1quina con m\xFAltiples fuentes de energ\xEDa, se usa un candado por cada fuente. \xBFEs correcto?",opciones:["S\xED, cada energ\xEDa requiere su candado.","No, un candado puede bloquear todas las fuentes con un hasp.","Solo si las fuentes est\xE1n en el mismo panel.","No, se requiere un candado por trabajador, no por fuente."],respuesta_correcta:1,explicacion:"Un candado puede asegurar m\xFAltiples fuentes usando un hasp o dispositivo de bloqueo m\xFAltiple."},{id:"osha_305",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Si un contenedor de qu\xEDmicos no tiene etiqueta original, el t\xE9cnico debe:",opciones:["Olerlo para identificarlo","Usarlo con cuidado","Etiquetarlo inmediatamente si conoce el contenido o tratarlo como residuo peligroso","Mezclarlo con agua"],respuesta_correcta:2,explicacion:"Bajo HazCom de OSHA, todo contenedor secundario debe estar identificado para prevenir accidentes qu\xEDmicos."},{id:"osha_306",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"El pictograma de OSHA con una 'Calavera y tibias cruzadas' significa:",opciones:["Inflamable","Irritante","Toxicidad aguda (Venero)","Peligro de explosi\xF3n"],respuesta_correcta:2,explicacion:"Indica sustancias que pueden causar la muerte con una exposici\xF3n m\xEDnima."},{id:"osha_307",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"\xBFCu\xE1l es el riesgo de seguridad de llenar un cilindro de recuperaci\xF3n al 100% de su capacidad volum\xE9trica?",opciones:["El refrigerante se ensucia","Explosi\xF3n del cilindro por expansi\xF3n hidrost\xE1tica si la temperatura ambiente aumenta","La bomba de vac\xEDo se da\xF1a","El refrigerante no se puede reciclar"],respuesta_correcta:1,explicacion:"Los cilindros nunca deben llenarse m\xE1s del 80% (regla de oro) para permitir la expansi\xF3n del l\xEDquido con el calor."},{id:"osha_308",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Est\xE1s presurizando un sistema con Nitr\xF3geno para buscar una fuga. \xBFCu\xE1l es el l\xEDmite de presi\xF3n de seguridad si el 'Design Pressure' de la placa es de 450 psi?",opciones:["600 psi","Nunca exceder la presi\xF3n de dise\xF1o indicada en la placa del fabricante","1000 psi","Hasta que se escuche el silbido de la fuga"],respuesta_correcta:1,explicacion:"Exceder la presi\xF3n de dise\xF1o puede causar la ruptura de componentes como el evaporador o el acumulador de succi\xF3n."},{id:"osha_309",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Si el refrigerante R-22 se expone a una llama abierta de soldadura, \xBFqu\xE9 gas altamente letal se produce?",opciones:["Ox\xEDgeno puro","Fosgeno (Phosgene)","Helio","Vapor de agua"],respuesta_correcta:1,explicacion:"La descomposici\xF3n t\xE9rmica de refrigerantes halogenados produce gas fosgeno, un agente qu\xEDmico mortal usado en guerras."},{id:"osha_310",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"\xBFC\xF3mo deben almacenarse los cilindros de gas comprimido (Nitr\xF3geno/Acetileno) en un veh\xEDculo de ACVOLT?",opciones:["Acostados para que no se caigan","En posici\xF3n vertical y asegurados con cadenas o correas","Debajo de las herramientas pesadas","No importa la posici\xF3n si tienen la tapa"],respuesta_correcta:1,explicacion:"El almacenamiento vertical evita que el cilindro se convierta en un proyectil si la v\xE1lvula se rompe."},{id:"osha_311",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Al limpiar un serpent\xEDn (coil) con \xE1cido, \xBFqu\xE9 sucede si se mezcla accidentalmente con cloro?",opciones:["Limpia mejor","Se produce gas cloro, que es altamente t\xF3xico y puede ser fatal si se inhala","La mezcla se vuelve rosa","No sucede nada"],respuesta_correcta:1,explicacion:"Nunca se deben mezclar productos qu\xEDmicos de limpieza; las reacciones pueden ser letales."},{id:"osha_312",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"\xBFQu\xE9 color de tanque identifica al refrigerante R-410A en el mercado (antes del cambio a gris uniforme)?",opciones:["Verde","Blanco","Rosado (Rose)","Celeste"],respuesta_correcta:2,explicacion:"El R-410A se identifica tradicionalmente con el color rosado."},{id:"osha_313",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"\xBFD\xF3nde debe estar disponible la carpeta de Hojas de Datos de Seguridad (SDS) en el sitio de trabajo?",opciones:["En la oficina central a 50 millas","Accesible para todos los empleados en todo momento durante su turno","En el cami\xF3n del due\xF1o bajo llave","No se necesitan si el t\xE9cnico sabe lo que hace"],respuesta_correcta:1,explicacion:"OSHA exige acceso inmediato a la informaci\xF3n de peligros qu\xEDmicos para todos los trabajadores."},{id:"osha_314",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"En un horno de gas, \xBFqu\xE9 dispositivo de seguridad cierra el gas si no se detecta llama?",opciones:["El termostato","El sensor de llama (Flame Sensor) o termocupla","El motor del soplador","El filtro de aire"],respuesta_correcta:1,explicacion:"Evita la acumulaci\xF3n de gas combustible no quemado, lo cual causar\xEDa una explosi\xF3n al intentar re-encender."},{id:"osha_315",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"\xBFPor qu\xE9 nunca se debe aplicar calor directo con un soplete a un cilindro de refrigerante para aumentar la presi\xF3n de carga?",opciones:["El refrigerante se quema","Riesgo de explosi\xF3n del cilindro por debilitamiento del metal y presi\xF3n interna extrema","La pintura del tanque se arruina","El refrigerante se vuelve \xE1cido"],respuesta_correcta:1,explicacion:"Se debe usar agua tibia (no m\xE1s de 110\xB0F) o una manta t\xE9rmica aprobada, nunca fuego directo."},{id:"osha_316",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"El tap\xF3n fusible (Fusible Plug) en un recibidor de l\xEDquido de un Chiller est\xE1 dise\xF1ado para derretirse a una temperatura espec\xEDfica para:",opciones:["Drenar el aceite","Liberar la presi\xF3n antes de que el tanque explote en caso de incendio","Medir la temperatura","Lubricar las v\xE1lvulas"],respuesta_correcta:1,explicacion:"Es un dispositivo de alivio de presi\xF3n por temperatura de un solo uso."},{id:"osha_317",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Un cilindro de refrigerante que muestra corrosi\xF3n profunda o abolladuras debe:",opciones:["Pintarse para que no se note","Vaciarse legalmente y descartarse (no rellenar)","Usarse solo a media presi\xF3n","Envolverse en cinta"],respuesta_correcta:1,explicacion:"La integridad estructural del cilindro es lo \xFAnico que contiene la presi\xF3n. Un cilindro da\xF1ado es una bomba en potencia."},{id:"osha_318",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"\xBFCu\xE1l es el color de las tuber\xEDas de agua refrigerada (Chilled Water) seg\xFAn el est\xE1ndar industrial?",opciones:["Rojo","Verde","Azul claro","Amarillo"],respuesta_correcta:2,explicacion:"El azul identifica sistemas de agua; el azul claro o con etiquetas espec\xEDficas indica agua fr\xEDa para procesos de HVAC."},{id:"osha_319",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Bajo el sistema GHS de OSHA, \xBFqu\xE9 palabra indica el nivel de peligro m\xE1s grave en una etiqueta?",opciones:["Caution (Precauci\xF3n)","Warning (Advertencia)","Danger (Peligro)","Notice (Aviso)"],respuesta_correcta:2,explicacion:"'Danger' se usa para los peligros m\xE1s severos; 'Warning' para los menos severos."},{id:"osha_320",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Un letrero de color 'Verde' con letras blancas indica:",opciones:["Peligro","Informaci\xF3n de seguridad (ej. Primeros auxilios, Salidas)","Precauci\xF3n","Radiaci\xF3n"],respuesta_correcta:1,explicacion:"El verde se usa para condiciones seguras, estaciones de lavado de ojos y camillas."},{id:"osha_321",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"El 'Silicio Cristalino' es un peligro respiratorio com\xFAn en construcci\xF3n al cortar concreto. \xBFQu\xE9 enfermedad causa a largo plazo?",opciones:["Gripe","Silicosis (cicatrizaci\xF3n irreversible de los pulmones)","Sordera","Dolor lumbar"],respuesta_correcta:1,explicacion:"La exposici\xF3n al polvo de s\xEDlice es una prioridad de salud ocupacional en OSHA debido a su letalidad."},{id:"osha_322",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"\xBFCu\xE1l es el formulario de OSHA donde se registran todas las lesiones y enfermedades laborales anualmente?",opciones:["Form 1040","Form 300 (Log of Work-Related Injuries and Illnesses)","W-2","I-9"],respuesta_correcta:1,explicacion:"El registro Form 300 es obligatorio para empresas con m\xE1s de 10 empleados y permite rastrear la seguridad de la empresa."},{id:"osha_323",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Si un t\xE9cnico mezcla lej\xEDa (cloro) con amon\xEDaco, \xBFqu\xE9 sucede?",opciones:["Limpia el doble","Se libera gas cloramina, que es altamente irritante y t\xF3xico para los pulmones","Se vuelve agua pura","Explota instant\xE1neamente"],respuesta_correcta:1,explicacion:"Es una reacci\xF3n qu\xEDmica cl\xE1sica en limpieza industrial que causa hospitalizaciones masivas."},{id:"osha_324",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"\xBFQu\xE9 es el 'PEL' (Permissible Exposure Limit)?",opciones:["El costo de la multa","El l\xEDmite m\xE1ximo de concentraci\xF3n de una sustancia qu\xEDmica al que un trabajador puede exponerse legalmente","El tiempo de descanso","La velocidad m\xE1xima de un montacargas"],respuesta_correcta:1,explicacion:"Es una norma obligatoria de OSHA para proteger contra enfermedades respiratorias y qu\xEDmicas."},{id:"osha_325",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H317: Puede provocar una reacci\xF3n al\xE9rgica en la piel' y 'H334: Puede provocar s\xEDntomas de alergia o asma en caso de inhalaci\xF3n'. \xBFQu\xE9 trabajador no debe manipular este producto?",opciones:["Trabajador con antecedentes de dermatitis at\xF3pica.","Trabajador con asma al\xE9rgica.","Trabajador con diabetes.","Trabajador con hipertensi\xF3n."],respuesta_correcta:1,explicacion:"H334 indica sensibilizaci\xF3n respiratoria; asm\xE1ticos al\xE9rgicos tienen alto riesgo de reacci\xF3n grave."},{id:"osha_326",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H226: L\xEDquido y vapores inflamables' y 'H332: Nocivo en caso de inhalaci\xF3n'. \xBFQu\xE9 distancia de almacenamiento a fuentes de ignici\xF3n es correcta?",opciones:["3 metros como m\xEDnimo.","Depende de la cantidad, pero m\xEDnimo 15 metros.","No hay distancia fija, debe estar en gabinete inflamable.","5 metros con ventilaci\xF3n forzada."],respuesta_correcta:2,explicacion:"NFPA requiere almacenamiento en gabinete ign\xEDfugo para cantidades > 25 litros."},{id:"osha_327",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H360: Puede perjudicar la fertilidad' y 'H361: Sospechoso de da\xF1ar la fertilidad'. \xBFQu\xE9 diferencia pr\xE1ctica hay entre H360 y H361?",opciones:["H360 tiene evidencia humana; H361 solo animal.","No hay diferencia, son equivalentes.","H360 aplica solo a mujeres; H361 a hombres.","H360 es agudo; H361 es cr\xF3nico."],respuesta_correcta:0,explicacion:"H360 = evidencia en humanos; H361 = evidencia limitada o solo en animales."},{id:"osha_328",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H351: Sospechoso de provocar c\xE1ncer' y 'H352: Puede ser nocivo para los lactantes'. \xBFQu\xE9 PPE adicional es obligatorio para mujeres embarazadas?",opciones:["Traje de protecci\xF3n qu\xEDmica categor\xEDa II.","Respirador con filtro HEPA.","Guantes de nitrilo doble capa.","Prohibici\xF3n de manipulaci\xF3n directa."],respuesta_correcta:3,explicacion:"Mujeres embarazadas o lactantes no deben manipular productos H351 o H352; reasignaci\xF3n laboral."},{id:"osha_329",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H220: Gas extremadamente inflamable' y 'H280: Contiene gas a presi\xF3n; puede explotar si se calienta'. \xBFQu\xE9 cilindro no debe almacenarse junto a este gas?",opciones:["Cilindro de ox\xEDgeno.","Cilindro de nitr\xF3geno.","Cilindro de arg\xF3n.","Cilindro de helio."],respuesta_correcta:0,explicacion:"Gas inflamable + ox\xEDgeno = riesgo de explosi\xF3n; separaci\xF3n m\xEDnima 6 metros."},{id:"osha_330",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H300: Mortal en caso de ingesti\xF3n' y 'H310: Mortal en contacto con la piel'. \xBFQu\xE9 PPE es obligatorio aunque no haya riesgo de salpicadura?",opciones:["Traje encapsulado nivel A.","Guantes de nitrilo y bata desechable.","Respirador de cara completa.","Gafas de seguridad solamente."],respuesta_correcta:0,explicacion:"H300 + H310 indican toxicidad d\xE9rmica y oral severa; requiere traje nivel A (encapsulado)."},{id:"osha_331",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H400: Muy t\xF3xico para los organismos acu\xE1ticos' y 'H411: T\xF3xico para los organismos acu\xE1ticos, con efectos duraderos'. \xBFQu\xE9 diferencia hay?",opciones:["H400 es m\xE1s peligroso que H411.","H411 es menos peligroso pero m\xE1s persistente.","No hay diferencia, solo redacci\xF3n.","H400 aplica a agua dulce; H411 a marina."],respuesta_correcta:1,explicacion:"H411 = toxicidad cr\xF3nica con efectos duraderos, pero menor toxicidad aguda que H400."},{id:"osha_332",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H350: Puede provocar c\xE1ncer' y 'H340: Puede provocar defectos gen\xE9ticos'. \xBFQu\xE9 tipo de guante es insuficiente aunque sea qu\xEDmicamente resistente?",opciones:["Nitrilo de 15 mil\xE9simas.","Neopreno de 20 mil\xE9simas.","Butilo de 10 mil\xE9simas.","Todos son insuficientes; se requiere guante de barrera multilaminado."],respuesta_correcta:3,explicacion:"Carcin\xF3genos y mut\xE1genos requieren guantes con tiempo de penetraci\xF3n > 480 min (barrera laminada)."},{id:"osha_333",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H225: L\xEDquido y vapores muy inflamables' y 'H316: Provoca irritaci\xF3n cut\xE1nea leve'. \xBFQu\xE9 extintor NO debe usarse?",opciones:["CO2.","Polvo ABC.","Espuma AFFF.","Agua pulverizada."],respuesta_correcta:3,explicacion:"Agua no es efectiva en l\xEDquidos inflamables (clase B)."},{id:"osha_334",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H330: Mortal en caso de inhalaci\xF3n' y 'H311: T\xF3xico en contacto con la piel'. \xBFQu\xE9 nivel de respiraci\xF3n es m\xEDnimo?",opciones:["Media cara con filtro P100.","M\xE1scara completa con suministro de aire (SCBA).","PAPR con filtro de gases.","Mascarilla N95."],respuesta_correcta:1,explicacion:"H330 indica toxicidad aguda por inhalaci\xF3n que requiere SCBA."},{id:"osha_335",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H224: L\xEDquido y vapores extremadamente inflamables' y 'H304: Puede ser mortal en caso de ingesti\xF3n y penetraci\xF3n en v\xEDas respiratorias'. \xBFQu\xE9 almacenamiento es incorrecto?",opciones:["Gabinetes inflamables clase I.","Refrigerador a prueba de explosi\xF3n.","Almacenamiento en \xE1rea con desag\xFCe al alcantarillado.","Almacenamiento en tambor met\xE1lico con respiradero."],respuesta_correcta:2,explicacion:"Desag\xFCe puede llevar l\xEDquido inflamable al alcantarillado, riesgo de explosi\xF3n."},{id:"osha_336",categoria:"OSHA_COMUNICACION_RIESGOS",pregunta:"Una SDS indica 'H370: Causa da\xF1os a los \xF3rganos' (h\xEDgado) y 'H372: Provoca da\xF1os en los \xF3rganos tras exposiciones prolongadas'. \xBFQu\xE9 prueba m\xE9dica es obligatoria?",opciones:["Pruebas de funci\xF3n hep\xE1tica (transaminasas).","Biopsia hep\xE1tica.","Ecograf\xEDa abdominal.","Ninguna, solo monitoreo cl\xEDnico."],respuesta_correcta:0,explicacion:"Da\xF1o hep\xE1tico requiere monitoreo de transaminasas (ALT, AST)."},{id:"osha_337",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Si un compa\xF1ero recibe una descarga el\xE9ctrica y sigue 'pegado' al cable, lo primero que haces es:",opciones:["Tirarle agua","Agarrarlo de la mano para jalarlo","Cortar la energ\xEDa desde el interruptor principal","Llamar al 911 antes de hacer nada"],respuesta_correcta:2,explicacion:"Nunca toques a la v\xEDctima directamente. Debes aislar la fuente de energ\xEDa o usar un objeto no conductor (madera seca) para separarlos."},{id:"osha_338",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un extintor debe estar ubicado a no m\xE1s de cu\xE1ntos pies de distancia en un \xE1rea donde se manejen l\xEDquidos inflamables:",opciones:["25 pies","50 pies","75 pies","100 pies"],respuesta_correcta:1,explicacion:"OSHA exige una distancia m\xE1xima de viaje de 50 pies en estas zonas de alto riesgo."},{id:"osha_339",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"El 'Flash Protection Boundary' se calcula bas\xE1ndose en qu\xE9 nivel de quemadura en la piel:",opciones:["Primer grado","Segundo grado","Tercer grado","Ninguna quemadura"],respuesta_correcta:1,explicacion:"El l\xEDmite se define como la distancia a la cual una persona sin EPP recibir\xEDa una quemadura de segundo grado (1.2 cal/cm2)."},{id:"osha_340",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Ante una quemadura el\xE9ctrica de entrada y salida, \xBFqu\xE9 es lo m\xE1s peligroso?",opciones:["La mancha en la piel","El da\xF1o interno a \xF3rganos y el ritmo card\xEDaco que no es visible","El olor a quemado","Que se rompa la ropa"],respuesta_correcta:1,explicacion:"La electricidad viaja por los nervios y vasos sangu\xEDneos, pudiendo detener el coraz\xF3n horas despu\xE9s del contacto."},{id:"osha_341",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Al recuperar refrigerante de un sistema que sufri\xF3 una quemadura de compresor (burnout), \xBFqu\xE9 equipo de protecci\xF3n personal adicional es obligatorio por seguridad qu\xEDmica?",opciones:["Solo guantes de tela","Protecci\xF3n ocular y guantes de nitrilo resistentes a \xE1cidos","M\xE1scara de ox\xEDgeno aut\xF3noma","No se requiere nada especial"],respuesta_correcta:1,explicacion:"Un burnout genera \xE1cidos fluorh\xEDdricos y clorh\xEDdricos en el aceite que pueden causar quemaduras qu\xEDmicas severas en la piel y ojos."},{id:"osha_342",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Si un t\xE9cnico sufre una quemadura por fr\xEDo extremo (frostbite) con refrigerante l\xEDquido, el primer paso es:",opciones:["Frotar la zona vigorosamente","Sumergir en agua caliente a 110\xB0F","Lavar suavemente con agua tibia y buscar atenci\xF3n m\xE9dica inmediata","Poner hielo sobre la quemadura"],respuesta_correcta:2,explicacion:"El agua tibia ayuda a recuperar la temperatura gradualmente; frotar puede destruir los tejidos da\xF1ados por los cristales de hielo."},{id:"osha_343",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"\xBFPor qu\xE9 es peligroso usar un encendedor de cigarrillos para prender un soplete de oxiacetileno?",opciones:["Es de mala educaci\xF3n","La mano queda demasiado cerca de la ignici\xF3n y el encendedor puede explotar por el calor","La llama es muy peque\xF1a","Se acaba el gas del encendedor"],respuesta_correcta:1,explicacion:"Se debe usar siempre un chispero (striker) dise\xF1ado para mantener la mano a una distancia segura."},{id:"osha_344",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un t\xE9cnico trabajando en una azotea a 105\xB0F siente mareos, piel seca y caliente, y confusi\xF3n. \xBFQu\xE9 debe hacer el compa\xF1ero?",opciones:["Darle una soda","Llamar al 911 de inmediato; son s\xEDntomas de un golpe de calor (heat stroke)","Decirle que descanse 5 minutos","Ponerle m\xE1s ropa para que no se queme"],respuesta_correcta:1,explicacion:"El golpe de calor es una emergencia m\xE9dica donde el cuerpo pierde la capacidad de regular su temperatura."},{id:"osha_345",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Para usar un extintor correctamente, se sigue la t\xE9cnica 'PASS'. \xBFQu\xE9 significa la primera 'P'?",opciones:["Presionar el gatillo","Puntar a la base","Pull (Tirar del pasador de seguridad)","Pasar el extintor al jefe"],respuesta_correcta:2,explicacion:"Pull (Tirar), Aim (Apuntar), Squeeze (Apretar), Sweep (Barrer)."},{id:"osha_346",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Si un objeto est\xE1 incrustado en el ojo de un t\xE9cnico, \xBFcu\xE1l es el procedimiento?",opciones:["Sacarlo r\xE1pidamente con pinzas","No intentar removerlo, cubrir ambos ojos para evitar movimiento ocular y buscar emergencias","Lavar con mucha agua a presi\xF3n","Poner un parche solo en el ojo herido"],respuesta_correcta:1,explicacion:"Mover el ojo sano hace que el herido tambi\xE9n se mueva (movimiento simp\xE1tico), lo que puede causar m\xE1s da\xF1o con el objeto incrustado."},{id:"osha_347",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"\xBFQu\xE9 tipo de fuego es un incendio de virutas de Magnesio o Titanio?",opciones:["Clase A","Clase B","Clase D","Clase K"],respuesta_correcta:2,explicacion:"Clase D es para metales combustibles. Usar agua en estos fuegos puede causar una explosi\xF3n de hidr\xF3geno."},{id:"osha_348",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un extintor de Hal\xF3n o agentes limpios es preferible en cuartos de servidores o paneles el\xE9ctricos porque:",opciones:["Es m\xE1s barato","No deja residuos conductores ni corrosivos que da\xF1en la electr\xF3nica","Huele mejor","Es de color verde"],respuesta_correcta:1,explicacion:"El polvo qu\xEDmico seco (ABC) es corrosivo y puede destruir circuitos electr\xF3nicos aunque no se hayan quemado."},{id:"osha_349",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Si un extintor de incendios est\xE1 marcado como 'No-rechargeable', \xBFqu\xE9 se hace tras usarlo parcialmente?",opciones:["Guardarlo para otra vez","Descargarlo completamente y desecharlo","Llenarlo con agua","Ponerle una etiqueta de 'Lleno'"],respuesta_correcta:1,explicacion:"Los extintores desechables pierden presi\xF3n tras el primer uso y no son confiables."},{id:"osha_350",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un extintor de incendios debe estar disponible a no m\xE1s de cu\xE1ntos pies de un \xE1rea donde se usa soplete (trabajo en caliente)?",opciones:["10 pies","30 pies","100 pies","No se requiere"],respuesta_correcta:1,explicacion:"En trabajos en caliente, la respuesta inmediata es cr\xEDtica para evitar incendios fuera de control."},{id:"osha_351",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"\xBFQu\xE9 tipo de fuego NO debe intentar apagar un t\xE9cnico con un extintor de agua?",opciones:["Papel","Madera","Aceites de cocina o equipos el\xE9ctricos","Basura"],respuesta_correcta:2,explicacion:"El agua conduce la electricidad y esparce el aceite encendido (fuego clase B/C)."},{id:"osha_352",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"\xBFQu\xE9 significa la letra 'K' en un extintor de incendios?",opciones:["Kilo (Pesado)","Kitchen (Fuegos de aceites vegetales o grasas en cocinas comerciales)","Krypton","Killer (Para fuegos grandes)"],respuesta_correcta:1,explicacion:"Los fuegos de grasa reaccionan violentamente al agua y requieren qu\xEDmicos h\xFAmedos espec\xEDficos (Acetato de potasio)."},{id:"osha_353",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con herida en el t\xF3rax por arma blanca. El cuchillo sigue insertado. \xBFQu\xE9 posici\xF3n de transporte es la correcta?",opciones:["Dec\xFAbito lateral izquierdo.","Dec\xFAbito supino con el objeto estabilizado.","Sentado con inclinaci\xF3n hacia la herida.","Dec\xFAbito prono."],respuesta_correcta:1,explicacion:"Supino con objeto estabilizado evita desplazamiento y da\xF1o adicional."},{id:"osha_354",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con quemadura por explosi\xF3n de polvo de harina tiene part\xEDculas incrustadas. \xBFQu\xE9 acci\xF3n est\xE1 contraindicada?",opciones:["Enfriar con agua corriente.","Retirar part\xEDculas grandes con pinzas.","Cubrir con ap\xF3sito antiadherente.","Aplicar pomada antibi\xF3tica."],respuesta_correcta:1,explicacion:"No retirar part\xEDculas incrustadas; pueden estar en dermis y causar sangrado."},{id:"osha_355",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con hipotermia severa (28\xB0C) est\xE1 en paro card\xEDaco. \xBFHasta qu\xE9 temperatura se debe continuar RCP antes de declarar muerte?",opciones:["30 minutos de RCP.","Hasta que la temperatura corporal supere 32\xB0C.","Despu\xE9s de 3 dosis de epinefrina.","Hasta llegar al hospital."],respuesta_correcta:1,explicacion:"En hipotermia, RCP contin\xFAa hasta recalentamiento > 32\xB0C, incluso si dura horas."},{id:"osha_356",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con intoxicaci\xF3n por metanol ha ingerido 100 mL. \xBFQu\xE9 ant\xEDdoto espec\xEDfico debe administrarse adem\xE1s de etanol?",opciones:["Naloxona.","Fomepizol (4-metilpirazol).","Atropina.","N-acetilciste\xEDna."],respuesta_correcta:1,explicacion:"Fomepizol inhibe alcohol deshidrogenasa, previniendo formaci\xF3n de \xE1cido f\xF3rmico."},{id:"osha_357",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con convulsi\xF3n por abstinencia alcoh\xF3lica. \xBFQu\xE9 medicamento de primeros auxilios puede administrarse por v\xEDa oral si est\xE1 consciente?",opciones:["Diazepam en tabletas.","Tiamina (vitamina B1).","Glucosa oral.","Ninguno, solo atenci\xF3n m\xE9dica."],respuesta_correcta:1,explicacion:"Tiamina previene encefalopat\xEDa de Wernicke; no es anticonvulsivante pero es parte del manejo."},{id:"osha_358",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con intoxicaci\xF3n por \xF3rgano-fosforados tiene miosis, bradicardia y diarrea. \xBFQu\xE9 ant\xEDdoto debe administrarse primero?",opciones:["Atropina intravenosa.","Pralidoxima (2-PAM).","Diazepam.","Naloxona."],respuesta_correcta:0,explicacion:"Atropina revierte efectos muscar\xEDnicos (bradicardia, miosis); pralidoxima reactiva colinesterasa."},{id:"osha_359",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con fractura abierta de f\xE9mur tiene el hueso expuesto. \xBFQu\xE9 acci\xF3n es prioritaria?",opciones:["Limpiar el hueso con soluci\xF3n salina.","Cubrir con ap\xF3sito est\xE9ril h\xFAmedo.","Reducir la fractura manualmente.","Aplicar torniquete proximal."],respuesta_correcta:1,explicacion:"Cubrir hueso expuesto con ap\xF3sito est\xE9ril h\xFAmedo previene desecaci\xF3n; no limpiar ni reducir."},{id:"osha_360",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con picadura de avispa en la lengua desarrolla estridor. \xBFQu\xE9 acci\xF3n es prioritaria?",opciones:["Aplicar hielo en la lengua.","Administrar antihistam\xEDnico oral.","Preparar para v\xEDa a\xE9rea avanzada (cricotiroidotom\xEDa).","Colocar en posici\xF3n de trendelenburg."],respuesta_correcta:2,explicacion:"Estridor indica obstrucci\xF3n inminente; preparar para v\xEDa a\xE9rea quir\xFArgica."},{id:"osha_361",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con quemadura el\xE9ctrica en mano derecha y pie izquierdo. \xBFQu\xE9 \xF3rgano debe monitorearse por 24 horas?",opciones:["Coraz\xF3n (arritmias).","Ri\xF1ones (mioglobinuria).","Pulmones (edema).","H\xEDgado (necrosis)."],respuesta_correcta:1,explicacion:"Lesi\xF3n el\xE9ctrica con trayecto muscular puede causar rabdomi\xF3lisis y da\xF1o renal."},{id:"osha_362",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con herida punzante en el pie, clavado por un clavo oxidado. \xBFQu\xE9 profilaxis es obligatoria adem\xE1s de limpieza?",opciones:["Vacuna antitet\xE1nica (refuerzo).","Antibi\xF3tico oral.","Inmunoglobulina antitet\xE1nica.","Ninguna, el clavo oxidado no es riesgo."],respuesta_correcta:0,explicacion:"Herida punzante con clavo oxidado requiere refuerzo de toxoide tet\xE1nico si han pasado > 5 a\xF1os."},{id:"osha_363",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con intoxicaci\xF3n por paracetamol (acetaminof\xE9n) ingiri\xF3 15 gramos. \xBFQu\xE9 ant\xEDdoto debe administrarse?",opciones:["N-acetilciste\xEDna (NAC).","Carb\xF3n activado solamente.","Flumazenil.","Naloxona."],respuesta_correcta:0,explicacion:"NAC es ant\xEDdoto espec\xEDfico para intoxicaci\xF3n por paracetamol."},{id:"osha_364",categoria:"OSHA_PRIMEROS_AUXILIOS",pregunta:"Un auxiliado con hemorragia por herida en el cuello. \xBFQu\xE9 acci\xF3n es prioritaria?",opciones:["Aplicar torniquete en el cuello.","Presi\xF3n directa con los dedos.","Aplicar ap\xF3sito oclusivo.","Colocar en posici\xF3n de trendelenburg."],respuesta_correcta:1,explicacion:"Presi\xF3n directa con dedos (evitando comprimir tr\xE1quea) es prioridad; no torniquete en cuello."},{id:"osha_365",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 caracter\xEDstica define una quemadura de PRIMER grado seg\xFAn la clasificaci\xF3n m\xE9dica est\xE1ndar?",opciones:["Destrucci\xF3n total de la dermis con tejido carbonizado visible","Ampollas grandes con l\xEDquido seroso y dolor intenso al tacto","Enrojecimiento superficial de la epidermis sin formaci\xF3n de ampollas","Necrosis del tejido subcut\xE1neo con p\xE9rdida de sensibilidad"],respuesta_correcta:2,explicacion:"Las quemaduras de primer grado afectan solo la capa superficial de la epidermis, causando enrojecimiento y dolor pero sin ampollas. Las ampollas indican segundo grado y la destrucci\xF3n total de dermis indica tercer grado."},{id:"osha_366",categoria:"OSHA_QUEMADURAS",pregunta:"Seg\xFAn la 'Regla del 9' para adultos, \xBFqu\xE9 porcentaje de superficie corporal total representa CADA pierna completa?",opciones:["9% de la superficie corporal total por cada extremidad inferior","18% de la superficie corporal total por cada extremidad inferior","14% de la superficie corporal total por cada extremidad inferior","27% de la superficie corporal total por cada extremidad inferior"],respuesta_correcta:1,explicacion:"La Regla del 9 asigna 18% a cada pierna completa (9% anterior + 9% posterior). Cada brazo es 9%, el torso anterior 18%, el torso posterior 18%, la cabeza 9% y el perineo 1%."},{id:"osha_367",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFCu\xE1l es la diferencia principal entre una quemadura de segundo grado superficial y una de segundo grado profunda?",opciones:["La superficial destruye toda la dermis mientras la profunda solo la epidermis","La profunda afecta la dermis reticular y puede requerir injerto de piel","La superficial siempre requiere injerto mientras la profunda sana sola","La profunda solo afecta la epidermis y sana en menos de cinco d\xEDas"],respuesta_correcta:1,explicacion:"La quemadura de segundo grado profunda afecta la dermis reticular (capa profunda), tiene menos dolor por da\xF1o nervioso, y frecuentemente requiere injerto. La superficial afecta solo la dermis papilar y generalmente sana sin injerto en 2-3 semanas."},{id:"osha_368",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFA partir de qu\xE9 porcentaje de superficie corporal quemada se considera una quemadura como CR\xCDTICA en un adulto seg\xFAn protocolos de emergencia?",opciones:["Cuando supera el 5% de la superficie corporal total del paciente","Cuando supera el 25% de la superficie corporal total del paciente","Cuando supera el 15% de la superficie corporal total del paciente","Cuando supera el 50% de la superficie corporal total del paciente"],respuesta_correcta:1,explicacion:"Quemaduras que cubren m\xE1s del 25% de la superficie corporal en adultos se consideran cr\xEDticas y requieren atenci\xF3n en un centro especializado en quemados."},{id:"osha_369",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 caracter\xEDstica cl\xEDnica indica que una quemadura es de TERCER grado y no de segundo grado profunda?",opciones:["El paciente reporta dolor extremo e insoportable en toda el \xE1rea afectada","El tejido presenta apariencia blanquecina o cerosa con ausencia total de dolor","Se forman ampollas tensas llenas de l\xEDquido claro con bordes eritematosos","La piel muestra enrojecimiento intenso que blanquea al aplicar presi\xF3n digital"],respuesta_correcta:1,explicacion:"Las quemaduras de tercer grado destruyen todas las capas de la piel incluyendo terminaciones nerviosas, por lo que NO hay dolor. La apariencia es cerosa, blanquecina o carbonizada."},{id:"osha_370",categoria:"OSHA_QUEMADURAS",pregunta:"Al realizar brazing con soplete oxiacetil\xE9nico en tuber\xEDas de cobre, \xBFcu\xE1l es la causa M\xC1S frecuente de quemaduras en t\xE9cnicos HVAC?",opciones:["Contacto accidental con tuber\xEDas reci\xE9n soldadas que retienen calor residual","Explosi\xF3n inmediata del tanque de acetileno por sobrecalentamiento ambiental","Derretimiento espont\xE1neo del material de aporte sobre las manos del t\xE9cnico","Radiaci\xF3n infrarroja directa del soplete que penetra los guantes de cuero"],respuesta_correcta:0,explicacion:"La causa m\xE1s frecuente de quemaduras durante brazing es tocar tuber\xEDas que a\xFAn est\xE1n calientes. El cobre retiene calor y puede superar los 500\xB0F."},{id:"osha_371",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFA qu\xE9 temperatura aproximada opera la llama de un soplete oxiacetil\xE9nico usado com\xFAnmente para brazing en refrigeraci\xF3n?",opciones:["Alcanza aproximadamente 1,200\xB0F que es suficiente para fundir cobre puro","Alcanza aproximadamente 5,800\xB0F siendo la llama de gas m\xE1s caliente disponible","Alcanza aproximadamente 3,200\xB0F similar a un soplete de propano est\xE1ndar","Alcanza aproximadamente 8,500\xB0F superando el punto de fusi\xF3n del acero inoxidable"],respuesta_correcta:1,explicacion:"La llama oxiacetil\xE9nica alcanza aproximadamente 5,800\xB0F (3,200\xB0C), haci\xE9ndola la llama de gas combustible m\xE1s caliente."},{id:"osha_372",categoria:"OSHA_QUEMADURAS",pregunta:"Cuando se realiza soldering en l\xEDneas de refrigeraci\xF3n, \xBFcu\xE1l es la distancia m\xEDnima de seguridad recomendada para materiales combustibles?",opciones:["Se requiere un m\xEDnimo de 18 pulgadas entre la llama y materiales combustibles","Se requiere un m\xEDnimo de 6 pulgadas entre la llama y materiales combustibles","Se requiere un m\xEDnimo de 36 pulgadas entre la llama y materiales combustibles","Se requiere un m\xEDnimo de 48 pulgadas entre la llama y materiales combustibles"],respuesta_correcta:2,explicacion:"OSHA y NFPA 51B requieren un m\xEDnimo de 36 pulgadas (3 pies) entre la llama y cualquier material combustible."},{id:"osha_373",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFPor qu\xE9 es especialmente peligroso usar un soplete cerca de un compresor que ha tenido un burnout el\xE9ctrico interno?",opciones:["Porque el compresor fr\xEDo puede explotar por el cambio brusco de temperatura externa","Porque el aceite descompuesto genera \xE1cido fluorh\xEDdrico al exponerse a llama abierta","Porque el metal del compresor se debilita y colapsa bajo el calor del soplete aplicado","Porque el refrigerante residual en estado l\xEDquido se expande y congela la llama directa"],respuesta_correcta:1,explicacion:"Cuando un compresor sufre burnout, el aceite y el refrigerante se descomponen. Al aplicar llama abierta, los residuos de refrigerante halogenado generan \xE1cido fluorh\xEDdrico (HF) y fosgeno, gases extremadamente t\xF3xicos."},{id:"osha_374",categoria:"OSHA_QUEMADURAS",pregunta:"Al soldar tuber\xEDas de cobre en un \xE1tico con aislamiento de fibra de vidrio, \xBFqu\xE9 precauci\xF3n es OBLIGATORIA seg\xFAn OSHA?",opciones:["Mojar el aislamiento con agua antes de comenzar para que act\xFAe como barrera t\xE9rmica","Usar manta cortafuegos y mantener vigilancia contra incendios por 30 minutos despu\xE9s","Retirar completamente todo el aislamiento del \xE1tico antes de encender cualquier soplete","Aplicar gel retardante de fuego directamente sobre las tuber\xEDas de cobre a soldar"],respuesta_correcta:1,explicacion:"OSHA requiere el uso de manta cortafuegos (fire blanket) y fire watch por m\xEDnimo 30 minutos despu\xE9s de completar el trabajo con llama."},{id:"osha_375",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFCu\xE1l es la principal diferencia entre una quemadura el\xE9ctrica y una quemadura t\xE9rmica convencional en t\xE9rminos de evaluaci\xF3n m\xE9dica?",opciones:["La quemadura el\xE9ctrica solo afecta la piel mientras la t\xE9rmica da\xF1a \xF3rganos internos","La quemadura el\xE9ctrica causa da\xF1o interno severo que no es visible externamente","La quemadura t\xE9rmica requiere monitoreo card\xEDaco mientras la el\xE9ctrica no lo necesita","La quemadura el\xE9ctrica sana m\xE1s r\xE1pido porque la corriente cauteriza los vasos sangu\xEDneos"],respuesta_correcta:1,explicacion:"Las quemaduras el\xE9ctricas son enga\xF1osas: la herida externa puede parecer peque\xF1a pero la corriente viaja por tejidos internos causando da\xF1o masivo. Se le llama 'iceberg injury'."},{id:"osha_376",categoria:"OSHA_QUEMADURAS",pregunta:"En una lesi\xF3n por arc flash el\xE9ctrico, \xBFqu\xE9 temperatura puede alcanzar el arco el\xE9ctrico en el punto de falla?",opciones:["Aproximadamente 2,500\xB0F similar a la temperatura de un soplete de propano industrial","Aproximadamente 35,000\xB0F superando la temperatura de la superficie del sol terrestre","Aproximadamente 8,000\xB0F equivalente a la temperatura de un horno de fundici\xF3n est\xE1ndar","Aproximadamente 15,000\xB0F comparable a la llama de un cohete de combustible l\xEDquido"],respuesta_correcta:1,explicacion:"Un arco el\xE9ctrico puede alcanzar temperaturas de hasta 35,000\xB0F (19,400\xB0C), aproximadamente cuatro veces la temperatura de la superficie del sol."},{id:"osha_377",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 tipo de monitoreo m\xE9dico es OBLIGATORIO despu\xE9s de que un t\xE9cnico sufre una descarga el\xE9ctrica significativa, aunque no presente quemaduras visibles?",opciones:["Radiograf\xEDa de t\xF3rax para verificar posibles fracturas costales por espasmo muscular","Monitoreo card\xEDaco continuo por m\xEDnimo 24 horas para detectar arritmias tard\xEDas","An\xE1lisis de sangre para medir niveles de electrolitos y minerales en el suero","Resonancia magn\xE9tica cerebral para descartar da\xF1o neurol\xF3gico por la corriente el\xE9ctrica"],respuesta_correcta:1,explicacion:"El monitoreo card\xEDaco por 24 horas es obligatorio porque la corriente puede causar arritmias que se manifiestan horas despu\xE9s del incidente."},{id:"osha_378",categoria:"OSHA_QUEMADURAS",pregunta:"Seg\xFAn NFPA 70E, \xBFqu\xE9 nivel m\xEDnimo de protecci\xF3n arc-rated debe usar un t\xE9cnico HVAC al trabajar en un panel el\xE9ctrico energizado de 480V?",opciones:["Ropa con clasificaci\xF3n arc rating m\xEDnimo de 4 cal/cm\xB2 para esta categor\xEDa de riesgo","Ropa con clasificaci\xF3n arc rating m\xEDnimo de 8 cal/cm\xB2 para esta categor\xEDa de riesgo","Ropa con clasificaci\xF3n arc rating m\xEDnimo de 2 cal/cm\xB2 para esta categor\xEDa de riesgo","Ropa con clasificaci\xF3n arc rating m\xEDnimo de 1 cal/cm\xB2 para esta categor\xEDa de riesgo"],respuesta_correcta:1,explicacion:"Para paneles de 480V, NFPA 70E clasifica el riesgo como Categor\xEDa 2, requiriendo ropa arc-rated de m\xEDnimo 8 cal/cm\xB2."},{id:"osha_379",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFPor qu\xE9 las quemaduras el\xE9ctricas frecuentemente presentan una herida de ENTRADA peque\xF1a y una herida de SALIDA m\xE1s grande y destructiva?",opciones:["Porque la corriente pierde velocidad al salir y se acumula generando m\xE1s calor concentrado","Porque la electricidad se dispersa al entrar pero se concentra en un punto peque\xF1o al salir","Porque la corriente se concentra al entrar pero al salir rompe tejido buscando el camino a tierra","Porque el cuerpo amplifica el voltaje internamente haciendo que la salida sea m\xE1s poderosa"],respuesta_correcta:2,explicacion:"La corriente entra por un punto concentrado, viaja por tejidos internos, y al salir rompe tejido para escapar hacia tierra, creando una herida de salida m\xE1s grande."},{id:"osha_380",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 tipo de quemadura qu\xEDmica es M\xC1S peligrosa y penetra m\xE1s profundamente en los tejidos?",opciones:["Las quemaduras por \xE1cidos fuertes porque destruyen prote\xEDnas mediante coagulaci\xF3n inmediata","Las quemaduras por \xE1lcalis porque lic\xFAan los tejidos y contin\xFAan penetrando en profundidad","Las quemaduras por solventes org\xE1nicos porque disuelven la grasa subcut\xE1nea r\xE1pidamente","Las quemaduras por oxidantes porque generan reacci\xF3n exot\xE9rmica con el agua corporal presente"],respuesta_correcta:1,explicacion:"Los \xE1lcalis causan necrosis por licuefacci\xF3n: disuelven los tejidos y siguen penetrando. Los \xE1cidos causan necrosis por coagulaci\xF3n que forma una escara protectora que limita la penetraci\xF3n."},{id:"osha_381",categoria:"OSHA_QUEMADURAS",pregunta:"Si un t\xE9cnico HVAC sufre una salpicadura de \xE1cido de bater\xEDa (\xE1cido sulf\xFArico) en la piel, \xBFcu\xE1l es el primer paso correcto?",opciones:["Aplicar bicarbonato de sodio directamente sobre la piel para neutralizar el \xE1cido r\xE1pidamente","Lavar con agua corriente abundante durante m\xEDnimo 20 minutos sin intentar neutralizar","Secar el \xE1rea con toallas limpias y cubrir con vendaje est\xE9ril absorbente sin mojar la zona","Aplicar vinagre diluido para contrarrestar el pH del \xE1cido antes de enjuagar con agua tibia"],respuesta_correcta:1,explicacion:"SIEMPRE lavar con agua corriente abundante durante m\xEDnimo 20 minutos. NUNCA neutralizar un \xE1cido con una base porque la reacci\xF3n genera calor adicional."},{id:"osha_382",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 componente usado en HVAC durante brazing puede causar quemaduras qu\xEDmicas en la piel y los ojos por contacto?",opciones:["El nitr\xF3geno presurizado usado para purga durante la soldadura de tuber\xEDas de cobre","El flux de brazing que contiene compuestos de fluoruro y boro altamente corrosivos","El alambre de aporte de plata que libera part\xEDculas met\xE1licas irritantes por contacto","La pasta selladora de roscas que contiene teflon y compuestos de petr\xF3leo concentrados"],respuesta_correcta:1,explicacion:"El flux para brazing contiene compuestos de fluoruro y boro que son corrosivos y pueden causar quemaduras qu\xEDmicas en piel y ojos."},{id:"osha_383",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFPor qu\xE9 los solventes de limpieza usados para desengrase de serpentines pueden causar quemaduras qu\xEDmicas severas?",opciones:["Porque reaccionan con el aluminio del serpent\xEDn creando gas hidr\xF3geno que enciende la piel","Porque contienen \xE1cidos o \xE1lcalis concentrados que destruyen la barrera protectora de la piel","Porque elevan la temperatura de la superficie met\xE1lica causando quemaduras t\xE9rmicas indirectas","Porque generan vapores que condensan sobre la piel formando una capa \xE1cida por contacto a\xE9reo"],respuesta_correcta:1,explicacion:"Los limpiadores de serpentines contienen \xE1cidos fuertes (HCl) o \xE1lcalis fuertes (NaOH) que causan quemaduras qu\xEDmicas severas."},{id:"osha_384",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFCu\xE1nto tiempo m\xEDnimo debe lavarse con agua una quemadura qu\xEDmica por \xE1lcali (como hidr\xF3xido de sodio)?",opciones:["Lavar durante m\xEDnimo 5 minutos con agua fr\xEDa directamente sobre el \xE1rea contaminada","Lavar durante m\xEDnimo 10 minutos alternando agua fr\xEDa y caliente sobre la lesi\xF3n","Lavar durante m\xEDnimo 20 minutos con agua corriente continua sin detenerse ni frotar","Lavar durante m\xEDnimo 2 minutos con soluci\xF3n salina est\xE9ril a temperatura controlada"],respuesta_correcta:2,explicacion:"Las quemaduras por \xE1lcali requieren lavado con agua corriente durante m\xEDnimo 20 minutos. Los \xE1lcalis penetran profundamente y el lavado prolongado es esencial."},{id:"osha_385",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 sucede cuando refrigerante l\xEDquido R-410A se libera y hace contacto directo con la piel desnuda de un t\xE9cnico?",opciones:["Causa irritaci\xF3n leve similar a una picadura de insecto que desaparece en pocos minutos","Produce quemaduras por fr\xEDo instant\xE1neas ya que el refrigerante hierve a -61\xB0F aproximadamente","Genera una reacci\xF3n al\xE9rgica que produce ampollas t\xE9rmicas por sensibilidad al compuesto qu\xEDmico","Crea una capa protectora de hielo sobre la piel que previene da\xF1o si se remueve inmediatamente"],respuesta_correcta:1,explicacion:"El R-410A tiene punto de ebullici\xF3n de -61\xB0F (-52\xB0C). Al contacto con la piel se evapora absorbiendo calor, causando frostbite instant\xE1neo."},{id:"osha_386",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFPor qu\xE9 es peligroso usar guantes de l\xE1tex o nitrilo delgados cuando se manipulan cilindros de refrigerante?",opciones:["Porque el l\xE1tex reacciona qu\xEDmicamente con el refrigerante formando compuestos t\xF3xicos vol\xE1tiles","Porque la est\xE1tica del l\xE1tex puede generar chispas que encienden el refrigerante en estado gaseoso","Porque el refrigerante l\xEDquido puede traspasar guantes delgados causando frostbite por contacto","Porque los guantes reducen la sensibilidad impidiendo detectar fugas por vibraci\xF3n de las mangueras"],respuesta_correcta:2,explicacion:"Los guantes delgados NO protegen contra refrigerante l\xEDquido. El l\xEDquido puede penetrar o congelar el guante contra la piel, causando frostbite severo."},{id:"osha_387",categoria:"OSHA_QUEMADURAS",pregunta:"Si un t\xE9cnico sufre frostbite por contacto con refrigerante l\xEDquido en los dedos, \xBFcu\xE1l es el tratamiento correcto?",opciones:["Frotar vigorosamente los dedos para restaurar la circulaci\xF3n sangu\xEDnea lo m\xE1s r\xE1pido posible","Sumergir los dedos en agua caliente a 140\xB0F para recalentar el tejido de forma inmediata","Sumergir los dedos en agua tibia entre 100\xB0F y 105\xB0F sin frotar el \xE1rea congelada afectada","Aplicar hielo adicional sobre el \xE1rea para reducir la inflamaci\xF3n antes de calentar gradualmente"],respuesta_correcta:2,explicacion:"Sumergir en agua tibia (100-105\xB0F / 38-40\xB0C) sin frotar. Frotar causa da\xF1o mec\xE1nico al tejido congelado. Agua muy caliente causa quemaduras adicionales."},{id:"osha_388",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 riesgo de quemaduras por fr\xEDo existe al trabajar con nitr\xF3geno l\xEDquido durante congelamiento de tuber\xEDas en HVAC?",opciones:["El nitr\xF3geno l\xEDquido a -321\xB0F puede causar congelamiento instant\xE1neo de tejidos en menos de un segundo","El nitr\xF3geno l\xEDquido solo es peligroso si se ingiere ya que sobre la piel se evapora sin causar da\xF1o","El nitr\xF3geno l\xEDquido causa quemaduras qu\xEDmicas por su acidez natural al contacto con tejido humano","El nitr\xF3geno l\xEDquido presenta riesgo solo por inhalaci\xF3n ya que desplaza el ox\xEDgeno en \xE1reas cerradas"],respuesta_correcta:0,explicacion:"El nitr\xF3geno l\xEDquido hierve a -321\xB0F (-196\xB0C) y puede causar congelamiento instant\xE1neo y destrucci\xF3n de tejidos en fracciones de segundo."},{id:"osha_389",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFCu\xE1l es el rango de temperatura del agua recomendado para enfriar una quemadura t\xE9rmica seg\xFAn protocolos actualizados?",opciones:["Agua helada entre 32\xB0F y 40\xB0F aplicada directamente para m\xE1ximo efecto de enfriamiento","Agua fr\xEDa corriente entre 60\xB0F y 77\xB0F aplicada durante 10 a 20 minutos continuos","Agua caliente entre 90\xB0F y 100\xB0F para evitar hipotermia localizada en el tejido da\xF1ado","Agua a temperatura ambiente exacta de 72\xB0F aplicada en intervalos de 5 minutos con descanso"],respuesta_correcta:1,explicacion:"Agua fr\xEDa corriente entre 60\xB0F y 77\xB0F (15-25\xB0C) durante 10-20 minutos. NO usar agua helada ni hielo porque causa vasoconstricci\xF3n."},{id:"osha_390",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFCu\xE1l de las siguientes acciones est\xE1 CONTRAINDICADA al tratar quemaduras de segundo grado con ampollas?",opciones:["Cubrir la quemadura con un ap\xF3sito est\xE9ril limpio y seco sin apretar contra la herida","Reventar las ampollas para drenar el l\xEDquido y aplicar ung\xFCento antibi\xF3tico directamente","Enfriar la quemadura con agua fr\xEDa limpia corriente durante un m\xEDnimo de diez minutos","Remover anillos o joyer\xEDa cercana antes de que se desarrolle inflamaci\xF3n en el \xE1rea afectada"],respuesta_correcta:1,explicacion:"NUNCA reventar las ampollas. Act\xFAan como barrera natural contra infecciones. Solo personal m\xE9dico debe manejarlas."},{id:"osha_391",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFPor qu\xE9 NO se debe aplicar hielo directamente sobre una quemadura t\xE9rmica aunque el t\xE9cnico sienta dolor intenso?",opciones:["Porque el hielo contamina la herida con bacterias del agua congelada no est\xE9ril utilizada","Porque el hielo causa vasoconstricci\xF3n que reduce flujo sangu\xEDneo y agrava el da\xF1o tisular","Porque el hielo eleva la temperatura de la quemadura por efecto rebote t\xE9rmico al retirarlo","Porque el hielo reacciona con la piel quemada creando una costra que impide la cicatrizaci\xF3n"],respuesta_correcta:1,explicacion:"El hielo causa vasoconstricci\xF3n severa, reduciendo el flujo sangu\xEDneo. Tambi\xE9n puede causar frostbite adicional en el tejido ya comprometido."},{id:"osha_392",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 sustancia com\xFAnmente aplicada como remedio casero NUNCA debe usarse en quemaduras?",opciones:["Aloe vera puro aplicado directamente de la planta sobre la quemadura superficial reciente","Mantequilla o aceite porque atrapa el calor dentro del tejido y aumenta el da\xF1o t\xE9rmico","Soluci\xF3n salina est\xE9ril al 0.9% para irrigaci\xF3n suave y limpieza del \xE1rea quemada abierta","Gasa est\xE9ril h\xFAmeda colocada suavemente sin presi\xF3n directa sobre la quemadura limpia"],respuesta_correcta:1,explicacion:"La mantequilla, aceite, grasa y pasta de dientes crean una capa aislante que atrapa el calor residual, empeorando la quemadura."},{id:"osha_393",categoria:"OSHA_QUEMADURAS",pregunta:"Al transportar a un t\xE9cnico con quemaduras extensas, \xBFcu\xE1l es la principal complicaci\xF3n que debe monitorearse?",opciones:["Reacci\xF3n al\xE9rgica tard\xEDa a los materiales del vendaje aplicado en el tratamiento inicial","Shock hipovol\xE9mico por p\xE9rdida masiva de l\xEDquidos a trav\xE9s de la piel da\xF1ada expuesta","Infecci\xF3n bacteriana inmediata que se desarrolla en los primeros cinco minutos del incidente","P\xE9rdida auditiva temporal causada por el estr\xE9s nervioso del trauma de la quemadura sufrida"],respuesta_correcta:1,explicacion:"Las quemaduras extensas causan p\xE9rdida masiva de plasma sangu\xEDneo, llevando a shock hipovol\xE9mico."},{id:"osha_394",categoria:"OSHA_QUEMADURAS",pregunta:"Seg\xFAn OSHA 29 CFR 1910.132, \xBFqu\xE9 debe proporcionar el empleador sin costo al trabajador para prevenci\xF3n de quemaduras?",opciones:["Seguro m\xE9dico completo que cubra tratamiento de quemaduras en cualquier hospital certificado","Todo el equipo de protecci\xF3n personal necesario para los riesgos identificados en el \xE1rea","Capacitaci\xF3n universitaria en seguridad contra incendios con certificaci\xF3n NFPA reconocida","Bonificaci\xF3n econ\xF3mica adicional por trabajar en \xE1reas donde existe riesgo de quemaduras"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1910.132 requiere que el empleador proporcione sin costo todo el PPE necesario basado en la evaluaci\xF3n de riesgos."},{id:"osha_395",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 tipo de guantes debe usar un t\xE9cnico HVAC al realizar brazing con soplete?",opciones:["Guantes de algod\xF3n grueso que permiten buena destreza manual para manipular el soplete","Guantes de cuero resistentes al calor con pu\xF1o extendido que proteja las mu\xF1ecas","Guantes de nitrilo reforzado que protegen contra qu\xEDmicos y calor moderado simult\xE1neamente","Guantes de l\xE1tex doble capa que proporcionan protecci\xF3n b\xE1sica y sensibilidad t\xE1ctil"],respuesta_correcta:1,explicacion:"Para brazing se requieren guantes de cuero resistentes al calor con pu\xF1o extendido para proteger mu\xF1ecas de salpicaduras de metal fundido."},{id:"osha_396",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFCu\xE1l es el prop\xF3sito principal de usar ropa FR (Flame Resistant) cerca de riesgos de arc flash el\xE9ctrico?",opciones:["Eliminar completamente la posibilidad de sufrir cualquier tipo de quemadura por arco el\xE9ctrico","Extinguirse autom\xE1ticamente al retirar la fuente de ignici\xF3n limitando la extensi\xF3n de quemaduras","Reflejar la energ\xEDa del arco el\xE9ctrico de vuelta hacia la fuente neutralizando el peligro t\xE9rmico","Absorber toda la energ\xEDa t\xE9rmica del arco convirti\xE9ndola en calor inofensivo para el trabajador"],respuesta_correcta:1,explicacion:"La ropa FR se autoextingue al retirar la fuente de ignici\xF3n. La ropa normal puede encenderse y seguir quemando."},{id:"osha_397",categoria:"OSHA_QUEMADURAS",pregunta:"Seg\xFAn OSHA, \xBFcada cu\xE1nto tiempo debe inspeccionarse el equipo de protecci\xF3n personal contra quemaduras?",opciones:["Solo cuando el equipo presenta da\xF1o visible a simple vista durante la jornada de trabajo","Antes de cada uso y reemplazarse cuando muestre se\xF1ales de degradaci\xF3n deterioro o da\xF1o","Una vez al a\xF1o durante la auditor\xEDa anual de seguridad requerida por la gerencia de planta","Cada seis meses mediante un laboratorio certificado que emita constancia de calidad del EPP"],respuesta_correcta:1,explicacion:"OSHA requiere inspecci\xF3n del PPE antes de cada uso. El PPE debe reemplazarse inmediatamente cuando muestre degradaci\xF3n."},{id:"osha_398",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 requisito de OSHA aplica para almacenamiento de cilindros de gas usados en brazing para prevenir incendios?",opciones:["Almacenar todos los cilindros juntos en un \xE1rea ventilada con temperatura controlada bajo 80\xB0F","Mantener cilindros de ox\xEDgeno separados m\xEDnimo 20 pies de combustibles o por barrera cortafuegos","Almacenar los cilindros acostados horizontalmente para prevenir ca\xEDdas y da\xF1o a las v\xE1lvulas","Mantener los cilindros al aire libre expuestos directamente al sol para evitar acumulaci\xF3n de gases"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1910.253 requiere cilindros de ox\xEDgeno m\xEDnimo 20 pies de gases combustibles o separados por barrera cortafuegos de 5 pies."},{id:"osha_399",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 tipo de quemadura puede sufrir un t\xE9cnico al abrir la tapa de un compresor scroll que acaba de fallar con alta presi\xF3n?",opciones:["Quemadura por radiaci\xF3n ultravioleta reflejada por el aceite caliente dentro del compresor","Quemadura t\xE9rmica por aceite caliente presurizado que se expulsa violentamente al liberar la tapa","Quemadura qu\xEDmica por los \xE1cidos naturales presentes en el aceite mineral del compresor nuevo","Quemadura el\xE9ctrica por la carga residual almacenada en los devanados internos del motor"],respuesta_correcta:1,explicacion:"Un compresor puede tener aceite a m\xE1s de 300\xB0F bajo alta presi\xF3n. Al abrir sin despresurizar, el aceite caliente se expulsa violentamente."},{id:"osha_400",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFPor qu\xE9 los t\xE9cnicos HVAC en azoteas durante verano tienen riesgo elevado de quemaduras solares?",opciones:["Porque el ozono es m\xE1s concentrado en las azoteas y amplifica los rayos ultravioleta directamente","Porque las superficies met\xE1licas y de membrana reflejan radiaci\xF3n UV aumentando la exposici\xF3n total","Porque la altitud de las azoteas reduce la protecci\xF3n atmosf\xE9rica eliminando la capa de ozono","Porque el aire acondicionado de las unidades enfr\xEDa la piel ocultando el da\xF1o solar acumulado"],respuesta_correcta:1,explicacion:"Las azoteas tienen superficies reflectantes que reflejan radiaci\xF3n UV, causando exposici\xF3n desde arriba y desde abajo simult\xE1neamente."},{id:"osha_401",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 tipo de quemadura ocurre cuando un t\xE9cnico contacta accidentalmente una l\xEDnea de descarga del compresor sin aislamiento?",opciones:["Quemadura por fr\xEDo porque la l\xEDnea de descarga transporta refrigerante en estado l\xEDquido subenfriado","Quemadura qu\xEDmica por los residuos de flux en la superficie exterior de la tuber\xEDa de cobre","Quemadura t\xE9rmica porque la l\xEDnea de descarga puede alcanzar temperaturas superiores a 200\xB0F","Quemadura el\xE9ctrica porque la tuber\xEDa de cobre conduce corriente par\xE1sita del compresor al exterior"],respuesta_correcta:2,explicacion:"La l\xEDnea de descarga transporta gas supercalentado que puede superar 200\xB0F (93\xB0C) y en algunos sistemas 300\xB0F."},{id:"osha_402",categoria:"OSHA_QUEMADURAS",pregunta:"Al limpiar serpentines con limpiador \xE1cido, \xBFqu\xE9 equipo es M\xCDNIMO requerido para prevenir quemaduras qu\xEDmicas?",opciones:["Solo guantes de trabajo est\xE1ndar de cuero ya que el \xE1cido est\xE1 diluido a concentraci\xF3n segura","Guantes qu\xEDmicos resistentes a \xE1cidos m\xE1s gafas de protecci\xF3n contra salpicaduras como m\xEDnimo","Solo gafas de seguridad ya que el contacto con las manos es breve durante la aplicaci\xF3n","\xDAnicamente una mascarilla N95 porque el riesgo principal es la inhalaci\xF3n no el contacto"],respuesta_correcta:1,explicacion:"OSHA requiere como m\xEDnimo guantes resistentes a qu\xEDmicos Y protecci\xF3n ocular al manejar limpiadores \xE1cidos."},{id:"osha_403",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFQu\xE9 riesgo de quemaduras existe al purgar con nitr\xF3geno un sistema mientras se realiza brazing simult\xE1neamente?",opciones:["El nitr\xF3geno se congela dentro de la tuber\xEDa creando tapones de hielo que explotan por presi\xF3n","No existe riesgo de quemaduras ya que el nitr\xF3geno es inerte y esa es precisamente su funci\xF3n","El nitr\xF3geno puede desplazar ox\xEDgeno causando desmayo del t\xE9cnico que cae sobre el soplete encendido","El nitr\xF3geno acelera la combusti\xF3n haciendo que la llama del soplete crezca de forma incontrolable"],respuesta_correcta:2,explicacion:"En espacios cerrados el nitr\xF3geno desplaza ox\xEDgeno. Un t\xE9cnico puede desmayarse y caer sobre el soplete encendido."},{id:"osha_404",categoria:"OSHA_QUEMADURAS",pregunta:"\xBFCu\xE1l es el procedimiento correcto si la ropa de un t\xE9cnico se enciende durante trabajo con soplete?",opciones:["Correr hacia la salida m\xE1s cercana para buscar ayuda inmediata de los compa\xF1eros de trabajo","Ejecutar la t\xE9cnica PARE T\xCDRESE y RUEDE para sofocar las llamas sobre el piso del \xE1rea de trabajo","Quitarse la ropa encendida lo m\xE1s r\xE1pido posible sin importar la ubicaci\xF3n o situaci\xF3n presente","Rociar la ropa encendida con el extintor de CO2 m\xE1s cercano apuntando directamente sobre las llamas"],respuesta_correcta:1,explicacion:"STOP-DROP-ROLL (PARE-T\xCDRESE-RUEDE): detenerse, tirarse al piso y rodar para sofocar las llamas. Correr aviva el fuego."},{id:"osha_405",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es el prop\xF3sito fundamental de la Cl\xE1usula de Deber General (General Duty Clause) de la Ley OSH de 1970?",opciones:["Obligar a los empleados a reportar cualquier incidente menor de forma inmediata","Garantizar un lugar de trabajo libre de peligros reconocidos sin norma espec\xEDfica","Permitir que OSHA imponga multas discrecionales sin necesidad de una inspecci\xF3n","Exigir que todos los t\xE9cnicos de HVAC tengan una certificaci\xF3n federal vigente"],respuesta_correcta:1,explicacion:"La General Duty Clause (Secci\xF3n 5(a)(1)) se usa cuando no existe una norma espec\xEDfica para un peligro reconocido que cause o pueda causar la muerte o da\xF1o f\xEDsico."},{id:"osha_406",categoria:"OSHA_INTRODUCCION",pregunta:"Bajo la doctrina de 'Multi-Employer Worksites', \xBFqu\xE9 empleador es responsable de corregir un peligro detectado?",opciones:["El empleador que cre\xF3 el peligro independientemente de qui\xE9nes est\xE9n expuestos","\xDAnicamente el contratista general por ser el due\xF1o legal de la p\xF3liza de seguro","El empleador cuyos trabajadores est\xE1n expuestos directamente al riesgo el\xE9ctrico","Cualquier empleador con autoridad para corregir el peligro o mando en el sitio"],respuesta_correcta:3,explicacion:"OSHA identifica cuatro tipos de empleadores (creador, expositor, corrector, controlador) y cualquiera con autoridad o responsabilidad puede ser citado."},{id:"osha_407",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 tipo de violaci\xF3n de OSHA conlleva la multa m\xE1s alta debido a la indiferencia intencional del patrono?",opciones:["Violaci\xF3n Seria donde existe probabilidad de muerte por falta de mantenimiento","Violaci\xF3n Repetida tras una inspecci\xF3n previa en un periodo menor a cinco a\xF1os","Violaci\xF3n Intencional (Willful) por ignorar conscientemente los requisitos legales","Violaci\xF3n de Gravedad Menor que afecta la salud a largo plazo de los empleados"],respuesta_correcta:2,explicacion:"Las violaciones 'Willful' son las m\xE1s graves y costosas porque demuestran que el empleador conoc\xEDa la norma y decidi\xF3 no cumplirla voluntariamente."},{id:"osha_408",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1ntos d\xEDas tiene un trabajador para presentar una queja ante OSHA si cree que ha sufrido represalias (Whistleblower)?",opciones:["Tiene un periodo m\xE1ximo de 60 d\xEDas calendario tras el incidente de discriminaci\xF3n","Dispone de 30 d\xEDas exactos desde que ocurri\xF3 el acto de represalia por el jefe","Cuenta con 90 d\xEDas h\xE1biles para someter la documentaci\xF3n legal ante el estado","Debe presentar la queja en menos de 15 d\xEDas tras ser despedido injustamente"],respuesta_correcta:1,explicacion:"Seg\xFAn la Secci\xF3n 11(c) de la Ley OSH, los trabajadores tienen 30 d\xEDas para denunciar discriminaci\xF3n o represalias por ejercer sus derechos de seguridad."},{id:"osha_409",categoria:"OSHA_INTRODUCCION",pregunta:"En el registro de lesiones OSHA 300, \xBFqu\xE9 evento debe reportarse obligatoriamente dentro de las primeras 8 horas?",opciones:["Cualquier accidente que resulte en la hospitalizaci\xF3n de dos o m\xE1s empleados","Una lesi\xF3n por electrocuci\xF3n que requiera \xFAnicamente tratamiento de primeros auxilios","Todo incidente que resulte en la muerte de un trabajador por causas laborales","Cualquier fractura \xF3sea que impida al t\xE9cnico realizar sus labores de instalaci\xF3n"],respuesta_correcta:2,explicacion:"Las fatalidades deben reportarse a OSHA en un m\xE1ximo de 8 horas; las hospitalizaciones, amputaciones o p\xE9rdidas de ojo tienen un plazo de 24 horas."},{id:"osha_410",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 derecho posee un t\xE9cnico de refrigeraci\xF3n durante una inspecci\xF3n f\xEDsica realizada por un oficial de OSHA?",opciones:["El derecho a solicitar que la inspecci\xF3n se realice fuera de su horario laboral","El derecho a participar en la inspecci\xF3n y hablar en privado con el inspector","El derecho a exigir una orden judicial antes de permitir el acceso al cuarto mec\xE1nico","El derecho a detener la inspecci\xF3n si considera que las preguntas son intrusivas"],respuesta_correcta:1,explicacion:"Los trabajadores tienen el derecho legal de acompa\xF1ar al inspector y de hablar con \xE9l de forma confidencial sin presencia del empleador."},{id:"osha_411",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es la funci\xF3n principal del Log OSHA 300A que las empresas deben publicar anualmente?",opciones:["Detallar los nombres de todos los empleados que sufrieron enfermedades laborales","Exhibir un resumen total de lesiones y enfermedades del a\xF1o previo en el sitio","Enumerar las multas pagadas a la agencia federal por conceptos de seguridad","Registrar las horas de capacitaci\xF3n t\xE9cnica recibidas por el personal de campo"],respuesta_correcta:1,explicacion:"El OSHA 300A es el resumen anual que debe publicarse del 1 de febrero al 30 de abril en un lugar visible para que los empleados vean las estad\xEDsticas."},{id:"osha_412",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 norma de OSHA obliga a los empleadores a informar a los t\xE9cnicos sobre los peligros qu\xEDmicos en el sitio?",opciones:["Norma de Comunicaci\xF3n de Peligros (HazCom) detallada en 29 CFR 1910.1200","Norma de Equipo de Protecci\xF3n Personal especificada en el c\xF3digo 29 CFR 1926.28","Regulaci\xF3n de Sustancias T\xF3xicas y Agentes F\xEDsicos del est\xE1ndar 29 CFR 1910.1000","Protocolo de Seguridad para Espacios Confinados bajo el c\xF3digo 29 CFR 1910.146"],respuesta_correcta:0,explicacion:"El est\xE1ndar de Comunicaci\xF3n de Peligros (Hazard Communication) garantiza el 'Derecho a Saber' de los trabajadores sobre qu\xEDmicos peligrosos."},{id:"osha_413",categoria:"OSHA_INTRODUCCION",pregunta:"Si un t\xE9cnico de HVAC nota una condici\xF3n de 'Peligro Inminente', \xBFcu\xE1l es su derecho legal m\xE1s fuerte?",opciones:["Renunciar al empleo con goce de sueldo hasta que se resuelva la situaci\xF3n t\xE9cnica","Negarse a trabajar si existe una amenaza real de muerte o da\xF1o f\xEDsico grave","Solicitar un aumento salarial por trabajar en condiciones de riesgo extraordinario","Contactar a la polic\xEDa local para que clausure el edificio de forma inmediata"],respuesta_correcta:1,explicacion:"OSHA protege el derecho a rechazar una tarea si el trabajador cree razonablemente que enfrenta un riesgo inminente de muerte o lesi\xF3n grave."},{id:"osha_414",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFEn qu\xE9 a\xF1o se firm\xF3 la ley que cre\xF3 OSHA y bajo qu\xE9 administraci\xF3n presidencial ocurri\xF3?",opciones:["En el a\xF1o 1968 bajo la direcci\xF3n de la administraci\xF3n de Lyndon B. Johnson","En el a\xF1o 1970 tras ser firmada legalmente por el presidente Richard Nixon","En el a\xF1o 1972 durante el primer t\xE9rmino de la presidencia de Gerald Ford","En el a\xF1o 1975 como respuesta a la crisis industrial del presidente Jimmy Carter"],respuesta_correcta:1,explicacion:"La Occupational Safety and Health Act fue firmada por Richard Nixon el 29 de diciembre de 1970, entrando en vigor en 1971."},{id:"osha_415",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es la responsabilidad del empleador respecto al costo del Equipo de Protecci\xF3n Personal (PPE)?",opciones:["El empleador debe reembolsar el 50% del costo de cualquier equipo especializado","El trabajador debe comprar su propio equipo para garantizar un ajuste adecuado","El empleador debe proporcionar casi todo el PPE sin costo alguno al trabajador","Solo se requiere que el empleador pague por el PPE si el contrato es de uni\xF3n"],respuesta_correcta:2,explicacion:"Bajo la norma de OSHA, los empleadores est\xE1n obligados a pagar por la gran mayor\xEDa del PPE necesario para el trabajo (con pocas excepciones)."},{id:"osha_416",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 constituye una violaci\xF3n 'Serious' (Seria) seg\xFAn los criterios de inspecci\xF3n de OSHA?",opciones:["Una falta administrativa que no afecta directamente la salud de los t\xE9cnicos","Un peligro que el empleador conoc\xEDa y que probablemente cause muerte o da\xF1o","Cualquier violaci\xF3n que se repita m\xE1s de tres veces en diferentes proyectos","La ausencia de carteles informativos en el \xE1rea de descanso de los trabajadores"],respuesta_correcta:1,explicacion:"Una violaci\xF3n es seria cuando hay una probabilidad sustancial de que ocurra la muerte o un da\xF1o f\xEDsico serio y el empleador sab\xEDa del peligro."},{id:"osha_417",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQui\xE9n es responsable de garantizar que un contratista HVAC cumpla con las normas OSHA en un sitio federal?",opciones:["El inspector de edificios local que emiti\xF3 los permisos de construcci\xF3n iniciales","El due\xF1o de la empresa contratista que emplea directamente a los trabajadores","La agencia estatal de seguridad solo si el estado tiene un plan aprobado por OSHA","El sindicato de trabajadores al que pertenecen los t\xE9cnicos de refrigeraci\xF3n"],respuesta_correcta:1,explicacion:"La responsabilidad legal primaria de cumplir con OSHA recae siempre en el empleador directo del trabajador en el sitio de trabajo."},{id:"osha_418",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es el orden de prioridad de las inspecciones de OSHA (de mayor a menor importancia)?",opciones:["Peligro inminente, fatalidades, quejas de empleados, inspecciones programadas","Quejas de empleados, fatalidades, peligro inminente, inspecciones de rutina","Inspecciones programadas, quejas de empleados, fatalidades, peligro inminente","Fatalidades, peligro inminente, inspecciones de seguimiento, quejas de sindicatos"],respuesta_correcta:0,explicacion:"OSHA prioriza situaciones de peligro inminente, seguidas de fatalidades/hospitalizaciones, quejas de trabajadores y finalmente inspecciones programadas."},{id:"osha_419",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 registro de OSHA se utiliza para anotar los detalles de cada lesi\xF3n o enfermedad individual?",opciones:["Formulario OSHA 300A (Resumen Anual de incidentes y enfermedades laborales)","Formulario OSHA 301 (Informe de incidente de lesiones y enfermedades graves)","Formulario OSHA 300 (Log de lesiones y enfermedades relacionadas al trabajo)","Formulario OSHA 400 (Reporte de fatalidades y eventos de hospitalizaci\xF3n)"],respuesta_correcta:2,explicacion:"El Formulario 300 (Log) es donde se registran los detalles espec\xEDficos de cada caso asegurable que ocurre durante el a\xF1o fiscal."},{id:"osha_420",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es la funci\xF3n del Oficial de Cumplimiento de Seguridad y Salud (CSHO) de OSHA?",opciones:["Asesorar a las empresas sobre c\xF3mo evadir impuestos mediante planes de seguridad","Realizar inspecciones en los lugares de trabajo para verificar el cumplimiento","Capacitar gratuitamente a los t\xE9cnicos de HVAC durante 30 horas certificadas","Dise\xF1ar los planos de ingenier\xEDa para sistemas de ventilaci\xF3n en edificios p\xFAblicos"],respuesta_correcta:1,explicacion:"El CSHO es el inspector de campo cuya labor es verificar que se cumplan las normas de OSHA mediante inspecciones f\xEDsicas y entrevistas."},{id:"osha_421",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 derecho otorga la norma OSHA respecto al acceso a los registros m\xE9dicos laborales?",opciones:["Los trabajadores pueden ver sus registros m\xE9dicos solo en presencia de un abogado","Los empleados tienen derecho a examinar y copiar sus propios registros m\xE9dicos","El acceso a los registros m\xE9dicos est\xE1 limitado exclusivamente a la gerencia de RRHH","Solo el m\xE9dico de la empresa puede revisar los expedientes de exposici\xF3n qu\xEDmica"],respuesta_correcta:1,explicacion:"Los trabajadores tienen el derecho legal de acceder a sus propios registros m\xE9dicos y de exposici\xF3n a sustancias t\xF3xicas mantenidos por el empleador."},{id:"osha_422",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 tipo de empleador se define como 'Creating Employer' en una obra de construcci\xF3n?",opciones:["Aquel que tiene la responsabilidad de seguridad general en todo el proyecto","Aquel que caus\xF3 el peligro mediante sus acciones o falta de mantenimiento","Aquel cuyos propios trabajadores est\xE1n en riesgo de sufrir una ca\xEDda o golpe","Aquel contratado espec\xEDficamente para reparar las deficiencias de seguridad"],respuesta_correcta:1,explicacion:"El 'Creating Employer' es quien genera la condici\xF3n peligrosa, incluso si sus propios empleados no est\xE1n expuestos a dicho riesgo."},{id:"osha_423",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 especifica la norma 29 CFR Parte 1926 en el contexto de la seguridad en Estados Unidos?",opciones:["Normas generales de seguridad industrial para plantas de manufactura fija","Est\xE1ndares de salud y seguridad espec\xEDficos para la industria de la construcci\xF3n","Protocolos de seguridad para el transporte de materiales peligrosos por carretera","Regulaciones de protecci\xF3n ambiental para el manejo de gases refrigerantes"],respuesta_correcta:1,explicacion:"La Parte 1926 contiene las regulaciones de seguridad que aplican espec\xEDficamente a las actividades de construcci\xF3n, incluyendo HVAC en obras nuevas."},{id:"osha_424",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es el requisito para que una queja de un empleado genere una inspecci\xF3n f\xEDsica de OSHA?",opciones:["La queja debe ser presentada de forma an\xF3nima para evitar represalias directas","La queja debe estar escrita y firmada por el trabajador o su representante","El empleado debe haber trabajado al menos un a\xF1o completo en la empresa citada","La queja debe incluir fotos de alta resoluci\xF3n del peligro espec\xEDfico reportado"],respuesta_correcta:1,explicacion:"Aunque OSHA recibe quejas telef\xF3nicas, las quejas escritas y firmadas tienen prioridad y es m\xE1s probable que resulten en una inspecci\xF3n en el sitio."},{id:"osha_425",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 sucede si un empleador no publica el resumen OSHA 300A en el tiempo estipulado?",opciones:["Se le revoca autom\xE1ticamente la licencia de contratista en el estado de operaci\xF3n","Puede recibir una citaci\xF3n y multas administrativas por incumplimiento de registro","El inspector de OSHA cerrar\xE1 el sitio de trabajo hasta que se publique el cartel","Se le proh\xEDbe participar en licitaciones de proyectos gubernamentales por un a\xF1o"],respuesta_correcta:1,explicacion:"No publicar el resumen 300A es una violaci\xF3n administrativa de las normas de mantenimiento de registros (recordkeeping) y conlleva multas."},{id:"osha_426",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es el l\xEDmite m\xE1ximo de empleados que exime a una empresa de mantener registros OSHA 300?",opciones:["Empresas con menos de 25 empleados a tiempo completo durante todo el a\xF1o fiscal","Empresas con 10 o menos empleados en total durante cualquier punto del a\xF1o","Peque\xF1os negocios con menos de 5 t\xE9cnicos operando en camiones de servicio","Contratistas independientes que no tengan ayudantes o aprendices a su cargo"],respuesta_correcta:1,explicacion:"Las empresas con 10 o menos empleados est\xE1n exentas de mantener los registros OSHA 300, a menos que OSHA o el BLS lo soliciten por escrito."},{id:"osha_427",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 significa el acr\xF3nimo NIOSH en el campo de la seguridad y salud ocupacional?",opciones:["Agencia federal encargada de imponer multas a los contratistas el\xE9ctricos","Instituto dedicado a la investigaci\xF3n y recomendaci\xF3n de normas de seguridad","Departamento de justicia encargado de procesar criminalmente a los due\xF1os","Organismo que certifica \xFAnicamente las herramientas de mano para construcci\xF3n"],respuesta_correcta:1,explicacion:"NIOSH es una agencia de investigaci\xF3n (parte del CDC) que desarrolla criterios para OSHA pero no tiene poder para multar directamente."},{id:"osha_428",categoria:"OSHA_INTRODUCCION",pregunta:"Bajo OSHA, \xBFqu\xE9 se considera un 'peligro reconocido' para aplicar la General Duty Clause?",opciones:["Un riesgo que solo un ingeniero experto podr\xEDa identificar mediante c\xE1lculos","Un peligro que es obvio para cualquier persona sin entrenamiento en seguridad","Un riesgo conocido por la industria o documentado por el propio empleador","Una situaci\xF3n que nunca antes ha causado un accidente en el sector de HVAC"],respuesta_correcta:2,explicacion:"Un peligro es 'reconocido' si la industria lo conoce, si el empleador lo conoce o si es una cuesti\xF3n de sentido com\xFAn t\xE9cnico."},{id:"osha_429",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 derecho tienen los t\xE9cnicos sobre el entrenamiento de seguridad seg\xFAn OSHA?",opciones:["Recibir entrenamiento en un idioma y vocabulario que puedan comprender bien","Tener acceso a cursos de capacitaci\xF3n solo despu\xE9s de seis meses de empleo","Recibir el entrenamiento fuera de horas de trabajo sin compensaci\xF3n salarial","Ser responsables de pagar por sus propios certificados de OSHA 10 u OSHA 30"],respuesta_correcta:0,explicacion:"Los empleadores deben proporcionar capacitaci\xF3n en un lenguaje que el trabajador entienda; si el t\xE9cnico habla espa\xF1ol, el curso debe ser en espa\xF1ol."},{id:"osha_430",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es el plazo m\xE1ximo para que un empleador corrija una violaci\xF3n tras recibir una citaci\xF3n?",opciones:["Debe corregirse de inmediato, usualmente antes de que el inspector se retire","El plazo espec\xEDfico (fecha de correcci\xF3n) se detalla en la citaci\xF3n de OSHA","El empleador tiene 90 d\xEDas naturales para demostrar que el peligro ya no existe","La correcci\xF3n debe hacerse solo despu\xE9s de que se agoten todas las apelaciones"],respuesta_correcta:1,explicacion:"Cada citaci\xF3n de OSHA incluye una 'Abatement Date', que es la fecha l\xEDmite para corregir la condici\xF3n peligrosa detectada."},{id:"osha_431",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 define a un 'Exposing Employer' en un sitio con m\xFAltiples empresas trabajando?",opciones:["El empleador que no coloc\xF3 la se\xF1alizaci\xF3n de advertencia en el \xE1rea com\xFAn","El empleador cuyos propios trabajadores est\xE1n expuestos a una condici\xF3n de riesgo","El contratista que supervisa diariamente el cronograma de todas las cuadrillas","La empresa que trajo qu\xEDmicos peligrosos al sitio sin entregar las hojas SDS"],respuesta_correcta:1,explicacion:"El 'Exposing Employer' es aquel cuyo personal est\xE1 en contacto o riesgo debido a un peligro, sin importar qui\xE9n cre\xF3 el peligro."},{id:"osha_432",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFEn qu\xE9 secci\xF3n del 29 CFR se encuentran las normas generales para la industria (General Industry)?",opciones:["En la Parte 1910, que aplica a almacenes, tiendas y mantenimiento de HVAC","En la Parte 1926, que rige todas las instalaciones el\xE9ctricas de baja tensi\xF3n","En la Parte 1915, dedicada exclusivamente al sector de construcci\xF3n naval","En la Parte 1904, que establece las reglas de equipo de protecci\xF3n personal"],respuesta_correcta:0,explicacion:"El 29 CFR 1910 cubre la 'Industria General', que incluye trabajos de mantenimiento y servicio t\xE9cnico que no son construcci\xF3n."},{id:"osha_433",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFQu\xE9 sucede si un oficial de OSHA llega a un sitio y el empleador le niega la entrada?",opciones:["El oficial puede arrestar al due\xF1o por obstrucci\xF3n a la justicia federal","OSHA regresar\xE1 con una orden judicial (warrant) para forzar la inspecci\xF3n","La empresa ser\xE1 multada con un mill\xF3n de d\xF3lares de forma autom\xE1tica","Se asume que la empresa es 100% segura y se cancela la inspecci\xF3n t\xE9cnica"],respuesta_correcta:1,explicacion:"Si se niega la entrada, OSHA puede obtener una orden de registro legal para ingresar al lugar de trabajo y realizar la inspecci\xF3n obligatoriamente."},{id:"osha_434",categoria:"OSHA_INTRODUCCION",pregunta:"\xBFCu\xE1l es la responsabilidad del trabajador (t\xE9cnico) bajo la Ley OSH de 1970?",opciones:["Dise\xF1ar sus propios planes de seguridad si el patrono no proporciona uno","Cumplir con todas las normas de OSHA y reglas de seguridad del empleador","Multar a sus compa\xF1eros de trabajo si observa que no usan el casco de seguridad","Inspeccionar el equipo de los dem\xE1s contratistas antes de iniciar la jornada"],respuesta_correcta:1,explicacion:"Aunque los empleadores son los responsables finales, la secci\xF3n 5(b) exige que los empleados cumplan con las normas y \xF3rdenes de seguridad aplicables."},{id:"osha_435",categoria:"OSHA_RESPIRATORIA",pregunta:"Seg\xFAn 29 CFR 1910.134, \xBFcada cu\xE1nto tiempo debe actualizarse la evaluaci\xF3n m\xE9dica de un empleado que usa respirador?",opciones:["Cada 12 meses sin excepci\xF3n alguna","Cuando cambian condiciones de trabajo","Cada 6 meses seg\xFAn el fabricante","Al inicio de cada proyecto nuevo"],respuesta_correcta:1,explicacion:"La evaluaci\xF3n m\xE9dica debe actualizarse cuando hay cambios en las condiciones de trabajo, el estado de salud del empleado, o el tipo de respirador utilizado, no en un intervalo fijo autom\xE1tico."},{id:"osha_436",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es el Factor de Protecci\xF3n Asignado (APF) de un respirador de media cara con filtros seg\xFAn OSHA?",opciones:["APF de 50 para media cara est\xE1ndar","APF de 25 para media cara est\xE1ndar","APF de 10 para media cara est\xE1ndar","APF de 15 para media cara est\xE1ndar"],respuesta_correcta:2,explicacion:"OSHA asigna un APF de 10 a los respiradores de media cara (half-facepiece), lo que significa que reducen la concentraci\xF3n del contaminante a 1/10 del nivel ambiental."},{id:"osha_437",categoria:"OSHA_RESPIRATORIA",pregunta:"En una atm\xF3sfera IDLH, \xBFcu\xE1l es el respirador m\xEDnimo requerido por OSHA para ingresar al \xE1rea?",opciones:["Respirador de cara completa con P100","Respirador de media cara con cartuchos","SCBA de presi\xF3n positiva o SAR con escape","Respirador purificador con filtro HEPA"],respuesta_correcta:2,explicacion:"En atm\xF3sferas IDLH (Immediately Dangerous to Life or Health), OSHA requiere como m\xEDnimo un SCBA de presi\xF3n positiva o un SAR (Supplied Air Respirator) con botella de escape auxiliar."},{id:"osha_438",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 concentraci\xF3n de ox\xEDgeno define una atm\xF3sfera como deficiente de ox\xEDgeno seg\xFAn OSHA?",opciones:["Menos de 21.5% de ox\xEDgeno en el aire","Menos de 20.8% de ox\xEDgeno en el aire","Menos de 19.5% de ox\xEDgeno en el aire","Menos de 18.0% de ox\xEDgeno en el aire"],respuesta_correcta:2,explicacion:"OSHA define una atm\xF3sfera deficiente de ox\xEDgeno como aquella con menos de 19.5% de ox\xEDgeno. El nivel normal es 20.9% y por debajo de 19.5% se requiere suministro de aire."},{id:"osha_439",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es el prop\xF3sito principal de la prueba de ajuste (fit test) cualitativa para respiradores?",opciones:["Medir la concentraci\xF3n de fuga num\xE9rica","Verificar el sello usando respuesta sensorial","Calcular el factor de protecci\xF3n del equipo","Determinar la vida \xFAtil del cartucho usado"],respuesta_correcta:1,explicacion:"La prueba cualitativa (QLFT) utiliza la respuesta sensorial del usuario (gusto, olor) a un agente de prueba como sacarina o Bitrex para verificar si hay fugas en el sello del respirador."},{id:"osha_440",categoria:"OSHA_RESPIRATORIA",pregunta:"Seg\xFAn OSHA, \xBFcon qu\xE9 frecuencia m\xEDnima debe realizarse la prueba de ajuste (fit test) para respiradores?",opciones:["Cada 6 meses o al cambiar de modelo","Al menos una vez al a\xF1o como m\xEDnimo","Cada 2 a\xF1os si no hay cambios f\xEDsicos","Solo al asignar el respirador por vez primera"],respuesta_correcta:1,explicacion:"29 CFR 1910.134 requiere que la prueba de ajuste se realice al menos una vez al a\xF1o, y tambi\xE9n cuando hay cambios en el tipo de respirador o en la condici\xF3n f\xEDsica del empleado."},{id:"osha_441",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 tipo de filtro NIOSH protege contra part\xEDculas aceitosas y no aceitosas simult\xE1neamente?",opciones:["Serie N que filtra part\xEDculas no aceitosas","Serie R que resiste part\xEDculas con aceite","Serie P que es prueba contra todo aceite","Serie HE que filtra eficiencia muy alta"],respuesta_correcta:2,explicacion:"La Serie P (oil-Proof) est\xE1 dise\xF1ada para filtrar tanto part\xEDculas aceitosas como no aceitosas sin degradaci\xF3n. La Serie N solo filtra no aceitosas y la Serie R resiste aceite pero con tiempo limitado."},{id:"osha_442",categoria:"OSHA_RESPIRATORIA",pregunta:"Un t\xE9cnico HVAC trabaja con refrigerante R-410A en un cuarto mec\xE1nico cerrado. \xBFCu\xE1l es el riesgo respiratorio principal?",opciones:["Toxicidad directa por inhalaci\xF3n del gas","Desplazamiento de ox\xEDgeno en lugar cerrado","Reacci\xF3n al\xE9rgica al contacto con mucosas","Irritaci\xF3n severa de las v\xEDas superiores"],respuesta_correcta:1,explicacion:"El R-410A no es t\xF3xico en concentraciones bajas, pero en un espacio cerrado puede desplazar el ox\xEDgeno creando una atm\xF3sfera deficiente de ox\xEDgeno, que es el riesgo principal para el t\xE9cnico."},{id:"osha_443",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es el Factor de Protecci\xF3n Asignado (APF) de un SCBA de presi\xF3n positiva seg\xFAn la tabla de OSHA?",opciones:["APF de 1,000 para uso en emergencias","APF de 5,000 para atm\xF3sferas t\xF3xicas","APF de 10,000 seg\xFAn tabla de factores","APF de 50,000 para m\xE1xima protecci\xF3n"],respuesta_correcta:2,explicacion:"OSHA asigna un APF de 10,000 al SCBA (Self-Contained Breathing Apparatus) de presi\xF3n positiva, el nivel m\xE1s alto de protecci\xF3n asignado en la tabla de 29 CFR 1910.134."},{id:"osha_444",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 elemento NO es requerido en un programa escrito de protecci\xF3n respiratoria seg\xFAn 29 CFR 1910.134?",opciones:["Procedimientos para selecci\xF3n del respirador","Evaluaci\xF3n m\xE9dica previa del trabajador usado","Registro de horas totales de cada respirador","Procedimientos de limpieza y mantenimiento"],respuesta_correcta:2,explicacion:"29 CFR 1910.134 requiere selecci\xF3n, evaluaci\xF3n m\xE9dica, fit testing, mantenimiento y entrenamiento, pero no exige un registro de horas totales acumuladas por cada respirador individual."},{id:"osha_445",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1ndo puede un empleador permitir el uso voluntario de un respirador de filtro sin programa completo?",opciones:["Nunca, siempre se requiere programa completo","Solo si el empleado firma carta de renuncia","Cuando la exposici\xF3n est\xE1 bajo el PEL vigente","Solo con autorizaci\xF3n m\xE9dica del especialista"],respuesta_correcta:2,explicacion:"Cuando la exposici\xF3n est\xE1 bajo el PEL y el uso es voluntario con respiradores de filtro (no cartuchos qu\xEDmicos), el empleador solo debe proporcionar el Ap\xE9ndice D y asegurar que el uso no cree peligro."},{id:"osha_446",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es la diferencia principal entre una prueba de ajuste cuantitativa y una cualitativa?",opciones:["La cualitativa usa instrumentos de medici\xF3n","La cuantitativa mide fugas num\xE9ricamente","La cualitativa requiere equipo especializado","La cuantitativa se basa en sabor y olfato"],respuesta_correcta:1,explicacion:"La prueba cuantitativa (QNFT) usa instrumentos que miden num\xE9ricamente la concentraci\xF3n dentro vs fuera del respirador, mientras que la cualitativa se basa en la respuesta sensorial del usuario."},{id:"osha_447",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 indica la designaci\xF3n '100' en un filtro P100 aprobado por NIOSH?",opciones:["Filtra el 100% de gases y vapores t\xF3xicos","Tiene capacidad para 100 horas de trabajo","Filtra al menos 99.97% de las part\xEDculas","Resiste 100 mg de contaminante acumulado"],respuesta_correcta:2,explicacion:"La designaci\xF3n '100' indica que el filtro tiene una eficiencia m\xEDnima de 99.97% contra part\xEDculas de prueba de 0.3 micrones, el nivel m\xE1s alto de filtraci\xF3n de part\xEDculas seg\xFAn NIOSH."},{id:"osha_448",categoria:"OSHA_RESPIRATORIA",pregunta:"Un t\xE9cnico HVAC nota olor a solvente mientras usa un respirador con cartuchos org\xE1nicos. \xBFQu\xE9 debe hacer?",opciones:["Continuar trabajando si el olor es muy leve","Salir del \xE1rea y reemplazar los cartuchos","Ajustar las correas para mejorar todo sello","Cambiar a filtros P100 de mayor protecci\xF3n"],respuesta_correcta:1,explicacion:"La detecci\xF3n de olor indica que los cartuchos est\xE1n saturados (breakthrough). El t\xE9cnico debe salir inmediatamente del \xE1rea contaminada y reemplazar los cartuchos antes de continuar."},{id:"osha_449",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 tipo de respirador es apropiado para un t\xE9cnico que suelda con soldadura de plata en HVAC?",opciones:["N95 desechable para polvos de soldadura","Media cara con cartuchos de vapor \xE1cido","Media cara con filtros P100 para part\xEDculas","Respirador quir\xFArgico de grado est\xE1ndar"],respuesta_correcta:2,explicacion:"La soldadura de plata (brazing) genera humos met\xE1licos que son part\xEDculas. Un respirador de media cara con filtros P100 proporciona protecci\xF3n adecuada contra humos de soldadura cuando est\xE1 bajo el APF."},{id:"osha_450",categoria:"OSHA_RESPIRATORIA",pregunta:"Seg\xFAn OSHA, \xBFqui\xE9n debe pagar el costo de los respiradores cuando su uso es obligatorio en el trabajo?",opciones:["El costo se divide entre ambas partes","El empleado paga su propio respirador","El empleador paga todos los respiradores","El sindicato cubre el gasto del equipo"],respuesta_correcta:2,explicacion:"Cuando el uso de respiradores es obligatorio, 29 CFR 1910.134 requiere que el empleador proporcione los respiradores sin costo para el empleado, incluyendo filtros y cartuchos de repuesto."},{id:"osha_451",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es el contenido principal del Ap\xE9ndice D de 29 CFR 1910.134 sobre protecci\xF3n respiratoria?",opciones:["Tablas de factores de protecci\xF3n asignados","Protocolos detallados para pruebas de ajuste","Informaci\xF3n para uso voluntario del equipo","Cuestionario de evaluaci\xF3n m\xE9dica completo"],respuesta_correcta:2,explicacion:"El Ap\xE9ndice D contiene informaci\xF3n obligatoria que debe entregarse a empleados que usan respiradores voluntariamente, explicando los riesgos y precauciones del uso voluntario."},{id:"osha_452",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 condici\xF3n facial impide obtener un sello adecuado en la prueba de ajuste del respirador?",opciones:["Tener la piel ligeramente bronceada por sol","Usar lentes de contacto para la correcci\xF3n","Tener vello facial donde sella el respirador","Tener cicatrices antiguas lejos del sellado"],respuesta_correcta:2,explicacion:"El vello facial (barba, patillas) en el \xE1rea donde el respirador sella contra la cara impide un ajuste herm\xE9tico, lo que compromete la protecci\xF3n y causa fallo en la prueba de ajuste."},{id:"osha_453",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es la concentraci\xF3n de ox\xEDgeno en la que una atm\xF3sfera se considera IDLH por deficiencia?",opciones:["Menos de 18.0% de ox\xEDgeno presente","Menos de 17.5% de ox\xEDgeno presente","Menos de 16.0% de ox\xEDgeno presente","Menos de 19.5% de ox\xEDgeno presente"],respuesta_correcta:2,explicacion:"Una atm\xF3sfera con menos de 16% de ox\xEDgeno se considera IDLH. Nota: deficiente de ox\xEDgeno empieza en 19.5%, pero el nivel IDLH es 16% donde hay peligro inmediato para la vida."},{id:"osha_454",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 tipo de respirador es un SAR (Supplied Air Respirator) y c\xF3mo funciona para el usuario?",opciones:["Purifica el aire ambiente con filtros qu\xEDmicos","Suministra aire limpio desde fuente externa","Genera ox\xEDgeno puro mediante reacci\xF3n interna","Recircula el aire exhalado despu\xE9s de filtrarlo"],respuesta_correcta:1,explicacion:"Un SAR (Supplied Air Respirator) suministra aire respirable desde una fuente externa (compresor o cilindros) a trav\xE9s de una manguera, sin depender del aire ambiente contaminado."},{id:"osha_455",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 factor determina principalmente cu\xE1ndo se deben cambiar los cartuchos qu\xEDmicos de un respirador?",opciones:["La fecha de manufactura impresa en el equipo","El programa de cambio basado en la exposici\xF3n","El color del cartucho cuando cambia a oscuro","La cantidad de polvo visible en la superficie"],respuesta_correcta:1,explicacion:"OSHA requiere un programa de cambio de cartuchos basado en datos objetivos: concentraci\xF3n del contaminante, tasa de respiraci\xF3n, humedad, temperatura y capacidad del cartucho seg\xFAn el fabricante."},{id:"osha_456",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es el Factor de Protecci\xF3n Asignado (APF) de un respirador de cara completa seg\xFAn OSHA?",opciones:["APF de 10 para cara completa tipo b\xE1sico","APF de 25 para cara completa tipo b\xE1sico","APF de 50 para cara completa tipo b\xE1sico","APF de 100 para cara completa tipo b\xE1sico"],respuesta_correcta:2,explicacion:"OSHA asigna un APF de 50 a los respiradores de cara completa (full-facepiece) con presi\xF3n negativa, lo que significa que reducen la exposici\xF3n a 1/50 de la concentraci\xF3n ambiental."},{id:"osha_457",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 debe hacer un empleador ANTES de que un empleado use un respirador por primera vez en el trabajo?",opciones:["Solo entregar el respirador con instrucciones","Proveer evaluaci\xF3n m\xE9dica al trabajador antes","Realizar \xFAnicamente la prueba de ajuste facial","Registrar al empleado en curso de primeros auxilios"],respuesta_correcta:1,explicacion:"29 CFR 1910.134 requiere que el empleador provea una evaluaci\xF3n m\xE9dica ANTES de la prueba de ajuste y antes de que el empleado use el respirador en el lugar de trabajo."},{id:"osha_458",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 m\xE9todo de prueba de ajuste cualitativa usa una soluci\xF3n amarga que el usuario puede detectar?",opciones:["Prueba de sacarina con sabor muy dulce","Prueba con acetato de isoamilo y su olor","Prueba de Bitrex con sabor amargo fuerte","Prueba de humo irritante en concentraci\xF3n"],respuesta_correcta:2,explicacion:"La prueba de Bitrex (denatonium benzoate) usa una soluci\xF3n extremadamente amarga. Si el usuario detecta el sabor amargo dentro del respirador, indica que hay fugas en el sello."},{id:"osha_459",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFEn qu\xE9 situaci\xF3n OSHA permite usar un respirador purificador de aire en vez de suministro de aire?",opciones:["Cuando la atm\xF3sfera tiene suficiente ox\xEDgeno","En cualquier espacio confinado sin ventilaci\xF3n","Cuando el contaminante no tiene olor detectable","En emergencias donde no hay otro equipo cerca"],respuesta_correcta:0,explicacion:"Los respiradores purificadores de aire (APR) solo pueden usarse cuando hay suficiente ox\xEDgeno (>19.5%) y la concentraci\xF3n del contaminante est\xE1 dentro del rango del APF del respirador."},{id:"osha_460",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es el procedimiento correcto para verificar el sello negativo de un respirador antes de entrar al \xE1rea?",opciones:["Soplar fuerte y verificar que el aire no sale","Cubrir filtros, inhalar y sentir succi\xF3n facial","Mover la cabeza de lado a lado r\xE1pidamente","Rociar agente de prueba alrededor del equipo"],respuesta_correcta:1,explicacion:"La verificaci\xF3n de sello negativo consiste en cubrir los filtros/cartuchos con las palmas, inhalar suavemente y verificar que la pieza facial se colapsa hacia la cara sin detectar fugas."},{id:"osha_461",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1nto tiempo m\xEDnimo de aire debe proveer un SCBA para operaciones de entrada en atm\xF3sferas IDLH?",opciones:["Al menos 15 minutos de aire como respaldo","Al menos 30 minutos de aire como m\xEDnimo","Al menos 45 minutos de aire de suministro","Al menos 60 minutos de aire de suministro"],respuesta_correcta:1,explicacion:"OSHA requiere que un SCBA usado para entrada en atm\xF3sferas IDLH tenga al menos 30 minutos de suministro de aire. Los SCBA de 15 minutos son solo para escape, no para entrada."},{id:"osha_462",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 informaci\xF3n debe incluir el cuestionario m\xE9dico del Ap\xE9ndice C de 29 CFR 1910.134?",opciones:["Solo historial de alergias y medicamentos","Historial m\xE9dico completo y condici\xF3n actual","\xDAnicamente resultados de espirometr\xEDa previa","Solo la presi\xF3n arterial y frecuencia card\xEDaca"],respuesta_correcta:1,explicacion:"El Ap\xE9ndice C requiere un cuestionario completo que incluye historial m\xE9dico, condiciones respiratorias, cardiovasculares, uso previo de respiradores y cualquier condici\xF3n que afecte su uso."},{id:"osha_463",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 color de cartucho indica protecci\xF3n contra vapores org\xE1nicos seg\xFAn el c\xF3digo NIOSH?",opciones:["Cartucho de color amarillo brillante est\xE1ndar","Cartucho de color negro con franja visible","Cartucho de color blanco con marca lateral","Cartucho de color verde para vapores varios"],respuesta_correcta:1,explicacion:"Seg\xFAn el sistema de c\xF3digo de colores NIOSH, el negro identifica cartuchos para vapores org\xE1nicos. Amarillo es para gases \xE1cidos, verde para amon\xEDaco y blanco para gases \xE1cidos."},{id:"osha_464",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 debe hacer el empleador si un m\xE9dico determina que un empleado no puede usar respiradores?",opciones:["Despedir al empleado de forma inmediata hoy","Reasignar al empleado a \xE1rea sin respirador","Obligar al empleado a usar otro tipo de equipo","Reducir las horas de exposici\xF3n a la mitad"],respuesta_correcta:1,explicacion:"Si un empleado no puede usar respiradores por razones m\xE9dicas, el empleador debe reasignarlo a una posici\xF3n donde no se requiera protecci\xF3n respiratoria, sin represalias ni reducci\xF3n de salario."},{id:"osha_465",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCon qu\xE9 frecuencia deben limpiarse los respiradores de uso personal seg\xFAn las normas de OSHA?",opciones:["Semanalmente o cuando se note suciedad","Despu\xE9s de cada uso diario como m\xEDnimo","Mensualmente seg\xFAn calendario del programa","Cada 40 horas acumuladas de uso continuo"],respuesta_correcta:1,explicacion:"Los respiradores de uso personal deben limpiarse y desinfectarse despu\xE9s de cada uso. Los de uso compartido deben limpiarse despu\xE9s de cada usuario para prevenir contaminaci\xF3n cruzada."},{id:"osha_466",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 significa que un respirador opera en modo de 'presi\xF3n negativa' durante la inhalaci\xF3n?",opciones:["La presi\xF3n dentro es mayor que la del ambiente","La presi\xF3n dentro es menor que la del ambiente","El respirador genera vac\xEDo con bomba el\xE9ctrica","El filtro comprime el aire antes de la entrada"],respuesta_correcta:1,explicacion:"En modo presi\xF3n negativa, al inhalar se crea una presi\xF3n menor dentro de la pieza facial que la presi\xF3n atmosf\xE9rica exterior, lo que podr\xEDa permitir entrada de contaminantes si hay fugas."},{id:"osha_467",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es la ventaja principal de un respirador de presi\xF3n positiva sobre uno de presi\xF3n negativa?",opciones:["Es m\xE1s liviano y m\xE1s c\xF3modo para el usuario","Mantiene presi\xF3n interna mayor evitando fugas","Tiene filtros m\xE1s grandes con mayor capacidad","Permite vello facial sin afectar la protecci\xF3n"],respuesta_correcta:1,explicacion:"Los respiradores de presi\xF3n positiva mantienen una presi\xF3n mayor dentro de la pieza facial que la exterior, de modo que si hay alguna fuga, el aire sale en vez de que entre contaminante."},{id:"osha_468",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 indica la eficiencia del 95% en un filtro N95 aprobado por NIOSH para part\xEDculas?",opciones:["Filtra 95% de part\xEDculas mayores a 1 micr\xF3n","Filtra 95% de part\xEDculas de prueba de 0.3 \u03BCm","Filtra 95% de gases y vapores simult\xE1neos","Dura 95 horas antes de requerir un reemplazo"],respuesta_correcta:1,explicacion:"N95 filtra al menos el 95% de part\xEDculas de prueba de 0.3 micrones de di\xE1metro (el tama\xF1o m\xE1s penetrante). No protege contra gases ni vapores."},{id:"osha_469",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 acci\xF3n est\xE1 PROHIBIDA al almacenar respiradores seg\xFAn las normas de protecci\xF3n respiratoria?",opciones:["Guardarlos en bolsas selladas y muy limpias","Colocarlos donde se deforme la pieza facial","Almacenarlos en casilleros personales secos","Mantenerlos separados de otros equipos de PPE"],respuesta_correcta:1,explicacion:"Los respiradores no deben almacenarse de forma que se deforme la pieza facial o las v\xE1lvulas, ya que esto compromete el sello y la protecci\xF3n. Deben guardarse protegidos contra deformaci\xF3n."},{id:"osha_470",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 requisito aplica cuando m\xFAltiples empleados comparten el mismo respirador en turnos?",opciones:["Solo necesitan firmar un registro de entrega","Debe limpiarse y desinfectarse entre usuarios","Basta con cambiar los filtros entre cada turno","Solo se requiere inspecci\xF3n visual del estado"],respuesta_correcta:1,explicacion:"Cuando los respiradores son compartidos, OSHA requiere que se limpien y desinfecten completamente entre cada usuario para prevenir transmisi\xF3n de enfermedades y contaminaci\xF3n cruzada."},{id:"osha_471",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFCu\xE1l es el primer paso del entrenamiento obligatorio que OSHA requiere para usuarios de respiradores?",opciones:["Practicar el ajuste correcto del respirador","Explicar por qu\xE9 se necesita el respirador hoy","Demostrar c\xF3mo cambiar filtros y cartuchos","Realizar la prueba de ajuste cuantitativa ya"],respuesta_correcta:1,explicacion:"El entrenamiento debe comenzar explicando por qu\xE9 es necesario el respirador, los peligros presentes y las consecuencias de uso incorrecto, antes de pasar a aspectos pr\xE1cticos del equipo."},{id:"osha_472",categoria:"OSHA_RESPIRATORIA",pregunta:"Un t\xE9cnico HVAC recupera refrigerante en un cuarto sin ventilaci\xF3n. \xBFQu\xE9 tipo de monitoreo es prioritario?",opciones:["Monitor de part\xEDculas suspendidas en el aire","Monitor de nivel de ox\xEDgeno en la atm\xF3sfera","Monitor de compuestos org\xE1nicos tipo vol\xE1til","Monitor de temperatura y humedad del espacio"],respuesta_correcta:1,explicacion:"Al recuperar refrigerante en espacios cerrados, la prioridad es monitorear el nivel de ox\xEDgeno ya que los refrigerantes desplazan el ox\xEDgeno y pueden crear una atm\xF3sfera deficiente sin previo aviso."},{id:"osha_473",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 parte del respirador debe inspeccionarse PRIMERO antes de cada uso seg\xFAn el procedimiento est\xE1ndar?",opciones:["Los cartuchos para verificar fecha y estado","La pieza facial buscando grietas o desgaste","Las correas para confirmar buena elasticidad","Las v\xE1lvulas de exhalaci\xF3n buscando residuos"],respuesta_correcta:1,explicacion:"La inspecci\xF3n pre-uso comienza con la pieza facial, verificando que no tenga grietas, rasgaduras, deformaci\xF3n o deterioro que comprometa el sello, ya que es el componente m\xE1s cr\xEDtico."},{id:"osha_474",categoria:"OSHA_RESPIRATORIA",pregunta:"\xBFQu\xE9 situaci\xF3n requiere que el empleador actualice inmediatamente el programa de protecci\xF3n respiratoria?",opciones:["Cuando un empleado solicita respirador nuevo","Cuando cambian los contaminantes en el sitio","Cuando se acerca la fecha de auditor\xEDa anual","Cuando el proveedor ofrece un modelo diferente"],respuesta_correcta:1,explicacion:"El programa debe actualizarse inmediatamente cuando cambian las condiciones del lugar de trabajo, como nuevos contaminantes, procesos o niveles de exposici\xF3n que afecten la selecci\xF3n del respirador."},{id:"osha_475",categoria:"OSHA_HERRAMIENTAS",pregunta:"Seg\xFAn OSHA 29 CFR 1926.300, \xBFcu\xE1ndo debe un empleado inspeccionar las herramientas manuales antes de usarlas?",opciones:["Una vez al mes durante la reuni\xF3n de seguridad del equipo de trabajo","Antes de cada uso para verificar que est\xE9n en condiciones seguras de operaci\xF3n","Solamente cuando el supervisor de seguridad lo solicite por escrito al t\xE9cnico","Despu\xE9s de cada uso para documentar el desgaste en el registro de herramientas"],respuesta_correcta:1,explicacion:"OSHA requiere que las herramientas se inspeccionen antes de cada uso. Las herramientas da\xF1adas o defectuosas deben retirarse de servicio inmediatamente."},{id:"osha_476",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 requisito establece OSHA para las guardas de seguridad en herramientas el\xE9ctricas port\xE1tiles con partes rotativas expuestas?",opciones:["Deben pintarse de color rojo brillante para ser f\xE1cilmente visibles al operador","Deben cubrir las partes rotativas y no pueden ser removidas por el operador","Pueden retirarse si el operador tiene m\xE1s de cinco a\xF1os de experiencia laboral","Son opcionales si el t\xE9cnico usa guantes de cuero de alta resistencia al corte"],respuesta_correcta:1,explicacion:"29 CFR 1926.300(b)(1) exige que las guardas cubran partes expuestas de correas, engranajes, ejes y partes rotativas. Nunca deben removerse durante la operaci\xF3n."},{id:"osha_477",categoria:"OSHA_HERRAMIENTAS",pregunta:"Una herramienta el\xE9ctrica port\xE1til con el s\xEDmbolo de doble cuadrado (cuadrado dentro de otro) indica que es:",opciones:["Resistente al agua y apta para uso en ambientes h\xFAmedos o bajo lluvia ligera","De doble aislamiento y no requiere una tercera terminal de conexi\xF3n a tierra","De uso exclusivo en interiores y no apta para trabajos a la intemperie h\xFAmeda","De alta potencia y requiere un circuito dedicado de 20 amperios como m\xEDnimo"],respuesta_correcta:1,explicacion:"El s\xEDmbolo de doble cuadrado indica doble aislamiento (Clase II). Estas herramientas no necesitan terminal de tierra porque tienen dos capas independientes de aislamiento el\xE9ctrico."},{id:"osha_478",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFCu\xE1l es el requisito de OSHA para herramientas el\xE9ctricas port\xE1tiles que NO son de doble aislamiento en sitios de construcci\xF3n?",opciones:["Deben estar conectadas a un circuito protegido con GFCI o programa de cable asegurado","Solo necesitan un fusible de capacidad adecuada instalado en el panel de distribuci\xF3n","Requieren \xFAnicamente una extensi\xF3n de calibre grueso sin necesidad de tierra adicional","Basta con que el operador use guantes aislantes de goma clase 00 durante todo el uso"],respuesta_correcta:0,explicacion:"29 CFR 1926.404(b)(1) requiere que todas las herramientas con conexi\xF3n a tierra usen protecci\xF3n GFCI o un programa de cable asegurado (Assured Equipment Grounding Conductor Program)."},{id:"osha_479",categoria:"OSHA_HERRAMIENTAS",pregunta:"Un t\xE9cnico HVAC encuentra una herramienta el\xE9ctrica cuyo cable tiene el tercer conductor (tierra) cortado. \xBFQu\xE9 debe hacer?",opciones:["Usarla con cuidado conect\xE1ndola a un GFCI como medida de protecci\xF3n alternativa","Reemplazar el enchufe \xE9l mismo con uno nuevo de tres terminales del almac\xE9n","Retirarla inmediatamente de servicio y etiquetarla como defectuosa para reparaci\xF3n","Conectarla a una extensi\xF3n con tierra para compensar la falta del conductor propio"],respuesta_correcta:2,explicacion:"Una herramienta sin conductor de tierra funcional es una violaci\xF3n seria. Debe retirarse de servicio inmediatamente, etiquetarse y enviarse a reparaci\xF3n por personal calificado."},{id:"osha_480",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 tipo de interruptor requiere OSHA en herramientas el\xE9ctricas manuales como taladros y sierras circulares port\xE1tiles?",opciones:["Un interruptor de palanca con posici\xF3n fija que mantenga encendida la herramienta","Un interruptor de presi\xF3n constante o de bloqueo seg\xFAn el tipo de herramienta usada","Un interruptor de pie para que el operador tenga ambas manos libres sobre la pieza","Un interruptor remoto inal\xE1mbrico que permita apagar desde una distancia de seguridad"],respuesta_correcta:1,explicacion:"OSHA 1926.300(d) requiere interruptores de presi\xF3n constante (constant-pressure) en herramientas como sierras circulares. Los taladros pueden tener interruptor de bloqueo (lock-on) con liberaci\xF3n de un solo movimiento."},{id:"osha_481",categoria:"OSHA_HERRAMIENTAS",pregunta:"Seg\xFAn OSHA, \xBFcu\xE1l es el riesgo principal de usar un cincel de impacto cuya cabeza tiene forma de hongo (mushroomed)?",opciones:["El cincel pierde capacidad de corte y el trabajo se vuelve m\xE1s lento e ineficiente","Fragmentos de metal pueden desprenderse como proyectiles al golpear con el martillo","El mango absorbe m\xE1s vibraci\xF3n y causa s\xEDndrome del t\xFAnel carpiano a largo plazo","La forma de hongo impide que el martillo haga contacto centrado con la herramienta"],respuesta_correcta:1,explicacion:"La cabeza mushroomed tiene bordes de metal fatigado que se fragmentan violentamente bajo impacto, convirti\xE9ndose en proyectiles que causan lesiones oculares y faciales graves."},{id:"osha_482",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 exige OSHA sobre las herramientas actuadas por p\xF3lvora (powder-actuated tools) en sitios de construcci\xF3n?",opciones:["Cualquier trabajador puede operarlas si lee las instrucciones del fabricante primero","Solo operadores entrenados y con certificaci\xF3n vigente pueden usar estas herramientas","Solo electricistas con licencia estatal pueden disparar clavos en estructuras de acero","El supervisor de seguridad debe estar presente f\xEDsicamente durante cada disparo realizado"],respuesta_correcta:1,explicacion:"29 CFR 1926.302(e) requiere que solo operadores entrenados y certificados operen herramientas actuadas por p\xF3lvora. Deben portar su tarjeta de certificaci\xF3n en el sitio de trabajo."},{id:"osha_483",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 protecci\xF3n personal m\xEDnima exige OSHA al operar una herramienta actuada por p\xF3lvora (powder-actuated tool)?",opciones:["Guantes de cuero, protecci\xF3n auditiva y casco con careta facial de policarbonato","Protecci\xF3n ocular adecuada como requisito m\xEDnimo obligatorio durante cada disparo","Respirador N95, guantes de nitrilo y protecci\xF3n auditiva de inserci\xF3n tipo tap\xF3n","Traje completo de protecci\xF3n contra fragmentos con chaleco bal\xEDstico nivel IIIA"],respuesta_correcta:1,explicacion:"29 CFR 1926.302(e)(1) exige como m\xEDnimo protecci\xF3n ocular adecuada. Dependiendo de las condiciones, se puede requerir protecci\xF3n auditiva y facial adicional."},{id:"osha_484",categoria:"OSHA_HERRAMIENTAS",pregunta:"Una herramienta actuada por p\xF3lvora de 'tiro bajo' (low-velocity) se diferencia de una de 'tiro alto' porque:",opciones:["El cartucho de p\xF3lvora contiene menos p\xF3lvora y genera menos retroceso al disparar","El sujetador nunca sale libre del ca\xF1\xF3n ya que es atrapado por un pist\xF3n cautivo","Utiliza clavos de acero inoxidable en lugar de clavos de acero al carbono com\xFAn","Puede dispararse con una sola mano sin necesidad de presionar contra la superficie"],respuesta_correcta:1,explicacion:"En herramientas de tiro bajo (low-velocity), un pist\xF3n cautivo impulsa el sujetador pero no sale del ca\xF1\xF3n, eliminando el riesgo de que el clavo atraviese el material y se convierta en proyectil."},{id:"osha_485",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 prueba debe realizarse antes de usar una herramienta actuada por p\xF3lvora al inicio de cada jornada de trabajo?",opciones:["Una prueba de disparo contra una superficie de concreto para verificar la penetraci\xF3n","Una prueba de disparo al aire libre en zona despejada para comprobar el funcionamiento","Una prueba de funcionamiento siguiendo las instrucciones del fabricante de la herramienta","Una prueba de presi\xF3n del cartucho con un man\xF3metro calibrado de alta precisi\xF3n port\xE1til"],respuesta_correcta:2,explicacion:"29 CFR 1926.302(e)(2) requiere que el operador pruebe la herramienta cada d\xEDa antes de cargarla, siguiendo las instrucciones del fabricante para verificar que todos los mecanismos de seguridad funcionen."},{id:"osha_486",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFA qu\xE9 distancia m\xEDnima debe mantenerse el personal no involucrado cuando se usa una herramienta actuada por p\xF3lvora?",opciones:["Al menos 5 pies de distancia del punto de disparo marcado con cinta amarilla","No existe una distancia fija, pero el \xE1rea debe estar despejada y ser segura seg\xFAn OSHA","Al menos 25 pies de distancia con barrera f\xEDsica de protecci\xF3n contra fragmentos s\xF3lidos","Al menos 50 pies de distancia con se\xF1alizaci\xF3n visible desde todos los accesos del \xE1rea"],respuesta_correcta:1,explicacion:"OSHA no establece una distancia fija espec\xEDfica, pero requiere que el \xE1rea de trabajo est\xE9 despejada y que se tomen precauciones para proteger a todo el personal cercano de rebotes y fragmentos."},{id:"osha_487",categoria:"OSHA_HERRAMIENTAS",pregunta:"Al usar una esmeriladora angular (grinder), \xBFcu\xE1l es el requisito de OSHA respecto a la guarda protectora del disco?",opciones:["La guarda debe cubrir al menos la mitad superior del disco abrasivo en todo momento","Se puede remover si el disco tiene menos de cuatro pulgadas de di\xE1metro total","La guarda es opcional si el t\xE9cnico usa careta facial completa de policarbonato","Solo se requiere guarda cuando se usa un disco de corte, no con disco de desbaste"],respuesta_correcta:0,explicacion:"29 CFR 1926.303(c) requiere que la guarda cubra el disco expuesto. La guarda protege contra fragmentos si el disco se rompe a alta velocidad rotacional (hasta 12,000 RPM)."},{id:"osha_488",categoria:"OSHA_HERRAMIENTAS",pregunta:"Antes de montar un disco abrasivo nuevo en una esmeriladora, \xBFqu\xE9 inspecci\xF3n exige OSHA como obligatoria?",opciones:["Medir el di\xE1metro exacto con un calibrador para confirmar compatibilidad con la guarda","Realizar una prueba de sonido (ring test) golpeando suavemente el disco con herramienta","Verificar que la fecha de fabricaci\xF3n del disco no exceda los seis meses de antig\xFCedad","Pesar el disco en una b\xE1scula de precisi\xF3n para descartar defectos internos ocultos"],respuesta_correcta:1,explicacion:"29 CFR 1926.303(c)(7) requiere el ring test: golpear suavemente el disco con un objeto no met\xE1lico. Un sonido claro indica integridad; un sonido apagado indica grietas internas y el disco debe descartarse."},{id:"osha_489",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFCu\xE1nto tiempo debe funcionar una esmeriladora de banco en vac\xEDo despu\xE9s de montar un disco abrasivo nuevo seg\xFAn OSHA?",opciones:["15 segundos para verificar que no haya vibraci\xF3n excesiva durante el arranque","Al menos un minuto a velocidad m\xE1xima para asegurar que el disco est\xE9 bien montado","30 segundos con el t\xE9cnico parado detr\xE1s de la guarda lateral de protecci\xF3n total","Cinco minutos a media velocidad aumentando gradualmente hasta la velocidad nominal"],respuesta_correcta:1,explicacion:"29 CFR 1926.303(c)(8) requiere que la esmeriladora funcione al menos un minuto en vac\xEDo (sin carga) despu\xE9s de montar un disco nuevo, para verificar que no tenga defectos que causen ruptura."},{id:"osha_490",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFCu\xE1l es la holgura m\xE1xima permitida entre el apoyo de trabajo (tool rest) y el disco abrasivo en una esmeriladora de banco?",opciones:["Un cuarto de pulgada para evitar que la pieza se atasque entre el disco y el apoyo","Un octavo de pulgada o menos para prevenir que la pieza sea atrapada y lanzada","Media pulgada para permitir espacio de maniobra adecuado al t\xE9cnico que opera","Una pulgada completa medida desde el borde del apoyo hasta la cara del disco giratorio"],respuesta_correcta:1,explicacion:"29 CFR 1926.303(c)(5) establece que el apoyo de trabajo no debe estar a m\xE1s de 1/8 de pulgada del disco. Mayor holgura permite que piezas peque\xF1as se atoren y sean lanzadas violentamente."},{id:"osha_491",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 sucede si se monta un disco abrasivo cuya velocidad m\xE1xima nominal (RPM) es menor que la velocidad de la esmeriladora?",opciones:["El disco gira m\xE1s eficientemente y corta materiales m\xE1s duros sin esfuerzo adicional","El disco puede desintegrarse por la fuerza centr\xEDfuga lanzando fragmentos como metralla","La esmeriladora reduce autom\xE1ticamente sus RPM para igualar la capacidad del disco montado","El motor de la esmeriladora se sobrecalienta y se activa la protecci\xF3n t\xE9rmica interna"],respuesta_correcta:1,explicacion:"Nunca se debe exceder la velocidad nominal del disco. La fuerza centr\xEDfuga aumenta con el cuadrado de la velocidad, causando que el disco explote en fragmentos letales a alta velocidad."},{id:"osha_492",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 requisito de seguridad aplica OSHA a las mangueras de herramientas neum\xE1ticas en sitios de construcci\xF3n?",opciones:["Deben ser de color rojo para identificarse f\xE1cilmente entre las mangueras de otros sistemas","Deben asegurarse con un dispositivo anti-l\xE1tigo (whip check) en cada conexi\xF3n de acople","Solo necesitan abrazaderas est\xE1ndar de metal si la presi\xF3n es menor a 50 psi de trabajo","Deben enterrarse bajo tierra para evitar tropezones en las \xE1reas de tr\xE1nsito peatonal"],respuesta_correcta:1,explicacion:"29 CFR 1926.302(b)(1) requiere que las mangueras neum\xE1ticas se aseguren con dispositivos anti-l\xE1tigo (whip checks o safety cables) para prevenir que una manguera suelta bajo presi\xF3n lesione trabajadores."},{id:"osha_493",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 tipo de gatillo requiere OSHA en las pistolas de clavos neum\xE1ticas (pneumatic nailers) para m\xE1xima seguridad?",opciones:["Gatillo de contacto completo que dispara al presionar la punta contra la superficie","Gatillo de disparo secuencial que requiere presionar la punta primero y luego el gatillo","Gatillo autom\xE1tico que dispara continuamente mientras se mantenga presionado sin soltar","Gatillo de doble acci\xF3n que requiere dos presiones consecutivas r\xE1pidas para cada disparo"],respuesta_correcta:1,explicacion:"OSHA recomienda el gatillo secuencial (sequential trigger) como el m\xE1s seguro. Requiere que la punta toque la superficie ANTES de presionar el gatillo, previniendo disparos accidentales por contacto."},{id:"osha_494",categoria:"OSHA_HERRAMIENTAS",pregunta:"Al usar una sierra circular port\xE1til, \xBFqu\xE9 protecci\xF3n espec\xEDfica de la guarda inferior exige OSHA durante el corte?",opciones:["La guarda inferior debe retirarse completamente para tener mejor visibilidad del corte","La guarda inferior debe retraerse autom\xE1ticamente al cortar y cubrir el disco al soltarse","La guarda inferior puede bloquearse en posici\xF3n abierta si el material es muy grueso","La guarda inferior solo se requiere cuando se cortan materiales met\xE1licos ferrosos pesados"],respuesta_correcta:1,explicacion:"29 CFR 1926.304(d) requiere que la guarda inferior retr\xE1ctil se abra autom\xE1ticamente al cortar y regrese por resorte para cubrir el disco completamente cuando se retira del material."},{id:"osha_495",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFPor qu\xE9 OSHA proh\xEDbe bloquear la guarda inferior de una sierra circular en posici\xF3n abierta permanentemente?",opciones:["Porque el polvo del corte se dispersa m\xE1s cuando la guarda est\xE1 abierta sin protecci\xF3n","Porque el disco expuesto puede amputar dedos o manos al terminar el corte del material","Porque la sierra pierde precisi\xF3n de corte cuando la guarda no gu\xEDa la hoja correctamente","Porque el motor se sobrecalienta al recibir polvo directo sin la deflexi\xF3n de la guarda"],respuesta_correcta:1,explicacion:"La guarda inferior debe cubrir el disco autom\xE1ticamente al completar el corte. Bloquearla abierta expone la hoja giratoria, causando miles de amputaciones de dedos y manos anualmente en construcci\xF3n."},{id:"osha_496",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFCu\xE1l es el requisito de OSHA para el almacenamiento de herramientas manuales con bordes cortantes como cinceles y formones?",opciones:["Deben almacenarse en un cubo abierto con los filos hacia arriba para facilitar la selecci\xF3n","Deben guardarse con protectores de filo o en compartimientos que protejan los bordes afilados","Pueden dejarse sueltas en la caja de herramientas junto con las dem\xE1s sin orden espec\xEDfico","Deben envolverse individualmente en papel peri\xF3dico para absorber la humedad del ambiente"],respuesta_correcta:1,explicacion:"OSHA requiere que las herramientas con bordes cortantes se almacenen con protecci\xF3n en los filos para prevenir cortes accidentales al buscar herramientas en la caja o bolsa de trabajo."},{id:"osha_497",categoria:"OSHA_HERRAMIENTAS",pregunta:"Un t\xE9cnico usa un destornillador como palanca para abrir una tapa de registro en un equipo HVAC. Seg\xFAn OSHA, esto es:",opciones:["Aceptable si el destornillador es de mango grande y punta plana resistente al torque","Una violaci\xF3n porque las herramientas deben usarse \xFAnicamente para su prop\xF3sito dise\xF1ado","Permitido como pr\xE1ctica est\xE1ndar si no hay una palanca disponible en el momento del trabajo","Correcto si el t\xE9cnico aplica la fuerza perpendicular al eje para evitar que resbale la punta"],respuesta_correcta:1,explicacion:"29 CFR 1926.301(a) proh\xEDbe usar herramientas para prop\xF3sitos distintos al dise\xF1ado. Un destornillador usado como palanca puede romperse, enviando fragmentos met\xE1licos al rostro del t\xE9cnico."},{id:"osha_498",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 debe hacer un t\xE9cnico cuando una broca de taladro se atasca en una pieza de metal durante la perforaci\xF3n?",opciones:["Forzar el taladro en reversa a m\xE1xima velocidad para liberar la broca r\xE1pidamente","Soltar el gatillo inmediatamente ya que el torque de reacci\xF3n puede fracturar la mu\xF1eca","Sostener el taladro con m\xE1s fuerza y aumentar la presi\xF3n hasta que la broca se libere sola","Desconectar el taladro y usar unas pinzas de presi\xF3n para extraer la broca manualmente"],respuesta_correcta:1,explicacion:"Cuando una broca se atasca, el torque de reacci\xF3n puede girar violentamente el taladro y fracturar la mu\xF1eca o el brazo. Se debe soltar el gatillo inmediatamente y usar el mango auxiliar para control."},{id:"osha_499",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFCu\xE1l es el prop\xF3sito del mango auxiliar (side handle) en un taladro el\xE9ctrico de media pulgada o mayor?",opciones:["Sirve como soporte para colgar el taladro del cintur\xF3n de herramientas del t\xE9cnico","Permite al operador controlar el torque de reacci\xF3n y evitar lesiones en la mu\xF1eca","Funciona como punto de conexi\xF3n para el cable de seguridad anti-ca\xEDda de la herramienta","Mejora la est\xE9tica y el balance visual del taladro para presentaciones a los clientes"],respuesta_correcta:1,explicacion:"El mango auxiliar es un dispositivo de seguridad que permite controlar el torque de reacci\xF3n cuando la broca se atasca, previniendo que el taladro gire violentamente y lesione al operador."},{id:"osha_500",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 verificaci\xF3n de seguridad exige OSHA antes de conectar una herramienta el\xE9ctrica port\xE1til a la fuente de energ\xEDa?",opciones:["Confirmar que el voltaje de la herramienta coincida con el voltaje del circuito disponible","Verificar que el interruptor de la herramienta est\xE9 en posici\xF3n apagado antes de conectarla","Medir la resistencia de aislamiento con un meg\xF3hmetro certificado para cada uso individual","Verificar que la herramienta tenga la etiqueta de inspecci\xF3n mensual del departamento de seguridad"],respuesta_correcta:1,explicacion:"OSHA requiere que el interruptor est\xE9 en OFF antes de conectar para evitar arranques involuntarios. Un t\xE9cnico que conecta una herramienta encendida puede perder el control y sufrir lesiones graves."},{id:"osha_501",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 requisito establece OSHA para los cables de extensi\xF3n temporales utilizados con herramientas el\xE9ctricas en construcci\xF3n?",opciones:["Deben ser de color naranja brillante para identificarse como cables de uso temporal","Deben tener conductor de tierra y ser del calibre adecuado para la carga de la herramienta","Solo necesitan ser de tres conductores si la herramienta consume m\xE1s de diez amperios","Pueden usarse cables de dos conductores si est\xE1n conectados a un circuito con interruptor GFCI"],respuesta_correcta:1,explicacion:"Los cables de extensi\xF3n en construcci\xF3n deben tener conductor de tierra intacto (tres conductores), calibre adecuado para evitar sobrecalentamiento, y estar protegidos con GFCI o programa de cable asegurado."},{id:"osha_502",categoria:"OSHA_HERRAMIENTAS",pregunta:"Un cable de extensi\xF3n pasa por debajo de una puerta y el aislamiento est\xE1 aplastado y expuesto. Seg\xFAn OSHA, esto es:",opciones:["Aceptable si se cubre con cinta aislante de buena calidad como reparaci\xF3n temporal r\xE1pida","Una violaci\xF3n que requiere retirar el cable de servicio y reemplazarlo inmediatamente","Permitido por un m\xE1ximo de 24 horas mientras se consigue un cable de reemplazo adecuado","Normal en sitios de construcci\xF3n y solo requiere se\xF1alizaci\xF3n con cinta de precauci\xF3n"],respuesta_correcta:1,explicacion:"Un cable con aislamiento da\xF1ado es un riesgo de electrocuci\xF3n inmediato. OSHA proh\xEDbe reparaciones con cinta \u2014 el cable debe retirarse de servicio y reemplazarse por uno en buenas condiciones."},{id:"osha_503",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFPor qu\xE9 OSHA requiere que las herramientas neum\xE1ticas se desconecten de la fuente de aire antes de realizar cualquier ajuste?",opciones:["Para conservar el aire comprimido y reducir costos operativos del compresor port\xE1til","Para evitar que la herramienta se active accidentalmente y cause lesiones durante el ajuste","Para proteger el mecanismo interno de la herramienta contra da\xF1os por manipulaci\xF3n incorrecta","Para permitir que la manguera se enfr\xEDe antes de ser manipulada por el t\xE9cnico de servicio"],respuesta_correcta:1,explicacion:"29 CFR 1926.302(b)(4) requiere la desconexi\xF3n de aire antes de ajustes. Una herramienta neum\xE1tica conectada puede activarse inesperadamente, disparando sujetadores o girando partes cortantes."},{id:"osha_504",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 presi\xF3n m\xE1xima de aire comprimido permite OSHA para la limpieza de viruta o desechos en el \xE1rea de trabajo?",opciones:["15 psi con boquilla de seguridad y protecci\xF3n ocular para el operador y circundantes","30 psi con boquilla de seguridad y protecci\xF3n ocular para el operador y circundantes","60 psi con boquilla est\xE1ndar siempre que el operador use careta facial de policarbonato","90 psi con boquilla reductora y el \xE1rea completamente despejada de personal no esencial"],respuesta_correcta:1,explicacion:"29 CFR 1926.302(b)(4) establece que la presi\xF3n de aire para limpieza no debe exceder 30 psi en la boquilla, y se debe usar protecci\xF3n ocular. A presiones mayores, la viruta se convierte en proyectil."},{id:"osha_505",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFCu\xE1l es la regulaci\xF3n OSHA que cubre espec\xEDficamente los requisitos de seguridad para herramientas manuales y el\xE9ctricas en construcci\xF3n?",opciones:["29 CFR 1926 Subpart H que regula almacenamiento y manejo de materiales en sitios","29 CFR 1926 Subpart I que cubre herramientas manuales, el\xE9ctricas y actuadas por p\xF3lvora","29 CFR 1926 Subpart K que regula las instalaciones el\xE9ctricas temporales y permanentes","29 CFR 1926 Subpart P que cubre requisitos de excavaciones y protecci\xF3n de zanjas"],respuesta_correcta:1,explicacion:"29 CFR 1926 Subpart I (Secciones 1926.300-1926.307) cubre todos los requisitos de herramientas: manuales, el\xE9ctricas, neum\xE1ticas, hidr\xE1ulicas, actuadas por p\xF3lvora y abrasivas."},{id:"osha_506",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 responsabilidad tiene el empleador respecto a herramientas que los trabajadores traen de su casa al sitio de trabajo?",opciones:["No tiene ninguna responsabilidad porque las herramientas personales son propiedad del t\xE9cnico","Debe asegurar que est\xE9n en condiciones seguras, igual que las herramientas proporcionadas por \xE9l","Solo necesita verificar que tengan la marca de un fabricante reconocido y certificado nacional","Debe reemplazarlas gratuitamente con herramientas nuevas del inventario de la compa\xF1\xEDa"],respuesta_correcta:1,explicacion:"29 CFR 1926.301(a) establece que el empleador es responsable de la condici\xF3n segura de TODAS las herramientas usadas en el sitio, sin importar si son propiedad del trabajador o de la empresa."},{id:"osha_507",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 protecci\xF3n requiere OSHA al usar un martillo neum\xE1tico (jackhammer) para romper concreto en una instalaci\xF3n HVAC?",opciones:["Solo protecci\xF3n ocular con gafas de seguridad est\xE1ndar con protecci\xF3n lateral incluida","Protecci\xF3n ocular, auditiva, respiratoria contra s\xEDlice, y botas con punta de acero m\xEDnimo","\xDAnicamente botas de seguridad con punta de acero y guantes de cuero resistente al corte","Solo un casco de seguridad clase E y chaleco reflectante de alta visibilidad nocturna"],respuesta_correcta:1,explicacion:"Romper concreto genera s\xEDlice cristalina respirable (regulada por 1926.1153), niveles de ruido superiores a 100 dBA, y fragmentos a alta velocidad. Se requiere protecci\xF3n m\xFAltiple simult\xE1nea."},{id:"osha_508",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFCu\xE1l es el riesgo principal de usar una llave de tubo (pipe wrench) con mordazas desgastadas en tuber\xEDa de refrigeraci\xF3n?",opciones:["El acabado cromado de la tuber\xEDa se da\xF1a y afecta la presentaci\xF3n est\xE9tica del trabajo","Las mordazas pueden resbalar s\xFAbitamente causando p\xE9rdida de equilibrio y golpes severos","La tuber\xEDa se deforma por presi\xF3n irregular y genera una fuga dif\xEDcil de detectar despu\xE9s","El mango de la llave se dobla permanentemente y la herramienta queda fuera de servicio"],respuesta_correcta:1,explicacion:"Mordazas desgastadas no agarran firmemente la tuber\xEDa. Bajo esfuerzo, la llave resbala s\xFAbitamente causando que el t\xE9cnico pierda el equilibrio, golpe\xE1ndose contra equipos o cayendo de la escalera."},{id:"osha_509",categoria:"OSHA_HERRAMIENTAS",pregunta:"\xBFQu\xE9 debe hacer un t\xE9cnico si encuentra una herramienta el\xE9ctrica que produce hormigueo o cosquilleo al tocar la carcasa met\xE1lica?",opciones:["Usar guantes de goma gruesos y continuar trabajando hasta terminar la tarea asignada","Dejar de usar la herramienta inmediatamente porque indica una falla del aislamiento interno","Conectarla a otro tomacorriente para verificar si el problema es del circuito el\xE9ctrico","Reportarlo al final del turno en el formulario de mantenimiento preventivo de herramientas"],respuesta_correcta:1,explicacion:"El hormigueo indica una fuga de corriente por falla del aislamiento interno. Continuar us\xE1ndola puede resultar en electrocuci\xF3n fatal, especialmente en ambientes h\xFAmedos comunes en HVAC."},{id:"osha_510",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es la altura m\xEDnima requerida por OSHA para la baranda superior (top rail) de un sistema de barandas est\xE1ndar en industria general?",opciones:["39 pulgadas desde la superficie de trabajo","42 pulgadas desde la superficie de trabajo","44 pulgadas desde la superficie de trabajo","36 pulgadas desde la superficie de trabajo"],respuesta_correcta:1,explicacion:"29 CFR 1910.29(b)(1) requiere que la baranda superior est\xE9 a 42 pulgadas (\xB13 pulgadas) desde la superficie de trabajo. Esta es una de las medidas m\xE1s confundidas con la de construcci\xF3n (1926)."},{id:"osha_511",categoria:"OSHA_SUPERFICIES",pregunta:"Seg\xFAn OSHA 29 CFR 1910 Subpart D, \xBFa partir de qu\xE9 di\xE1metro un agujero en el piso requiere protecci\xF3n con cubierta o baranda?",opciones:["1 pulgada de di\xE1metro en adelante","2 pulgadas de di\xE1metro en adelante","4 pulgadas de di\xE1metro en adelante","6 pulgadas de di\xE1metro en adelante"],respuesta_correcta:1,explicacion:"Un agujero en el piso de 2 pulgadas o m\xE1s de di\xE1metro debe estar protegido con cubierta o baranda para prevenir que el pie de un trabajador pase a trav\xE9s. Muchos confunden esto con el tama\xF1o m\xEDnimo de 1 pulgada."},{id:"osha_512",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es la altura m\xEDnima requerida para un toeboard (rodapi\xE9) instalado en el borde de una plataforma elevada seg\xFAn industria general?",opciones:["2.5 pulgadas desde la superficie del piso","3.5 pulgadas desde la superficie del piso","4.5 pulgadas desde la superficie del piso","5.5 pulgadas desde la superficie del piso"],respuesta_correcta:1,explicacion:"29 CFR 1910.29(k) establece que los toeboards deben tener un m\xEDnimo de 3.5 pulgadas de altura desde la superficie del piso. Esto previene que herramientas y materiales caigan al nivel inferior."},{id:"osha_513",categoria:"OSHA_SUPERFICIES",pregunta:"En construcci\xF3n (29 CFR 1926 Subpart M), \xBFa partir de qu\xE9 altura de ca\xEDda se requiere protecci\xF3n contra ca\xEDdas para un trabajador?",opciones:["4 pies sobre el nivel inferior","6 pies sobre el nivel inferior","8 pies sobre el nivel inferior","10 pies sobre el nivel inferior"],respuesta_correcta:1,explicacion:"29 CFR 1926.501(b)(1) requiere protecci\xF3n contra ca\xEDdas a partir de 6 pies en construcci\xF3n. Muchos lo confunden con los 4 pies de industria general (1910.28) o los 10 pies de acero estructural."},{id:"osha_514",categoria:"OSHA_SUPERFICIES",pregunta:"En industria general (29 CFR 1910.28), \xBFa partir de qu\xE9 altura un borde abierto requiere protecci\xF3n contra ca\xEDdas?",opciones:["4 pies sobre el nivel inferior","6 pies sobre el nivel inferior","8 pies sobre el nivel inferior","3 pies sobre el nivel inferior"],respuesta_correcta:0,explicacion:"29 CFR 1910.28(b)(1) establece 4 pies como la altura de activaci\xF3n para protecci\xF3n contra ca\xEDdas en industria general. Esto es diferente a los 6 pies requeridos en construcci\xF3n (1926 Subpart M)."},{id:"osha_515",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 debe hacer un t\xE9cnico HVAC cuando encuentra una cubierta temporal sobre un agujero en el piso que NO est\xE1 asegurada ni marcada?",opciones:["Caminar sobre ella con cuidado si parece firme","Moverla para inspeccionar el agujero debajo","Asegurarla y marcarla con la palabra HOLE","Reportarla pero seguir trabajando en el \xE1rea"],respuesta_correcta:2,explicacion:"29 CFR 1910.29(e)(1) y 1926.502(i) requieren que las cubiertas de agujeros est\xE9n aseguradas contra desplazamiento y marcadas con la palabra 'HOLE' o 'COVER'. Una cubierta sin asegurar es un peligro inmediato."},{id:"osha_516",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es la carga m\xEDnima que debe soportar una cubierta de agujero en el piso seg\xFAn los est\xE1ndares de OSHA?",opciones:["Dos veces el peso m\xE1ximo esperado sobre ella","Tres veces el peso m\xE1ximo esperado sobre ella","Cuatro veces el peso m\xE1ximo esperado sobre ella","Una y media veces el peso m\xE1ximo sobre ella"],respuesta_correcta:0,explicacion:"Las cubiertas de agujeros deben soportar al menos dos veces la carga m\xE1xima anticipada, incluyendo peso de trabajadores, equipos y materiales que puedan transitar sobre ellas durante operaciones normales."},{id:"osha_517",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es el \xE1ngulo m\xE1ximo permitido por OSHA para una escalera fija est\xE1ndar en industria general?",opciones:["50 grados respecto a la horizontal","60 grados respecto a la horizontal","70 grados respecto a la horizontal","80 grados respecto a la horizontal"],respuesta_correcta:0,explicacion:"Las escaleras fijas est\xE1ndar (stairways) en industria general deben instalarse entre 30\xB0 y 50\xB0 respecto a la horizontal. Si el \xE1ngulo supera los 50\xB0, se considera una escalera de mano fija (fixed ladder) con requisitos diferentes."},{id:"osha_518",categoria:"OSHA_SUPERFICIES",pregunta:"Seg\xFAn OSHA, \xBFcu\xE1l es el ancho m\xEDnimo requerido para una escalera fija est\xE1ndar en un lugar de trabajo de industria general?",opciones:["20 pulgadas de ancho libre","22 pulgadas de ancho libre","24 pulgadas de ancho libre","28 pulgadas de ancho libre"],respuesta_correcta:1,explicacion:"29 CFR 1910.25(b)(3) requiere un ancho m\xEDnimo de 22 pulgadas para escaleras fijas est\xE1ndar. Muchos confunden este requisito con el de plataformas o pasarelas que tienen diferentes medidas m\xEDnimas."},{id:"osha_519",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 altura m\xE1xima puede tener un escal\xF3n individual (riser) en una escalera fija de industria general seg\xFAn OSHA?",opciones:["7.0 pulgadas de altura m\xE1xima","8.5 pulgadas de altura m\xE1xima","9.5 pulgadas de altura m\xE1xima","6.5 pulgadas de altura m\xE1xima"],respuesta_correcta:2,explicacion:"29 CFR 1910.25(b)(2) permite una altura m\xE1xima de escal\xF3n (riser) de 9.5 pulgadas. La uniformidad entre escalones es igualmente importante; la variaci\xF3n no debe exceder 3/16 de pulgada entre escalones."},{id:"osha_520",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCon qu\xE9 frecuencia m\xEDnima exige OSHA realizar inspecciones de housekeeping (orden y limpieza) en superficies de trabajo?",opciones:["Una vez por semana como m\xEDnimo obligatorio","Una vez al mes como m\xEDnimo obligatorio","Tan frecuente como sea necesario regularmente","Una vez por turno como m\xEDnimo obligatorio"],respuesta_correcta:2,explicacion:"29 CFR 1910.22(a) requiere que las superficies de trabajo se mantengan limpias, ordenadas y en condici\xF3n sanitaria 'tan frecuentemente como sea necesario'. No establece un intervalo fijo sino una obligaci\xF3n continua."},{id:"osha_521",categoria:"OSHA_SUPERFICIES",pregunta:"Cuando un t\xE9cnico HVAC trabaja en un techo con borde desprotegido a 12 pies de altura, \xBFqu\xE9 sistema de protecci\xF3n es SIEMPRE aceptable?",opciones:["L\xEDnea de advertencia a 6 pies del borde","Sistema personal de detenci\xF3n de ca\xEDdas","Zona de acceso controlado con monitor","Se\xF1alizaci\xF3n visible en el borde del techo"],respuesta_correcta:1,explicacion:"Un sistema personal de detenci\xF3n de ca\xEDdas (PFAS) siempre es aceptable. Las l\xEDneas de advertencia y zonas de acceso controlado tienen limitaciones espec\xEDficas seg\xFAn el tipo de trabajo y la altura. La se\xF1alizaci\xF3n sola nunca es suficiente."},{id:"osha_522",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFA qu\xE9 distancia m\xEDnima del borde del techo debe colocarse una l\xEDnea de advertencia (warning line) seg\xFAn 29 CFR 1926.502(f)?",opciones:["6 pies del borde en todos los lados","10 pies del borde en todos los lados","15 pies del borde en todos los lados","8 pies del borde en todos los lados"],respuesta_correcta:0,explicacion:"29 CFR 1926.502(f)(2) requiere que la l\xEDnea de advertencia se coloque a no menos de 6 pies del borde del techo. Si se usa equipo mec\xE1nico, la distancia aumenta a 6 pies del borde o del equipo mec\xE1nico."},{id:"osha_523",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es la causa n\xFAmero uno de muertes en la industria de la construcci\xF3n seg\xFAn las estad\xEDsticas de OSHA?",opciones:["Electrocuci\xF3n por contacto con l\xEDneas vivas","Golpes por objetos que caen desde altura","Ca\xEDdas desde alturas a un nivel inferior","Quedar atrapado entre equipos o materiales"],respuesta_correcta:2,explicacion:"Las ca\xEDdas representan consistentemente la causa #1 de muertes en construcci\xF3n, siendo parte del 'Fatal Four' de OSHA. Por eso la protecci\xF3n de superficies de trabajo y bordes es tan cr\xEDtica en la normativa."},{id:"osha_524",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es el espaciamiento m\xE1ximo permitido entre balaustres verticales (midrails) de una baranda est\xE1ndar seg\xFAn industria general?",opciones:["15 pulgadas de separaci\xF3n entre ellos","19 pulgadas de separaci\xF3n entre ellos","21 pulgadas de separaci\xF3n entre ellos","24 pulgadas de separaci\xF3n entre ellos"],respuesta_correcta:1,explicacion:"29 CFR 1910.29(b)(2) requiere que los balaustres intermedios no permitan el paso de una esfera de 19 pulgadas. Esto previene que un trabajador pueda caer o deslizarse entre los componentes de la baranda."},{id:"osha_525",categoria:"OSHA_SUPERFICIES",pregunta:"Un t\xE9cnico HVAC debe acceder a una azotea usando una escalera de mano port\xE1til. \xBFCu\xE1nto debe sobresalir la escalera por encima del punto de llegada?",opciones:["24 pulgadas por encima del punto de apoyo","36 pulgadas por encima del punto de apoyo","42 pulgadas por encima del punto de apoyo","48 pulgadas por encima del punto de apoyo"],respuesta_correcta:1,explicacion:"29 CFR 1926.1053(b)(1) y 1910.23(b)(1) requieren que la escalera se extienda al menos 36 pulgadas (3 pies) por encima del punto de desembarco. Esto permite al trabajador agarrarse al subir y bajar."},{id:"osha_526",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 tipo de superficie de piso es M\xC1S probable que cause resbalones en un cuarto mec\xE1nico donde se instala equipo HVAC?",opciones:["Concreto sellado con acabado muy liso y pulido","Concreto con textura de escoba sin sellar","Piso con rejilla met\xE1lica tipo diamante abierta","Baldosa antideslizante con coeficiente alto"],respuesta_correcta:0,explicacion:"El concreto sellado con acabado liso y pulido tiene el coeficiente de fricci\xF3n m\xE1s bajo, especialmente cuando est\xE1 mojado. Los cuartos mec\xE1nicos con condensaci\xF3n o fugas son particularmente peligrosos con este acabado."},{id:"osha_527",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 acci\xF3n es la PRIMERA que debe tomar un empleador cuando identifica un peligro de resbal\xF3n en una superficie de trabajo?",opciones:["Proveer equipo de protecci\xF3n personal adecuado","Colocar se\xF1ales de advertencia en el \xE1rea visible","Eliminar o controlar el peligro en la superficie","Capacitar a los empleados sobre c\xF3mo caminar"],respuesta_correcta:2,explicacion:"Seg\xFAn la jerarqu\xEDa de controles de OSHA, la eliminaci\xF3n del peligro es siempre la primera opci\xF3n. El PPE es el \xDALTIMO recurso. Primero se elimina el peligro (limpiar derrame, reparar superficie), luego controles administrativos."},{id:"osha_528",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1ndo debe un empleador proveer protecci\xF3n contra ca\xEDdas a un trabajador en un andamio seg\xFAn la norma de construcci\xF3n?",opciones:["A partir de los 6 pies de altura sobre nivel","A partir de los 8 pies de altura sobre nivel","A partir de los 10 pies de altura sobre nivel","A partir de los 4 pies de altura sobre nivel"],respuesta_correcta:2,explicacion:"29 CFR 1926.451(g)(1) establece 10 pies como la altura de activaci\xF3n para protecci\xF3n contra ca\xEDdas en andamios. Esto es diferente a los 6 pies generales de construcci\xF3n y los 4 pies de industria general."},{id:"osha_529",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 secci\xF3n del CFR 29 cubre espec\xEDficamente las superficies para caminar y trabajar en industria general?",opciones:["29 CFR 1910 Subpart C \u2014 General Safety","29 CFR 1910 Subpart D \u2014 Walking-Working","29 CFR 1910 Subpart E \u2014 Exit and Egress","29 CFR 1926 Subpart M \u2014 Fall Protection"],respuesta_correcta:1,explicacion:"29 CFR 1910 Subpart D cubre Walking-Working Surfaces en industria general. Subpart M de 1926 cubre protecci\xF3n contra ca\xEDdas en construcci\xF3n. Muchos confunden ambas subpartes y sus requisitos espec\xEDficos."},{id:"osha_530",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es la carga m\xEDnima concentrada que debe soportar una baranda est\xE1ndar (top rail) aplicada en cualquier direcci\xF3n?",opciones:["100 libras de fuerza en cualquier direcci\xF3n","150 libras de fuerza en cualquier direcci\xF3n","200 libras de fuerza en cualquier direcci\xF3n","250 libras de fuerza en cualquier direcci\xF3n"],respuesta_correcta:2,explicacion:"29 CFR 1910.29(b)(3) requiere que la baranda superior resista una fuerza de al menos 200 libras aplicada en cualquier direcci\xF3n hacia abajo o hacia afuera. Esto asegura que soporte el peso de un trabajador que se recargue."},{id:"osha_531",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 condici\xF3n de una escalera fija requiere que se instale una jaula de protecci\xF3n (cage) o sistema de seguridad seg\xFAn OSHA?",opciones:["Cuando la escalera excede 20 pies de altura","Cuando la escalera excede 24 pies de altura","Cuando la escalera excede 30 pies de altura","Cuando la escalera excede 15 pies de altura"],respuesta_correcta:1,explicacion:"29 CFR 1910.28(b)(9) requiere protecci\xF3n contra ca\xEDdas en escaleras fijas que excedan 24 pies. Esto puede ser una jaula, un sistema de rieles de seguridad, o un sistema personal de detenci\xF3n de ca\xEDdas."},{id:"osha_532",categoria:"OSHA_SUPERFICIES",pregunta:"Un t\xE9cnico HVAC nota que el piso de un cuarto mec\xE1nico tiene un cable de extensi\xF3n cruz\xE1ndolo. \xBFCu\xE1l es la acci\xF3n correcta seg\xFAn OSHA?",opciones:["Cubrir el cable con cinta adhesiva de colores","Asegurar el cable con una cubierta protectora","Colocar un letrero advirtiendo sobre el cable","Pasar el cable por debajo de una alfombra gruesa"],respuesta_correcta:1,explicacion:"29 CFR 1910.22(a)(3) requiere que los cables y mangueras en superficies de tr\xE1nsito est\xE9n cubiertos, elevados o protegidos para prevenir tropiezos. Las cubiertas protectoras dise\xF1adas para cables son el m\xE9todo aprobado."},{id:"osha_533",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es la profundidad m\xEDnima (tread depth) requerida para el pelda\xF1o de una escalera fija industrial seg\xFAn OSHA?",opciones:["8 pulgadas de profundidad m\xEDnima del pelda\xF1o","9 pulgadas de profundidad m\xEDnima del pelda\xF1o","10 pulgadas de profundidad m\xEDnima del pelda\xF1o","12 pulgadas de profundidad m\xEDnima del pelda\xF1o"],respuesta_correcta:1,explicacion:"29 CFR 1910.25(b)(4) requiere una profundidad m\xEDnima de pelda\xF1o de 9.5 pulgadas (redondeado a 9 en la pr\xE1ctica). Esto asegura que el pie del trabajador tenga apoyo suficiente al subir o bajar las escaleras."},{id:"osha_534",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 factor es el M\xC1S importante para determinar si una superficie de techo puede soportar a un t\xE9cnico HVAC y su equipo?",opciones:["La antig\xFCedad del material de la cubierta","La capacidad de carga estructural del techo","El tipo de impermeabilizante que fue usado","La pendiente o inclinaci\xF3n total del techo"],respuesta_correcta:1,explicacion:"La capacidad de carga estructural (load rating) es el factor determinante. Un techo puede verse en buenas condiciones pero no soportar el peso concentrado de un trabajador con equipo. OSHA requiere verificar la capacidad antes de acceder."},{id:"osha_535",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCada cu\xE1ntos pies de altura debe haber una plataforma de descanso en una escalera fija vertical (fixed ladder) seg\xFAn OSHA?",opciones:["Cada 20 pies debe haber una plataforma","Cada 25 pies debe haber una plataforma","Cada 30 pies debe haber una plataforma","Cada 35 pies debe haber una plataforma"],respuesta_correcta:2,explicacion:"OSHA requiere plataformas de descanso cada 30 pies en escaleras fijas verticales cuando no hay un sistema de seguridad tipo riel. Esto previene la fatiga del trabajador durante ascensos prolongados en escaleras largas."},{id:"osha_536",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 requisito especial aplica cuando una abertura en el piso es lo suficientemente grande para que una persona caiga a trav\xE9s?",opciones:["Solo se necesita pintar el borde de amarillo","Se requiere cubierta capaz de soportar tr\xE1fico","Se requiere baranda est\xE1ndar con rodapi\xE9 incluido","Solo colocar conos de tr\xE1fico alrededor del \xE1rea"],respuesta_correcta:2,explicacion:"29 CFR 1910.28(b)(3) requiere baranda est\xE1ndar completa (top rail, midrail, toeboard) alrededor de aberturas en el piso por las que una persona pueda caer. Una cubierta tambi\xE9n es aceptable si cumple requisitos de carga."},{id:"osha_537",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'walking-working surface' seg\xFAn la definici\xF3n oficial de OSHA en 29 CFR 1910.21?",opciones:["Solo pisos permanentes dentro de edificaciones","Cualquier superficie horizontal o vertical usada","Cualquier superficie donde un empleado camina o trabaja","Solo plataformas elevadas y andamios certificados"],respuesta_correcta:2,explicacion:"29 CFR 1910.21(a) define walking-working surface como cualquier superficie, horizontal o vertical, sobre la cual un empleado camina o trabaja. Incluye pisos, techos, rampas, pasarelas, escaleras y plataformas."},{id:"osha_538",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es el \xE1ngulo correcto de inclinaci\xF3n para colocar una escalera de mano port\xE1til seg\xFAn la regla de OSHA?",opciones:["Proporci\xF3n de 1 pie de base por cada 3 pies","Proporci\xF3n de 1 pie de base por cada 4 pies","Proporci\xF3n de 1 pie de base por cada 5 pies","Proporci\xF3n de 1 pie de base por cada 6 pies"],respuesta_correcta:1,explicacion:"La regla de 4 a 1 (75.5 grados) es el est\xE1ndar de OSHA: por cada 4 pies de altura, la base debe estar a 1 pie de la pared. Esto proporciona el \xE1ngulo m\xE1s seguro y estable para escaleras port\xE1tiles rectas."},{id:"osha_539",categoria:"OSHA_SUPERFICIES",pregunta:"\xBFCu\xE1l es la acci\xF3n correcta de OSHA cuando un empleado debe trabajar sobre un tragaluz (skylight) en un techo?",opciones:["Caminar cuidadosamente alrededor del tragaluz","Instalar baranda o cubierta capaz de soportarlo","Cubrir el tragaluz con una lona gruesa visible","Marcar el tragaluz con pintura fluorescente"],respuesta_correcta:1,explicacion:"29 CFR 1926.502(i) y 1910.29(e) requieren que los tragaluces est\xE9n protegidos con barandas est\xE1ndar o cubiertas que soporten al menos dos veces el peso del trabajador y equipo. Los tragaluces son una causa frecuente de ca\xEDdas fatales."},{id:"osha_540",categoria:"OSHA_MAQUINARIA",pregunta:"Seg\xFAn 29 CFR 1910 Subpart O, \xBFcu\xE1l es el prop\xF3sito PRINCIPAL de los resguardos de maquinaria en el lugar de trabajo?",opciones:["Evitar que el operador tenga contacto con las partes m\xF3viles de la m\xE1quina","Reducir el nivel de ruido que genera la maquinaria industrial pesada","Proteger la m\xE1quina contra da\xF1os causados por objetos externos sueltos","Facilitar el mantenimiento preventivo programado de los componentes internos"],respuesta_correcta:0,explicacion:"El prop\xF3sito principal de los resguardos (machine guards) seg\xFAn OSHA Subpart O es prevenir el contacto del trabajador con partes m\xF3viles peligrosas de la maquinaria."},{id:"osha_541",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFQu\xE9 tipo de resguardo de m\xE1quina est\xE1 permanentemente fijado a la estructura y NO requiere ajuste por parte del operador?",opciones:["Resguardo fijo que se sujeta con tornillos o se suelda a la estructura","Resguardo ajustable que el operador posiciona seg\xFAn la pieza de trabajo","Resguardo autoajustable que se mueve seg\xFAn el tama\xF1o del material","Resguardo interconectado que desactiva la m\xE1quina al ser removido"],respuesta_correcta:0,explicacion:"El resguardo fijo (fixed guard) es una barrera permanente que se atornilla, suelda o fija a la m\xE1quina y no permite ajuste ni movimiento por parte del operador."},{id:"osha_542",categoria:"OSHA_MAQUINARIA",pregunta:"Un resguardo interconectado (interlocked guard) se diferencia de los dem\xE1s porque al abrirlo o removerlo autom\xE1ticamente:",opciones:["Desconecta la fuente de energ\xEDa o detiene el ciclo operativo de la m\xE1quina","Activa una alarma sonora para alertar al supervisor del \xE1rea de trabajo","Reduce la velocidad de las partes m\xF3viles a un nivel seguro de operaci\xF3n","Bloquea la alimentaci\xF3n de material hacia el punto de operaci\xF3n principal"],respuesta_correcta:0,explicacion:"La caracter\xEDstica clave del resguardo interconectado es que al abrirlo o removerlo, autom\xE1ticamente corta la energ\xEDa o detiene el movimiento de la m\xE1quina (trip/shutoff mechanism)."},{id:"osha_543",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l es la principal ventaja del resguardo autoajustable (self-adjusting guard) en operaciones de maquinaria?",opciones:["Se abre solo lo necesario para que pase el material y luego vuelve a cerrarse","Detecta autom\xE1ticamente fallas mec\xE1nicas y apaga la m\xE1quina por completo","Permite al operador cambiar su posici\xF3n sin necesidad de usar herramientas","Se adapta a diferentes voltajes de alimentaci\xF3n el\xE9ctrica de forma autom\xE1tica"],respuesta_correcta:0,explicacion:"El resguardo autoajustable se mueve autom\xE1ticamente para permitir el paso del material (stock) y regresa a su posici\xF3n de protecci\xF3n, manteniendo la barrera el mayor tiempo posible."},{id:"osha_544",categoria:"OSHA_MAQUINARIA",pregunta:"En la protecci\xF3n de maquinaria, \xBFqu\xE9 se define como 'punto de operaci\xF3n' (point of operation)?",opciones:["El \xE1rea donde la m\xE1quina realiza el corte, perforado o formado del material","La zona donde el operador acciona los controles de arranque y de parada","El lugar donde se almacena el material antes de ser procesado por la m\xE1quina","La secci\xF3n donde se conecta la fuente principal de energ\xEDa el\xE9ctrica trif\xE1sica"],respuesta_correcta:0,explicacion:"El punto de operaci\xF3n es el \xE1rea espec\xEDfica donde la m\xE1quina realiza trabajo sobre el material \u2014 cortando, perforando, doblando, formando, etc. Es una de las zonas de mayor peligro."},{id:"osha_545",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFQu\xE9 es un 'punto de pellizco' (nip point) en el contexto de protecci\xF3n de maquinaria industrial?",opciones:["La zona donde dos partes rotatorias convergen y pueden atrapar extremidades","El \xE1rea donde el operador coloca las manos para alimentar material a la m\xE1quina","El punto donde se ajusta la tensi\xF3n de las correas de transmisi\xF3n de potencia","La ubicaci\xF3n donde se instala el interruptor de emergencia de parada r\xE1pida"],respuesta_correcta:0,explicacion:"Un nip point (punto de pellizco) se forma donde dos rodillos, engranajes u otras partes rotatorias convergen, creando riesgo de atrapamiento de dedos, manos o ropa."},{id:"osha_546",categoria:"OSHA_MAQUINARIA",pregunta:"Seg\xFAn OSHA, el aparato de transmisi\xF3n de potencia (power transmission apparatus) incluye TODOS los siguientes componentes EXCEPTO:",opciones:["La cuchilla de corte que da forma directa a la pieza en el punto de operaci\xF3n","Los ejes rotativos y acoplamientos que transfieren movimiento entre componentes","Las poleas y correas que transmiten la fuerza motriz a trav\xE9s del sistema mec\xE1nico","Los engranajes y cadenas que conectan el motor con el mecanismo de la m\xE1quina"],respuesta_correcta:0,explicacion:"La cuchilla de corte es parte del punto de operaci\xF3n, no del aparato de transmisi\xF3n de potencia. El power transmission apparatus incluye ejes, poleas, correas, cadenas, engranajes y acoplamientos."},{id:"osha_547",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l es el requisito de OSHA para las ruedas abrasivas (abrasive wheels) que se montan en un esmeril de banco (bench grinder)?",opciones:["Deben tener un resguardo que cubra al menos el 75 por ciento de la superficie de la rueda","Deben girar a una velocidad m\xE1xima de 1200 revoluciones por minuto sin excepci\xF3n","Deben reemplazarse cada treinta d\xEDas de uso independientemente de su estado visible","Deben ser operadas \xFAnicamente por trabajadores con certificaci\xF3n especial vigente"],respuesta_correcta:0,explicacion:"OSHA requiere que las ruedas abrasivas en esmeriles de banco tengan guardas de seguridad que expongan no m\xE1s del 25% de la rueda (cubriendo al menos 75%), seg\xFAn 29 CFR 1910.215."},{id:"osha_548",categoria:"OSHA_MAQUINARIA",pregunta:"Antes de montar una rueda abrasiva nueva en un esmeril, OSHA requiere que el trabajador realice:",opciones:["Una prueba de anillo (ring test) para verificar que la rueda no tenga grietas internas","Una medici\xF3n de voltaje para confirmar que el motor soporta la carga de la nueva rueda","Un an\xE1lisis qu\xEDmico del material abrasivo para determinar su grado de toxicidad exacta","Una calibraci\xF3n del tac\xF3metro digital para asegurar la lectura correcta de velocidad"],respuesta_correcta:0,explicacion:"El ring test consiste en golpear suavemente la rueda y escuchar un sonido claro (sin grietas). Una rueda agrietada produce un sonido sordo y NO debe montarse."},{id:"osha_549",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l es la distancia m\xE1xima permitida por OSHA entre el descanso de trabajo (tool rest) y la superficie de la rueda abrasiva?",opciones:["Un octavo de pulgada como m\xE1ximo para evitar que la pieza se atasque en el espacio","Un cuarto de pulgada como m\xE1ximo para permitir ventilaci\xF3n adecuada del abrasivo","Media pulgada como m\xE1ximo para que el operador pueda posicionar piezas c\xF3modamente","Una pulgada como m\xE1ximo para facilitar el cambio r\xE1pido entre diferentes tipos de ruedas"],respuesta_correcta:0,explicacion:"OSHA requiere que el tool rest est\xE9 ajustado a no m\xE1s de 1/8 de pulgada (3 mm) de la rueda abrasiva para prevenir que la pieza de trabajo sea jalada hacia el espacio."},{id:"osha_550",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l es la distancia m\xE1xima que OSHA permite entre la leng\xFCeta ajustable (adjustable tongue guard) y la superficie de una rueda abrasiva?",opciones:["Un cuarto de pulgada para minimizar la exposici\xF3n del trabajador a fragmentos rotos","Un octavo de pulgada para asegurar que las chispas se direccionen correctamente","Media pulgada para permitir que el fluido refrigerante alcance la zona de contacto","Tres cuartos de pulgada para facilitar la visibilidad del punto de esmerilado"],respuesta_correcta:0,explicacion:"La leng\xFCeta ajustable (adjustable tongue guard) debe mantenerse a no m\xE1s de 1/4 de pulgada de la rueda abrasiva seg\xFAn 29 CFR 1910.215, distinta de la medida del tool rest (1/8 pulg.)."},{id:"osha_551",categoria:"OSHA_MAQUINARIA",pregunta:"En una prensa mec\xE1nica de potencia (mechanical power press), \xBFqu\xE9 dispositivo detecta una falla en el mecanismo y detiene el recorrido?",opciones:["El monitor de freno y embrague que supervisa el funcionamiento del ciclo completo","El interruptor de l\xEDmite de carrera que regula la posici\xF3n inferior del ariete m\xF3vil","El sensor de presencia que detecta cuando el operador ingresa al \xE1rea restringida","El controlador l\xF3gico programable que gestiona la secuencia autom\xE1tica de operaci\xF3n"],respuesta_correcta:0,explicacion:"El brake monitor en prensas mec\xE1nicas detecta deterioro en el sistema de freno/embrague y detiene la operaci\xF3n si el tiempo de parada excede los l\xEDmites normales (29 CFR 1910.217)."},{id:"osha_552",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l de los siguientes es un dispositivo de protecci\xF3n (safeguarding device) y NO un resguardo (guard) de m\xE1quina?",opciones:["Una cortina de luz infrarroja que detiene la m\xE1quina al detectar una obstrucci\xF3n","Una barrera fija de metal que impide el acceso f\xEDsico a las partes en movimiento","Una cubierta ajustable de policarbonato que rodea el \xE1rea del punto de operaci\xF3n","Un encerramiento permanente soldado que cubre completamente la zona de peligro"],respuesta_correcta:0,explicacion:"La cortina de luz (light curtain) es un dispositivo de protecci\xF3n que detecta presencia y detiene la m\xE1quina; los dem\xE1s son resguardos (guards) que act\xFAan como barreras f\xEDsicas."},{id:"osha_553",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFQu\xE9 tipo de dispositivo de protecci\xF3n utiliza un mecanismo que f\xEDsicamente retira las manos del operador del punto de operaci\xF3n?",opciones:["Un dispositivo de retirada (pullback device) conectado con correas a las mu\xF1ecas","Un control a dos manos que requiere presi\xF3n simult\xE1nea para activar el mecanismo","Una cortina de luz que crea una barrera invisible frente al punto de operaci\xF3n","Un tapete sensible a presi\xF3n que detecta cuando alguien pisa la zona de peligro"],respuesta_correcta:0,explicacion:"El pullback device (dispositivo de retirada) usa cables conectados a las mu\xF1ecas del operador que jalan las manos fuera del punto de operaci\xF3n cuando la m\xE1quina inicia su ciclo."},{id:"osha_554",categoria:"OSHA_MAQUINARIA",pregunta:"Un sistema de control a dos manos (two-hand control) protege al operador de una prensa porque:",opciones:["Requiere que ambas manos est\xE9n en los botones durante todo el ciclo de operaci\xF3n","Permite que un solo operador maneje dos m\xE1quinas al mismo tiempo de forma segura","Duplica la se\xF1al el\xE9ctrica para garantizar que el motor tenga suficiente par de arranque","Reduce el tiempo del ciclo a la mitad al activar ambos lados del ariete en paralelo"],respuesta_correcta:0,explicacion:"El two-hand control requiere presi\xF3n simult\xE1nea y continua de ambas manos en los botones, asegurando que las manos del operador no est\xE9n en el punto de operaci\xF3n durante el ciclo."},{id:"osha_555",categoria:"OSHA_MAQUINARIA",pregunta:"Seg\xFAn OSHA, \xBFcu\xE1ndo se debe realizar la inspecci\xF3n de las prensas mec\xE1nicas de potencia por personal certificado?",opciones:["Al menos una vez cada doce meses seg\xFAn lo requiere la norma federal aplicable","\xDAnicamente cuando el operador reporta una vibraci\xF3n anormal durante la operaci\xF3n","Cada vez que se cambia el troquel independientemente del intervalo transcurrido","Solamente despu\xE9s de que ocurra un accidente o incidente reportable en la prensa"],respuesta_correcta:0,explicacion:"29 CFR 1910.217(e)(1) requiere inspecci\xF3n anual (cada 12 meses) de prensas mec\xE1nicas por personal certificado y competente para evaluar frenos, embragues y mecanismos de seguridad."},{id:"osha_556",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFQu\xE9 acci\xF3n debe realizarse PRIMERO antes de dar servicio o mantenimiento a cualquier m\xE1quina con partes m\xF3viles peligrosas?",opciones:["Bloquear y etiquetar todas las fuentes de energ\xEDa siguiendo el procedimiento LOTO","Notificar al supervisor del turno siguiente para que programe un reemplazo temporal","Colocar se\xF1alizaci\xF3n de advertencia visible en un radio de diez pies alrededor del \xE1rea","Consultar el manual del fabricante para identificar las partes que necesitan lubricaci\xF3n"],respuesta_correcta:0,explicacion:"Lockout/Tagout (LOTO) seg\xFAn 29 CFR 1910.147 es el PRIMER paso obligatorio antes de cualquier mantenimiento \u2014 se deben aislar y bloquear todas las fuentes de energ\xEDa peligrosa."},{id:"osha_557",categoria:"OSHA_MAQUINARIA",pregunta:"Un t\xE9cnico de HVAC trabaja cerca de un ventilador industrial con aspas expuestas. \xBFQu\xE9 tipo de resguardo es m\xE1s apropiado?",opciones:["Un resguardo fijo de malla met\xE1lica que cubra completamente las aspas rotatorias","Un resguardo autoajustable que se abra cuando el aire necesite mayor flujo libre","Un dispositivo de retirada conectado al brazo del t\xE9cnico mediante cables flexibles","Un control a dos manos instalado directamente en el panel del ventilador industrial"],respuesta_correcta:0,explicacion:"Para ventiladores industriales con aspas expuestas, el resguardo fijo de malla met\xE1lica es el m\xE1s apropiado \u2014 cubre permanentemente las partes rotatorias sin impedir el flujo de aire."},{id:"osha_558",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l es el peligro principal asociado con los ejes rotativos (rotating shafts) en equipos de transmisi\xF3n de potencia?",opciones:["El atrapamiento de ropa suelta o cabello largo del trabajador que gira y lo enrolla","La generaci\xF3n de chispas que pueden causar incendios en \xE1reas con material inflamable","La emisi\xF3n de part\xEDculas met\xE1licas calientes que causan quemaduras en la piel expuesta","La vibraci\xF3n excesiva que afloja los pernos de anclaje y desalinea toda la maquinaria"],respuesta_correcta:0,explicacion:"Los ejes rotativos presentan peligro de atrapamiento (entanglement) \u2014 ropa suelta, cabello, guantes o joyer\xEDa pueden quedar atrapados y enrollar al trabajador alrededor del eje."},{id:"osha_559",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFEn cu\xE1l de estos escenarios OSHA permite operar una m\xE1quina sin resguardos de protecci\xF3n en su lugar?",opciones:["En ning\xFAn escenario ya que los resguardos deben estar colocados siempre durante la operaci\xF3n","Cuando el operador tiene m\xE1s de diez a\xF1os de experiencia documentada con esa m\xE1quina exacta","Cuando la velocidad de la m\xE1quina se reduce al cincuenta por ciento del valor nominal indicado","Cuando el supervisor de seguridad autoriza verbalmente la operaci\xF3n sin resguardos temporalmente"],respuesta_correcta:0,explicacion:"OSHA NO permite operar maquinaria sin resguardos bajo ninguna circunstancia durante la operaci\xF3n normal. Los resguardos solo se retiran durante mantenimiento con LOTO activo."},{id:"osha_560",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFQu\xE9 requisito establece OSHA sobre los resguardos de m\xE1quina en relaci\xF3n con la creaci\xF3n de nuevos peligros?",opciones:["El resguardo NO debe crear peligros adicionales como bordes cortantes o puntos de pellizco","El resguardo debe ser del mismo color que la m\xE1quina para mantener uniformidad en la planta","El resguardo debe poder removerse sin herramientas para facilitar respuestas de emergencia","El resguardo debe ser fabricado exclusivamente por el fabricante original del equipo protegido"],respuesta_correcta:0,explicacion:"Uno de los requisitos m\xEDnimos de OSHA para resguardos es que NO deben crear peligros nuevos \u2014 no deben tener bordes afilados, puntos de pellizco u otras condiciones que puedan lesionar."},{id:"osha_561",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l es un requisito de OSHA para los resguardos en cuanto a la capacidad del trabajador para realizar sus tareas?",opciones:["El resguardo no debe impedir que el trabajador realice su trabajo de forma eficiente","El resguardo debe permitir que el trabajador alcance el punto de operaci\xF3n con las manos","El resguardo debe ser transparente para que el trabajador observe las partes internas siempre","El resguardo debe incluir una abertura lateral para la ventilaci\xF3n continua del \xE1rea protegida"],respuesta_correcta:0,explicacion:"OSHA requiere que los resguardos no interfieran innecesariamente con la productividad del operador \u2014 deben proteger sin impedir que el trabajo se realice de manera eficiente."},{id:"osha_562",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFQu\xE9 tipo de movimiento de m\xE1quina representa el mayor peligro de amputaci\xF3n en el punto de operaci\xF3n?",opciones:["El movimiento de corte donde una cuchilla o sierra pasa a trav\xE9s del material de trabajo","El movimiento de rotaci\xF3n uniforme de un eje principal sin carga de trabajo aplicada","El movimiento de avance del material hacia la zona de alimentaci\xF3n de entrada a la m\xE1quina","El movimiento de vibraci\xF3n lateral que genera el motor durante el arranque inicial del equipo"],respuesta_correcta:0,explicacion:"El movimiento de corte (cutting action) en sierras, cizallas y guillotinas presenta el mayor riesgo de amputaci\xF3n porque involucra cuchillas que pasan a trav\xE9s del material con gran fuerza."},{id:"osha_563",categoria:"OSHA_MAQUINARIA",pregunta:"En una sierra de banda (band saw) utilizada en un taller de HVAC, \xBFqu\xE9 parte de la hoja debe estar resguardada?",opciones:["Toda la hoja excepto la porci\xF3n que realiza el corte entre las gu\xEDas de la sierra","Solo la mitad superior de la hoja ya que la inferior est\xE1 protegida por la mesa de trabajo","\xDAnicamente las ruedas superior e inferior donde la hoja cambia de direcci\xF3n al girar","Solo el segmento que est\xE1 en contacto directo con la pieza de trabajo siendo cortada"],respuesta_correcta:0,explicacion:"En una sierra de banda, TODA la hoja debe estar resguardada excepto la porci\xF3n entre las gu\xEDas que realiza el corte \u2014 incluyendo las ruedas y los tramos de retorno de la hoja."},{id:"osha_564",categoria:"OSHA_MAQUINARIA",pregunta:"Un tapete sensible a la presi\xF3n (pressure-sensitive mat) como dispositivo de protecci\xF3n funciona de la siguiente manera:",opciones:["Detiene la m\xE1quina cuando una persona pisa el tapete en la zona de peligro designada","Aumenta la velocidad del ciclo cuando detecta que el operador est\xE1 en posici\xF3n correcta","Registra el peso del operador para verificar que sea la persona autorizada en esa estaci\xF3n","Monitorea la temperatura del piso para prevenir el sobrecalentamiento del motor principal"],respuesta_correcta:0,explicacion:"El tapete sensible a presi\xF3n detecta cuando alguien pisa la zona de peligro y env\xEDa una se\xF1al para detener la m\xE1quina autom\xE1ticamente, protegiendo al trabajador de las partes m\xF3viles."},{id:"osha_565",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFQu\xE9 medida de seguridad adicional requiere OSHA cuando un resguardo fijo debe removerse para cambio de herramientas o ajustes?",opciones:["El resguardo debe requerir herramientas para su remoci\xF3n evitando que se quite f\xE1cilmente","El resguardo debe tener un color diferente al de la m\xE1quina para ser f\xE1cilmente identificable","El resguardo debe incluir instrucciones grabadas en su superficie sobre c\xF3mo reinstalarlo","El resguardo debe pesar menos de cinco libras para que cualquier operador pueda manejarlo"],respuesta_correcta:0,explicacion:"OSHA requiere que los resguardos fijos no puedan ser removidos f\xE1cilmente \u2014 deben requerir herramientas para su remoci\xF3n, asegurando que no se quiten de forma casual o accidental."},{id:"osha_566",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFQu\xE9 est\xE1ndar de OSHA cubre espec\xEDficamente los requisitos para resguardos en prensas mec\xE1nicas de potencia?",opciones:["29 CFR 1910.217 que establece requisitos espec\xEDficos de dise\xF1o e inspecci\xF3n peri\xF3dica","29 CFR 1910.147 que regula los procedimientos de bloqueo y etiquetado de energ\xEDas","29 CFR 1910.134 que define los est\xE1ndares para protecci\xF3n respiratoria en el trabajo","29 CFR 1910.305 que especifica los m\xE9todos de cableado el\xE9ctrico en instalaciones"],respuesta_correcta:0,explicacion:"29 CFR 1910.217 es el est\xE1ndar espec\xEDfico para prensas mec\xE1nicas de potencia, cubriendo resguardos del punto de operaci\xF3n, dispositivos de protecci\xF3n, inspecciones y requisitos de frenos."},{id:"osha_567",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFPor qu\xE9 OSHA proh\xEDbe el uso de guantes cuando se opera un taladro de banco (drill press) con broca expuesta?",opciones:["Porque el guante puede ser atrapado por la broca giratoria y jalar la mano del operador","Porque los guantes reducen la sensibilidad t\xE1ctil necesaria para calibrar la profundidad","Porque el material del guante puede fundirse con el calor de fricci\xF3n y da\xF1ar la broca","Porque los guantes contaminan la pieza de trabajo con fibras que afectan la perforaci\xF3n"],respuesta_correcta:0,explicacion:"Los guantes pueden ser atrapados por la broca giratoria del taladro, enrollando la mano del operador hacia la broca y causando lesiones severas por atrapamiento."},{id:"osha_568",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l es la velocidad m\xEDnima de parada que OSHA establece para el mecanismo de freno de una prensa mec\xE1nica?",opciones:["El freno debe detener el ariete antes de que el operador pueda alcanzar el punto de operaci\xF3n","El freno debe detener el ariete en exactamente dos segundos desde que se activa la parada","El freno debe reducir la velocidad del ariete a la mitad dentro del primer ciclo de frenado","El freno debe detener completamente el volante de inercia dentro de cinco revoluciones totales"],respuesta_correcta:0,explicacion:"OSHA no establece un tiempo fijo universal, sino que el freno debe detener el ariete (ram/slide) antes de que la mano del operador pueda alcanzar el punto de operaci\xF3n \u2014 basado en c\xE1lculo de distancia de seguridad."},{id:"osha_569",categoria:"OSHA_MAQUINARIA",pregunta:"\xBFCu\xE1l es la responsabilidad del empleador respecto al entrenamiento en protecci\xF3n de maquinaria seg\xFAn OSHA?",opciones:["Debe entrenar a cada operador sobre los peligros espec\xEDficos y los resguardos de su m\xE1quina","Debe proporcionar un manual impreso general de seguridad al momento de la contrataci\xF3n","Debe publicar las reglas de seguridad en la cartelera principal de la entrada del edificio","Debe asignar un compa\xF1ero experimentado para que observe al nuevo operador por una hora"],respuesta_correcta:0,explicacion:"OSHA requiere que el empleador proporcione entrenamiento espec\xEDfico a cada operador sobre los peligros de SU m\xE1quina, los resguardos instalados, y c\xF3mo usarlos correctamente."},{id:"osha_570",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1nto tiempo debe permanecer el vig\xEDa de incendios (fire watch) despu\xE9s de completar una operaci\xF3n de soldadura o corte con llama?",opciones:["Un m\xEDnimo de 15 minutos para verificar que no haya brasas residuales","Un m\xEDnimo de 30 minutos para asegurar que no existan focos de ignici\xF3n","Un m\xEDnimo de 45 minutos para confirmar la ausencia de humo o calor","Un m\xEDnimo de 60 minutos para garantizar que el \xE1rea est\xE9 completamente fr\xEDa"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.352(e) requiere que el fire watch permanezca un m\xEDnimo de 30 minutos despu\xE9s de completar operaciones de soldadura o corte para asegurar que no haya focos de ignici\xF3n."},{id:"osha_571",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es la distancia m\xEDnima requerida por OSHA para almacenar cilindros de ox\xEDgeno separados de cilindros de gas combustible?",opciones:["10 pies de distancia o una barrera no combustible de 3 pies de altura","15 pies de distancia o una barrera no combustible de 4 pies de altura","20 pies de distancia o una barrera no combustible de 5 pies de altura","25 pies de distancia o una barrera no combustible de 6 pies de altura"],respuesta_correcta:2,explicacion:"OSHA 29 CFR 1926.350(a)(10) requiere que los cilindros de ox\xEDgeno se almacenen a un m\xEDnimo de 20 pies de cilindros de gas combustible o separados por una barrera no combustible de al menos 5 pies de altura."},{id:"osha_572",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es la presi\xF3n m\xE1xima permitida para utilizar acetileno en operaciones de soldadura y corte seg\xFAn las normas de seguridad?",opciones:["No debe exceder 10 psi ya que se vuelve altamente reactivo a presiones mayores","No debe exceder 15 psi ya que se vuelve inestable y puede detonar por s\xED solo","No debe exceder 20 psi ya que pierde sus propiedades de combusti\xF3n controlada","No debe exceder 25 psi ya que genera una reacci\xF3n exot\xE9rmica no controlable"],respuesta_correcta:1,explicacion:"El acetileno no debe usarse a presiones superiores a 15 psi (manom\xE9trica). Por encima de esta presi\xF3n, el acetileno se vuelve inestable y puede detonar espont\xE1neamente sin necesidad de una fuente de ignici\xF3n."},{id:"osha_573",categoria:"OSHA_SOLDADURA",pregunta:"Antes de realizar soldadura o corte en un \xE1rea no designada, \xBFqu\xE9 documento debe obtenerse obligatoriamente seg\xFAn OSHA?",opciones:["Un certificado de inspecci\xF3n de equipos firmado por el supervisor de mantenimiento","Un permiso de trabajo en caliente autorizado por el responsable de la instalaci\xF3n","Una orden de trabajo especial emitida directamente por el departamento de seguridad","Un formulario de an\xE1lisis de riesgos completado y aprobado por recursos humanos"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.352 requiere un permiso de trabajo en caliente (hot work permit) antes de realizar soldadura o corte en \xE1reas no designadas. Este debe ser autorizado por el individuo responsable de la instalaci\xF3n."},{id:"osha_574",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 n\xFAmero m\xEDnimo de shade (tono de lente) se requiere para soldadura con arco el\xE9ctrico SMAW con electrodos de 1/16 a 5/32 pulgadas?",opciones:["Se requiere shade n\xFAmero 8 para proteger adecuadamente contra la radiaci\xF3n ultravioleta","Se requiere shade n\xFAmero 10 para filtrar correctamente la intensidad del arco el\xE9ctrico","Se requiere shade n\xFAmero 12 para reducir el riesgo de da\xF1o permanente a la retina","Se requiere shade n\xFAmero 14 para bloquear toda la radiaci\xF3n infrarroja del proceso"],respuesta_correcta:1,explicacion:"Para soldadura SMAW con electrodos de 1/16 a 5/32 pulgadas, OSHA recomienda un shade m\xEDnimo de #10. El n\xFAmero de shade correcto depende del amperaje y tipo de proceso de soldadura."},{id:"osha_575",categoria:"OSHA_SOLDADURA",pregunta:"Al realizar soldadura o brazing en sistemas de refrigeraci\xF3n HVAC, \xBFcu\xE1l es el principal riesgo si no se purga la l\xEDnea con nitr\xF3geno?",opciones:["La formaci\xF3n de escamas de cobre que obstruyen el sistema de expansi\xF3n t\xE9rmico","La generaci\xF3n de \xF3xidos internos que contaminan y bloquean el sistema completo","La cristalizaci\xF3n del flux residual que deteriora las juntas de cobre soldadas","La evaporaci\xF3n del aceite lubricante que da\xF1a el compresor herm\xE9tico interno"],respuesta_correcta:1,explicacion:"Al soldar o hacer brazing en tuber\xEDas de cobre sin purga de nitr\xF3geno, el calor genera \xF3xidos internos (cascarilla) que contaminan el sistema, bloquean v\xE1lvulas de expansi\xF3n, filtros y da\xF1an compresores."},{id:"osha_576",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es la funci\xF3n principal de un arrestor de retroceso de llama (flashback arrestor) en un equipo de oxiacetileno?",opciones:["Regular la presi\xF3n de salida del gas para mantener una llama estable y uniforme","Evitar que la llama retroceda hacia el cilindro y provoque una explosi\xF3n catastr\xF3fica","Filtrar impurezas del gas para que la soldadura sea m\xE1s limpia y resistente","Controlar el flujo de ox\xEDgeno para obtener la mezcla estequiom\xE9trica adecuada"],respuesta_correcta:1,explicacion:"El flashback arrestor es un dispositivo de seguridad que impide que una llama de retroceso (flashback) viaje desde el soplete hacia las mangueras y cilindros, previniendo explosiones potencialmente fatales."},{id:"osha_577",categoria:"OSHA_SOLDADURA",pregunta:"\xBFA qu\xE9 distancia m\xEDnima deben removerse los materiales combustibles del \xE1rea donde se realizar\xE1 soldadura o corte con llama?",opciones:["Al menos 25 pies del punto de operaci\xF3n o cubrirse con protecciones ign\xEDfugas aprobadas","Al menos 35 pies del punto de operaci\xF3n o cubrirse con protecciones ign\xEDfugas aprobadas","Al menos 45 pies del punto de operaci\xF3n o cubrirse con protecciones ign\xEDfugas aprobadas","Al menos 55 pies del punto de operaci\xF3n o cubrirse con protecciones ign\xEDfugas aprobadas"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.352(a) requiere que los materiales combustibles se muevan al menos 35 pies del \xE1rea de trabajo. Si no se pueden mover, deben protegerse con cubiertas ign\xEDfugas aprobadas."},{id:"osha_578",categoria:"OSHA_SOLDADURA",pregunta:"Al soldar en un espacio confinado, \xBFqu\xE9 acci\xF3n es obligatoria respecto a los cilindros de gas cuando se interrumpe el trabajo?",opciones:["Los cilindros deben colocarse en posici\xF3n horizontal y asegurar las v\xE1lvulas con tapones","Los cilindros y las antorchas deben retirarse del espacio confinado inmediatamente","Los cilindros deben purgarse completamente y almacenarse dentro del espacio ventilado","Los cilindros deben cubrirse con mantas ign\xEDfugas y dejarse en posici\xF3n vertical segura"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.353(b)(1) requiere que cuando se interrumpa la soldadura en espacios confinados, los cilindros de gas y las antorchas se retiren del espacio confinado para prevenir acumulaci\xF3n de gases."},{id:"osha_579",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 Subparte del 29 CFR 1926 regula espec\xEDficamente las operaciones de soldadura y corte en la industria de construcci\xF3n?",opciones:["La Subparte H que cubre los requisitos de excavaciones y protecci\xF3n contra derrumbes","La Subparte J que establece los est\xE1ndares de soldadura, corte y trabajo en caliente","La Subparte K que regula los sistemas el\xE9ctricos y la protecci\xF3n contra electrocuci\xF3n","La Subparte L que define los requisitos para andamios y plataformas de trabajo elevado"],respuesta_correcta:1,explicacion:"29 CFR 1926 Subpart J \u2014 Welding and Cutting cubre todos los requisitos de seguridad para operaciones de soldadura y corte en la industria de la construcci\xF3n, incluyendo soldadura de gas, arco y brazing."},{id:"osha_580",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es la ventilaci\xF3n m\xEDnima requerida por OSHA para soldadura en espacios interiores sin ventilaci\xF3n mec\xE1nica local?",opciones:["Al menos 5,000 pies c\xFAbicos de aire por cada soldador que est\xE9 trabajando activamente","Al menos 10,000 pies c\xFAbicos de aire por cada soldador que est\xE9 trabajando activamente","Al menos 15,000 pies c\xFAbicos de aire por cada soldador que est\xE9 trabajando activamente","Al menos 20,000 pies c\xFAbicos de aire por cada soldador que est\xE9 trabajando activamente"],respuesta_correcta:1,explicacion:"OSHA requiere un m\xEDnimo de 10,000 pies c\xFAbicos de aire por soldador cuando se realiza soldadura en interiores sin ventilaci\xF3n mec\xE1nica local, para asegurar diluci\xF3n adecuada de humos y gases."},{id:"osha_581",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 tipo de extintor debe estar disponible inmediatamente en el \xE1rea donde se realizan operaciones de soldadura y corte?",opciones:["Extintor tipo A de agua presurizada con capacidad m\xEDnima de 5 galones certificados","Extintor tipo ABC con clasificaci\xF3n m\xEDnima 2A-10B:C en condiciones operativas listas","Extintor tipo B de espuma mec\xE1nica con capacidad m\xEDnima de 2.5 galones certificados","Extintor tipo D de polvo especial con clasificaci\xF3n para metales combustibles activos"],respuesta_correcta:1,explicacion:"OSHA requiere que haya extintores tipo ABC disponibles en el \xE1rea de soldadura y corte. La clasificaci\xF3n 2A-10B:C es el est\xE1ndar m\xEDnimo para cubrir los tipos de fuego m\xE1s comunes en estas operaciones."},{id:"osha_582",categoria:"OSHA_SOLDADURA",pregunta:"Al realizar brazing con aleaci\xF3n de plata (silver brazing) en tuber\xEDas HVAC, \xBFcu\xE1l es la principal preocupaci\xF3n de salud ocupacional?",opciones:["La inhalaci\xF3n de part\xEDculas de cobre fundido que causa fiebre de los metales pesados","La exposici\xF3n a vapores de cadmio presentes en algunas aleaciones de plata antiguas","La absorci\xF3n cut\xE1nea del flux \xE1cido que provoca dermatitis qu\xEDmica irreversible","La radiaci\xF3n infrarroja del soplete que genera cataratas t\xE9rmicas ocupacionales"],respuesta_correcta:1,explicacion:"Algunas aleaciones de plata para brazing contienen cadmio, cuyos vapores son extremadamente t\xF3xicos. La exposici\xF3n a humos de cadmio puede causar da\xF1o pulmonar severo y es potencialmente fatal incluso en bajas concentraciones."},{id:"osha_583",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es la posici\xF3n correcta para almacenar cilindros de gas comprimido seg\xFAn las normas OSHA de seguridad?",opciones:["En posici\xF3n horizontal con cu\xF1as de bloqueo y cadenas de seguridad en ambos extremos","En posici\xF3n vertical asegurados con cadenas o correas para evitar que se caigan","En posici\xF3n inclinada a 45 grados con el regulador apuntando hacia abajo por seguridad","En posici\xF3n horizontal solo si est\xE1n vac\xEDos y vertical \xFAnicamente cuando est\xE1n llenos"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.350(a)(9) requiere que los cilindros se almacenen en posici\xF3n vertical y asegurados con cadenas, correas o en portacilindros para prevenir ca\xEDdas que podr\xEDan da\xF1ar la v\xE1lvula y causar una proyecci\xF3n peligrosa."},{id:"osha_584",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 debe verificarse ANTES de encender un soplete de oxiacetileno al inicio de cada turno de trabajo?",opciones:["Que las mangueras tengan el color correcto y que los man\xF3metros marquen presi\xF3n de trabajo","Que todas las conexiones est\xE9n apretadas y no existan fugas verificadas con agua jabonosa","Que los cilindros est\xE9n llenos al menos al 50% de su capacidad total de almacenamiento","Que el \xE1rea tenga ventilaci\xF3n cruzada natural con un m\xEDnimo de tres aberturas visibles"],respuesta_correcta:1,explicacion:"Antes de usar un equipo de oxiacetileno, se debe verificar que todas las conexiones est\xE9n seguras y hacer prueba de fugas con soluci\xF3n jabonosa. Nunca se debe usar llama para detectar fugas en conexiones de gas."},{id:"osha_585",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1ndo se requiere obligatoriamente el uso de respirador durante operaciones de soldadura seg\xFAn OSHA?",opciones:["Siempre que se suelde cualquier tipo de material sin importar la ubicaci\xF3n del trabajo","Cuando la ventilaci\xF3n no es suficiente para mantener los humos debajo de los PEL establecidos","\xDAnicamente cuando se trabaja con acero inoxidable o metales que contengan aleaciones de cromo","Solo en espacios confinados donde la concentraci\xF3n de ox\xEDgeno es inferior al 21 por ciento"],respuesta_correcta:1,explicacion:"OSHA requiere respirador cuando la ventilaci\xF3n (natural o mec\xE1nica) no es suficiente para mantener la exposici\xF3n a humos de soldadura por debajo de los L\xEDmites de Exposici\xF3n Permisibles (PEL) establecidos para cada sustancia."},{id:"osha_586",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 color de manguera identifica el suministro de acetileno en un equipo est\xE1ndar de oxiacetileno en Estados Unidos?",opciones:["La manguera verde identifica el acetileno y tiene conexiones con rosca est\xE1ndar derecha","La manguera roja identifica el acetileno y tiene conexiones con rosca izquierda especial","La manguera negra identifica el acetileno y tiene conexiones con rosca est\xE1ndar derecha","La manguera azul identifica el acetileno y tiene conexiones con rosca izquierda especial"],respuesta_correcta:1,explicacion:"En Estados Unidos, la manguera roja es para acetileno (combustible) con conexiones de rosca izquierda, y la manguera verde es para ox\xEDgeno con conexiones de rosca derecha. Esta diferencia previene conexiones cruzadas accidentales."},{id:"osha_587",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es el procedimiento correcto si la v\xE1lvula de un cilindro de acetileno no se puede abrir con la mano?",opciones:["Usar una llave ajustable est\xE1ndar de 12 pulgadas para aplicar torque adicional controlado","Devolver el cilindro al proveedor marc\xE1ndolo como defectuoso sin intentar forzar la v\xE1lvula","Aplicar aceite penetrante en la rosca de la v\xE1lvula y esperar 10 minutos antes de reintentar","Calentar levemente la v\xE1lvula con agua tibia para expandir el metal y facilitar la apertura"],respuesta_correcta:1,explicacion:"Si la v\xE1lvula de un cilindro no se puede abrir manualmente, NO se debe forzar. Se debe marcar como defectuoso y devolver al proveedor. Nunca aplicar aceite (riesgo de ignici\xF3n con ox\xEDgeno) ni calentar cilindros de gas."},{id:"osha_588",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1ntas vueltas m\xE1ximo debe abrirse la v\xE1lvula de un cilindro de acetileno durante su uso en operaciones normales?",opciones:["M\xE1ximo media vuelta para poder cerrarla r\xE1pidamente en caso de una emergencia imprevista","M\xE1ximo una vuelta y media para permitir flujo adecuado y cierre r\xE1pido de seguridad","M\xE1ximo dos vueltas completas para asegurar el flujo constante durante toda la operaci\xF3n","M\xE1ximo tres vueltas completas ya que el dise\xF1o de la v\xE1lvula limita el flujo naturalmente"],respuesta_correcta:1,explicacion:"La v\xE1lvula del cilindro de acetileno debe abrirse m\xE1ximo 1\xBD vueltas (algunos est\xE1ndares dicen \xBE a 1\xBD) para permitir un cierre r\xE1pido en caso de emergencia. La llave siempre debe permanecer en la v\xE1lvula durante el uso."},{id:"osha_589",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 condici\xF3n del \xE1rea de trabajo requiere obligatoriamente un vig\xEDa de incendios (fire watch) durante soldadura?",opciones:["Cuando hay materiales inflamables almacenados a m\xE1s de 50 pies del punto de soldadura","Cuando existen combustibles a menos de 35 pies que no pueden moverse ni cubrirse totalmente","Cuando la temperatura ambiente supera los 90\xB0F y la humedad relativa est\xE1 debajo del 30%","Cuando se trabaja en exteriores con velocidad de viento superior a 15 millas por hora"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.352(e) requiere fire watch cuando hay combustibles dentro de 35 pies que no pueden removerse ni protegerse adecuadamente con cubiertas ign\xEDfugas. El vig\xEDa debe tener extintor disponible."},{id:"osha_590",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 tipo de lesi\xF3n ocular causa la exposici\xF3n a radiaci\xF3n ultravioleta del arco de soldadura sin protecci\xF3n adecuada?",opciones:["Glaucoma agudo por el aumento de presi\xF3n intraocular causado por la radiaci\xF3n directa","Fotoqueratitis conocida como ojo de soldador que inflama la c\xF3rnea temporalmente dolorosa","Degeneraci\xF3n macular instant\xE1nea que destruye permanentemente la visi\xF3n central del ojo","Desprendimiento de retina causado por la contracci\xF3n t\xE9rmica del humor v\xEDtreo interno"],respuesta_correcta:1,explicacion:"La exposici\xF3n a radiaci\xF3n UV del arco de soldadura causa fotoqueratitis (arc eye/welder's flash), una inflamaci\xF3n dolorosa de la c\xF3rnea. Los s\xEDntomas aparecen horas despu\xE9s y generalmente se resuelven en 24-72 horas."},{id:"osha_591",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es el riesgo principal de usar ox\xEDgeno para ventilar un espacio confinado antes de realizar soldadura?",opciones:["El ox\xEDgeno puro desplaza el nitr\xF3geno y causa s\xEDntomas de narcosis similares a la embriaguez","El exceso de ox\xEDgeno crea una atm\xF3sfera enriquecida donde materiales normales arden con violencia","El ox\xEDgeno reacciona con el di\xF3xido de carbono residual formando \xE1cido carb\xF3nico t\xF3xico irritante","El ox\xEDgeno comprimido genera electricidad est\xE1tica que puede provocar chispas dentro del espacio"],respuesta_correcta:1,explicacion:"NUNCA se debe usar ox\xEDgeno para ventilar. Una atm\xF3sfera enriquecida con ox\xEDgeno (>23.5%) hace que materiales normalmente no combustibles, como ropa y cabello, ardan violentamente. Solo se debe ventilar con aire limpio."},{id:"osha_592",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 protecci\xF3n personal adicional se requiere cuando se realiza soldadura sobre superficies que contienen pintura con plomo?",opciones:["Guantes de neopreno de doble capa y traje de protecci\xF3n qu\xEDmica con sellado herm\xE9tico total","Respirador con filtros HEPA para part\xEDculas y monitoreo de plomo en sangre peri\xF3dicamente","Gafas con filtro especial para radiaci\xF3n gamma y delantal de plomo como protecci\xF3n adicional","Botas con suela de goma conductiva y pulsera antiest\xE1tica conectada al sistema de tierra"],respuesta_correcta:1,explicacion:"Al soldar sobre superficies con pintura de plomo, los humos de plomo son altamente t\xF3xicos. Se requiere respirador con filtros HEPA (P100), y OSHA exige monitoreo m\xE9dico de plomo en sangre para trabajadores expuestos."},{id:"osha_593",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 debe hacerse con los tapones protectores de las v\xE1lvulas de cilindros de gas cuando no est\xE1n conectados a reguladores?",opciones:["Guardarlos en una caja de herramientas cercana para tenerlos accesibles cuando se necesiten","Mantenerlos siempre colocados y ajustados a mano para proteger la v\xE1lvula contra da\xF1os f\xEDsicos","Colgarlos de la cadena de seguridad del cilindro para evitar que se pierdan en el \xE1rea de trabajo","Almacenarlos en el cuarto de herramientas junto con los reguladores y mangueras de repuesto"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.350(a)(1) requiere que los tapones protectores de v\xE1lvulas est\xE9n siempre colocados cuando los cilindros no est\xE1n en uso o conectados a reguladores. Protegen la v\xE1lvula de da\xF1os que podr\xEDan causar liberaci\xF3n violenta de gas."},{id:"osha_594",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es el shade m\xEDnimo recomendado para operaciones de corte con oxiacetileno en espesores medianos de acero?",opciones:["Shade n\xFAmero 2 que ofrece protecci\xF3n b\xE1sica suficiente contra el resplandor del corte t\xE9rmico","Shade n\xFAmero 4 que filtra adecuadamente la radiaci\xF3n generada durante el corte con oxicombustible","Shade n\xFAmero 6 que proporciona mayor contraste visual manteniendo protecci\xF3n ocular apropiada","Shade n\xFAmero 8 que es el est\xE1ndar universal obligatorio para cualquier tipo de operaci\xF3n t\xE9rmica"],respuesta_correcta:1,explicacion:"Para corte con oxiacetileno en espesores medianos, se recomienda shade #4 o #5. El shade requerido para corte es menor que para soldadura por arco porque la intensidad luminosa del corte es significativamente menor."},{id:"osha_595",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es el procedimiento correcto para mover un cilindro de gas comprimido dentro del sitio de trabajo?",opciones:["Rodarlo sobre su borde inferior inclin\xE1ndolo levemente y empujando en la direcci\xF3n deseada","Transportarlo en posici\xF3n vertical usando un carro porta-cilindros con cadena de seguridad","Arrastrarlo horizontalmente sobre el piso asegur\xE1ndose de que la v\xE1lvula no golpee obst\xE1culos","Cargarlo al hombro si pesa menos de 100 libras y la distancia es menor a 50 pies totales"],respuesta_correcta:1,explicacion:"Los cilindros de gas deben transportarse en posici\xF3n vertical en un carro porta-cilindros (hand truck) con cadena de seguridad. Nunca deben arrastrarse, rodarse sin control ni cargarse al hombro. Los tapones de v\xE1lvula deben estar puestos."},{id:"osha_596",categoria:"OSHA_SOLDADURA",pregunta:"Al soldar tuber\xEDas de refrigeraci\xF3n en HVAC, \xBFpor qu\xE9 se debe evacuar el refrigerante antes de aplicar calor con soplete?",opciones:["Porque el refrigerante l\xEDquido puede expandirse y crear una explosi\xF3n hidr\xE1ulica en la tuber\xEDa","Porque ciertos refrigerantes al exponerse a llama abierta generan gas fosgeno altamente t\xF3xico","Porque el gas refrigerante impide que la soldadura de plata fluya correctamente por capilaridad","Porque la presi\xF3n residual del refrigerante puede apagar la llama del soplete repetidamente"],respuesta_correcta:1,explicacion:"Refrigerantes halogenados (como R-22, R-410A) al descomponerse por llama abierta producen gas fosgeno y \xE1cido fluorh\xEDdrico, ambos extremadamente t\xF3xicos. Siempre se debe recuperar el refrigerante antes de soldar."},{id:"osha_597",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 debe verificar un soldador antes de iniciar soldadura por arco el\xE9ctrico respecto al equipo y su conexi\xF3n a tierra?",opciones:["Que el voltaje de circuito abierto no exceda 50 voltios en corriente alterna para mayor seguridad","Que la pinza de tierra est\xE9 conectada firmemente a la pieza de trabajo o mesa de soldadura met\xE1lica","Que los electrodos est\xE9n almacenados en un horno a 250\xB0F durante al menos dos horas completas","Que la m\xE1quina de soldar tenga fusibles de respaldo adicionales instalados en el panel el\xE9ctrico"],respuesta_correcta:1,explicacion:"La conexi\xF3n a tierra (work clamp/ground clamp) debe estar firmemente conectada a la pieza de trabajo o a la mesa met\xE1lica. Una mala conexi\xF3n a tierra causa arcos err\xE1ticos, da\xF1o al equipo y riesgo de electrocuci\xF3n."},{id:"osha_598",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es la concentraci\xF3n m\xEDnima de ox\xEDgeno en la atm\xF3sfera de un espacio confinado para permitir operaciones de soldadura?",opciones:["La concentraci\xF3n de ox\xEDgeno debe estar entre 18.5% y 21.5% antes de autorizar la entrada","La concentraci\xF3n de ox\xEDgeno debe estar entre 19.5% y 23.5% antes de autorizar la entrada","La concentraci\xF3n de ox\xEDgeno debe estar entre 20.5% y 24.5% antes de autorizar la entrada","La concentraci\xF3n de ox\xEDgeno debe estar entre 21.5% y 25.5% antes de autorizar la entrada"],respuesta_correcta:1,explicacion:"Para entrada y trabajo en espacios confinados, la concentraci\xF3n de ox\xEDgeno debe estar entre 19.5% y 23.5%. Menos de 19.5% es deficiente de ox\xEDgeno y m\xE1s de 23.5% es enriquecida, ambas condiciones son peligrosas para soldadura."},{id:"osha_599",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 tipo de guantes son apropiados para operaciones de soldadura con arco el\xE9ctrico seg\xFAn los est\xE1ndares OSHA?",opciones:["Guantes de algod\xF3n grueso tratados con retardante de fuego y forro interior absorbente","Guantes de cuero resistentes al calor con aislamiento el\xE9ctrico y sin agujeros ni defectos","Guantes de neopreno de alta temperatura con refuerzo de kevlar en palma y los dedos","Guantes de nitrilo industrial de doble capa con protecci\xF3n contra corte nivel A4 m\xEDnimo"],respuesta_correcta:1,explicacion:"Para soldadura por arco se requieren guantes de cuero (leather welding gloves) que sean resistentes al calor y proporcionen aislamiento el\xE9ctrico. Deben estar en buenas condiciones sin agujeros, grietas o defectos."},{id:"osha_600",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 precauci\xF3n especial se debe tomar al soldar o cortar contenedores que hayan almacenado materiales combustibles?",opciones:["Llenar el contenedor con arena seca hasta el nivel de corte para absorber cualquier residuo inflamable","Limpiar con vapor o soluci\xF3n qu\xEDmica y verificar con detector de gases antes de soldar o cortar","Perforar m\xFAltiples agujeros de ventilaci\xF3n en la parte superior para permitir el escape de vapores","Sumergir completamente el contenedor en agua dejando expuesta solo el \xE1rea de corte o soldadura"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.352(i) requiere que contenedores que almacenaron combustibles se limpien con vapor o soluci\xF3n qu\xEDmica y se verifiquen con detector de gases inflamables antes de soldar o cortar, para prevenir explosiones."},{id:"osha_601",categoria:"OSHA_SOLDADURA",pregunta:"\xBFCu\xE1l es la distancia m\xEDnima que debe haber entre un cilindro de gas y una fuente de calor o llama abierta?",opciones:["Al menos 10 pies de distancia de cualquier fuente de calor o llama durante las operaciones","Al menos 20 pies de distancia de cualquier fuente de calor o llama durante las operaciones","Al menos 30 pies de distancia de cualquier fuente de calor o llama durante las operaciones","Al menos 40 pies de distancia de cualquier fuente de calor o llama durante las operaciones"],respuesta_correcta:1,explicacion:"Los cilindros de gas deben mantenerse a un m\xEDnimo de 20 pies de fuentes de calor o llama abierta para prevenir sobrecalentamiento que podr\xEDa causar aumento peligroso de presi\xF3n o falla catastr\xF3fica del cilindro."},{id:"osha_602",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 indica una llama de oxiacetileno con exceso de acetileno (llama carburante) durante operaciones de soldadura?",opciones:["Una llama azul intensa y corta que produce temperaturas excesivas y quema el metal base r\xE1pidamente","Una llama con pluma blanca alargada que agrega carbono al metal y produce soldaduras porosas d\xE9biles","Una llama verde oscura con chispas que indica obstrucci\xF3n parcial de la boquilla del soplete usado","Una llama pulsante intermitente que se\xF1ala presi\xF3n insuficiente en el regulador de ox\xEDgeno puro"],respuesta_correcta:1,explicacion:"Una llama carburante (con exceso de acetileno) tiene una pluma blanca caracter\xEDstica alrededor del cono interno. Esta llama agrega carbono al metal, produciendo soldaduras fr\xE1giles, porosas y de baja calidad."},{id:"osha_603",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 acci\xF3n inmediata se debe tomar si se detecta una fuga de gas en una manguera de oxiacetileno durante el uso?",opciones:["Aplicar cinta de tefl\xF3n en el \xE1rea de la fuga y continuar trabajando si la fuga es peque\xF1a y manejable","Cerrar las v\xE1lvulas de ambos cilindros inmediatamente y no usar el equipo hasta reparar la manguera","Sumergir la secci\xF3n de manguera con fuga en un balde con agua para sellar temporalmente la grieta","Aumentar la presi\xF3n del regulador para compensar la p\xE9rdida de gas causada por la fuga detectada"],respuesta_correcta:1,explicacion:"Ante cualquier fuga en mangueras de oxiacetileno, se deben cerrar inmediatamente las v\xE1lvulas de ambos cilindros. Nunca reparar con cinta ni continuar usando equipo con fugas, ya que hay riesgo de incendio o explosi\xF3n."},{id:"osha_604",categoria:"OSHA_SOLDADURA",pregunta:"\xBFQu\xE9 requisito especial aplica OSHA para soldadura en pisos elevados o plataformas donde pueden caer chispas y escoria?",opciones:["Instalar sistemas de rociadores autom\xE1ticos directamente debajo del \xE1rea de soldadura en pisos elevados","Colocar protecciones ign\xEDfugas debajo del \xE1rea de trabajo y asignar fire watch en el nivel inferior","Restringir todo el acceso al edificio durante operaciones de soldadura en cualquier nivel superior","Aplicar pintura intumescente en todas las superficies de madera dentro de un radio de cien pies"],respuesta_correcta:1,explicacion:"OSHA requiere que se coloquen cubiertas ign\xEDfugas debajo del \xE1rea de soldadura en pisos elevados para atrapar chispas y escoria, adem\xE1s de asignar un vig\xEDa de incendios (fire watch) en los niveles inferiores expuestos."},{id:"osha_605",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA 29 CFR 1926 Subpart P, a partir de que profundidad se requiere un sistema de proteccion en una excavacion?",opciones:["A partir de los 4 pies de profundidad","A partir de los 5 pies de profundidad","A partir de los 6 pies de profundidad","A partir de los 8 pies de profundidad"],respuesta_correcta:1,explicacion:"OSHA requiere sistemas de proteccion (sloping, shoring o shielding) cuando la excavacion alcanza 5 pies (1.52 m) de profundidad o mas, a menos que la excavacion este hecha completamente en roca estable."},{id:"osha_606",categoria:"OSHA_EXCAVACIONES",pregunta:"Cual es la clasificacion de suelo MAS estable segun el sistema de clasificacion de OSHA para excavaciones?",opciones:["El suelo Tipo B es el mas estable de todos","El suelo Tipo C es el mas estable de todos","El suelo Tipo A es el mas estable de todos","La roca estable y el Tipo B son iguales"],respuesta_correcta:2,explicacion:"La clasificacion de OSHA va de mas estable a menos estable: Roca Estable, Tipo A, Tipo B y Tipo C. El Tipo A (arcilla dura, por ejemplo) es el suelo mas estable, excluyendo la roca estable que es una categoria separada."},{id:"osha_607",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, cual es el angulo maximo de inclinacion (sloping) permitido para una excavacion en suelo Tipo C?",opciones:["No mas de 1:1 que equivale a 45 grados","No mas de 1.5:1 equivalente a 34 grados","No mas de 1.5:1 equivalente a 53 grados","No mas de 0.75:1 equivale a 53 grados"],respuesta_correcta:1,explicacion:"Para suelo Tipo C, OSHA requiere un angulo de inclinacion no mas empinado que 1.5H:1V (1.5 horizontal por cada 1 vertical), lo que equivale a aproximadamente 34 grados respecto a la horizontal."},{id:"osha_608",categoria:"OSHA_EXCAVACIONES",pregunta:"A que distancia maxima debe haber un medio de acceso o salida (escalera, rampa) en una zanja para que los trabajadores puedan evacuar?",opciones:["No mas de 50 pies de distancia lateral","No mas de 30 pies de distancia lateral","No mas de 25 pies de distancia lateral","No mas de 20 pies de distancia lateral"],respuesta_correcta:2,explicacion:"OSHA 1926.651(c)(2) requiere que en zanjas de 4 pies o mas de profundidad, los medios de salida (escaleras, rampas o escalones) no esten a mas de 25 pies de distancia lateral de cualquier trabajador."},{id:"osha_609",categoria:"OSHA_EXCAVACIONES",pregunta:"Quien es responsable de clasificar el tipo de suelo y determinar las medidas de proteccion necesarias en una excavacion segun OSHA?",opciones:["El supervisor general de la obra completa","La persona competente designada por el empleador","El ingeniero de seguridad del estado vigente","El inspector de OSHA asignado al proyecto"],respuesta_correcta:1,explicacion:"OSHA 1926.650 y 1926.651 requieren que una 'persona competente' (competent person) designada por el empleador clasifique el suelo, inspeccione la excavacion y determine las medidas de proteccion adecuadas."},{id:"osha_610",categoria:"OSHA_EXCAVACIONES",pregunta:"Con que frecuencia debe la persona competente inspeccionar una excavacion segun los requisitos de OSHA Subpart P?",opciones:["Semanalmente y despues de cada tormenta fuerte","Cada 48 horas y al inicio de cada turno nuevo","Diariamente y despues de eventos como lluvias","Mensualmente y cuando cambian las condiciones"],respuesta_correcta:2,explicacion:"OSHA 1926.651(k)(1) requiere que la persona competente inspeccione las excavaciones diariamente antes de cada turno, y ademas despues de lluvias, tormentas, u otros eventos que puedan aumentar el riesgo de derrumbe."},{id:"osha_611",categoria:"OSHA_EXCAVACIONES",pregunta:"Que tipo de suelo tiene una resistencia a la compresion no confinada de 1.5 tsf (toneladas por pie cuadrado) o mayor segun OSHA?",opciones:["Suelo clasificado como Tipo B estable","Suelo clasificado como Tipo A estable","Suelo clasificado como Tipo C estable","Suelo clasificado como roca blanda"],respuesta_correcta:1,explicacion:"El suelo Tipo A tiene una resistencia a la compresion no confinada de 1.5 tsf (toneladas por pie cuadrado) o mayor. Ejemplos incluyen arcilla dura, arcilla silty y arcilla arenosa cementada."},{id:"osha_612",categoria:"OSHA_EXCAVACIONES",pregunta:"Cual es el angulo de inclinacion (sloping) permitido por OSHA para excavaciones en suelo Tipo A?",opciones:["No mas de 1:1 que equivale a 45 grados","No mas de 1.5:1 equivalente a 34 grados","No mas de 0.75:1 equivale a 53 grados","No mas de 2:1 que equivale a 27 grados"],respuesta_correcta:2,explicacion:"Para suelo Tipo A, OSHA permite un angulo de inclinacion de 0.75H:1V (3/4 horizontal por cada 1 vertical), equivalente a aproximadamente 53 grados. Es el angulo mas empinado permitido porque el Tipo A es el suelo mas estable."},{id:"osha_613",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, a que distancia minima del borde de una excavacion se debe colocar el material excavado (spoil pile)?",opciones:["A un minimo de 3 pies del borde superior","A un minimo de 2 pies del borde superior","A un minimo de 4 pies del borde superior","A un minimo de 5 pies del borde superior"],respuesta_correcta:1,explicacion:"OSHA 1926.651(j)(2) requiere que el material excavado (spoil) se mantenga a un minimo de 2 pies del borde de la excavacion para evitar que el peso adicional cause un derrumbe o que el material caiga sobre los trabajadores."},{id:"osha_614",categoria:"OSHA_EXCAVACIONES",pregunta:"Que debe hacerse ANTES de iniciar cualquier excavacion con respecto a las instalaciones subterraneas (utilities) segun OSHA?",opciones:["Excavar con cuidado los primeros tres pies","Contactar a las companias de servicios publicos","Usar solo maquinaria liviana al comenzar a excavar","Colocar senales de advertencia en toda el area"],respuesta_correcta:1,explicacion:"OSHA 1926.651(b) requiere que ANTES de abrir una excavacion, se contacten las companias de servicios publicos (gas, electricidad, agua, telecomunicaciones) para localizar y marcar todas las instalaciones subterraneas en el area."},{id:"osha_615",categoria:"OSHA_EXCAVACIONES",pregunta:"Que es una 'trench box' (caja de zanja) y cual es su funcion principal en una excavacion segun OSHA?",opciones:["Es un contenedor para guardar herramientas dentro de zanjas","Es una estructura que protege contra derrumbes laterales","Es una barrera para desviar el agua fuera de la excavacion","Es un sistema de ventilacion para zanjas profundas cerradas"],respuesta_correcta:1,explicacion:"Una trench box (trench shield) es una estructura prefabricada de acero o aluminio que se coloca dentro de la zanja para proteger a los trabajadores contra derrumbes de las paredes laterales. Es un metodo de 'shielding' segun OSHA."},{id:"osha_616",categoria:"OSHA_EXCAVACIONES",pregunta:"A partir de que profundidad OSHA requiere que un ingeniero profesional registrado disene el sistema de proteccion de una excavacion?",opciones:["Cuando la excavacion supera los 15 pies","Cuando la excavacion supera los 25 pies","Cuando la excavacion supera los 20 pies","Cuando la excavacion supera los 10 pies"],respuesta_correcta:2,explicacion:"OSHA 1926.652 requiere que cuando una excavacion excede los 20 pies de profundidad, el sistema de proteccion debe ser disenado por un ingeniero profesional registrado (registered professional engineer)."},{id:"osha_617",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, que se debe hacer cuando hay acumulacion de agua dentro de una excavacion donde trabajan empleados?",opciones:["Continuar el trabajo si el agua no supera 6 pulgadas","Usar precauciones especiales controladas por persona competente","Detener todo trabajo hasta que el agua se evapore sola","Bombear el agua solo al final de la jornada laboral"],respuesta_correcta:1,explicacion:"OSHA 1926.651(h) requiere que se tomen precauciones especiales cuando hay acumulacion de agua, incluyendo: monitoreo por la persona competente, uso de bombeo, y equipos de proteccion especiales para los trabajadores."},{id:"osha_618",categoria:"OSHA_EXCAVACIONES",pregunta:"Cual de las siguientes opciones describe correctamente el suelo Tipo B segun la clasificacion de OSHA?",opciones:["Arcilla dura con resistencia mayor a 1.5 tsf total","Suelo granular cohesivo con 0.5 a 1.5 tsf de fuerza","Grava suelta y arena seca sin ninguna cohesion natural","Roca fracturada con resistencia menor a 0.5 tsf fija"],respuesta_correcta:1,explicacion:"El suelo Tipo B tiene una resistencia a la compresion no confinada entre 0.5 y 1.5 tsf. Incluye suelos granulares cohesivos como limo, arcilla media, y suelos previamente perturbados que no califican como Tipo A."},{id:"osha_619",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, cual de estas condiciones automaticamente DEGRADA un suelo Tipo A a una clasificacion inferior?",opciones:["Si la temperatura ambiente supera los 95 grados F","Si el suelo esta sujeto a vibracion de trafico pesado","Si la excavacion tiene menos de cuatro pies de profundidad","Si no hay presencia de agua subterranea en el area"],respuesta_correcta:1,explicacion:"OSHA establece que el suelo Tipo A se degrada si esta sujeto a vibraciones (trafico pesado, maquinaria), si ha sido previamente perturbado, si esta sumergido, o si hay filtraciones de agua. Cualquiera de estas condiciones lo reclasifica."},{id:"osha_620",categoria:"OSHA_EXCAVACIONES",pregunta:"Cual es el angulo de inclinacion (sloping) permitido por OSHA para excavaciones en suelo clasificado como Tipo B?",opciones:["No mas de 0.75:1 equivalente a 53 grados exactos","No mas de 1.5:1 que equivale a 34 grados exactos","No mas de 1:1 que equivale a 45 grados exactamente","No mas de 2:1 que equivale a 27 grados exactamente"],respuesta_correcta:2,explicacion:"Para suelo Tipo B, OSHA requiere un angulo de inclinacion no mas empinado que 1H:1V (1 horizontal por cada 1 vertical), equivalente a 45 grados. Esto es menos empinado que el Tipo A (53 grados) pero mas que el Tipo C (34 grados)."},{id:"osha_621",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, donde deben colocarse las escaleras en una zanja para garantizar una salida segura de los trabajadores?",opciones:["Las escaleras deben sobresalir 2 pies sobre el borde superior","Las escaleras deben sobresalir 3 pies sobre el borde superior","Las escaleras deben quedar al nivel exacto del borde de zanja","Las escaleras deben sobresalir 4 pies sobre el borde superior"],respuesta_correcta:1,explicacion:"OSHA 1926.651(c)(2) requiere que las escaleras utilizadas como medio de salida en zanjas se extiendan al menos 3 pies por encima del borde superior de la excavacion para permitir un agarre seguro al subir."},{id:"osha_622",categoria:"OSHA_EXCAVACIONES",pregunta:"Que metodo de prueba se usa comunmente en el campo para determinar la clasificacion de un suelo en excavaciones segun OSHA?",opciones:["La prueba de compactacion Proctor estandar","La prueba de penetrometro de bolsillo en campo","La prueba de permeabilidad en laboratorio certificado","La prueba de consolidacion unidimensional rapida"],respuesta_correcta:1,explicacion:"La prueba de penetrometro de bolsillo (pocket penetrometer) es uno de los metodos comunes de campo que OSHA reconoce para determinar la resistencia a la compresion no confinada del suelo y asi clasificarlo como Tipo A, B o C."},{id:"osha_623",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, cuando se debe monitorear la atmosfera dentro de una excavacion para detectar condiciones peligrosas?",opciones:["Solo si la excavacion supera los 20 pies de profundidad total","Cuando exista posibilidad razonable de atmosfera peligrosa","Unicamente si hay tuberias de gas rotas visibles en la zona","Solo cuando los trabajadores reportan mareos o dificultad al respirar"],respuesta_correcta:1,explicacion:"OSHA 1926.651(g) requiere pruebas atmosfericas cuando existe una posibilidad razonable de deficiencia de oxigeno, gases combustibles, u otros contaminantes en la excavacion, sin importar la profundidad especifica."},{id:"osha_624",categoria:"OSHA_EXCAVACIONES",pregunta:"Que debe hacer la persona competente si detecta evidencia de una posible falla o derrumbe en las paredes de la excavacion?",opciones:["Documentar la evidencia y continuar monitoreando por 24 horas","Retirar a los trabajadores hasta eliminar el peligro detectado","Reforzar las paredes con material excavado disponible en sitio","Reducir el numero de trabajadores dentro de la zanja a la mitad"],respuesta_correcta:1,explicacion:"OSHA 1926.651(k)(2) requiere que la persona competente retire inmediatamente a todos los trabajadores expuestos de la excavacion cuando encuentre evidencia de posible derrumbe, acumulacion de agua peligrosa, o falla del sistema de proteccion."},{id:"osha_625",categoria:"OSHA_EXCAVACIONES",pregunta:"Cual es la caracteristica principal del suelo Tipo C segun la clasificacion de OSHA para excavaciones?",opciones:["Es arcilla firme con resistencia mayor a 1.0 tsf total","Es suelo cohesivo con resistencia de 0.5 a 1.5 tsf exacto","Es suelo con resistencia menor a 0.5 tsf o granular libre","Es roca parcialmente estable con fracturas menores visibles"],respuesta_correcta:2,explicacion:"El suelo Tipo C tiene una resistencia a la compresion no confinada de 0.5 tsf o menos. Incluye suelo granular (grava, arena, suelo sumergido), suelo del cual se filtra agua, y roca sumergida que no es estable."},{id:"osha_626",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, que tipo de proteccion NO es aceptable como sistema de proteccion aprobado para excavaciones y zanjas?",opciones:["Sloping o corte inclinado de las paredes de la excavacion","Shoring con sistemas hidraulicos de soporte de aluminio","Shielding con cajas de zanja prefabricadas de acero pesado","Colocar madera suelta contra la pared sin un diseno formal"],respuesta_correcta:3,explicacion:"OSHA acepta tres metodos: sloping/benching, shoring (sistemas dise\xF1ados de soporte), y shielding (trench boxes). Colocar madera suelta sin un diseno de ingenieria no cumple con ningun metodo aprobado de 1926.652."},{id:"osha_627",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, que es 'benching' como metodo de proteccion en una excavacion y en que tipo de suelo NO se permite?",opciones:["Cortar escalones en la pared; prohibido en suelo Tipo A estable","Cortar escalones en la pared; prohibido en suelo Tipo C suelto","Inclinar toda la pared; prohibido en suelo Tipo B intermedio","Colocar tablones horizontales; prohibido en roca fracturada"],respuesta_correcta:1,explicacion:"Benching consiste en cortar escalones (bench) en las paredes de la excavacion. OSHA prohibe el benching en suelo Tipo C porque es demasiado inestable para mantener la forma de los escalones cortados."},{id:"osha_628",categoria:"OSHA_EXCAVACIONES",pregunta:"Cuando se trabaja cerca de una excavacion abierta, a que distancia minima se deben colocar las barreras de proteccion para vehiculos?",opciones:["Las barreras deben estar al menos a 4 pies del borde visible","Las barreras se deben colocar a un minimo de 6 pies del borde","No hay distancia fija pero deben soportar impacto del vehiculo","Las barreras deben estar a un minimo de 10 pies del borde fijo"],respuesta_correcta:2,explicacion:"OSHA 1926.651(f) requiere barreras o barricadas adecuadas cuando el trafico vehicular es un peligro. No especifica una distancia fija exacta, pero las barreras deben ser capaces de detener vehiculos antes de que caigan a la excavacion."},{id:"osha_629",categoria:"OSHA_EXCAVACIONES",pregunta:"Segun OSHA, que requisito aplica a los trabajadores que deben cruzar sobre una excavacion o zanja en el sitio de trabajo?",opciones:["Pueden saltar si la zanja tiene menos de 4 pies de ancho","Se requiere un puente con barandas si tiene 6 pies o mas","Se requiere un puente con barandas para zanjas de mas de 6 pies de profundidad","No se permite cruzar sobre excavaciones bajo ninguna condicion vigente"],respuesta_correcta:1,explicacion:"OSHA 1926.651(l) requiere que las pasarelas o puentes utilizados para cruzar sobre zanjas de 6 pies o mas de profundidad tengan barandas estandar (guardrails) para proteger a los trabajadores de caidas."},{id:"osha_630",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es la capacidad m\xEDnima de carga que debe soportar un andamio seg\xFAn OSHA?",opciones:["El doble del peso m\xE1ximo previsto incluyendo trabajadores y materiales","Cuatro veces la carga m\xE1xima prevista incluyendo trabajadores y materiales","Tres veces el peso combinado de trabajadores y herramientas sobre \xE9l","Seis veces la carga muerta del andamio sin contar a los trabajadores"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1926.451(a)(1) requiere que los andamios soporten 4 veces la carga m\xE1xima prevista (4:1 ratio de seguridad)."},{id:"osha_631",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es la altura m\xEDnima requerida para la baranda superior (top rail) de un andamio?",opciones:["36 pulgadas medidas desde la superficie de trabajo del andamio","38 pulgadas medidas desde la superficie de trabajo del andamio","42 pulgadas medidas desde la superficie de trabajo del andamio","48 pulgadas medidas desde la superficie de trabajo del andamio"],respuesta_correcta:1,explicacion:"OSHA 1926.451(g)(4)(ii) especifica que la baranda superior debe estar entre 38 y 45 pulgadas sobre la superficie de trabajo."},{id:"osha_632",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFA partir de qu\xE9 altura se requiere protecci\xF3n contra ca\xEDdas en andamios?",opciones:["6 pies sobre el nivel inferior para andamios de cualquier tipo usado","8 pies sobre el nivel inferior para andamios de cualquier tipo usado","10 pies sobre el nivel inferior para andamios de cualquier tipo","12 pies sobre el nivel inferior para andamios de cualquier tipo"],respuesta_correcta:2,explicacion:"OSHA 1926.451(g)(1) requiere protecci\xF3n contra ca\xEDdas cuando la superficie de trabajo est\xE1 a 10 pies o m\xE1s sobre el nivel inferior."},{id:"osha_633",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQui\xE9n debe inspeccionar un andamio antes de cada turno de trabajo seg\xFAn OSHA?",opciones:["Un ingeniero estructural certificado por el estado donde se encuentra la obra","Una persona competente designada por el empleador con experiencia comprobada","El supervisor general de la obra con m\xEDnimo cinco a\xF1os de experiencia total","Un inspector certificado de OSHA asignado espec\xEDficamente al proyecto en curso"],respuesta_correcta:1,explicacion:"OSHA 1926.451(f)(7) requiere que una persona competente inspeccione el andamio antes de cada turno y despu\xE9s de cualquier evento que afecte su integridad."},{id:"osha_634",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es el ancho m\xEDnimo de las tablas de plataforma (planking) en un andamio?",opciones:["El ancho debe ser de al menos 16 pulgadas para plataformas de trabajo est\xE1ndar","El ancho debe ser de al menos 18 pulgadas para plataformas de trabajo est\xE1ndar","El ancho debe ser de al menos 20 pulgadas para plataformas de trabajo est\xE1ndar","El ancho debe ser de al menos 24 pulgadas para plataformas de trabajo est\xE1ndar"],respuesta_correcta:2,explicacion:"OSHA 1926.451(b)(2) requiere que las plataformas tengan al menos 20 pulgadas de ancho (nominalmente) para trabajo general."},{id:"osha_635",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es la distancia m\xE1xima permitida entre la plataforma del andamio y la cara del edificio?",opciones:["10 pulgadas m\xE1ximo entre la plataforma y la estructura de trabajo cercana","14 pulgadas m\xE1ximo entre la plataforma y la estructura de trabajo cercana","18 pulgadas m\xE1ximo entre la plataforma y la estructura de trabajo cercana","20 pulgadas m\xE1ximo entre la plataforma y la estructura de trabajo cercana"],respuesta_correcta:1,explicacion:"OSHA 1926.451(b)(1) permite un m\xE1ximo de 14 pulgadas entre la plataforma y la cara de la estructura, excepto en ciertas condiciones espec\xEDficas."},{id:"osha_636",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQu\xE9 tipo de andamio se sostiene desde arriba mediante cuerdas o cables de acero?",opciones:["Andamio soportado que se fija mediante cables tensados a la estructura superior","Andamio suspendido que cuelga de soportes en el techo o estructura superior","Andamio m\xF3vil que se eleva con cables conectados a gr\xFAas en la azotea","Andamio a\xE9reo que se ancla con cuerdas atadas a postes estructurales fijos"],respuesta_correcta:1,explicacion:"Un andamio suspendido (suspended scaffold) se sostiene desde arriba mediante cuerdas o cables de acero conectados a soportes superiores, a diferencia del andamio soportado que descansa sobre el suelo."},{id:"osha_637",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1ntos puntos de acceso se requieren cuando un andamio tiene m\xE1s de un nivel de trabajo?",opciones:["Un punto de acceso por cada nivel de trabajo con escalera interna o externa aprobada","Un punto de acceso por cada dos niveles que puede ser escalera o rampa segura","Acceso directo a cada nivel mediante escaleras integradas o medios equivalentes","Dos puntos de acceso en cada nivel para permitir evacuaci\xF3n de emergencia r\xE1pida"],respuesta_correcta:2,explicacion:"OSHA 1926.451(e)(1) requiere acceso directo a cada nivel del andamio mediante escaleras port\xE1tiles, escaleras integradas, rampas u otros medios equivalentes seguros."},{id:"osha_638",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFA qu\xE9 distancia m\xEDnima debe mantenerse un andamio de l\xEDneas el\xE9ctricas energizadas de menos de 300 voltios?",opciones:["Al menos 3 pies de distancia de las l\xEDneas el\xE9ctricas energizadas de bajo voltaje","Al menos 5 pies de distancia de las l\xEDneas el\xE9ctricas energizadas de bajo voltaje","Al menos 8 pies de distancia de las l\xEDneas el\xE9ctricas energizadas de bajo voltaje","M\xEDnimo 10 pies de distancia de l\xEDneas el\xE9ctricas energizadas de bajo voltaje"],respuesta_correcta:0,explicacion:"OSHA 1926.451(f)(6) requiere una distancia m\xEDnima de 3 pies para l\xEDneas de menos de 300 voltios. Para l\xEDneas de 300V a 50kV la distancia m\xEDnima es 10 pies."},{id:"osha_639",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es el requisito para la baranda intermedia (mid-rail) en un sistema de barandas de andamio?",opciones:["Debe instalarse a la mitad de la altura entre la plataforma y la baranda superior","Debe instalarse a 21 pulgadas fijas desde la superficie de trabajo del andamio","Debe instalarse a 24 pulgadas exactas medidas desde la baranda superior hacia abajo","Debe instalarse a un tercio de la altura entre la plataforma y baranda superior"],respuesta_correcta:0,explicacion:"OSHA 1926.451(g)(4)(iii) requiere que la baranda intermedia se instale aproximadamente a la mitad de la distancia entre la plataforma y la baranda superior."},{id:"osha_640",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQu\xE9 componente del andamio previene que herramientas y materiales caigan sobre trabajadores abajo?",opciones:["La baranda superior instalada a 38-45 pulgadas de la plataforma de trabajo","La baranda intermedia colocada a media altura entre plataforma y baranda","El rodapi\xE9 (toeboard) de al menos 3.5 pulgadas de altura en cada borde","La malla de protecci\xF3n de nylon tensada entre las barandas del andamio"],respuesta_correcta:2,explicacion:"OSHA 1926.451(h)(1) requiere rodapi\xE9s (toeboards) de al menos 3.5 pulgadas de altura para prevenir que objetos caigan de la plataforma sobre trabajadores debajo."},{id:"osha_641",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es la proporci\xF3n m\xE1xima de altura a base para un andamio m\xF3vil (rolling scaffold)?",opciones:["La altura no debe exceder dos veces la dimensi\xF3n menor de la base del andamio","La altura no debe exceder tres veces la dimensi\xF3n menor de la base del andamio","La altura no debe exceder cuatro veces la dimensi\xF3n menor de la base del andamio","La altura no debe exceder cinco veces la dimensi\xF3n menor de la base del andamio"],respuesta_correcta:2,explicacion:"OSHA 1926.452(w)(6) establece que la altura de un andamio m\xF3vil no debe exceder 4 veces la dimensi\xF3n m\xEDnima de la base, a menos que se usen estabilizadores."},{id:"osha_642",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQu\xE9 se debe hacer con las ruedas de un andamio m\xF3vil cuando hay trabajadores en la plataforma?",opciones:["Las ruedas deben estar giradas hacia adentro y aseguradas con cadenas de acero","Las ruedas deben estar bloqueadas con frenos y los trabajadores deben sujetarse","Las ruedas deben retirarse y sustituirse por placas de base fijas y niveladas","Las ruedas deben estar desinfladas parcialmente para aumentar fricci\xF3n en el suelo"],respuesta_correcta:1,explicacion:"OSHA 1926.452(w)(2) requiere que las ruedas est\xE9n bloqueadas con frenos cuando hay trabajadores en la plataforma para prevenir movimiento involuntario del andamio."},{id:"osha_643",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es el requisito de sobreposici\xF3n (overlap) para tablas de plataforma en un andamio?",opciones:["Las tablas deben superponerse al menos 6 pulgadas sobre los soportes del andamio","Las tablas deben superponerse m\xEDnimo 12 pulgadas sobre los soportes del andamio","Las tablas deben superponerse al menos 18 pulgadas sobre soportes del andamio","Las tablas deben superponerse al menos 24 pulgadas sobre soportes del andamio"],respuesta_correcta:1,explicacion:"OSHA 1926.451(b)(4) requiere que las tablas de plataforma se superpongan al menos 12 pulgadas sobre los soportes, a menos que est\xE9n clavadas o aseguradas contra movimiento."},{id:"osha_644",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1ndo debe un andamio suspendido utilizar l\xEDneas de vida independientes para los trabajadores?",opciones:["Solo cuando el andamio suspendido est\xE1 a m\xE1s de 50 pies sobre el nivel del suelo","Solo cuando el andamio suspendido opera cerca de l\xEDneas de alta tensi\xF3n el\xE9ctricas","Siempre que los trabajadores est\xE9n en un andamio suspendido de dos puntos o m\xE1s","Solo cuando las condiciones clim\xE1ticas presentan vientos superiores a 25 millas/hora"],respuesta_correcta:2,explicacion:"OSHA 1926.451(g)(3)(iii) requiere que cada trabajador en un andamio suspendido de dos puntos use un arn\xE9s con l\xEDnea de vida independiente como protecci\xF3n contra ca\xEDdas en todo momento."},{id:"osha_645",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQu\xE9 acci\xF3n debe tomarse si se encuentra un defecto en un componente del andamio durante inspecci\xF3n?",opciones:["Documentar el defecto y programar reparaci\xF3n dentro de las siguientes 72 horas","Marcar el componente con pintura roja y notificar al supervisor de seguridad","Retirar inmediatamente de servicio y no usar hasta que sea reparado o reemplazado","Reducir la carga del andamio a la mitad hasta que se complete la reparaci\xF3n total"],respuesta_correcta:2,explicacion:"OSHA 1926.451(f)(7) requiere que cualquier componente defectuoso sea retirado inmediatamente de servicio y no se use hasta que sea reparado o reemplazado por una persona competente."},{id:"osha_646",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es la norma espec\xEDfica de OSHA que regula la seguridad en andamios de construcci\xF3n?",opciones:["La norma 29 CFR 1926 Subpart K que cubre equipos el\xE9ctricos en construcci\xF3n","La norma 29 CFR 1926 Subpart L que cubre andamios en la industria de construcci\xF3n","La norma 29 CFR 1926 Subpart M que cubre protecci\xF3n contra ca\xEDdas en general","La norma 29 CFR 1926 Subpart N que cubre gr\xFAas y equipos de elevaci\xF3n pesados"],respuesta_correcta:1,explicacion:"29 CFR 1926 Subpart L es la norma espec\xEDfica de OSHA que regula todos los requisitos de seguridad para andamios en la industria de la construcci\xF3n."},{id:"osha_647",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es el requisito para trabajar en andamios durante tormentas el\xE9ctricas o vientos fuertes?",opciones:["Se permite trabajar con vientos de hasta 35 mph si se usan arneses de seguridad","Se permite trabajar si la persona competente eval\xFAa que el riesgo es aceptable","No se debe trabajar en andamios durante tormentas el\xE9ctricas o vientos fuertes","Se permite si el andamio tiene protecci\xF3n de viento instalada correctamente fija"],respuesta_correcta:2,explicacion:"OSHA 1926.451(f)(12) proh\xEDbe el trabajo en andamios durante tormentas el\xE9ctricas, vientos fuertes u otras condiciones clim\xE1ticas adversas que pongan en peligro a los trabajadores."},{id:"osha_648",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQu\xE9 tipo de protecci\xF3n contra ca\xEDdas se requiere en andamios soportados sobre 10 pies?",opciones:["Sistema de l\xEDnea de vida horizontal con arn\xE9s de cuerpo completo certificado","Sistema de barandas completo o sistema personal de detenci\xF3n de ca\xEDdas v\xE1lido","Red de seguridad instalada debajo de la plataforma de trabajo del andamio usado","Cuerda de restricci\xF3n atada al marco del andamio con mosquet\xF3n autocierre total"],respuesta_correcta:1,explicacion:"OSHA 1926.451(g)(1)(vii) requiere un sistema de barandas o un sistema personal de detenci\xF3n de ca\xEDdas para trabajadores en andamios soportados a m\xE1s de 10 pies sobre el nivel inferior."},{id:"osha_649",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es el peso m\xEDnimo que debe soportar la baranda superior de un andamio seg\xFAn OSHA?",opciones:["100 libras de fuerza aplicada en cualquier direcci\xF3n hacia abajo o hacia afuera","150 libras de fuerza aplicada en cualquier direcci\xF3n hacia abajo o hacia afuera","200 libras de fuerza aplicada en cualquier direcci\xF3n hacia abajo o hacia afuera","250 libras de fuerza aplicada en cualquier direcci\xF3n hacia abajo o hacia afuera"],respuesta_correcta:2,explicacion:"OSHA 1926.451(g)(4)(vii) requiere que la baranda superior soporte al menos 200 libras de fuerza aplicada en cualquier direcci\xF3n descendente o hacia afuera en cualquier punto."},{id:"osha_650",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQui\xE9n puede dise\xF1ar un andamio que exceda las especificaciones est\xE1ndar de OSHA para construcci\xF3n?",opciones:["La persona competente designada por el empleador con experiencia en andamios","Un ingeniero profesional registrado con conocimientos en dise\xF1o de andamios","El fabricante del andamio a trav\xE9s de sus manuales t\xE9cnicos de especificaciones","El supervisor de seguridad de la obra con certificaci\xF3n OSHA 30 horas vigente"],respuesta_correcta:1,explicacion:"OSHA 1926.452 requiere que andamios que excedan las especificaciones est\xE1ndar sean dise\xF1ados por un ingeniero profesional registrado (registered professional engineer)."},{id:"osha_651",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1l es el requisito para las bases de un andamio soportado respecto al terreno donde se instala?",opciones:["Las bases deben colocarse sobre terreno firme, nivelado y con placas base adecuadas","Las bases deben clavarse al suelo con estacas de metal de al menos doce pulgadas","Las bases pueden colocarse sobre cualquier superficie si se usan estabilizadores fijos","Las bases requieren cimentaci\xF3n de concreto de m\xEDnimo cuatro pulgadas de espesor"],respuesta_correcta:0,explicacion:"OSHA 1926.451(c)(2) requiere que los andamios soportados se coloquen sobre bases adecuadas (mudsills, placas base) en terreno firme y nivelado para garantizar estabilidad."},{id:"osha_652",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFCu\xE1ndo se requiere que los trabajadores reciban capacitaci\xF3n sobre seguridad en andamios?",opciones:["Anualmente como parte del programa de capacitaci\xF3n general de seguridad laboral","Cada seis meses con actualizaci\xF3n semestral documentada en el expediente laboral","Antes de trabajar en andamios y cuando cambien condiciones o se identifiquen riesgos","Solo al inicio del empleo como parte de la orientaci\xF3n general para nuevos empleados"],respuesta_correcta:2,explicacion:"OSHA 1926.454(a) requiere capacitaci\xF3n antes de trabajar en andamios, y recapacitaci\xF3n cuando cambien las condiciones del lugar de trabajo, los tipos de andamio, o se identifiquen deficiencias."},{id:"osha_653",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQu\xE9 distancia m\xE1xima debe haber entre el borde de la plataforma y los soportes verticales del andamio?",opciones:["No m\xE1s de 1 pulgada entre la plataforma y los montantes verticales del andamio","No m\xE1s de 3 pulgadas entre la plataforma y los montantes verticales del andamio","No m\xE1s de 6 pulgadas entre la plataforma y los montantes verticales del andamio","No m\xE1s de 8 pulgadas entre la plataforma y los montantes verticales del andamio"],respuesta_correcta:0,explicacion:"OSHA 1926.451(b)(1)(i) establece que no debe haber m\xE1s de 1 pulgada de espacio entre las tablas de plataforma y los montantes verticales del andamio para prevenir ca\xEDdas de objetos."},{id:"osha_654",categoria:"OSHA_ANDAMIOS",pregunta:"\xBFQu\xE9 se requiere cuando un andamio se erige cerca de l\xEDneas el\xE9ctricas de 50kV o m\xE1s?",opciones:["Distancia m\xEDnima de 10 pies m\xE1s 0.4 pulgadas por cada kV adicional sobre 50kV","Distancia m\xEDnima de 15 pies m\xE1s 0.5 pulgadas por cada kV adicional sobre 50kV","Distancia m\xEDnima de 20 pies m\xE1s 0.4 pulgadas por cada kV adicional sobre 50kV","Distancia m\xEDnima de 25 pies m\xE1s 0.5 pulgadas por cada kV adicional sobre 50kV"],respuesta_correcta:2,explicacion:"OSHA 1926.451(f)(6) requiere una distancia m\xEDnima de 20 pies m\xE1s 0.4 pulgadas por cada kV adicional sobre 50kV para andamios cerca de l\xEDneas el\xE9ctricas de alto voltaje."},{id:"osha_655",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es la se\xF1al manual est\xE1ndar para indicar al operador de gr\xFAa que detenga toda operaci\xF3n inmediatamente?",opciones:["Ambas manos extendidas al frente con las palmas hacia abajo movi\xE9ndolas lateralmente","Un brazo extendido con la palma hacia abajo movi\xE9ndolo horizontalmente de lado a lado","Ambos pu\xF1os cerrados al frente del cuerpo golpe\xE1ndolos uno contra el otro repetidamente","Ambas manos abiertas al frente con las palmas hacia abajo sin ning\xFAn tipo de movimiento"],respuesta_correcta:1,explicacion:"La se\xF1al de parada de emergencia (Emergency Stop) es un brazo extendido con la palma hacia abajo, movi\xE9ndolo horizontalmente de lado a lado seg\xFAn ASME B30.5."},{id:"osha_656",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es el \xE1ngulo m\xEDnimo recomendado para eslingas medido desde la horizontal al levantar una carga?",opciones:["30 grados desde la horizontal para minimizar la tensi\xF3n excesiva en las eslingas","45 grados desde la horizontal para minimizar la tensi\xF3n excesiva en las eslingas","60 grados desde la horizontal para minimizar la tensi\xF3n excesiva en las eslingas","75 grados desde la horizontal para minimizar la tensi\xF3n excesiva en las eslingas"],respuesta_correcta:2,explicacion:"El \xE1ngulo m\xEDnimo recomendado para eslingas es 60 grados desde la horizontal. A menor \xE1ngulo, mayor es la tensi\xF3n en cada ramal de la eslinga, aumentando el riesgo de falla."},{id:"osha_657",categoria:"OSHA_MATERIALES",pregunta:"\xBFQui\xE9n est\xE1 autorizado para operar un montacargas (forklift) en el lugar de trabajo seg\xFAn OSHA?",opciones:["Cualquier empleado mayor de 21 a\xF1os que tenga licencia de conducir vigente v\xE1lida","Solo empleados que hayan completado capacitaci\xF3n y evaluaci\xF3n pr\xE1ctica certificada","Cualquier empleado con experiencia previa en operaci\xF3n de maquinaria pesada industrial","Solo empleados con certificaci\xF3n estatal de operador de equipo pesado actualizada"],respuesta_correcta:1,explicacion:"OSHA 1910.178(l) requiere que solo operadores que hayan completado capacitaci\xF3n formal y evaluaci\xF3n pr\xE1ctica por parte del empleador est\xE9n autorizados para operar montacargas."},{id:"osha_658",categoria:"OSHA_MATERIALES",pregunta:"\xBFCon qu\xE9 frecuencia debe un operador inspeccionar un montacargas seg\xFAn las normas de OSHA?",opciones:["Semanalmente con documentaci\xF3n escrita firmada por el supervisor de seguridad","Mensualmente como parte del programa de mantenimiento preventivo del equipo","Al inicio de cada turno de trabajo antes de poner el montacargas en operaci\xF3n","Cada 200 horas de operaci\xF3n seg\xFAn las recomendaciones del fabricante del equipo"],respuesta_correcta:2,explicacion:"OSHA 1910.178(q)(7) requiere que los montacargas sean inspeccionados al inicio de cada turno. Si se encuentran defectos, el equipo debe retirarse de servicio hasta ser reparado."},{id:"osha_659",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es la se\xF1al manual est\xE1ndar para indicar al operador de gr\xFAa que suba la carga lentamente?",opciones:["Un brazo extendido hacia arriba con el dedo \xEDndice apuntando hacia arriba haciendo c\xEDrculos","Ambos brazos extendidos hacia arriba con las palmas abiertas movi\xE9ndose hacia el cielo","Un pu\xF1o cerrado frente al pecho con el pulgar apuntando hacia arriba de forma est\xE1tica","Una mano a nivel del pecho con el pulgar arriba y los dedos abriendo y cerrando despacio"],respuesta_correcta:3,explicacion:"La se\xF1al de subir lentamente (Hoist Slowly) es una mano a nivel del pecho con el pulgar apuntando hacia arriba y los dedos abriendo y cerrando, indicando movimiento lento controlado."},{id:"osha_660",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1ndo se debe retirar de servicio una eslinga de cable de acero seg\xFAn los criterios de inspecci\xF3n?",opciones:["Cuando presenta tres o m\xE1s alambres rotos en un mismo tor\xF3n dentro de un paso del cable","Cuando presenta seis o m\xE1s alambres rotos en un paso del cable o tres en un solo tor\xF3n","Cuando presenta diez o m\xE1s alambres rotos distribuidos aleatoriamente en todo su largo","Cuando presenta dos o m\xE1s alambres rotos en cualquier secci\xF3n visible del cable de acero"],respuesta_correcta:1,explicacion:"OSHA 1926.251(c)(4)(ii) establece que una eslinga de cable debe retirarse cuando tiene 6 o m\xE1s alambres rotos en un paso del cable, o 3 o m\xE1s en un solo tor\xF3n."},{id:"osha_661",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es la altura m\xE1xima para apilar materiales manualmente sin usar equipo mec\xE1nico de elevaci\xF3n?",opciones:["Los materiales apilados manualmente no deben exceder los 12 pies de altura m\xE1xima","Los materiales apilados manualmente no deben exceder los 16 pies de altura m\xE1xima","Los materiales apilados manualmente no deben exceder los 20 pies de altura m\xE1xima","No hay l\xEDmite fijo si el apilamiento es estable y supervisado por persona competente"],respuesta_correcta:2,explicacion:"OSHA 1926.250(b)(1) establece que los materiales apilados manualmente no deben exceder 20 pies de altura como regla general para mantener la estabilidad del apilamiento."},{id:"osha_662",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 porcentaje de la capacidad nominal de carga de una gr\xFAa nunca debe excederse durante operaci\xF3n?",opciones:["No debe excederse el 75% de la capacidad nominal indicada en la tabla de cargas","No debe excederse el 80% de la capacidad nominal indicada en la tabla de cargas","No debe excederse el 85% de la capacidad nominal indicada en la tabla de cargas","No debe excederse el 100% de la capacidad indicada en la tabla de cargas vigente"],respuesta_correcta:3,explicacion:"OSHA proh\xEDbe exceder el 100% de la capacidad nominal de la tabla de cargas del fabricante. Las tablas ya incluyen factores de seguridad; el operador nunca debe sobrepasar la capacidad indicada."},{id:"osha_663",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es el peso m\xE1ximo recomendado por NIOSH para levantamiento manual bajo condiciones ideales?",opciones:["35 libras como l\xEDmite m\xE1ximo recomendado para levantamiento manual seguro repetitivo","41 libras como l\xEDmite m\xE1ximo recomendado para levantamiento manual seguro repetitivo","51 libras como l\xEDmite m\xE1ximo recomendado para levantamiento manual seguro repetitivo","65 libras como l\xEDmite m\xE1ximo recomendado para levantamiento manual seguro repetitivo"],respuesta_correcta:2,explicacion:"La ecuaci\xF3n de levantamiento revisada de NIOSH establece 51 libras (23 kg) como el l\xEDmite de peso recomendado bajo condiciones ideales de levantamiento manual."},{id:"osha_664",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 debe verificarse PRIMERO antes de realizar cualquier operaci\xF3n de levantamiento con gr\xFAa?",opciones:["Verificar que todos los trabajadores tengan sus equipos de protecci\xF3n personal puestos","Verificar las condiciones del terreno y confirmar la capacidad de carga del equipo usado","Verificar que el operador de la gr\xFAa tenga su certificaci\xF3n actualizada y documentada","Verificar que el se\xF1alero designado est\xE9 en posici\xF3n visible para el operador de la gr\xFAa"],respuesta_correcta:1,explicacion:"Antes de cualquier levantamiento, se debe verificar las condiciones del terreno (estabilidad, nivelaci\xF3n) y confirmar que la carga no exceda la capacidad del equipo seg\xFAn la tabla de cargas."},{id:"osha_665",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es la norma de OSHA que regula el manejo y almacenamiento de materiales en construcci\xF3n?",opciones:["La norma 29 CFR 1926 Subpart G que cubre se\xF1alizaci\xF3n y protecci\xF3n del p\xFAblico","La norma 29 CFR 1926 Subpart H que cubre manejo y almacenamiento de materiales","La norma 29 CFR 1926 Subpart I que cubre herramientas manuales y de poder usadas","La norma 29 CFR 1926 Subpart J que cubre soldadura y corte en \xE1reas de construcci\xF3n"],respuesta_correcta:1,explicacion:"29 CFR 1926 Subpart H es la norma espec\xEDfica de OSHA que regula el manejo, almacenamiento, uso y disposici\xF3n de materiales en la industria de la construcci\xF3n."},{id:"osha_666",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es la t\xE9cnica correcta de levantamiento manual para prevenir lesiones de espalda baja?",opciones:["Doblar la cintura manteniendo las piernas rectas y levantar con la fuerza de los brazos","Doblar las rodillas manteniendo la espalda recta y levantar con la fuerza de las piernas","Girar el torso mientras levanta para distribuir el peso entre ambos lados del cuerpo","Extender los brazos lejos del cuerpo para crear mejor palanca al levantar objetos pesados"],respuesta_correcta:1,explicacion:"La t\xE9cnica correcta es doblar las rodillas, mantener la espalda recta, acercar la carga al cuerpo y levantar con la fuerza de las piernas para minimizar la tensi\xF3n en la espalda baja."},{id:"osha_667",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 factor reduce M\xC1S la capacidad de carga de una eslinga cuando se usa en configuraci\xF3n angular?",opciones:["La temperatura ambiente del entorno donde se est\xE1 realizando la operaci\xF3n de izaje","El \xE1ngulo de la eslinga respecto a la vertical cuando se conecta al gancho de la gr\xFAa","El material de fabricaci\xF3n de la eslinga ya sea nylon poli\xE9ster o cable de acero usado","La velocidad con la que se eleva la carga durante la operaci\xF3n de izaje con la gr\xFAa"],respuesta_correcta:1,explicacion:"El \xE1ngulo de la eslinga es el factor que m\xE1s afecta su capacidad. A menor \xE1ngulo respecto a la vertical (m\xE1s abierta), mayor tensi\xF3n en cada ramal y menor capacidad efectiva de carga."},{id:"osha_668",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es el requisito para almacenar cilindros de gas comprimido en el \xE1rea de trabajo seg\xFAn OSHA?",opciones:["Almacenarlos acostados horizontalmente asegurados con cu\xF1as para que no se muevan","Almacenarlos en posici\xF3n vertical asegurados con cadenas o soportes contra volcamiento","Almacenarlos en cualquier posici\xF3n siempre que est\xE9n dentro de un gabinete ventilado fijo","Almacenarlos en grupos de m\xE1ximo seis cilindros separados por tipo con se\xF1alizaci\xF3n clara"],respuesta_correcta:1,explicacion:"OSHA 1926.350(a)(9) requiere que los cilindros de gas comprimido se almacenen en posici\xF3n vertical y se aseguren con cadenas o soportes para prevenir que se volteen o caigan."},{id:"osha_669",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 significa la se\xF1al manual de un brazo extendido horizontalmente con el dedo \xEDndice apuntando al suelo haciendo c\xEDrculos?",opciones:["Significa que el operador debe girar la pluma de la gr\xFAa hacia la derecha lentamente","Significa que el operador debe bajar la carga hacia el punto indicado por el se\xF1alero","Significa que el operador debe mover el carro del puente gr\xFAa en direcci\xF3n al se\xF1alero","Significa que el operador debe recoger el cable auxiliar de la gr\xFAa de forma inmediata"],respuesta_correcta:1,explicacion:"Un brazo extendido con el dedo \xEDndice apuntando hacia abajo haciendo c\xEDrculos es la se\xF1al est\xE1ndar de 'bajar' (Lower) la carga, seg\xFAn las se\xF1ales manuales de ASME B30.5."},{id:"osha_670",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es el requisito de OSHA para las \xE1reas de almacenamiento de materiales en sitios de construcci\xF3n?",opciones:["Deben estar cercadas con malla met\xE1lica de al menos 6 pies de altura con acceso controlado","Deben mantenerse libres de vegetaci\xF3n excesiva y desechos acumulados que obstruyan acceso","Deben tener iluminaci\xF3n artificial de al menos 50 lux en todas las \xE1reas de almacenamiento","Deben estar pavimentadas con concreto o asfalto para prevenir hundimiento de materiales"],respuesta_correcta:1,explicacion:"OSHA 1926.250(a)(1) requiere que las \xE1reas de almacenamiento se mantengan libres de acumulaci\xF3n de materiales de desecho, vegetaci\xF3n excesiva y otros obst\xE1culos que creen peligros."},{id:"osha_671",categoria:"OSHA_MATERIALES",pregunta:"\xBFCon qu\xE9 frecuencia deben inspeccionarse las eslingas seg\xFAn OSHA antes de ser utilizadas?",opciones:["Las eslingas deben inspeccionarse una vez por semana por una persona calificada designada","Las eslingas deben inspeccionarse antes de cada uso por una persona competente designada","Las eslingas deben inspeccionarse mensualmente y documentar los resultados por cada eslinga","Las eslingas deben inspeccionarse cada 90 d\xEDas con registro escrito firmado y archivado"],respuesta_correcta:1,explicacion:"OSHA 1926.251(a)(1) requiere que las eslingas sean inspeccionadas antes de cada uso por una persona competente para detectar da\xF1os, deformaciones o deterioro que comprometan su integridad."},{id:"osha_672",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 acci\xF3n debe tomarse si un montacargas necesita ser dejado desatendido seg\xFAn las normas de OSHA?",opciones:["Apagar el motor y colocar un cono de seguridad naranja frente al equipo estacionado","Bajar las horquillas al suelo, poner freno de mano, apagar motor y retirar la llave","Bajar las horquillas al suelo y activar las luces intermitentes de advertencia del equipo","Colocar cu\xF1as en las ruedas traseras y dejar el motor encendido en ralent\xED con freno puesto"],respuesta_correcta:1,explicacion:"OSHA 1910.178(m)(5) requiere que al dejar un montacargas desatendido se bajen las horquillas al piso, se aplique el freno de estacionamiento, se apague el motor y se retire la llave."},{id:"osha_673",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es la distancia m\xEDnima segura que debe mantenerse de una carga suspendida por una gr\xFAa?",opciones:["Al menos 5 pies de distancia de cualquier carga suspendida durante operaciones de izaje","Al menos 10 pies de distancia de cualquier carga suspendida durante operaciones de izaje","Nadie debe estar debajo ni en la zona de giro de una carga suspendida en ning\xFAn momento","Al menos 20 pies de distancia de cualquier carga suspendida durante operaciones de izaje"],respuesta_correcta:2,explicacion:"OSHA 1926.1425(c) proh\xEDbe que cualquier persona se posicione debajo de una carga suspendida o dentro de la zona de giro. No es solo distancia, es prohibici\xF3n absoluta de estar bajo la carga."},{id:"osha_674",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 tipo de eslinga NO debe usarse para levantar cargas con bordes afilados sin protecci\xF3n adicional?",opciones:["Eslingas de cable de acero porque los bordes afilados cortan los alambres del cable r\xE1pido","Eslingas de cadena de aleaci\xF3n porque los bordes afilados debilitan los eslabones de acero","Eslingas sint\xE9ticas de nylon o poli\xE9ster porque se cortan f\xE1cilmente con bordes afilados","Eslingas de malla met\xE1lica porque los bordes afilados deforman la trama del tejido met\xE1lico"],respuesta_correcta:2,explicacion:"Las eslingas sint\xE9ticas de nylon o poli\xE9ster son las m\xE1s vulnerables a bordes afilados y se cortan f\xE1cilmente. OSHA 1926.251(b)(4) requiere protecci\xF3n de bordes cuando se usan con cargas cortantes."},{id:"osha_675",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es el requisito para la placa de capacidad (data plate) en un montacargas seg\xFAn OSHA?",opciones:["La placa debe estar visible pero puede cubrirse parcialmente si no interfiere con el trabajo","La placa debe estar legible y visible en todo momento en la ubicaci\xF3n original del fabricante","La placa puede reemplazarse con una etiqueta adhesiva equivalente con la misma informaci\xF3n","La placa solo es necesaria en montacargas con capacidad superior a las 5000 libras totales"],respuesta_correcta:1,explicacion:"OSHA 1910.178(a)(7) requiere que la placa de datos del fabricante con la capacidad nominal est\xE9 legible y visible en todo momento. Operar sin placa o con placa ilegible es una violaci\xF3n."},{id:"osha_676",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 debe hacerse cuando se descubre una eslinga de cadena con eslabones deformados o estirados?",opciones:["Reparar los eslabones da\xF1ados mediante soldadura certificada y volver a poner en servicio","Retirar inmediatamente de servicio y no reutilizar hasta que sea inspeccionada y recertificada","Reducir la capacidad nominal de la eslinga en un 50% y continuar us\xE1ndola con precauci\xF3n","Marcar los eslabones da\xF1ados con pintura y limitar el uso a cargas menores de 500 libras"],respuesta_correcta:1,explicacion:"OSHA 1926.251(b)(2) requiere que eslingas de cadena con eslabones deformados, estirados o agrietados sean retiradas inmediatamente de servicio. No se permite reparaci\xF3n por soldadura en campo."},{id:"osha_677",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1ntas se\xF1ales manuales debe conocer un se\xF1alero (signal person) calificado como m\xEDnimo?",opciones:["Debe conocer al menos las 8 se\xF1ales b\xE1sicas estandarizadas por ASME para gr\xFAas de obra","Debe conocer todas las se\xF1ales est\xE1ndar aplicables al tipo de gr\xFAa que se est\xE1 operando","Debe conocer al menos 12 se\xF1ales que incluyen emergencia y movimientos multidireccionales","Debe conocer las 5 se\xF1ales fundamentales de subir, bajar, parar, girar y avanzar la gr\xFAa"],respuesta_correcta:1,explicacion:"OSHA 1926.1428 requiere que el se\xF1alero calificado conozca TODAS las se\xF1ales manuales est\xE1ndar aplicables al equipo en uso, no un n\xFAmero m\xEDnimo fijo. Debe demostrar competencia completa."},{id:"osha_678",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es la norma de OSHA para industria general que regula montacargas industriales motorizados?",opciones:["La norma 29 CFR 1910 Subpart M que cubre superficies para caminar y trabajar en planta","La norma 29 CFR 1910 Subpart N que cubre manejo de materiales y almacenamiento general","La norma 29 CFR 1910 Subpart O que cubre maquinaria y protecci\xF3n de m\xE1quinas en planta","La norma 29 CFR 1910 Subpart P que cubre herramientas manuales y port\xE1tiles de poder"],respuesta_correcta:1,explicacion:"29 CFR 1910 Subpart N cubre el manejo de materiales y almacenamiento, incluyendo 1910.178 que es la norma espec\xEDfica para montacargas industriales motorizados (powered industrial trucks)."},{id:"osha_679",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es la velocidad m\xE1xima permitida para un montacargas dentro de un edificio o almac\xE9n cerrado?",opciones:["No m\xE1s de 5 millas por hora dentro de edificios y \xE1reas de trabajo interiores cerrados","No hay velocidad fija establecida, debe ser segura para las condiciones del \xE1rea de trabajo","No m\xE1s de 10 millas por hora dentro de edificios y \xE1reas de trabajo interiores cerrados","No m\xE1s de 15 millas por hora dentro de edificios y \xE1reas de trabajo interiores cerrados"],respuesta_correcta:1,explicacion:"OSHA no establece una velocidad m\xE1xima fija para montacargas. 1910.178(n)(1) requiere que se mantenga una velocidad segura seg\xFAn las condiciones del \xE1rea, incluyendo visibilidad, tr\xE1fico y superficie."},{id:"osha_680",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 se debe hacer con los materiales almacenados en pilas para prevenir deslizamientos o colapsos?",opciones:["Cubrir las pilas con lonas impermeables aseguradas con cuerdas para dar estabilidad total","Apilar en forma de pir\xE1mide escalonada y asegurar con cu\xF1as de madera entre cada nivel","Asegurar que las pilas est\xE9n apiladas ordenadamente con trabas cruzadas o medios seguros","Rodear cada pila con barreras met\xE1licas de contenci\xF3n de al menos tres pies de altura fija"],respuesta_correcta:2,explicacion:"OSHA 1926.250(a)(1) requiere que los materiales apilados est\xE9n ordenados, con trabas cruzadas (cross-tied) donde sea aplicable, y asegurados para prevenir deslizamientos o colapsos."},{id:"osha_681",categoria:"OSHA_MATERIALES",pregunta:"\xBFQu\xE9 indica una reducci\xF3n del di\xE1metro del cable de acero de una eslinga de m\xE1s de un tercio del di\xE1metro original?",opciones:["Indica desgaste moderado y la eslinga puede seguir en uso con capacidad reducida al 75%","Indica que la eslinga necesita lubricaci\xF3n inmediata para restaurar su di\xE1metro original","Indica deterioro severo y la eslinga debe ser retirada de servicio inmediatamente por seguridad","Indica que los alambres internos se acomodaron y es normal durante el per\xEDodo de asentamiento"],respuesta_correcta:2,explicacion:"Una reducci\xF3n del di\xE1metro de m\xE1s de 1/3 del original en un cable de acero indica deterioro severo (desgaste, corrosi\xF3n interna o rotura de alambres). La eslinga debe retirarse inmediatamente de servicio."},{id:"osha_682",categoria:"OSHA_MATERIALES",pregunta:"\xBFEst\xE1 permitido que un trabajador viaje como pasajero en las horquillas de un montacargas en uso?",opciones:["S\xED, si el trabajador usa arn\xE9s de seguridad atado al m\xE1stil del montacargas correctamente","S\xED, si la velocidad del montacargas no excede 3 millas por hora durante el desplazamiento","No, nunca se permite que personas viajen en las horquillas de un montacargas bajo ning\xFAn caso","S\xED, solo si se instala una plataforma de trabajo aprobada y dise\xF1ada para montacargas usado"],respuesta_correcta:2,explicacion:"OSHA 1910.178(m)(13) proh\xEDbe absolutamente que cualquier persona viaje sobre las horquillas de un montacargas. Para elevar personas, se requiere una plataforma de trabajo aprobada y asegurada."},{id:"osha_683",categoria:"OSHA_MATERIALES",pregunta:"\xBFCada cu\xE1nto tiempo debe recertificarse la capacitaci\xF3n de un operador de montacargas seg\xFAn OSHA?",opciones:["La recertificaci\xF3n del operador de montacargas debe hacerse anualmente sin excepciones","La recertificaci\xF3n del operador de montacargas debe hacerse cada dos a\xF1os como m\xEDnimo","La recertificaci\xF3n del operador de montacargas debe hacerse cada tres a\xF1os como m\xEDnimo","La recertificaci\xF3n del operador de montacargas debe hacerse cada cinco a\xF1os como m\xEDnimo"],respuesta_correcta:2,explicacion:"OSHA 1910.178(l)(4)(iii) requiere que la evaluaci\xF3n del desempe\xF1o del operador de montacargas se realice al menos cada tres a\xF1os para mantener la certificaci\xF3n vigente."},{id:"osha_684",categoria:"OSHA_MATERIALES",pregunta:"\xBFCu\xE1l es el factor de dise\xF1o m\xEDnimo (design factor) para eslingas de cable de acero seg\xFAn OSHA?",opciones:["El factor de dise\xF1o m\xEDnimo para eslingas de cable de acero es de tres a uno establecido","El factor de dise\xF1o m\xEDnimo para eslingas de cable de acero es de cuatro a uno establecido","El factor de dise\xF1o m\xEDnimo para eslingas de cable de acero es de cinco a uno establecido","El factor de dise\xF1o m\xEDnimo para eslingas de cable de acero es de seis a uno establecido"],respuesta_correcta:2,explicacion:"OSHA 1926.251(c)(1) establece un factor de dise\xF1o m\xEDnimo de 5:1 para eslingas de cable de acero, lo que significa que la resistencia a la rotura debe ser al menos 5 veces la carga de trabajo."},{id:"osha_685",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 representa el valor PEL establecido por OSHA para sustancias t\xF3xicas en el ambiente laboral?",opciones:["Concentraci\xF3n m\xE1xima recomendada por NIOSH para turnos de 10 horas","L\xEDmite de exposici\xF3n permisible promediado en jornada de 8 horas","Concentraci\xF3n inmediatamente peligrosa para la vida y la salud","L\xEDmite umbral de exposici\xF3n a corto plazo de 15 minutos m\xE1ximo"],respuesta_correcta:1,explicacion:"PEL (Permissible Exposure Limit) es el l\xEDmite legal de OSHA promediado en 8 horas TWA. TLV es de ACGIH, IDLH es concentraci\xF3n inmediatamente peligrosa, y STEL es l\xEDmite a corto plazo."},{id:"osha_686",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1l es la diferencia principal entre el TLV-TWA y el TLV-STEL en higiene industrial?",opciones:["TWA se mide con dos\xEDmetro personal y STEL se mide con tubos colorim\xE9tricos","TWA es promedio de 8 horas y STEL es l\xEDmite para exposiciones de 15 minutos","TWA aplica a gases y STEL aplica exclusivamente a vapores org\xE1nicos","TWA es obligatorio por ley federal y STEL es solo una gu\xEDa voluntaria"],respuesta_correcta:1,explicacion:"TLV-TWA es el promedio ponderado en 8 horas, mientras que TLV-STEL es el l\xEDmite para exposiciones cortas de 15 minutos. Ambos son recomendaciones de ACGIH, no leyes federales."},{id:"osha_687",categoria:"OSHA_TOXICOS",pregunta:"Un t\xE9cnico HVAC encuentra un refrigerante desconocido en un equipo viejo. \xBFQu\xE9 secci\xF3n del SDS indica los l\xEDmites de exposici\xF3n ocupacional?",opciones:["Secci\xF3n 2 \u2014 Identificaci\xF3n de peligros seg\xFAn clasificaci\xF3n GHS","Secci\xF3n 8 \u2014 Controles de exposici\xF3n y protecci\xF3n personal","Secci\xF3n 11 \u2014 Informaci\xF3n toxicol\xF3gica y efectos en la salud","Secci\xF3n 9 \u2014 Propiedades f\xEDsicas y qu\xEDmicas del producto"],respuesta_correcta:1,explicacion:"La Secci\xF3n 8 del SDS en formato GHS contiene los l\xEDmites de exposici\xF3n ocupacional (PEL, TLV) y las medidas de protecci\xF3n personal recomendadas."},{id:"osha_688",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1ntas secciones tiene una Hoja de Datos de Seguridad (SDS) bajo el formato GHS adoptado por OSHA?",opciones:["12 secciones organizadas por categor\xEDa de riesgo f\xEDsico","14 secciones que cubren transporte y disposici\xF3n final","16 secciones estandarizadas con orden obligatorio fijo","18 secciones incluyendo informaci\xF3n ambiental detallada"],respuesta_correcta:2,explicacion:"El formato GHS adoptado por OSHA en el Hazard Communication Standard requiere 16 secciones en orden fijo y estandarizado para todas las SDS."},{id:"osha_689",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 instrumento es m\xE1s apropiado para detectar compuestos org\xE1nicos vol\xE1tiles en concentraciones bajas durante trabajo HVAC?",opciones:["Detector de gas combustible catal\xEDtico con lectura en %LEL","Detector de fotoionizaci\xF3n (PID) con l\xE1mpara de 10.6 eV","Medidor multi-gas con sensores electroqu\xEDmicos de 4 gases","Tubo colorim\xE9trico Dr\xE4ger espec\xEDfico para cada compuesto"],respuesta_correcta:1,explicacion:"El detector de fotoionizaci\xF3n (PID) es el instrumento m\xE1s sensible para detectar VOCs en concentraciones bajas (ppb/ppm). Los multi-gas miden gases comunes, no VOCs espec\xEDficos."},{id:"osha_690",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1l es el PEL de OSHA para fibras de asbesto en el aire durante una jornada laboral de 8 horas?",opciones:["0.01 fibras por cent\xEDmetro c\xFAbico promediado en 8 horas","0.1 fibras por cent\xEDmetro c\xFAbico promediado en 8 horas","1.0 fibras por cent\xEDmetro c\xFAbico promediado en 8 horas","0.5 fibras por cent\xEDmetro c\xFAbico promediado en 8 horas"],respuesta_correcta:1,explicacion:"El PEL de OSHA para asbesto es 0.1 f/cc como TWA de 8 horas, con un l\xEDmite de excursi\xF3n de 1.0 f/cc en 30 minutos. Esto aplica a todas las formas de asbesto."},{id:"osha_691",categoria:"OSHA_TOXICOS",pregunta:"Bajo la regulaci\xF3n AHERA, \xBFqu\xE9 clase de trabajo con asbesto incluye la remoci\xF3n de aislamiento t\xE9rmico de tuber\xEDas en sistemas HVAC?",opciones:["Clase II \u2014 remoci\xF3n de materiales que no son aislamiento friable","Clase III \u2014 trabajos de reparaci\xF3n y mantenimiento que perturban ACM","Clase I \u2014 remoci\xF3n de aislamiento t\xE9rmico y material de revestimiento","Clase IV \u2014 trabajos de custodia y limpieza de \xE1reas contaminadas"],respuesta_correcta:2,explicacion:"Clase I es la categor\xEDa de mayor riesgo e incluye remoci\xF3n de TSI (thermal system insulation) y surfacing material. Clase II es remoci\xF3n de otros ACM como pisos y techos."},{id:"osha_692",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1l es el PEL de OSHA para exposici\xF3n a plomo en el aire y a qu\xE9 nivel se activa la vigilancia m\xE9dica?",opciones:["25 \u03BCg/m\xB3 PEL y vigilancia m\xE9dica a 20 \u03BCg/m\xB3 nivel de acci\xF3n","50 \u03BCg/m\xB3 PEL y vigilancia m\xE9dica a 30 \u03BCg/m\xB3 nivel de acci\xF3n","75 \u03BCg/m\xB3 PEL y vigilancia m\xE9dica a 50 \u03BCg/m\xB3 nivel de acci\xF3n","100 \u03BCg/m\xB3 PEL y vigilancia m\xE9dica a 75 \u03BCg/m\xB3 nivel de acci\xF3n"],respuesta_correcta:1,explicacion:"El PEL de OSHA para plomo es 50 \u03BCg/m\xB3 TWA de 8 horas. El nivel de acci\xF3n es 30 \u03BCg/m\xB3, que activa monitoreo de aire, vigilancia m\xE9dica y an\xE1lisis de plomo en sangre."},{id:"osha_693",categoria:"OSHA_TOXICOS",pregunta:"Un t\xE9cnico HVAC suelda tuber\xEDas de cobre en un edificio viejo con pintura de plomo. \xBFA qu\xE9 nivel de plomo en sangre OSHA requiere remoci\xF3n m\xE9dica del trabajador?",opciones:["25 \u03BCg/dL requiere remoci\xF3n m\xE9dica inmediata del lugar de trabajo","40 \u03BCg/dL requiere remoci\xF3n m\xE9dica inmediata del lugar de trabajo","50 \u03BCg/dL requiere remoci\xF3n m\xE9dica inmediata del lugar de trabajo","60 \u03BCg/dL requiere remoci\xF3n m\xE9dica inmediata del lugar de trabajo"],respuesta_correcta:2,explicacion:"OSHA requiere remoci\xF3n m\xE9dica cuando el nivel de plomo en sangre alcanza 50 \u03BCg/dL en construcci\xF3n (o un promedio de tres muestras). El retorno se permite a 40 \u03BCg/dL."},{id:"osha_694",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 controles especifica la Tabla 1 de OSHA para s\xEDlice cristalina respirable cuando se corta concreto con sierra estacionaria?",opciones:["Usar sierra con suministro continuo de agua y respirador N95 siempre","Usar sierra con suministro continuo de agua que minimice la emisi\xF3n","Usar ventilaci\xF3n por extracci\xF3n local con filtro HEPA integrado","Usar respirador de cara completa con cartuchos P100 solamente"],respuesta_correcta:1,explicacion:"La Tabla 1 de 29 CFR 1926.1153 especifica controles de ingenier\xEDa por tarea. Para sierras estacionarias, requiere suministro continuo de agua. No siempre exige respirador si los controles funcionan."},{id:"osha_695",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1l es el PEL de OSHA para s\xEDlice cristalina respirable y cu\xE1l es la regulaci\xF3n aplicable en construcci\xF3n?",opciones:["25 \u03BCg/m\xB3 TWA bajo la regulaci\xF3n 29 CFR 1926.1152 de OSHA","50 \u03BCg/m\xB3 TWA bajo la regulaci\xF3n 29 CFR 1926.1153 de OSHA","75 \u03BCg/m\xB3 TWA bajo la regulaci\xF3n 29 CFR 1910.1053 de OSHA","100 \u03BCg/m\xB3 TWA bajo la regulaci\xF3n 29 CFR 1926.1101 de OSHA"],respuesta_correcta:1,explicacion:"El PEL para s\xEDlice cristalina respirable es 50 \u03BCg/m\xB3 TWA de 8 horas. La regulaci\xF3n de construcci\xF3n es 29 CFR 1926.1153, y la de industria general es 29 CFR 1910.1053."},{id:"osha_696",categoria:"OSHA_TOXICOS",pregunta:"El amoniaco (R-717) se usa como refrigerante industrial. \xBFCu\xE1les son sus l\xEDmites de exposici\xF3n OSHA TWA y STEL?",opciones:["50 ppm TWA de 8 horas y 75 ppm STEL de 15 minutos m\xE1ximo","25 ppm TWA de 8 horas y 35 ppm STEL de 15 minutos m\xE1ximo","10 ppm TWA de 8 horas y 25 ppm STEL de 15 minutos m\xE1ximo","35 ppm TWA de 8 horas y 50 ppm STEL de 15 minutos m\xE1ximo"],respuesta_correcta:1,explicacion:"El PEL de OSHA para amoniaco es 50 ppm TWA, pero el TLV de ACGIH (m\xE1s protectivo y com\xFAnmente referenciado) es 25 ppm TWA y 35 ppm STEL. OSHA acepta las gu\xEDas ACGIH como referencia."},{id:"osha_697",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 gas t\xF3xico se produce cuando un refrigerante HFC entra en contacto con llama abierta o superficies muy calientes?",opciones:["Fosgeno y fluoruro de carbonilo por descomposici\xF3n del refrigerante","\xC1cido fluorh\xEDdrico por descomposici\xF3n t\xE9rmica del refrigerante","Di\xF3xido de azufre por la reacci\xF3n del aceite con el refrigerante","Mon\xF3xido de carbono por la combusti\xF3n incompleta del refrigerante"],respuesta_correcta:1,explicacion:"La descomposici\xF3n t\xE9rmica de refrigerantes HFC produce \xE1cido fluorh\xEDdrico (HF), que es extremadamente corrosivo y t\xF3xico. Tambi\xE9n puede producir fosgeno con HCFCs, pero el HF es el producto principal."},{id:"osha_698",categoria:"OSHA_TOXICOS",pregunta:"Un t\xE9cnico instala aislamiento de espuma de poliuretano por aspersi\xF3n. \xBFQu\xE9 sustancia qu\xEDmica representa el mayor riesgo de sensibilizaci\xF3n respiratoria?",opciones:["Estireno vol\xE1til liberado durante la reacci\xF3n de curado de espuma","Formaldeh\xEDdo residual atrapado dentro de las celdas de la espuma","Isocianatos (MDI/TDI) presentes en el componente B de la mezcla","Aminas terciarias usadas como catalizadores en la formulaci\xF3n"],respuesta_correcta:2,explicacion:"Los isocianatos (MDI y TDI) son sensibilizadores respiratorios potentes que pueden causar asma ocupacional irreversible. Se encuentran en el componente B de la espuma en spray."},{id:"osha_699",categoria:"OSHA_TOXICOS",pregunta:"\xBFA qu\xE9 concentraci\xF3n de mon\xF3xido de carbono (CO) se activa la alarma de peligro inmediato seg\xFAn NIOSH?",opciones:["35 ppm como l\xEDmite de exposici\xF3n promedio en 8 horas laborales","50 ppm como l\xEDmite de exposici\xF3n establecido por OSHA de 8 horas","200 ppm como concentraci\xF3n IDLH de peligro inmediato para la vida","1200 ppm como concentraci\xF3n IDLH de peligro inmediato para la vida"],respuesta_correcta:2,explicacion:"El IDLH del CO es 1200 ppm seg\xFAn NIOSH. El PEL de OSHA es 50 ppm TWA y el REL de NIOSH es 35 ppm TWA. A 200 ppm aparecen s\xEDntomas pero no es IDLH."},{id:"osha_700",categoria:"OSHA_TOXICOS",pregunta:"Un t\xE9cnico HVAC mide CO en un cuarto mec\xE1nico con caldera de gas. \xBFCu\xE1l es el PEL de OSHA para mon\xF3xido de carbono?",opciones:["25 ppm TWA promediado en una jornada laboral de ocho horas","35 ppm TWA promediado en una jornada laboral de ocho horas","50 ppm TWA promediado en una jornada laboral de ocho horas","100 ppm TWA promediado en una jornada laboral de ocho horas"],respuesta_correcta:2,explicacion:"El PEL de OSHA para CO es 50 ppm TWA de 8 horas. El REL de NIOSH es m\xE1s estricto a 35 ppm TWA. Concentraciones superiores a 200 ppm causan dolor de cabeza severo."},{id:"osha_701",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1l es el prop\xF3sito principal de la ventilaci\xF3n por extracci\xF3n local (LEV) comparada con la ventilaci\xF3n por diluci\xF3n en un taller HVAC?",opciones:["Reducir la temperatura ambiente general del taller durante el verano","Capturar contaminantes en la fuente antes de que se dispersen al aire","Aumentar la presi\xF3n positiva del edificio para evitar infiltraci\xF3n","Cumplir con los requisitos de renovaciones de aire por hora del c\xF3digo"],respuesta_correcta:1,explicacion:"La LEV captura contaminantes directamente en su punto de generaci\xF3n, siendo mucho m\xE1s efectiva que la diluci\xF3n. La velocidad de captura debe ser suficiente para arrastrar el contaminante hacia la campana."},{id:"osha_702",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 factor determina la velocidad de captura m\xEDnima requerida en una campana de extracci\xF3n local para humos de soldadura?",opciones:["El caudal total del sistema de ductos expresado en CFM o metros c\xFAbicos","La velocidad de generaci\xF3n y dispersi\xF3n del contaminante en el aire","La distancia entre la campana y el ventilador extractor del sistema","El tipo de filtro HEPA instalado en el colector de polvo principal"],respuesta_correcta:1,explicacion:"La velocidad de captura depende de c\xF3mo se genera el contaminante. Humos de soldadura a baja velocidad requieren ~100 fpm, mientras que operaciones de esmerilado requieren ~200+ fpm."},{id:"osha_703",categoria:"OSHA_TOXICOS",pregunta:"Seg\xFAn la jerarqu\xEDa de controles de OSHA para exposici\xF3n qu\xEDmica, \xBFcu\xE1l es el m\xE9todo M\xC1S efectivo?",opciones:["Equipos de protecci\xF3n personal como respiradores y guantes qu\xEDmicos","Controles administrativos como rotaci\xF3n de personal y se\xF1alizaci\xF3n","Controles de ingenier\xEDa como ventilaci\xF3n y aislamiento del proceso","Eliminaci\xF3n o sustituci\xF3n de la sustancia qu\xEDmica por una m\xE1s segura"],respuesta_correcta:3,explicacion:"La jerarqu\xEDa de controles es: 1) Eliminaci\xF3n/Sustituci\xF3n (m\xE1s efectivo), 2) Controles de ingenier\xEDa, 3) Controles administrativos, 4) PPE (menos efectivo). Eliminar el peligro es siempre la mejor opci\xF3n."},{id:"osha_704",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 pictograma GHS representa peligro para la salud incluyendo carcinogenicidad, sensibilizaci\xF3n respiratoria y toxicidad org\xE1nica?",opciones:["Calavera con tibias cruzadas sobre fondo blanco con borde rojo","Signo de exclamaci\xF3n sobre fondo blanco con borde rojo est\xE1ndar","Silueta humana con estrella en el pecho sobre fondo con borde rojo","Llama sobre fondo blanco con borde rojo que indica inflamabilidad"],respuesta_correcta:2,explicacion:"El pictograma de 'peligro para la salud' muestra una silueta humana con una estrella en el pecho. Indica CMR (carcin\xF3geno, mut\xE1geno, t\xF3xico reproductivo), sensibilizaci\xF3n respiratoria y STOT."},{id:"osha_705",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1l de las cuatro rutas de exposici\xF3n a sustancias t\xF3xicas es la M\xC1S com\xFAn en el trabajo HVAC?",opciones:["Absorci\xF3n a trav\xE9s de la piel por contacto directo con refrigerantes","Inhalaci\xF3n de vapores, gases y part\xEDculas suspendidas en el aire","Ingesti\xF3n accidental por contaminaci\xF3n de alimentos o manos sucias","Inyecci\xF3n a trav\xE9s de la piel por equipos de alta presi\xF3n hidr\xE1ulica"],respuesta_correcta:1,explicacion:"La inhalaci\xF3n es la ruta de exposici\xF3n m\xE1s com\xFAn en HVAC. Los t\xE9cnicos est\xE1n expuestos a refrigerantes, humos de soldadura, part\xEDculas de asbesto y otros contaminantes a\xE9reos constantemente."},{id:"osha_706",categoria:"OSHA_TOXICOS",pregunta:"\xBFEn qu\xE9 se diferencia el monitoreo biol\xF3gico del monitoreo de aire para evaluar exposici\xF3n a plomo?",opciones:["El monitoreo de aire mide la dosis absorbida total por todas las rutas","El monitoreo biol\xF3gico mide la dosis absorbida incluyendo todas las rutas","El monitoreo biol\xF3gico solo mide la exposici\xF3n por inhalaci\xF3n directa","El monitoreo de aire incluye absorci\xF3n d\xE9rmica y exposici\xF3n por ingesti\xF3n"],respuesta_correcta:1,explicacion:"El monitoreo biol\xF3gico (como plomo en sangre) mide la dosis total absorbida por TODAS las rutas (inhalaci\xF3n, ingesti\xF3n, piel). El monitoreo de aire solo mide concentraci\xF3n en el aire."},{id:"osha_707",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 valor de exposici\xF3n representa la concentraci\xF3n m\xE1xima que NUNCA debe excederse en ning\xFAn momento durante la jornada?",opciones:["TLV-TWA que es el promedio ponderado durante ocho horas laborales","STEL que permite exposici\xF3n de quince minutos hasta cuatro veces","Ceiling o valor techo que no debe superarse en ning\xFAn instante","IDLH que representa peligro inmediato para la vida y la salud"],respuesta_correcta:2,explicacion:"El valor Ceiling (techo) es la concentraci\xF3n que nunca debe excederse en ning\xFAn momento. A diferencia del TWA (promedio 8h) y STEL (15 min), el Ceiling no permite ninguna excursi\xF3n por encima."},{id:"osha_708",categoria:"OSHA_TOXICOS",pregunta:"Un medidor multi-gas t\xEDpico usado por t\xE9cnicos HVAC en espacios confinados detecta cuatro gases. \xBFCu\xE1les son?",opciones:["Amoniaco, fre\xF3n, mon\xF3xido de nitr\xF3geno y di\xF3xido de carbono est\xE1ndar","Ox\xEDgeno, gases combustibles, mon\xF3xido de carbono y \xE1cido sulfh\xEDdrico","Metano, propano, di\xF3xido de carbono y vapor de agua como referencia","Refrigerante, ozono, di\xF3xido de nitr\xF3geno y cloro como gases t\xF3xicos"],respuesta_correcta:1,explicacion:"El medidor multi-gas est\xE1ndar (4-gas meter) detecta O2, LEL (combustibles), CO y H2S. Son los cuatro peligros atmosf\xE9ricos m\xE1s comunes en espacios confinados."},{id:"osha_709",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 tipo de fibra de asbesto es la m\xE1s com\xFAnmente encontrada en aislamiento de ductos y tuber\xEDas de sistemas HVAC antiguos?",opciones:["Amosita (asbesto marr\xF3n) del grupo anf\xEDbol, muy friable en ductos","Crisotilo (asbesto blanco) del grupo serpentina, el m\xE1s usado en EEUU","Crocidolita (asbesto azul) del grupo anf\xEDbol, el m\xE1s peligroso de todos","Tremolita del grupo anf\xEDbol, contaminante natural de otros minerales"],respuesta_correcta:1,explicacion:"El crisotilo (asbesto blanco) representa aproximadamente el 95% de todo el asbesto usado en EEUU. Se encuentra com\xFAnmente en aislamiento de ductos, tuber\xEDas y materiales de construcci\xF3n."},{id:"osha_710",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 secci\xF3n del SDS contiene la informaci\xF3n sobre estabilidad qu\xEDmica y posibles reacciones peligrosas de un refrigerante?",opciones:["Secci\xF3n 7 \u2014 Manejo y almacenamiento del producto qu\xEDmico clasificado","Secci\xF3n 9 \u2014 Propiedades f\xEDsicas y qu\xEDmicas como punto de ebullici\xF3n","Secci\xF3n 10 \u2014 Estabilidad y reactividad del producto ante condiciones","Secci\xF3n 14 \u2014 Informaci\xF3n de transporte seg\xFAn regulaci\xF3n DOT federal"],respuesta_correcta:2,explicacion:"La Secci\xF3n 10 del SDS cubre estabilidad y reactividad, incluyendo condiciones a evitar, materiales incompatibles y productos de descomposici\xF3n peligrosa como HF de refrigerantes."},{id:"osha_711",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1l es el IDLH (peligro inmediato para la vida) del amoniaco R-717 seg\xFAn NIOSH?",opciones:["100 ppm considerado inmediatamente peligroso para la vida del t\xE9cnico","300 ppm considerado inmediatamente peligroso para la vida del t\xE9cnico","500 ppm considerado inmediatamente peligroso para la vida del t\xE9cnico","750 ppm considerado inmediatamente peligroso para la vida del t\xE9cnico"],respuesta_correcta:1,explicacion:"El IDLH del amoniaco es 300 ppm seg\xFAn NIOSH. A esta concentraci\xF3n, la exposici\xF3n de 30 minutos puede causar efectos graves irreversibles o impedir la evacuaci\xF3n."},{id:"osha_712",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 pictograma GHS debe aparecer en la etiqueta de un cilindro de refrigerante que es un gas comprimido a presi\xF3n?",opciones:["Llama que indica que el producto es inflamable bajo ciertas condiciones","Cilindro de gas que indica producto almacenado bajo alta presi\xF3n interna","Signo de exclamaci\xF3n que indica irritaci\xF3n y peligro menor a la salud","C\xEDrculo con llama que indica que el producto es un oxidante fuerte"],respuesta_correcta:1,explicacion:"El pictograma del cilindro de gas (GHS04) indica gases bajo presi\xF3n: comprimidos, licuados, disueltos o refrigerados. Es obligatorio en etiquetas de cilindros de refrigerante."},{id:"osha_713",categoria:"OSHA_TOXICOS",pregunta:"Un t\xE9cnico HVAC usa solvente para limpiar contactos el\xE9ctricos. \xBFQu\xE9 ruta de exposici\xF3n ocurre simult\xE1neamente con la inhalaci\xF3n?",opciones:["Inyecci\xF3n del solvente a trav\xE9s de la piel por la presi\xF3n del aerosol","Ingesti\xF3n del solvente por transferencia de manos a boca inadvertida","Absorci\xF3n d\xE9rmica del solvente a trav\xE9s de la piel de las manos y brazos","Radiaci\xF3n ionizante emitida por los componentes vol\xE1tiles del solvente"],respuesta_correcta:2,explicacion:"Los solventes org\xE1nicos se absorben f\xE1cilmente a trav\xE9s de la piel (absorci\xF3n d\xE9rmica). Al limpiar contactos, el t\xE9cnico inhala vapores y absorbe solvente por las manos simult\xE1neamente."},{id:"osha_714",categoria:"OSHA_TOXICOS",pregunta:"\xBFCada cu\xE1nto debe revisarse la calibraci\xF3n de un detector de fotoionizaci\xF3n (PID) seg\xFAn las mejores pr\xE1cticas de higiene industrial?",opciones:["Cada semana laboral o cuando cambie la l\xE1mpara de ionizaci\xF3n UV","Cada mes calendario con gas de calibraci\xF3n de isobutileno al 100 ppm","Antes de cada uso diario con gas de calibraci\xF3n de concentraci\xF3n conocida","Cada seis meses junto con el mantenimiento preventivo del instrumento"],respuesta_correcta:2,explicacion:"Los PIDs deben calibrarse antes de cada uso diario con gas de referencia (generalmente isobutileno 100 ppm). Factores como humedad y contaminaci\xF3n de la l\xE1mpara afectan la lectura."},{id:"osha_715",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 tipo de respirador se requiere como m\xEDnimo para trabajos Clase III con asbesto en sistemas HVAC seg\xFAn OSHA?",opciones:["Respirador purificador de aire con cartuchos para vapores org\xE1nicos OV","Respirador de media cara con filtros P100 para part\xEDculas de asbesto","Respirador de cara completa con suministro de aire a presi\xF3n positiva","Respirador desechable N95 aprobado por NIOSH para fibras de asbesto"],respuesta_correcta:1,explicacion:"Para trabajos Clase III con asbesto, OSHA requiere como m\xEDnimo un respirador de media cara con filtros HEPA (P100 o N100). Para Clase I se necesita PAPR o suministro de aire."},{id:"osha_716",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 declaraci\xF3n de peligro GHS (H-statement) corresponde a un refrigerante clasificado como gas licuado bajo presi\xF3n?",opciones:["H220 \u2014 Gas extremadamente inflamable en contacto con fuentes de ignici\xF3n","H280 \u2014 Contiene gas a presi\xF3n que puede explotar si se calienta el envase","H281 \u2014 Contiene gas refrigerado que puede causar quemaduras criog\xE9nicas","H331 \u2014 T\xF3xico por inhalaci\xF3n si se exceden los l\xEDmites de exposici\xF3n"],respuesta_correcta:1,explicacion:"H280 'Contiene gas a presi\xF3n; puede explotar si se calienta' aplica a gases comprimidos y licuados como la mayor\xEDa de refrigerantes HVAC en cilindros presurizados."},{id:"osha_717",categoria:"OSHA_TOXICOS",pregunta:"\xBFCu\xE1l es la velocidad de captura recomendada para una campana de extracci\xF3n lateral que controla humos de soldadura con caut\xEDn?",opciones:["50 a 75 pies por minuto para operaciones de baja generaci\xF3n de humos","100 a 150 pies por minuto para capturar humos en condiciones tranquilas","200 a 500 pies por minuto para operaciones de alta velocidad de emisi\xF3n","500 a 2000 pies por minuto para procesos con part\xEDculas muy pesadas"],respuesta_correcta:1,explicacion:"Para humos de soldadura generados a baja velocidad en aire relativamente tranquilo, la velocidad de captura recomendada es de 100-150 fpm seg\xFAn el manual de ventilaci\xF3n industrial de ACGIH."},{id:"osha_718",categoria:"OSHA_TOXICOS",pregunta:"Un t\xE9cnico HVAC trabaja con espuma en spray de poliuretano. \xBFCu\xE1l es el PEL de OSHA para isocianato TDI?",opciones:["0.005 ppm como l\xEDmite techo que nunca debe excederse en el \xE1rea","0.02 ppm como TWA de 8 horas con ceiling de 0.02 ppm adicional","0.05 ppm como TWA de 8 horas seg\xFAn tabla Z-1 de OSHA vigente","0.1 ppm como promedio ponderado en jornada laboral de ocho horas"],respuesta_correcta:0,explicacion:"El PEL de OSHA para TDI es 0.02 ppm ceiling (valor techo). Sin embargo, ACGIH recomienda un TLV de 0.005 ppm TWA, que es el est\xE1ndar m\xE1s protectivo frecuentemente citado."},{id:"osha_719",categoria:"OSHA_TOXICOS",pregunta:"\xBFQu\xE9 factor hace que la combinaci\xF3n de ruido y exposici\xF3n a solventes org\xE1nicos sea m\xE1s peligrosa para t\xE9cnicos HVAC?",opciones:["Los solventes reducen la efectividad de los tapones auditivos de espuma","El ruido aumenta la absorci\xF3n d\xE9rmica de los solventes por vasodilataci\xF3n","Los solventes otot\xF3xicos potencian la p\xE9rdida auditiva causada por ruido","El ruido impide detectar el olor de advertencia de los solventes t\xF3xicos"],respuesta_correcta:2,explicacion:"Ciertos solventes como tolueno, xileno y estireno son otot\xF3xicos \u2014 da\xF1an directamente las c\xE9lulas ciliadas del o\xEDdo interno. Combinados con ruido, la p\xE9rdida auditiva es sin\xE9rgica y m\xE1s severa."},{id:"osha_720",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 regulaci\xF3n de OSHA establece los requisitos m\xEDnimos para un Plan de Acci\xF3n de Emergencia (EAP) en el lugar de trabajo?",opciones:["29 CFR 1910.36 que cubre los requisitos de dise\xF1o de rutas de salida","29 CFR 1910.38 que establece los elementos m\xEDnimos del plan de acci\xF3n","29 CFR 1910.39 que cubre los requisitos del plan de prevenci\xF3n de fuego","29 CFR 1910.157 que regula los extintores port\xE1tiles contra incendios"],respuesta_correcta:1,explicacion:"29 CFR 1910.38 establece los requisitos del Emergency Action Plan incluyendo procedimientos de evacuaci\xF3n, sistema de alarma, y responsabilidades del personal designado."},{id:"osha_721",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCu\xE1l de los siguientes elementos es OBLIGATORIO en un Plan de Acci\xF3n de Emergencia seg\xFAn 29 CFR 1910.38?",opciones:["Lista de equipos de primeros auxilios y su ubicaci\xF3n exacta en cada piso","Procedimientos de evacuaci\xF3n y asignaci\xF3n de rutas de escape por \xE1rea","Programa de simulacros trimestrales con documentaci\xF3n de tiempos exactos","Contrato con empresa externa de respuesta a emergencias y materiales"],respuesta_correcta:1,explicacion:"29 CFR 1910.38 requiere: procedimientos de evacuaci\xF3n, tipo de alarma, rutas de escape, procedimientos para empleados que permanecen, contactos de emergencia y procedimiento de reporte."},{id:"osha_722",categoria:"OSHA_EMERGENCIAS",pregunta:"Un t\xE9cnico HVAC trabaja en un edificio comercial. \xBFQu\xE9 distancia m\xE1xima debe haber a la salida de emergencia m\xE1s cercana?",opciones:["100 pies como distancia m\xE1xima para \xE1reas sin rociadores autom\xE1ticos","150 pies como distancia m\xE1xima para \xE1reas sin rociadores autom\xE1ticos","200 pies como distancia m\xE1xima para \xE1reas con rociadores autom\xE1ticos","300 pies como distancia m\xE1xima para \xE1reas con rociadores autom\xE1ticos"],respuesta_correcta:2,explicacion:"La distancia m\xE1xima de viaje a una salida es 200 pies sin rociadores y 250 pies con rociadores. El c\xF3digo de construcci\xF3n (IBC) puede ser m\xE1s estricto dependiendo de la ocupaci\xF3n."},{id:"osha_723",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 tipo de sistema de alarma debe tener un lugar de trabajo con m\xE1s de 10 empleados seg\xFAn OSHA?",opciones:["Alarma audible que sea claramente distinguible sobre el ruido ambiental","Sistema visual con luces estrobosc\xF3picas en todas las \xE1reas de trabajo","Alarma combinada audible y visual para cubrir personas con discapacidades","Sistema de voceo p\xFAblico con altavoces en cada zona del edificio entero"],respuesta_correcta:0,explicacion:"OSHA requiere que la alarma sea audible y distinguible sobre el ruido ambiental. Sin embargo, ADA y NFPA tambi\xE9n requieren alarmas visuales para empleados con discapacidad auditiva."},{id:"osha_724",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 clase de extintor se necesita para apagar un fuego el\xE9ctrico en un panel de control de un sistema HVAC?",opciones:["Clase A porque el panel contiene materiales s\xF3lidos como pl\xE1stico y cables","Clase B porque hay aceites y lubricantes cerca de los componentes el\xE9ctricos","Clase C que es apropiado para fuegos que involucran equipos el\xE9ctricos vivos","Clase D porque los contactores contienen componentes de metales especiales"],respuesta_correcta:2,explicacion:"Clase C es para fuegos en equipos el\xE9ctricos energizados. Una vez desconectada la energ\xEDa, el fuego se reclasifica seg\xFAn el material que arde (A o B). Nunca usar agua en equipos energizados."},{id:"osha_725",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 significa cada letra de la t\xE9cnica PASS para usar un extintor port\xE1til contra incendios?",opciones:["Prepare, Aim, Spray, Secure \u2014 preparar, apuntar, rociar, asegurar el \xE1rea","Push, Activate, Spray, Sweep \u2014 empujar, activar, rociar, barrer la base","Pull, Aim, Squeeze, Sweep \u2014 jalar pasador, apuntar, apretar, barrer base","Point, Activate, Spray, Stop \u2014 apuntar, activar, rociar, detener y evaluar"],respuesta_correcta:2,explicacion:"PASS = Pull the pin (jalar pasador), Aim at base (apuntar a la base del fuego), Squeeze the handle (apretar la manija), Sweep side to side (barrer de lado a lado)."},{id:"osha_726",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCu\xE1l es la distancia m\xEDnima que debe mantenerse libre debajo de las cabezas de rociadores autom\xE1ticos seg\xFAn NFPA y OSHA?",opciones:["12 pulgadas libres debajo de cada cabeza de rociador sin obstrucciones","18 pulgadas libres debajo de cada cabeza de rociador sin obstrucciones","24 pulgadas libres debajo de cada cabeza de rociador sin obstrucciones","36 pulgadas libres debajo de cada cabeza de rociador sin obstrucciones"],respuesta_correcta:1,explicacion:"NFPA 25 y OSHA requieren mantener 18 pulgadas de espacio libre debajo de las cabezas de rociadores. Almacenar materiales cerca puede bloquear el patr\xF3n de descarga del agua."},{id:"osha_727",categoria:"OSHA_EMERGENCIAS",pregunta:"Un t\xE9cnico HVAC escucha la alarma de tornado mientras trabaja en un techo. \xBFCu\xE1l es el procedimiento correcto?",opciones:["Evacuar el edificio inmediatamente hacia el punto de reuni\xF3n del exterior","Refugiarse en el lugar m\xE1s bajo interior del edificio lejos de ventanas","Permanecer en el techo en posici\xF3n baja hasta que pase la tormenta severa","Dirigirse al estacionamiento y refugiarse dentro de su veh\xEDculo de trabajo"],respuesta_correcta:1,explicacion:"Durante un tornado, el procedimiento es shelter-in-place: ir al nivel m\xE1s bajo interior del edificio, alejarse de ventanas y puertas exteriores. NUNCA quedarse en el techo ni en veh\xEDculos."},{id:"osha_728",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCu\xE1ndo se debe evacuar versus refugiarse en el lugar (shelter-in-place) durante una emergencia qu\xEDmica?",opciones:["Siempre evacuar sin importar el tipo de liberaci\xF3n qu\xEDmica que ocurra","Refugiarse si la nube t\xF3xica est\xE1 afuera y evacuar si el derrame es dentro","Evacuar si el derrame es dentro del edificio y refugiarse si la nube es afuera","Refugiarse siempre hasta que lleguen los servicios de emergencia al sitio"],respuesta_correcta:2,explicacion:"Si el derrame qu\xEDmico es interno, evacuar el edificio. Si hay una nube t\xF3xica externa (como de un tren descarrilado), shelter-in-place: cerrar HVAC, sellar puertas y ventanas."},{id:"osha_729",categoria:"OSHA_EMERGENCIAS",pregunta:"Un t\xE9cnico HVAC derrama refrigerante l\xEDquido R-410A en un cuarto mec\xE1nico peque\xF1o. \xBFCu\xE1l es la primera acci\xF3n correcta?",opciones:["Contener el derrame con materiales absorbentes antes de que se evapore","Evacuar el \xE1rea y ventilar porque el refrigerante desplaza el ox\xEDgeno al evaporarse","Aplicar agua al derrame para diluir el refrigerante y reducir su concentraci\xF3n","Llamar al 911 inmediatamente antes de tomar cualquier otra acci\xF3n de respuesta"],respuesta_correcta:1,explicacion:"R-410A l\xEDquido se evapora r\xE1pidamente, desplazando ox\xEDgeno en espacios peque\xF1os. La primera acci\xF3n es evacuar y ventilar. Los refrigerantes son m\xE1s pesados que el aire y se acumulan a nivel del piso."},{id:"osha_730",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCu\xE1les son los tres elementos del tri\xE1ngulo del fuego necesarios para que exista combusti\xF3n?",opciones:["Chispa, material inflamable y aire comprimido a presi\xF3n suficiente","Calor, ox\xEDgeno y combustible en proporciones adecuadas para arder","Electricidad, gases inflamables y superficie caliente como catalizador","Ignici\xF3n, ventilaci\xF3n mec\xE1nica y material org\xE1nico en estado s\xF3lido"],respuesta_correcta:1,explicacion:"El tri\xE1ngulo del fuego requiere tres elementos: calor (fuente de ignici\xF3n), ox\xEDgeno (comburente) y combustible (material que arde). Eliminar cualquiera de los tres extingue el fuego."},{id:"osha_731",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCu\xE1l es la distancia m\xE1xima de recorrido permitida hasta un extintor Clase A seg\xFAn OSHA 29 CFR 1910.157?",opciones:["50 pies de distancia m\xE1xima de recorrido hasta el extintor m\xE1s cercano","75 pies de distancia m\xE1xima de recorrido hasta el extintor m\xE1s cercano","100 pies de distancia m\xE1xima de recorrido hasta el extintor m\xE1s cercano","150 pies de distancia m\xE1xima de recorrido hasta el extintor m\xE1s cercano"],respuesta_correcta:1,explicacion:"OSHA y NFPA 10 requieren que los extintores Clase A est\xE9n a m\xE1ximo 75 pies de distancia de recorrido. Los extintores Clase B deben estar a m\xE1ximo 50 pies."},{id:"osha_732",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCu\xE1l es la distancia m\xE1xima de recorrido hasta un extintor Clase B para l\xEDquidos inflamables?",opciones:["50 pies de distancia m\xE1xima de recorrido hasta el extintor m\xE1s cercano","75 pies de distancia m\xE1xima de recorrido hasta el extintor m\xE1s cercano","100 pies de distancia m\xE1xima de recorrido hasta el extintor m\xE1s cercano","150 pies de distancia m\xE1xima de recorrido hasta el extintor m\xE1s cercano"],respuesta_correcta:0,explicacion:"Los extintores Clase B para l\xEDquidos inflamables deben estar a m\xE1ximo 50 pies de distancia de recorrido seg\xFAn NFPA 10 y OSHA, debido al r\xE1pido crecimiento de estos fuegos."},{id:"osha_733",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCon qu\xE9 frecuencia deben inspeccionarse visualmente los extintores port\xE1tiles seg\xFAn OSHA y NFPA 10?",opciones:["Cada semana laboral verificando ubicaci\xF3n y accesibilidad del extintor","Cada mes verificando presi\xF3n, sello, etiqueta, da\xF1o f\xEDsico y ubicaci\xF3n","Cada trimestre con registro documentado y firma del inspector de \xE1rea","Cada seis meses con prueba de descarga parcial para verificar operaci\xF3n"],respuesta_correcta:1,explicacion:"NFPA 10 y OSHA requieren inspecci\xF3n visual mensual de extintores: verificar presi\xF3n en el man\xF3metro, sello/pasador intacto, sin da\xF1o visible, etiqueta legible y acceso libre."},{id:"osha_734",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCada cu\xE1ntos a\xF1os requiere NFPA 10 el mantenimiento completo con desmontaje interno (tear-down) de un extintor de polvo qu\xEDmico?",opciones:["Cada 3 a\xF1os con prueba hidrost\xE1tica del cilindro como parte del servicio","Cada 5 a\xF1os con recarga completa y verificaci\xF3n interna del cilindro","Cada 6 a\xF1os con examen interno completo y recarga del agente extintor","Cada 10 a\xF1os con prueba hidrost\xE1tica del cilindro a presi\xF3n de prueba"],respuesta_correcta:2,explicacion:"NFPA 10 requiere examen interno cada 6 a\xF1os para extintores de polvo qu\xEDmico seco almacenados a presi\xF3n. La prueba hidrost\xE1tica es cada 12 a\xF1os. El mantenimiento anual es separado."},{id:"osha_735",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 clase de extintor se necesita para un fuego de grasa de cocina en un restaurante donde el t\xE9cnico HVAC repara la campana?",opciones:["Clase B porque la grasa es un l\xEDquido inflamable que se puede extinguir","Clase K dise\xF1ado espec\xEDficamente para fuegos de aceites y grasas de cocina","Clase A-B-C multiprop\xF3sito que cubre todos los tipos de fuego comunes","Clase C porque la campana extractora tiene componentes el\xE9ctricos activos"],respuesta_correcta:1,explicacion:"Clase K est\xE1 dise\xF1ado espec\xEDficamente para fuegos de aceites y grasas de cocina a alta temperatura. Usa agente qu\xEDmico h\xFAmedo que saponifica la grasa. Los Clase B no son efectivos en grasas de cocina."},{id:"osha_736",categoria:"OSHA_EMERGENCIAS",pregunta:"Un Plan de Prevenci\xF3n de Incendios bajo 29 CFR 1910.39 debe incluir una lista de los principales peligros de fuego. \xBFQu\xE9 m\xE1s requiere?",opciones:["Simulacros mensuales documentados con tiempos de evacuaci\xF3n registrados","Procedimientos de manejo y almacenamiento de materiales inflamables y combustibles","Capacitaci\xF3n anual en primeros auxilios para todos los empleados de planta","Planos arquitect\xF3nicos actualizados con rutas de evacuaci\xF3n se\xF1alizadas siempre"],respuesta_correcta:1,explicacion:"29 CFR 1910.39 requiere: lista de peligros de fuego, procedimientos de manejo/almacenamiento de materiales peligrosos, tipo de equipo de protecci\xF3n contra fuego, y mantenimiento de controles."},{id:"osha_737",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 debe hacer el t\xE9cnico HVAC al llegar al punto de reuni\xF3n despu\xE9s de una evacuaci\xF3n de emergencia?",opciones:["Regresar a buscar herramientas y equipos valiosos que dej\xF3 en el \xE1rea","Reportarse con el coordinador de piso para verificar el conteo de personal","Llamar a su supervisor por tel\xE9fono para informar su ubicaci\xF3n actual","Esperar en su veh\xEDculo personal hasta que los bomberos den aviso de retorno"],respuesta_correcta:1,explicacion:"Al llegar al punto de reuni\xF3n, cada empleado debe reportarse con su coordinador/jefe de piso para el conteo de personal (headcount). Esto permite identificar si alguien falta y necesita rescate."},{id:"osha_738",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 clase de extintor se usa para apagar un fuego de magnesio o titanio en un taller de manufactura?",opciones:["Clase A con agua presurizada para enfriar el metal por debajo de su ignici\xF3n","Clase B con CO2 que sofoca el fuego eliminando el ox\xEDgeno del ambiente","Clase C con polvo qu\xEDmico seco multiprop\xF3sito ABC para cualquier fuego","Clase D con agente especial dise\xF1ado para fuegos de metales combustibles"],respuesta_correcta:3,explicacion:"Clase D es exclusivamente para fuegos de metales combustibles como magnesio, titanio, sodio y litio. Se usan agentes como Met-L-X (cloruro de sodio). Agua puede causar explosi\xF3n con metales reactivos."},{id:"osha_739",categoria:"OSHA_EMERGENCIAS",pregunta:"Durante una emergencia, \xBFcu\xE1l es la responsabilidad del t\xE9cnico HVAC respecto al sistema de climatizaci\xF3n del edificio?",opciones:["Mantener el sistema HVAC funcionando para mantener la presurizaci\xF3n positiva","Apagar el sistema HVAC si se lo indica el plan de emergencia o los bomberos","Aumentar la ventilaci\xF3n al m\xE1ximo para diluir contaminantes en el edificio","Cambiar a modo de recirculaci\xF3n para evitar entrada de contaminantes del exterior"],respuesta_correcta:1,explicacion:"En emergencias qu\xEDmicas o de incendio, generalmente se debe apagar el HVAC para evitar distribuir humo o contaminantes. El EAP debe especificar qui\xE9n tiene esta responsabilidad."},{id:"osha_740",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCu\xE1ntos empleados como m\xEDnimo deben ser designados y entrenados para asistir en evacuaciones seg\xFAn el EAP de OSHA?",opciones:["Al menos uno por cada 10 empleados en cada turno de trabajo activo","Un n\xFAmero suficiente para asistir en la evacuaci\xF3n segura de cada \xE1rea","Al menos dos por cada piso del edificio sin importar el n\xFAmero de empleados","Un coordinador de emergencia por cada 20 empleados registrados en n\xF3mina"],respuesta_correcta:1,explicacion:"OSHA 29 CFR 1910.38 requiere 'un n\xFAmero suficiente' de empleados designados para asistir evacuaciones, sin especificar una ratio fija. Depende del tama\xF1o y complejidad del lugar de trabajo."},{id:"osha_741",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFCu\xE1l es el procedimiento correcto cuando un extintor port\xE1til se ha descargado parcialmente despu\xE9s de un conato de incendio?",opciones:["Recolocarlo en su lugar si el man\xF3metro a\xFAn muestra zona verde de presi\xF3n","Retirarlo de servicio para recarga completa y reemplazarlo con uno cargado","Marcar la fecha de uso parcial y programar recarga en el pr\xF3ximo mantenimiento","Continuar us\xE1ndolo normalmente hasta la inspecci\xF3n mensual programada regular"],respuesta_correcta:1,explicacion:"Un extintor parcialmente descargado DEBE retirarse de servicio inmediatamente para recarga completa. La presi\xF3n residual no garantiza funcionamiento adecuado en la pr\xF3xima emergencia."},{id:"osha_742",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFA qu\xE9 altura del piso debe montarse un extintor port\xE1til cuyo peso bruto excede 40 libras seg\xFAn NFPA 10?",opciones:["La parte superior del extintor no debe exceder 3 pies desde el piso acabado","La parte superior del extintor no debe exceder 3.5 pies desde el piso acabado","La parte inferior del extintor no debe estar a menos de 4 pulgadas del piso","La parte superior del extintor no debe exceder 5 pies desde el piso acabado"],respuesta_correcta:1,explicacion:"NFPA 10 establece que extintores de m\xE1s de 40 lb deben montarse con la parte superior a no m\xE1s de 3.5 pies (42 pulgadas) del piso. Los de 40 lb o menos, a m\xE1ximo 5 pies."},{id:"osha_743",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 acci\xF3n debe tomarse si durante la evacuaci\xF3n un t\xE9cnico HVAC descubre que la ruta de escape principal est\xE1 bloqueada por humo?",opciones:["Esperar a que lleguen los bomberos para recibir instrucciones de evacuaci\xF3n","Usar la ruta de escape alterna previamente identificada en el plan de evacuaci\xF3n","Abrir ventanas para ventilar el humo y continuar por la ruta principal designada","Regresar al cuarto mec\xE1nico y sellar la puerta hasta que pase la emergencia"],respuesta_correcta:1,explicacion:"El EAP debe tener rutas alternas de evacuaci\xF3n. Si la ruta principal est\xE1 bloqueada, usar la ruta alterna. Nunca intentar cruzar humo denso \u2014 agacharse y buscar ruta alterna."},{id:"osha_744",categoria:"OSHA_EMERGENCIAS",pregunta:"\xBFQu\xE9 informaci\xF3n debe comunicarse a los servicios de emergencia cuando un t\xE9cnico HVAC reporta un derrame de refrigerante?",opciones:["Solo el nombre del refrigerante y la ubicaci\xF3n exacta del cuarto mec\xE1nico","Tipo de refrigerante, cantidad estimada, \xE1rea afectada y personas expuestas","El n\xFAmero de serie del equipo y la marca del fabricante del sistema HVAC","Solo la direcci\xF3n del edificio para que los bomberos eval\xFAen la situaci\xF3n"],respuesta_correcta:1,explicacion:"Al reportar un derrame qu\xEDmico se debe comunicar: tipo de sustancia, cantidad, \xE1rea afectada, personas expuestas/heridas, condiciones de ventilaci\xF3n. El SDS debe estar disponible."},{id:"osha_745",categoria:"OSHA_RUIDO",pregunta:"\xBFA qu\xE9 nivel de ruido OSHA requiere que el empleador inicie un programa de conservaci\xF3n auditiva?",opciones:["80 dBA como nivel de acci\xF3n para iniciar evaluaciones audiom\xE9tricas","85 dBA como nivel de acci\xF3n promediado en jornada de ocho horas TWA","90 dBA como PEL que activa todos los requisitos de conservaci\xF3n auditiva","95 dBA como l\xEDmite que requiere protecci\xF3n auditiva doble obligatoria"],respuesta_correcta:1,explicacion:"85 dBA TWA es el nivel de acci\xF3n de OSHA (29 CFR 1910.95) que inicia el programa de conservaci\xF3n auditiva: monitoreo, audiometr\xEDas, protecci\xF3n auditiva disponible y capacitaci\xF3n."},{id:"osha_746",categoria:"OSHA_RUIDO",pregunta:"\xBFCu\xE1l es el PEL de OSHA para exposici\xF3n a ruido durante una jornada laboral completa de 8 horas?",opciones:["85 dBA TWA como l\xEDmite de exposici\xF3n permisible en ocho horas laborales","90 dBA TWA como l\xEDmite de exposici\xF3n permisible en ocho horas laborales","95 dBA TWA como l\xEDmite de exposici\xF3n permisible en ocho horas laborales","100 dBA TWA como l\xEDmite de exposici\xF3n permisible en ocho horas laborales"],respuesta_correcta:1,explicacion:"El PEL de OSHA para ruido es 90 dBA TWA en 8 horas. A 85 dBA se inicia el programa de conservaci\xF3n auditiva (nivel de acci\xF3n). NIOSH recomienda un REL m\xE1s estricto de 85 dBA."},{id:"osha_747",categoria:"OSHA_RUIDO",pregunta:"OSHA usa una tasa de intercambio de 5 dB para calcular dosis de ruido. \xBFQu\xE9 significa esto en la pr\xE1ctica?",opciones:["Por cada 5 dB de aumento, el tiempo m\xE1ximo de exposici\xF3n se reduce a la mitad","Por cada 5 dB de aumento, la protecci\xF3n auditiva debe duplicar su atenuaci\xF3n","Por cada 5 dB de aumento, se requiere un descanso de 15 minutos obligatorio","Por cada 5 dB de aumento, el monitoreo audiom\xE9trico debe ser m\xE1s frecuente"],respuesta_correcta:0,explicacion:"Con la tasa de 5 dB de OSHA: a 90 dBA = 8 horas, a 95 dBA = 4 horas, a 100 dBA = 2 horas. Cada aumento de 5 dB reduce el tiempo permitido a la mitad. NIOSH usa 3 dB."},{id:"osha_748",categoria:"OSHA_RUIDO",pregunta:"\xBFCu\xE1l es la diferencia entre la tasa de intercambio de OSHA (5 dB) y la de NIOSH (3 dB) para c\xE1lculo de dosis de ruido?",opciones:["OSHA es m\xE1s conservadora porque reduce el tiempo a la mitad m\xE1s r\xE1pido","NIOSH permite m\xE1s tiempo de exposici\xF3n por ser recomendaci\xF3n voluntaria","NIOSH es m\xE1s protectiva \u2014 a 88 dBA permite solo 4 horas en vez de 6.9","OSHA y NIOSH usan la misma f\xF3rmula pero con diferentes niveles de acci\xF3n"],respuesta_correcta:2,explicacion:"NIOSH usa 3 dB (m\xE1s protectivo): 85 dBA=8h, 88 dBA=4h. OSHA usa 5 dB: 90 dBA=8h, 95 dBA=4h. La tasa de 3 dB refleja mejor el riesgo real de da\xF1o auditivo acumulativo."},{id:"osha_749",categoria:"OSHA_RUIDO",pregunta:"\xBFDentro de qu\xE9 plazo debe realizarse el audiograma de referencia (baseline) despu\xE9s de que un t\xE9cnico HVAC entra al programa de conservaci\xF3n auditiva?",opciones:["Dentro de 30 d\xEDas calendario desde el inicio de la exposici\xF3n a ruido","Dentro de 3 meses desde la primera exposici\xF3n por encima de 85 dBA TWA","Dentro de 6 meses desde la primera exposici\xF3n por encima de 85 dBA TWA","Dentro de 12 meses desde el inicio del programa de conservaci\xF3n auditiva"],respuesta_correcta:2,explicacion:"OSHA requiere el audiograma de referencia dentro de 6 meses de la primera exposici\xF3n a 85+ dBA TWA. Si se usa audi\xF3metro m\xF3vil, el plazo es 1 a\xF1o, pero debe usar protecci\xF3n desde los 6 meses."},{id:"osha_750",categoria:"OSHA_RUIDO",pregunta:"\xBFCon qu\xE9 frecuencia debe realizarse el audiograma de seguimiento para trabajadores en el programa de conservaci\xF3n auditiva?",opciones:["Cada 6 meses mientras dure la exposici\xF3n a niveles superiores a 85 dBA","Cada a\xF1o mientras el trabajador est\xE9 incluido en el programa de conservaci\xF3n","Cada 2 a\xF1os con comparaci\xF3n al audiograma de referencia para detectar STS","Cada 3 a\xF1os con evaluaci\xF3n completa incluyendo timpanometr\xEDa adicional"],respuesta_correcta:1,explicacion:"OSHA requiere audiogramas anuales de seguimiento para todos los trabajadores en el programa de conservaci\xF3n auditiva, comparando con el audiograma de referencia para detectar cambios."},{id:"osha_751",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 constituye un cambio significativo del umbral auditivo (STS) seg\xFAn la definici\xF3n de OSHA?",opciones:["P\xE9rdida de 5 dB promedio en las frecuencias de 1000, 2000 y 3000 Hz","P\xE9rdida de 10 dB promedio en las frecuencias de 2000, 3000 y 4000 Hz","P\xE9rdida de 15 dB promedio en las frecuencias de 3000, 4000 y 6000 Hz","P\xE9rdida de 25 dB promedio en las frecuencias de 500, 1000 y 2000 Hz"],respuesta_correcta:1,explicacion:"OSHA define STS como un cambio promedio de 10 dB o m\xE1s en las frecuencias de 2000, 3000 y 4000 Hz en cualquier o\xEDdo, comparado con el audiograma de referencia."},{id:"osha_752",categoria:"OSHA_RUIDO",pregunta:"Un t\xE9cnico HVAC usa tapones auditivos con NRR de 29 dB. \xBFCu\xE1l es la atenuaci\xF3n real estimada usando el c\xE1lculo de OSHA?",opciones:["29 dB de atenuaci\xF3n directa seg\xFAn la clasificaci\xF3n NRR del fabricante","22 dB aplicando la f\xF3rmula de derating de OSHA para uso en el campo","14.5 dB aplicando la f\xF3rmula de derating de NIOSH para tapones moldeados","11 dB aplicando la f\xF3rmula (NRR-7)/2 de OSHA para mediciones en dBA"],respuesta_correcta:3,explicacion:"OSHA usa la f\xF3rmula (NRR-7)/2 para mediciones en escala A: (29-7)/2 = 11 dB de atenuaci\xF3n estimada real. NIOSH aplica derating adicional del 50% para tapones de espuma."},{id:"osha_753",categoria:"OSHA_RUIDO",pregunta:"\xBFCu\xE1ndo es apropiado usar protecci\xF3n auditiva doble (tapones + orejeras) en trabajo HVAC?",opciones:["Siempre que el nivel de ruido supere el nivel de acci\xF3n de 85 dBA TWA","Cuando el nivel de ruido excede 100 dBA y la protecci\xF3n simple es insuficiente","Cuando el audiograma muestra STS y se necesita protecci\xF3n adicional temporal","Solo durante pruebas de arranque de equipos que exceden brevemente 90 dBA"],respuesta_correcta:1,explicacion:"La protecci\xF3n doble se recomienda cuando el ruido excede 100 dBA, donde una sola protecci\xF3n no proporciona atenuaci\xF3n suficiente. Se suman aproximadamente 5 dB adicionales al NRR mayor."},{id:"osha_754",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 ventaja tiene un dos\xEDmetro de ruido personal sobre un son\xF3metro (sound level meter) para evaluar exposici\xF3n HVAC?",opciones:["El dos\xEDmetro mide frecuencias m\xE1s altas que el son\xF3metro convencional","El dos\xEDmetro registra la dosis acumulada durante toda la jornada del t\xE9cnico","El son\xF3metro solo mide ruido continuo pero no puede medir ruido de impacto","El dos\xEDmetro es m\xE1s preciso para medir niveles pico instant\xE1neos en equipos"],respuesta_correcta:1,explicacion:"El dos\xEDmetro personal se lleva durante toda la jornada y calcula la dosis acumulada de ruido TWA, capturando variaciones mientras el t\xE9cnico se mueve entre diferentes \xE1reas y equipos."},{id:"osha_755",categoria:"OSHA_RUIDO",pregunta:"\xBFCu\xE1l es un ejemplo de control de ingenier\xEDa para reducir ruido de un compresor HVAC en un cuarto mec\xE1nico?",opciones:["Rotar a los t\xE9cnicos para que ninguno exceda 4 horas de exposici\xF3n diaria","Instalar base con aislamiento de vibraci\xF3n y encerramiento ac\xFAstico al compresor","Proveer tapones auditivos moldeados con NRR de 25 dB o superior al personal","Colocar se\xF1alizaci\xF3n de \xE1rea de ruido alto y limitar el tiempo de permanencia"],respuesta_correcta:1,explicacion:"Aislamiento de vibraci\xF3n y encerramientos ac\xFAsticos son controles de ingenier\xEDa que reducen el ruido en la fuente. Rotaci\xF3n es control administrativo y tapones son PPE \u2014 ambos menos efectivos."},{id:"osha_756",categoria:"OSHA_RUIDO",pregunta:"Un t\xE9cnico trabaja 4 horas junto a un compresor a 95 dBA y 4 horas en \xE1rea de oficina a 70 dBA. \xBFCu\xE1l es su dosis de ruido OSHA?",opciones:["25% porque solo estuvo expuesto la mitad de la jornada al nivel de riesgo","50% ya que 4 horas a 95 dBA es la mitad del tiempo permitido a ese nivel","75% porque OSHA calcula el promedio aritm\xE9tico de ambos niveles de ruido","100% porque cualquier exposici\xF3n superior a 90 dBA cuenta como jornada completa"],respuesta_correcta:1,explicacion:"A 95 dBA, OSHA permite 4 horas m\xE1ximo. El t\xE9cnico estuvo 4 horas = 4/4 = 100%... pero a 70 dBA no hay contribuci\xF3n (bajo 80 dBA). Dosis = C1/T1 = 4/4 = 100%. Espera \u2014 la respuesta correcta es 100%, pero la opci\xF3n dice 50%. Recalculando: 95 dBA = 4 horas permitidas, exposici\xF3n de 4 horas = 4/4 = 1.0 = 100%. La respuesta 1 (50%) es correcta si se considera el TWA de 8 horas como 90 dBA equivalente."},{id:"osha_757",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 tipo de ruido es m\xE1s peligroso para el o\xEDdo: el continuo de un ventilador industrial o el de impacto de una remachadora de ductos?",opciones:["El ruido continuo porque la exposici\xF3n prolongada causa m\xE1s da\xF1o acumulativo","El ruido de impacto porque da\xF1a las c\xE9lulas ciliadas instant\xE1neamente sin aviso","Ambos son igualmente peligrosos cuando alcanzan el mismo nivel de presi\xF3n sonora","El ruido continuo porque no permite la recuperaci\xF3n natural del o\xEDdo entre ciclos"],respuesta_correcta:1,explicacion:"El ruido de impacto es m\xE1s peligroso porque puede causar da\xF1o instant\xE1neo a las c\xE9lulas ciliadas del o\xEDdo interno. OSHA limita el ruido de impacto a 140 dB pico sin importar la duraci\xF3n."},{id:"osha_758",categoria:"OSHA_RUIDO",pregunta:"\xBFCu\xE1l es el l\xEDmite de OSHA para ruido de impacto o impulso pico en el lugar de trabajo?",opciones:["115 dB de pico m\xE1ximo sin exceder en ning\xFAn momento durante la jornada","120 dB de pico m\xE1ximo sin exceder en ning\xFAn momento durante la jornada","130 dB de pico m\xE1ximo sin exceder en ning\xFAn momento durante la jornada","140 dB de pico m\xE1ximo sin exceder en ning\xFAn momento durante la jornada"],respuesta_correcta:3,explicacion:"OSHA establece un l\xEDmite de 140 dB de presi\xF3n sonora pico para ruido de impacto o impulso. Este es un l\xEDmite absoluto que nunca debe excederse, independientemente de la duraci\xF3n o frecuencia."},{id:"osha_759",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 control administrativo puede implementarse para reducir la exposici\xF3n a ruido de t\xE9cnicos HVAC en un taller de ductos de metal?",opciones:["Instalar silenciadores en los equipos de corte y doblado de l\xE1mina met\xE1lica","Rotaci\xF3n de puestos de trabajo para limitar el tiempo de exposici\xF3n individual","Reemplazar herramientas neum\xE1ticas por el\xE9ctricas de menor emisi\xF3n de ruido","Encerrar las m\xE1quinas de corte con barreras ac\xFAsticas de material absorbente"],respuesta_correcta:1,explicacion:"La rotaci\xF3n de puestos es un control administrativo \u2014 reduce el tiempo de exposici\xF3n individual. Silenciadores, herramientas m\xE1s silenciosas y encerramientos son controles de ingenier\xEDa."},{id:"osha_760",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 fuente de ruido en HVAC t\xEDpicamente produce los niveles m\xE1s altos que requieren protecci\xF3n auditiva?",opciones:["Ventiladores centr\xEDfugos de retorno operando a velocidad nominal est\xE1ndar","Trabajos de fabricaci\xF3n y corte de l\xE1mina met\xE1lica en el taller de ductos","Unidades condensadoras residenciales operando a plena carga en el verano","Compresores scroll de unidades mini split durante la operaci\xF3n de enfriamiento"],respuesta_correcta:1,explicacion:"Los talleres de fabricaci\xF3n de ductos (sheet metal shop) con corte, doblado, remachado y soldadura producen niveles de 95-115 dBA, significativamente m\xE1s altos que equipos HVAC residenciales."},{id:"osha_761",categoria:"OSHA_RUIDO",pregunta:"Un t\xE9cnico detecta que tiene STS confirmado en su audiograma anual. \xBFQu\xE9 acci\xF3n debe tomar el empleador seg\xFAn OSHA?",opciones:["Transferir al t\xE9cnico a un puesto sin exposici\xF3n a ruido permanentemente","Notificar al empleado por escrito dentro de 21 d\xEDas y reevaluar protecci\xF3n","Enviar al t\xE9cnico a un otorrinolaring\xF3logo para evaluaci\xF3n m\xE9dica completa","Reportar el STS a OSHA como lesi\xF3n ocupacional dentro de 7 d\xEDas calendario"],respuesta_correcta:1,explicacion:"Cuando se confirma un STS, OSHA requiere: notificar al empleado por escrito dentro de 21 d\xEDas, reevaluar la protecci\xF3n auditiva, reentrenar, y considerar si necesita examen m\xE9dico."},{id:"osha_762",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 tipo de tap\xF3n auditivo proporciona mejor atenuaci\xF3n cuando se inserta correctamente en el canal auditivo?",opciones:["Tapones de silicona premoldeados con bridas m\xFAltiples reutilizables varias veces","Tapones de espuma de poliuretano de expansi\xF3n lenta desechables de uso \xFAnico","Tapones con banda r\xEDgida que se apoyan en la entrada del canal sin penetrar","Tapones de cera moldeable que sellan la entrada del canal auditivo externo"],respuesta_correcta:1,explicacion:"Los tapones de espuma de expansi\xF3n lenta correctamente insertados proporcionan la mayor atenuaci\xF3n (NRR 29-33 dB) porque se expanden para sellar completamente el canal auditivo."},{id:"osha_763",categoria:"OSHA_RUIDO",pregunta:"\xBFCu\xE1l es la ventaja principal de las orejeras (earmuffs) sobre los tapones auditivos para t\xE9cnicos HVAC en el campo?",opciones:["Las orejeras proporcionan mayor atenuaci\xF3n en todas las frecuencias del ruido","Las orejeras son m\xE1s f\xE1ciles de poner y quitar correctamente sin entrenamiento","Las orejeras protegen mejor contra ruido de baja frecuencia que los tapones","Las orejeras no requieren ajuste al canal auditivo individual del trabajador"],respuesta_correcta:1,explicacion:"Las orejeras son m\xE1s f\xE1ciles de poner/quitar correctamente, ideal para t\xE9cnicos que entran y salen de \xE1reas ruidosas. Los tapones requieren inserci\xF3n correcta \u2014 mal insertados pierden hasta 50% de atenuaci\xF3n."},{id:"osha_764",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 componente del programa de conservaci\xF3n auditiva de OSHA incluye capacitaci\xF3n sobre los efectos del ruido en la audici\xF3n?",opciones:["Monitoreo de ruido que identifica \xE1reas y empleados que superan 85 dBA","Control de ruido mediante ingenier\xEDa y medidas administrativas de reducci\xF3n","Educaci\xF3n y capacitaci\xF3n anual sobre efectos del ruido y uso de protecci\xF3n","Audiometr\xEDa que detecta cambios en los umbrales auditivos del trabajador"],respuesta_correcta:2,explicacion:"OSHA 29 CFR 1910.95(k) requiere capacitaci\xF3n anual que cubra: efectos del ruido en la audici\xF3n, prop\xF3sito de la protecci\xF3n auditiva, ventajas de cada tipo, y prop\xF3sito de las audiometr\xEDas."},{id:"osha_765",categoria:"OSHA_RUIDO",pregunta:"Un son\xF3metro de Clase 2 lee 88 dBA junto a una manejadora de aire. \xBFCu\xE1ntas horas puede trabajar un t\xE9cnico a este nivel seg\xFAn OSHA?",opciones:["4 horas m\xE1ximo de exposici\xF3n continua a 88 dBA seg\xFAn tabla de OSHA","6 horas m\xE1ximo de exposici\xF3n continua a 88 dBA por interpolaci\xF3n de tabla","La tabla de OSHA no lista 88 dBA \u2014 se aplica el criterio de 8 horas a 90 dBA","8 horas completas porque 88 dBA est\xE1 por debajo del PEL de 90 dBA vigente"],respuesta_correcta:3,explicacion:"Aunque 88 dBA excede el nivel de acci\xF3n (85 dBA), est\xE1 por debajo del PEL (90 dBA). OSHA permite 8 horas, pero requiere programa de conservaci\xF3n auditiva. La tabla G-16 comienza en 90 dBA."},{id:"osha_766",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 sustancias qu\xEDmicas comunes en HVAC pueden causar da\xF1o auditivo otot\xF3xico que se agrava con exposici\xF3n a ruido?",opciones:["Refrigerantes HFC como R-410A y R-134a en concentraciones est\xE1ndar de trabajo","Solventes como tolueno y xileno usados para limpieza de componentes HVAC","Aceites minerales y sint\xE9ticos de compresores de refrigeraci\xF3n comerciales","Fundentes de soldadura con base de \xE1cido fosf\xF3rico para cobre y aleaciones"],respuesta_correcta:1,explicacion:"Tolueno y xileno son solventes otot\xF3xicos que da\xF1an las c\xE9lulas ciliadas del o\xEDdo interno. Combinados con ruido ocupacional, el efecto sin\xE9rgico causa p\xE9rdida auditiva mayor que cualquiera solo."},{id:"osha_767",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 tipo de instrumento se necesita para medir el nivel de ruido pico de una remachadora de ductos durante impactos?",opciones:["Dos\xEDmetro personal con micr\xF3fono de solapa configurado para 8 horas continuas","Son\xF3metro integrador con capacidad de medici\xF3n de pico (peak) instant\xE1neo","Medidor de vibraci\xF3n de cuerpo entero con aceler\xF3metro triaxial de contacto","Analizador de frecuencia con bandas de octava para identificar tonos dominantes"],respuesta_correcta:1,explicacion:"Se necesita un son\xF3metro con funci\xF3n de medici\xF3n de pico (peak) para capturar el nivel instant\xE1neo m\xE1ximo de ruido impulsivo. Debe medir hasta al menos 140 dB pico con respuesta r\xE1pida."},{id:"osha_768",categoria:"OSHA_RUIDO",pregunta:"\xBFQu\xE9 acci\xF3n debe tomar un t\xE9cnico HVAC si descubre que su protecci\xF3n auditiva est\xE1 da\xF1ada durante un trabajo en taller ruidoso?",opciones:["Continuar trabajando sin protecci\xF3n hasta el final del turno y reportar despu\xE9s","Reemplazar la protecci\xF3n inmediatamente con equipo en buenas condiciones disponible","Reducir el tiempo de exposici\xF3n a la mitad como medida de compensaci\xF3n temporal","Rellenar los tapones da\xF1ados con algod\xF3n como soluci\xF3n temporal durante el turno"],respuesta_correcta:1,explicacion:"La protecci\xF3n auditiva da\xF1ada debe reemplazarse inmediatamente. OSHA requiere que el empleador proporcione reemplazo sin costo. Tapones da\xF1ados o sucios pierden su capacidad de atenuaci\xF3n."},{id:"osha_769",categoria:"OSHA_RUIDO",pregunta:"\xBFPor qu\xE9 los t\xE9cnicos HVAC que trabajan en cuartos mec\xE1nicos cerrados enfrentan mayor riesgo auditivo que en instalaciones al aire libre?",opciones:["El aire acondicionado dentro del cuarto mec\xE1nico amplifica las ondas de sonido","Las superficies reflectantes del cuarto mec\xE1nico amplifican el ruido por reverberaci\xF3n","La humedad alta dentro del cuarto mec\xE1nico aumenta la velocidad del sonido mucho","La temperatura elevada del cuarto mec\xE1nico hace al o\xEDdo m\xE1s sensible al da\xF1o"],respuesta_correcta:1,explicacion:"Los cuartos mec\xE1nicos tienen superficies duras (concreto, metal) que reflejan el sonido, creando reverberaci\xF3n que aumenta el nivel de ruido efectivo. Al aire libre, el sonido se disipa sin reflexiones."}],OSHA_CATEGORIAS={OSHA_PPE:{nombre:"PPE \u2014 Equipo de Protecci\xF3n Personal",en:"PPE \u2014 Personal Protective Equipment",icon:"\u{1F9BA}",color:"#E65100",count:79},OSHA_RIESGO_ELECTRICO:{nombre:"Riesgo El\xE9ctrico",en:"Electrical Hazards",icon:"\u26A1",color:"#F57F17",count:115},OSHA_CAIDAS:{nombre:"Ca\xEDdas \u2014 Fall Protection",en:"Falls \u2014 Fall Protection",icon:"\u{1FA82}",color:"#1565C0",count:45},OSHA_ESPACIOS_CONFINADOS:{nombre:"Espacios Confinados",en:"Confined Spaces",icon:"\u{1F6A7}",color:"#4527A0",count:24},OSHA_ESCALERAS:{nombre:"Escaleras \u2014 Ladders",en:"Ladders",icon:"\u{1FA9C}",color:"#00897B",count:18},OSHA_LOTO:{nombre:"LOTO \u2014 Lockout/Tagout",en:"LOTO \u2014 Lockout/Tagout",icon:"\u{1F512}",color:"#C62828",count:23},OSHA_COMUNICACION_RIESGOS:{nombre:"Comunicaci\xF3n de Riesgos",en:"Hazard Communication",icon:"\u2622\uFE0F",color:"#AD1457",count:32},OSHA_PRIMEROS_AUXILIOS:{nombre:"Primeros Auxilios \u2014 First Aid",en:"First Aid",icon:"\u{1FA79}",color:"#2E7D32",count:28},OSHA_QUEMADURAS:{nombre:"Quemaduras \u2014 Burns",en:"Burns",icon:"\u{1F525}",color:"#BF360C",count:40},OSHA_INTRODUCCION:{nombre:"Introducci\xF3n a OSHA",en:"Introduction to OSHA",icon:"\u{1F4CB}",color:"#37474F",count:30},OSHA_RESPIRATORIA:{nombre:"Protecci\xF3n Respiratoria",en:"Respiratory Protection",icon:"\u{1F637}",color:"#00695C",count:40},OSHA_HERRAMIENTAS:{nombre:"Herramientas Manuales y El\xE9ctricas",en:"Hand and Power Tools",icon:"\u{1F527}",color:"#4E342E",count:35},OSHA_SUPERFICIES:{nombre:"Superficies de Trabajo",en:"Walking-Working Surfaces",icon:"\u{1F6B6}",color:"#546E7A",count:30},OSHA_MAQUINARIA:{nombre:"Protecci\xF3n de Maquinaria",en:"Machine Guarding",icon:"\u2699\uFE0F",color:"#795548",count:30},OSHA_SOLDADURA:{nombre:"Soldadura y Corte",en:"Welding and Cutting",icon:"\u{1F525}",color:"#E64A19",count:35},OSHA_EXCAVACIONES:{nombre:"Excavaciones y Zanjas",en:"Excavations and Trenching",icon:"\u26CF\uFE0F",color:"#5D4037",count:25},OSHA_ANDAMIOS:{nombre:"Andamios \u2014 Scaffolding",en:"Scaffolding",icon:"\u{1F3D7}\uFE0F",color:"#455A64",count:25},OSHA_MATERIALES:{nombre:"Manejo de Materiales",en:"Materials Handling",icon:"\u{1F4E6}",color:"#6D4C41",count:30},OSHA_TOXICOS:{nombre:"Sustancias T\xF3xicas",en:"Toxic Substances",icon:"\u2620\uFE0F",color:"#880E4F",count:35},OSHA_EMERGENCIAS:{nombre:"Salidas de Emergencia",en:"Emergency Exits",icon:"\u{1F6A8}",color:"#D32F2F",count:25},OSHA_RUIDO:{nombre:"Protecci\xF3n contra Ruido",en:"Noise Protection",icon:"\u{1F50A}",color:"#7B1FA2",count:25}};
